    def _pvp_room_policy(self, room_id: int) -> dict[str, Any] | None:
        getter = getattr(self.knowledge, "get", None)
        if not callable(getter):
            return {"known": False, "room_id": int(room_id)}
        result = getter(f"location:{int(room_id)}")
        if result.get("status") != "found" or not isinstance(result.get("entity"), dict):
            return {"known": False, "room_id": int(room_id)}
        entity = result["entity"]
        facts = entity.get("facts") if isinstance(entity.get("facts"), dict) else {}
        evidence = entity.get("evidence") if isinstance(entity.get("evidence"), dict) else {}
        return {
            "known": True,
            "room_id": facts.get("room_id", int(room_id)),
            "name": entity.get("canonical_name"),
            "region": facts.get("region"),
            "flags": facts.get("flags", []),
            "terrain": facts.get("terrain", []),
            "flag_evidence": facts.get("flag_evidence"),
            "evidence": {
                "source_tier": evidence.get("source_tier"),
                "source_ref": evidence.get("source_ref"),
                "corpus_version": evidence.get("corpus_version"),
            },
        }

    def _room_properties(self, room_id: Any) -> dict[str, Any]:
        """Return compact source-derived properties for a displayed room."""

        try:
            numeric_room_id = int(room_id)
        except (TypeError, ValueError):
            return {
                "known": False,
                "safe": None,
                "flags": [],
                "terrain": [],
                "region": None,
            }
        policy = self._pvp_room_policy(numeric_room_id)
        if not isinstance(policy, dict) or policy.get("known") is not True:
            return {
                "known": False,
                "safe": None,
                "flags": [],
                "terrain": [],
                "region": None,
            }
        return {
            "known": True,
            "safe": self._is_verified_safe_staging(policy),
            "flags": sorted(str(value) for value in policy.get("flags", [])),
            "terrain": sorted(str(value) for value in policy.get("terrain", [])),
            "region": policy.get("region"),
        }

    @staticmethod
    def _is_verified_safe_staging(policy: dict[str, Any] | None) -> bool:
        if not isinstance(policy, dict) or policy.get("known") is not True:
            return False
        flags = policy.get("flags")
        return isinstance(flags, list) and bool(
            SAFE_STAGING_FLAGS.intersection(str(value) for value in flags)
        )

    def _verified_safe_staging(self, room_id: Any) -> dict[str, Any] | None:
        try:
            numeric_room_id = int(room_id)
        except (TypeError, ValueError):
            return None
        policy = self._pvp_room_policy(numeric_room_id)
        if not self._is_verified_safe_staging(policy):
            return None
        assert isinstance(policy, dict)
        return {
            "room_id": numeric_room_id,
            "name": str(policy.get("name") or f"room {numeric_room_id}"),
            "flags": sorted(str(value) for value in policy.get("flags", [])),
            "evidence": policy.get("evidence"),
            "basis": "source_verified_current_or_remembered_room",
        }

    def _remember_safe_staging(self, observation: dict[str, Any]) -> dict[str, Any] | None:
        room_id = deep_get(
            observation,
            "look.room.num",
            deep_get(observation, "look.room_id"),
        )
        staging = self._verified_safe_staging(room_id)
        if staging is None:
            return None
        value = {**staging, "observed_at": timestamp()}
        self.storage.set_runtime(SAFE_STAGING_RUNTIME_KEY, value)
        return value

    def _safe_ending_context(self, observation: dict[str, Any]) -> dict[str, Any]:
        """Expose verified choices while leaving the destination choice to the model."""

        room_id = deep_get(
            observation,
            "look.room.num",
            deep_get(observation, "look.room_id"),
        )
        finder = getattr(self.knowledge, "safe_location_candidates", None)
        result: dict[str, Any] = {
            "status": "unavailable",
            "from_room_id": room_id,
            "candidates": [],
        }
        if callable(finder) and room_id is not None:
            try:
                found = finder(int(room_id), limit=12)
                if isinstance(found, dict):
                    result = found
            except (TypeError, ValueError):
                pass
        candidates = result.get("candidates")
        candidates = (
            [dict(item) for item in candidates if isinstance(item, dict)]
            if isinstance(candidates, list)
            else []
        )
        current = self._verified_safe_staging(room_id)
        if current is not None and not any(
            str(item.get("room_id")) == str(current["room_id"])
            for item in candidates
        ):
            candidates.insert(
                0,
                {
                    **current,
                    "distance": 0,
                    "from_room_id": room_id,
                    "basis": "source_verified_current_room",
                },
            )
        usable_candidates: list[dict[str, Any]] = []
        excluded_routes: list[dict[str, Any]] = []
        deferred_tactics = self.storage.goal_lessons(
            statuses=["deferred"], limit=200
        )
        for candidate in candidates:
            destination = candidate.get("room_id")
            if destination is None:
                continue
            tactic_key = self.learning.tactic_key(
                "travel",
                {"agent": self.config.game.agent, "to": destination},
                observation,
            )
            lesson = next(
                (
                    item
                    for item in deferred_tactics
                    if item.get("scope") == "tactic"
                    and item.get("tactic_key") == tactic_key
                ),
                None,
            )
            if lesson is None:
                usable_candidates.append(candidate)
                continue
            evaluation = self.learning.evaluate_retry(lesson, observation)
            if evaluation.get("met") is True:
                # Unlocking is owned by the normal learning refresh. Building
                # planning context must remain read-only, particularly during
                # diagnostics and status inspection.
                usable_candidates.append(candidate)
                continue
            excluded_routes.append(
                {
                    "from_room_id": room_id,
                    "room_id": destination,
                    "classification": lesson.get("classification"),
                    "summary": str(lesson.get("summary") or "")[:300],
                    "scope": "exact_origin_destination_travel",
                }
            )
        return {
            **result,
            "candidates": usable_candidates[:12],
            "excluded_exact_routes": excluded_routes[:12],
            "selection_owner": "planning_model",
            "required_source_flags": sorted(SAFE_STAGING_FLAGS),
        }

    def _validated_safe_ending(
        self,
        raw_plan: dict[str, Any],
        steps: list[dict[str, Any]],
    ) -> dict[str, Any]:
        """Verify a model-selected terminal room and its final travel step."""

        ending = raw_plan.get("safe_ending")
        if not isinstance(ending, dict):
            raise ModelError(
                "execution_plan.safe_ending is required; choose one source-verified "
                "safe ending from grounded_knowledge.safe_ending_candidates.candidates"
            )
        unknown = set(ending) - {"room_id", "step_id", "rationale"}
        if unknown:
            raise ModelError(
                "execution_plan.safe_ending contains unknown field(s): "
                + ", ".join(sorted(str(value) for value in unknown))
            )
        room_id = ending.get("room_id")
        if not isinstance(room_id, int) or isinstance(room_id, bool) or room_id <= 0:
            raise ModelError("execution_plan.safe_ending.room_id must be a positive integer")
        step_id = str(ending.get("step_id") or "").strip()
        rationale = " ".join(str(ending.get("rationale") or "").split())
        if not step_id or not rationale:
            raise ModelError(
                "execution_plan.safe_ending requires step_id and a persona-aware rationale"
            )
        policy = self._pvp_room_policy(room_id)
        if not self._is_verified_safe_staging(policy):
            raise ModelError(
                f"execution_plan.safe_ending room {room_id} is not source-verified with "
                "ROOM_SANCTUARY or ROOM_NO_COMBAT"
            )
        if not steps or str(steps[-1].get("id") or "") != step_id:
            raise ModelError(
                "execution_plan.safe_ending.step_id must name the final actionable plan step"
            )
        final_step = steps[-1]
        if final_step.get("tool") != "travel":
            raise ModelError("the safe-ending step must use the travel tool")
        final_text = canonical_json(final_step)
        if re.search(rf"(?<!\d){room_id}(?!\d)", final_text) is None:
            raise ModelError(
                f"the final safe-ending travel step must name exact room id {room_id}"
            )
        assert isinstance(policy, dict)
        flags = sorted(str(value) for value in policy.get("flags", []))
        return {
            "room_id": room_id,
            "name": str(policy.get("name") or f"room {room_id}"),
            "flags": flags,
            "step_id": step_id,
            "rationale": rationale[:1000],
            "evidence": redact(policy.get("evidence")),
        }

    def _verified_guild_eligibility(self) -> bool:
        """Return true only when ordinary client state positively proves membership."""

        observation = self.last_observation or {}
        for path in (
            "status.guild",
            "status.guild_name",
            "status.character.guild",
            "look.self.guild",
            "look.you.guild",
        ):
            value = deep_get(observation, path)
            if isinstance(value, dict):
                if value.get("is_member") is True or value.get("member") is True:
                    return True
                if any(value.get(key) not in (None, "", 0, False) for key in ("id", "name", "guild_id", "guild_name")):
                    return True
            elif value not in (None, "", 0, False):
                if str(value).strip().casefold() not in {"none", "unguilded", "no guild"}:
                    return True
        # These viewer-relative relation bits require both players to be
        # guilded. They are valid positive evidence even when a secret guild's
        # name is absent from self-description.
        objects = deep_get(observation, "look.objects", [])
        return any(
            isinstance(item, dict)
            and item.get("is_player") is True
            and str(item.get("relation") or "").strip().casefold()
            in {"guildmate", "friend", "enemy"}
            for item in (objects if isinstance(objects, list) else [])
        )

    @staticmethod
    def _has_live_hostility_evidence(item: dict[str, Any]) -> bool:
        relation = str(item.get("relation") or "").strip().casefold()
        return relation in LIVE_HOSTILITY_RELATIONS or any(
            item.get(field) is True
            for field in (
                "hostile",
                "aggressive",
                "attacking_self",
                "targeting_self",
            )
        )

    def _repair_false_faction_troop_quarantines(self) -> list[dict[str, Any]]:
        """Remove legacy quarantines created from troop presence alone.

        Historical combat evidence remains immutable.  This only corrects the
        runtime gate when every recorded reason is the old attackable-is-hostile
        inference and all resolved threats are political faction troops.
        """
        raw = self.storage.get_runtime("farm_tactic_quarantine_v1", {})
        if not isinstance(raw, dict):
            return []
        quarantines = dict(raw)
        removed: list[dict[str, Any]] = []
        for key, value in list(quarantines.items()):
            if not isinstance(value, dict):
                continue
            threats = value.get("live_overlevel_hostiles")
            threats = threats if isinstance(threats, list) else []
            entity_ids = {
                str(item.get("entity_id") or "")
                for item in threats
                if isinstance(item, dict)
            }
            reasons = [
                str(reason).casefold()
                for reason in value.get("reasons", [])
                if reason is not None
            ]
            presence_only = bool(reasons) and all(
                "source-resolved hostile" in reason
                or ("soldier" in reason and "danger limit" in reason)
                for reason in reasons
            )
            if (
                entity_ids
                and entity_ids <= POLITICAL_FACTION_TROOP_ENTITY_IDS
                and presence_only
            ):
                removed.append(dict(value))
                quarantines.pop(key, None)
        if removed:
            self.storage.set_runtime("farm_tactic_quarantine_v1", quarantines)
            self.storage.emit_event(
                "background_farm.quarantine_corrected",
                "Removed faction-troop quarantines that lacked aggression evidence",
                severity="notice",
                interesting=True,
                data={
                    "rooms": [item.get("room") for item in removed],
                    "reason": (
                        "ordinary-client attackability is permission to initiate combat, "
                        "not proof that a political faction troop is hostile"
                    ),
                },
            )
        return removed

    def _repair_gentle_overlevel_farm_quarantines(
        self, observation: dict[str, Any]
    ) -> list[dict[str, Any]]:
        """Release level-only quarantines disproved by grounded attack ratings.

        Legacy records retained only the classifier's conclusion, so the text
        alone is not enough to delete one.  Re-read the current source spawn
        table and release the room only when it contains at least one overlevel
        spawn, every such spawn has a known gentle rating, and no dangerous or
        unknown overlevel spawn remains.
        """

        raw = self.storage.get_runtime("farm_tactic_quarantine_v1", {})
        if not isinstance(raw, dict):
            return []
        quarantines = dict(raw)
        released: list[dict[str, Any]] = []
        for key, record in list(quarantines.items()):
            if not isinstance(record, dict):
                continue
            reasons = [
                str(reason).strip().casefold()
                for reason in record.get("reasons", [])
                if str(reason).strip()
            ]
            level_only = bool(reasons) and all(
                "source-resolved hostile above the verified danger band" in reason
                for reason in reasons
            )
            if not level_only:
                continue
            room = record.get("room", record.get("assigned_room"))
            assessment = self._source_room_overlevel_assessment(room, observation)
            if (
                assessment is None
                or assessment["threats"]
                or not assessment["forgiven"]
            ):
                continue
            released.append(
                {
                    **record,
                    "released_at": timestamp(),
                    "release_reason": (
                        "fresh source difficulty proves every overlevel spawn is "
                        "inside the keeper's gentle attack-rating band"
                    ),
                    "forgiven_overlevel_spawns": assessment["forgiven"],
                }
            )
            quarantines.pop(key, None)
        if not released:
            return []

        self.storage.set_runtime("farm_tactic_quarantine_v1", quarantines)
        self._clear_released_farm_retreat_incidents(released)
        repaired_lessons: list[dict[str, Any]] = []
        for item in released:
            lesson_id = item.get("lesson_id")
            lesson = self.storage.goal_lesson(str(lesson_id)) if lesson_id else None
            if isinstance(lesson, dict) and lesson.get("status") in {
                "deferred",
                "unlocked",
            }:
                repaired_lessons.append(
                    self.storage.update_goal_lesson(
                        str(lesson_id),
                        "resolved",
                        evidence={
                            "repair": item["release_reason"],
                            "forgiven_overlevel_spawns": item[
                                "forgiven_overlevel_spawns"
                            ],
                            "at": timestamp(),
                        },
                    )
                )
        affected_goal_ids = {
            str(item.get("goal_id") or "")
            for item in released
            if item.get("goal_id")
        }
        for goal_id in affected_goal_ids:
            self._clear_research_recipe_exhaustion(goal_id)
            run = self.storage.campaign_run(goal_id)
            blocker = run.get("external_blocker") if isinstance(run, dict) else None
            if (
                isinstance(blocker, dict)
                and blocker.get("kind") == "no_usable_farm_recipe"
            ):
                self.storage.clear_campaign_external_blocker(str(run["id"]))
        suppression = self.storage.get_runtime("safety_suppression_v1")
        if isinstance(suppression, dict) and "quarantined_farm_tactic" in suppression.get(
            "blocker_kinds", []
        ):
            self.storage.set_runtime("safety_suppression_v1", None)
            self._clear_planner_feedback()
        self.storage.emit_event(
            "background_farm.quarantine_released",
            "Released farm quarantines created by the obsolete level-only classifier",
            severity="notice",
            interesting=False,
            data={
                "rooms": [item.get("room") for item in released],
                "targets": [item.get("target") for item in released],
                "lesson_ids": [item.get("id") for item in repaired_lessons],
                "reason": "fresh source attack ratings align the controller with the keeper",
            },
        )
        return released

    def _repair_capability_unlocked_farm_quarantines(
        self, observation: dict[str, Any]
    ) -> list[dict[str, Any]]:
        """Release survivability quarantines after a verified capability gain.

        Farm quarantines are retry gates, not permanent room bans. Legacy
        records predate an explicit retry predicate, so compare them with the
        closest pre-quarantine combat observation for the same room and prey.
        Structural wall failures, live-world hazards, and deaths remain gated.
        """
        raw = self.storage.get_runtime("farm_tactic_quarantine_v1", {})
        if not isinstance(raw, dict):
            return []
        history = self.storage.get_runtime("combat_outcomes_v1", [])
        outcomes = [item for item in history if isinstance(item, dict)] if isinstance(history, list) else []
        current_health = deep_get(
            observation,
            "status.vitals.health.max",
            deep_get(observation, "look.vitals.health.max"),
        )
        quarantines = dict(raw)
        released: list[dict[str, Any]] = []
        for key, record in list(quarantines.items()):
            if not isinstance(record, dict):
                continue
            reasons = [
                str(reason).casefold()
                for reason in record.get("reasons", [])
                if reason is not None
            ]
            if not reasons or any(
                marker in " ".join(reasons)
                for marker in (
                    "death",
                    "died",
                    "no safe spot",
                    "outside the fight's reach",
                    "overlevel hostile",
                )
            ):
                continue
            if all("safe spot" in reason for reason in reasons):
                continue
            quarantined_at = str(record.get("quarantined_at") or "")
            room = record.get("room", record.get("assigned_room"))
            target = str(record.get("target") or "").strip().casefold()
            candidates: list[dict[str, Any]] = []
            for outcome in outcomes:
                occurred_at = str(outcome.get("occurred_at") or "")
                if quarantined_at and occurred_at and occurred_at > quarantined_at:
                    continue
                outcome_room = outcome.get("room")
                if isinstance(outcome_room, dict):
                    outcome_room = outcome_room.get("id", outcome_room.get("name"))
                if str(outcome_room) != str(room):
                    continue
                if target and str(outcome.get("target") or "").strip().casefold() != target:
                    continue
                candidates.append(outcome)
            if not candidates:
                continue
            baseline = max(candidates, key=lambda item: str(item.get("occurred_at") or ""))
            baseline_health = deep_get(
                baseline,
                "health_after.max",
                deep_get(baseline, "health_before.max"),
            )
            health_improved = (
                isinstance(current_health, (int, float))
                and isinstance(baseline_health, (int, float))
                and current_health > baseline_health
            )
            # Older combat records only retained a directionless hash. A
            # different hash may mean the character lost its weapon on death,
            # so it cannot release a safety quarantine. Newer records retain
            # semantic equipment and can prove a monotonic addition.
            equipment_improved = bool(
                "equipment" in baseline
                and self.learning.capability_improved(
                    {"equipment": baseline.get("equipment")}, observation
                )
            )
            if not (health_improved or equipment_improved):
                continue
            released.append(
                {
                    **record,
                    "released_at": timestamp(),
                    "release_reason": "verified capability improved since quarantine",
                    "baseline_max_health": baseline_health,
                    "current_max_health": current_health,
                    "equipment_improved": equipment_improved,
                }
            )
            quarantines.pop(key, None)
        if not released:
            return []
        self.storage.set_runtime("farm_tactic_quarantine_v1", quarantines)
        self._clear_released_farm_retreat_incidents(released)
        suppression = self.storage.get_runtime("safety_suppression_v1")
        if isinstance(suppression, dict) and "quarantined_farm_tactic" in suppression.get(
            "blocker_kinds", []
        ):
            self.storage.set_runtime("safety_suppression_v1", None)
            self._clear_planner_feedback()
        self.storage.emit_event(
            "background_farm.quarantine_released",
            "Released farm quarantines after verified capability improvement",
            severity="notice",
            interesting=False,
            data={
                "rooms": [item.get("room") for item in released],
                "targets": [item.get("target") for item in released],
            },
        )
        return released

    def _clear_released_farm_retreat_incidents(
        self, released: list[dict[str, Any]]
    ) -> None:
        """Reset escalation counters when their matching quarantine is released."""

        raw = self.storage.get_runtime("farm_tactic_retreat_incidents_v1", {})
        records = dict(raw) if isinstance(raw, dict) else {}
        if not records or not released:
            return

        def matches(record: dict[str, Any], release: dict[str, Any]) -> bool:
            release_room = release.get("assigned_room", release.get("room"))
            if str(record.get("assigned_room")) != str(release_room):
                return False
            release_target = " ".join(
                str(release.get("target") or "").casefold().split()
            )
            record_target = " ".join(
                str(record.get("target") or "").casefold().split()
            )
            if release_target and record_target and release_target != record_target:
                return False
            release_safe_spots = release.get("use_safe_spots")
            record_safe_spots = record.get("use_safe_spots")
            if (
                isinstance(release_safe_spots, bool)
                and isinstance(record_safe_spots, bool)
                and release_safe_spots != record_safe_spots
            ):
                return False
            release_goal = str(release.get("goal_id") or "")
            record_goal = str(record.get("goal_id") or "")
            return not release_goal or not record_goal or release_goal == record_goal

        filtered = {
            key: record
            for key, record in records.items()
            if not (
                isinstance(record, dict)
                and any(matches(record, release) for release in released)
            )
        }
        if len(filtered) != len(records):
            self.storage.set_runtime("farm_tactic_retreat_incidents_v1", filtered)

    def _repair_policy_obsolete_farm_quarantines(self) -> list[dict[str, Any]]:
        """Release records caused only by ordinary farm recovery cycles.

        Threshold crossings, safe breakoffs, and successful withdrawals prove
        that recovery policy engaged. Repetition does not turn them into room
        failure. Deaths and independently verified hazards remain retained.
        """
        raw = self.storage.get_runtime("farm_tactic_quarantine_v1", {})
        quarantines = dict(raw) if isinstance(raw, dict) else {}
        released: list[dict[str, Any]] = []
        for key, record in list(quarantines.items()):
            if not isinstance(record, dict):
                continue
            try:
                prior_threshold = float(record.get("flee_threshold"))
            except (TypeError, ValueError):
                prior_threshold = None
            reasons = [
                str(reason).strip().casefold()
                for reason in record.get("reasons", [])
                if str(reason).strip()
            ]
            deltas = (
                record.get("deltas")
                if isinstance(record.get("deltas"), dict)
                else {}
            )
            recovery_only = bool(reasons) and all(
                any(marker in reason for marker in FARM_RECOVERY_REASON_MARKERS)
                for reason in reasons
            )
            fatal_failure = any(
                int(deltas.get(name, 0) or 0) > 0
                for name in (
                    "deaths",
                    "deaths_in_safe_spot",
                    "deaths_in_proven_safe_spot",
                )
            )
            if not recovery_only or fatal_failure:
                continue
            released.append(
                {
                    **record,
                    "released_at": timestamp(),
                    "release_reason": (
                        "repeated successful farm recovery is work-cycle telemetry, "
                        "not quarantine evidence"
                    ),
                    "prior_flee_threshold": prior_threshold,
                    "current_flee_threshold": FARM_FLEE_THRESHOLD,
                }
            )
            quarantines.pop(key, None)
        if released:
            self.storage.set_runtime("farm_tactic_quarantine_v1", quarantines)
            self._clear_released_farm_retreat_incidents(released)
        affected_goal_ids = {
            str(item.get("goal_id") or "")
            for item in released
            if item.get("goal_id")
        }

        def is_legacy_recovery_lesson(lesson: dict[str, Any]) -> bool:
            if not is_obsolete_farm_recovery_failure(lesson.get("summary")):
                return False
            return bool(
                (
                    lesson.get("scope") == "tactic"
                    and lesson.get("classification") == "ineffective_tactic"
                )
                or (
                    lesson.get("scope") == "goal"
                    and lesson.get("classification") == "insufficient_combat_power"
                    and "repeated critical-health interrupts"
                    in str(lesson.get("summary") or "").casefold()
                )
            )

        repaired_lessons = [
            self.storage.update_goal_lesson(
                lesson["id"],
                "resolved",
                resolution_goal_id=lesson.get("goal_id"),
                evidence={
                    "repair": (
                        "ordinary threshold/rest/withdraw/resume cycles cannot "
                        "invalidate a productive farm tactic or strategic goal"
                    ),
                    "at": timestamp(),
                },
            )
            for lesson in self.storage.goal_lessons(
                statuses=["deferred", "unlocked"], limit=200
            )
            if is_legacy_recovery_lesson(lesson)
        ]
        affected_goal_ids.update(
            str(lesson.get("goal_id") or "")
            for lesson in repaired_lessons
            if lesson.get("goal_id")
        )
        if not released and not repaired_lessons:
            return []
        for goal_id in affected_goal_ids:
            self._clear_research_recipe_exhaustion(goal_id)
            self.storage.set_runtime(
                f"background_farm_failure_handled_v1:{goal_id}", False
            )
            run = self.storage.campaign_run(goal_id)
            blocker = run.get("external_blocker") if isinstance(run, dict) else None
            if (
                isinstance(blocker, dict)
                and blocker.get("kind") == "no_usable_farm_recipe"
            ):
                self.storage.clear_campaign_external_blocker(str(run["id"]))
        suppression = self.storage.get_runtime("safety_suppression_v1")
        if isinstance(suppression, dict) and "quarantined_farm_tactic" in suppression.get(
            "blocker_kinds", []
        ):
            self.storage.set_runtime("safety_suppression_v1", None)
            self._clear_planner_feedback()
        self.storage.emit_event(
            "background_farm.quarantine_released",
            "Released quarantines created from ordinary farm recovery cycles",
            severity="notice",
            interesting=False,
            data={
                "rooms": [item.get("room") for item in released],
                "prior_thresholds": [
                    item.get("prior_flee_threshold") for item in released
                ],
                "current_threshold": FARM_FLEE_THRESHOLD,
                "lesson_ids": [item.get("id") for item in repaired_lessons],
                "research_retry_reopened": bool(affected_goal_ids),
            },
        )
        return released

    def _repair_overbroad_safe_spot_quarantines(self) -> list[dict[str, Any]]:
        """Release room bans created from local square or supply evidence.

        A failed safe-spot coordinate is durable input to the keeper's square
        selector, not evidence that every other square in the room is unsafe.
        Likewise, using the last carried healing supply describes preparation,
        not an intrinsic property of the room/prey tactic. Older controllers
        promoted either condition to a whole-room quarantine.
        """

        local_markers = (
            "repeated safe-spot failures left too little healing margin",
            "healing supplies were depleted",
        )
        raw = self.storage.get_runtime("farm_tactic_quarantine_v1", {})
        if not isinstance(raw, dict):
            return []
        quarantines = dict(raw)
        released: list[dict[str, Any]] = []
        for key, record in list(quarantines.items()):
            if not isinstance(record, dict):
                continue
            reasons = [
                str(reason).strip().casefold()
                for reason in record.get("reasons", [])
                if str(reason).strip()
            ]
            deltas = record.get("deltas")
            deltas = deltas if isinstance(deltas, dict) else {}
            consequential = any(
                int(deltas.get(name, 0) or 0) > 0
                for name in (
                    "deaths",
                    "withdrawals",
                    "deaths_in_safe_spot",
                    "deaths_in_proven_safe_spot",
                )
            )
            local_only = bool(reasons) and all(
                any(marker in reason for marker in local_markers)
                for reason in reasons
            )
            if not local_only or consequential:
                continue
            released.append(
                {
                    **record,
                    "released_at": timestamp(),
                    "release_reason": (
                        "safe-spot failures are coordinate-scoped and healing "
                        "supplies are preparation state, not whole-room evidence"
                    ),
                }
            )
            quarantines.pop(key, None)
        if not released:
            return []

        self.storage.set_runtime("farm_tactic_quarantine_v1", quarantines)
        self._clear_released_farm_retreat_incidents(released)
        affected_goal_ids = {
            str(item.get("goal_id") or "") for item in released if item.get("goal_id")
        }

        def matches_release(lesson: dict[str, Any]) -> bool:
            summary = str(lesson.get("summary") or "").casefold()
            if not any(marker in summary for marker in local_markers):
                return False
            failed = deep_get(lesson, "failed_state.failed_tactic", {})
            failed = failed if isinstance(failed, dict) else {}
            arguments = failed.get("arguments")
            arguments = arguments if isinstance(arguments, dict) else {}
            room = arguments.get("assigned_room")
            target = " ".join(str(arguments.get("hunt") or "").casefold().split())
            use_safe_spots = arguments.get("use_safe_spots")
            for item in released:
                item_room = item.get("assigned_room", item.get("room"))
                item_target = " ".join(
                    str(item.get("target") or "").casefold().split()
                )
                item_safe_spots = item.get("use_safe_spots")
                if str(room) != str(item_room):
                    continue
                if target and item_target and target != item_target:
                    continue
                if (
                    isinstance(use_safe_spots, bool)
                    and isinstance(item_safe_spots, bool)
                    and use_safe_spots != item_safe_spots
                ):
                    continue
                return True
            return False

        repaired_lessons = [
            self.storage.update_goal_lesson(
                lesson["id"],
                "resolved",
                evidence={
                    "repair": (
                        "the failed coordinates remain excluded by keeper safe-spot "
                        "evidence; the surrounding room/prey tactic is available"
                    ),
                    "at": timestamp(),
                },
            )
            for lesson in self.storage.goal_lessons(
                statuses=["deferred", "unlocked"], limit=200
            )
            if lesson.get("scope") == "tactic" and matches_release(lesson)
        ]
        for goal_id in affected_goal_ids:
            self._clear_research_recipe_exhaustion(goal_id)
            run = self.storage.campaign_run(goal_id)
            blocker = run.get("external_blocker") if isinstance(run, dict) else None
            if (
                isinstance(blocker, dict)
                and blocker.get("kind") == "no_usable_farm_recipe"
            ):
                self.storage.clear_campaign_external_blocker(str(run["id"]))
        suppression = self.storage.get_runtime("safety_suppression_v1")
        if isinstance(suppression, dict) and "quarantined_farm_tactic" in suppression.get(
            "blocker_kinds", []
        ):
            self.storage.set_runtime("safety_suppression_v1", None)
            self._clear_planner_feedback()
        self.storage.emit_event(
            "background_farm.quarantine_released",
            "Released room quarantines created from coordinate-local safe-spot failures",
            severity="notice",
            interesting=False,
            data={
                "rooms": [item.get("room") for item in released],
                "targets": [item.get("target") for item in released],
                "lesson_ids": [item.get("id") for item in repaired_lessons],
                "research_retry_reopened": bool(affected_goal_ids),
            },
        )
        return released

    def _repair_recovered_farm_route_evidence(
        self, observation: dict[str, Any]
    ) -> list[dict[str, Any]]:
        """Release route failures disproved by live presence at the assignment."""
        current_room = self._observation_room(observation)
        if current_room is None:
            return []
        stagnations = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
        stagnations = dict(stagnations) if isinstance(stagnations, dict) else {}
        repaired: list[dict[str, Any]] = []
        for goal in self.storage.goals(["paused"]):
            intent = self._goal_farm_intent(goal)
            assigned_room = intent.get("assigned_room")
            target = str(intent.get("hunt") or "").strip().casefold()
            if assigned_room is None or not target:
                continue
            stagnation_key = f"{goal['id']}|{assigned_room}|{target}"
            stagnation = stagnations.get(stagnation_key)
            live_arrival = str(current_room) == str(assigned_room)
            recorded_arrival = (
                isinstance(stagnation, dict)
                and str(stagnation.get("room")) == str(assigned_room)
                and stagnation.get("stalled_in_transit") is False
            )
            if not live_arrival and not recorded_arrival:
                continue
            lessons = [
                lesson
                for lesson in self.storage.goal_lessons(
                    statuses=["deferred", "unlocked"], goal_id=goal["id"], limit=50
                )
                if lesson.get("classification") == "route_unavailable"
                and str(
                    deep_get(
                        lesson,
                        "failed_state.failed_tactic.arguments.assigned_room",
                    )
                )
                == str(assigned_room)
            ]
            if not isinstance(stagnation, dict) and not lessons:
                continue
            stagnations.pop(stagnation_key, None)
            resolved_lessons = [
                self.storage.update_goal_lesson(
                    lesson["id"],
                    "resolved",
                    resolution_goal_id=goal["id"],
                    evidence={
                        "repair": (
                            "live ordinary-client observation is already in the assigned room"
                            if live_arrival
                            else "the controller's own failure record says the assigned room had already been reached"
                        ),
                        "room": current_room,
                        "recorded_room": (
                            stagnation.get("room")
                            if isinstance(stagnation, dict)
                            else None
                        ),
                        "at": timestamp(),
                    },
                )
                for lesson in lessons
            ]
            resumed = self.storage.manage_goal(
                {
                    "request_id": f"controller-route-recovered-{goal['id']}-{uuid7()}",
                    "goal_id": goal["id"],
                    "expected_version": goal.get("version"),
                    "action": "resume",
                    "reason": (
                        f"Controller verified the character reached assigned_room={assigned_room}; "
                        "the retained keeper route failure was historical, not terminal"
                    ),
                }
            ).get("goal")
            self.storage.set_runtime(
                f"background_farm_route_failure_handled_v1:{goal['id']}", True
            )
            repair = {
                "goal_id": goal["id"],
                "assigned_room": assigned_room,
                "target": target,
                "lesson_ids": [item["id"] for item in resolved_lessons],
                "resumed_status": resumed.get("status") if isinstance(resumed, dict) else None,
            }
            repaired.append(repair)
            self.storage.emit_event(
                "background_farm.route_recovered",
                "Released a retained route failure after live arrival was verified",
                severity="notice",
                interesting=True,
                goal_id=goal["id"],
                data=repair,
            )
        if repaired:
            self.storage.set_runtime("farm_tactic_stagnation_v1", stagnations)
        return repaired

    @staticmethod
    def _transient_movement_failure_text(value: Any) -> str | None:
        """Classify protocol/position loss that can never prove a route invalid."""

        reason = str(value or "").strip()
        if any(
            marker in reason.casefold()
            for marker in TRANSIENT_MOVEMENT_FAILURE_MARKERS
        ):
            return reason[:500]
        return None

    @classmethod
    def _transient_movement_failure_reason(
        cls, tool: str, result: Any
    ) -> str | None:
        """Return a retryable foreground client/protocol failure."""

        if tool not in MOVEMENT_TOOLS or not isinstance(result, dict):
            return None
        if not any(
            result.get(field) is False
            for field in ("arrived", "left", "ok", "success")
        ):
            return None
        reason = str(result.get("reason") or "").strip()
        transient = cls._transient_movement_failure_text(reason)
        if transient is None:
            return None
        if "own position unknown" in reason.casefold():
            return transient
        return transient if tool in FOREGROUND_ROOM_TRANSITION_TOOLS else None

    @staticmethod
    def _transient_cast_failure_reason(tool: str, result: Any) -> str | None:
        """Return a cast outcome that is not durable evidence against a tactic."""

        if tool != "cast" or not isinstance(result, dict):
            return None
        reading = str(result.get("what_the_mana_says") or "").strip()
        folded = reading.casefold()
        mana_spent = result.get("mana_spent")
        no_cast = (
            isinstance(mana_spent, (int, float))
            and not isinstance(mana_spent, bool)
            and mana_spent == 0
        )
        failed_roll = "failed its roll" in folded or "half cost" in folded
        if no_cast or failed_roll:
            if reading:
                return reading[:500]
            return (
                "zero mana was spent; the requested cast did not happen"
                if no_cast
                else "the spell spent only its failure cost and failed its roll"
            )

        # Creation spells have an explicitly requested before/after inventory
        # observation.  Full mana expenditure with neither an item delta nor an
        # authoritative refusal is still inconclusive: it can mean a missed
        # inventory update or hidden server hold-state disagreement.  It cannot
        # prove that the spell is ineffective, and it especially cannot prove
        # that the character lacks combat power.  Preserve the plan step and let
        # a later live refresh/retry or an explicit refusal supply real evidence.
        spell = " ".join(str(result.get("spell") or "").casefold().split())
        created = result.get("created")
        messages = result.get("messages")
        full_cost_unverified_creation = (
            spell in {"create food", "create weapon"}
            and result.get("cast") is not False
            and isinstance(mana_spent, (int, float))
            and not isinstance(mana_spent, bool)
            and mana_spent > 0
            and isinstance(created, list)
            and not created
            and (not isinstance(messages, list) or not messages)
        )
        if full_cost_unverified_creation:
            return (
                f"full-cost {spell} cast had no authoritative created-item delta "
                "or refusal; refresh live inventory and equipment before retrying"
            )[:500]
        return None

    @staticmethod
    def _look_room_matches_destination(refreshed: Any, destination: Any) -> bool:
        if not isinstance(refreshed, dict) or destination is None:
            return False
        room = refreshed.get("room")
        room = room if isinstance(room, dict) else deep_get(refreshed, "look.room", {})
        if not isinstance(room, dict):
            return False
        return any(
            value is not None and str(value).casefold() == str(destination).casefold()
            for value in (room.get("num"), room.get("name"))
        )

    @staticmethod
    def _successful_room_transition_receipt(
        tool: str, result: Any
    ) -> dict[str, Any] | None:
        if tool not in FOREGROUND_ROOM_TRANSITION_TOOLS or not isinstance(
            result, dict
        ):
            return None
        succeeded = (
            (tool == "travel" and result.get("arrived") is True)
            or (tool in {"go_through", "leave_raza"} and result.get("left") is True)
        )
        if not succeeded:
            return None
        room = deep_get(result, "now.room")
        if not isinstance(room, dict):
            room = result.get("room")
        if not isinstance(room, dict) and tool == "travel":
            room = result.get("destination")
        if not isinstance(room, dict):
            return None
        room_id = room.get("num", room.get("id"))
        room_name = room.get("name")
        if room_id is None and room_name is None:
            return None
        return dict(room)

    @classmethod
    def _reconcile_successful_room_transition(
        cls,
        tool: str,
        result: Any,
        observation: dict[str, Any],
    ) -> dict[str, Any]:
        """Prefer an affirmative movement receipt over a briefly stale look.

        A successful foreground transition returns its arrival room directly.
        The first separate ``look`` after a long multi-hop travel can still
        expose the source room from the client's cache.  Mixing that stale room
        with the fresh inventory/status response makes stored-plan validation
        reject legitimate room-local follow-up steps such as ``bank``.  Preserve
        the full fresh observation, but replace only its room with the movement
        receipt's authoritative destination.
        """

        room = cls._successful_room_transition_receipt(tool, result)
        if room is None:
            return observation
        reconciled = dict(observation)
        look = observation.get("look")
        look = dict(look) if isinstance(look, dict) else {}
        look["room"] = dict(room)
        reconciled["look"] = look
        return reconciled

    def _remember_successful_room_transition(
        self,
        tool: str,
        result: Any,
        *,
        goal_id: str | None,
    ) -> None:
        """Retain one short-lived receipt for the next independent observation."""

        room = self._successful_room_transition_receipt(tool, result)
        if room is None:
            return
        self.storage.set_runtime(
            RECENT_ROOM_TRANSITION_RUNTIME_KEY,
            {
                "tool": tool,
                "goal_id": goal_id,
                "room": room,
                "recorded_at": timestamp(),
                # The stale client cache normally clears within one controller
                # cadence, but the intervening model turn can take up to two
                # minutes. A bounded time/count window avoids overriding a
                # later genuine manual or out-of-band room transition.
                "expires_unix": time.time() + 180,
                "stale_observations_reconciled": 0,
            },
        )

    def _reconcile_recent_room_transition(
        self, observation: dict[str, Any]
    ) -> dict[str, Any]:
        """Carry an authoritative arrival receipt across the next stale look."""

        receipt = self.storage.get_runtime(RECENT_ROOM_TRANSITION_RUNTIME_KEY)
        if not isinstance(receipt, dict):
            return observation
        expires_unix = receipt.get("expires_unix")
        if not isinstance(expires_unix, (int, float)) or expires_unix < time.time():
            self.storage.set_runtime(RECENT_ROOM_TRANSITION_RUNTIME_KEY, None)
            return observation
        room = receipt.get("room")
        if not isinstance(room, dict):
            self.storage.set_runtime(RECENT_ROOM_TRANSITION_RUNTIME_KEY, None)
            return observation
        receipt_room = room.get("num", room.get("id", room.get("name")))
        observed_room = self._observation_room(observation)
        if str(observed_room) == str(receipt_room):
            # A second independent observation corroborated the receipt.
            self.storage.set_runtime(RECENT_ROOM_TRANSITION_RUNTIME_KEY, None)
            return observation
        stale_count = int(receipt.get("stale_observations_reconciled", 0) or 0)
        if stale_count >= 3:
            self.storage.set_runtime(RECENT_ROOM_TRANSITION_RUNTIME_KEY, None)
            return observation
        receipt = {
            **receipt,
            "stale_observations_reconciled": stale_count + 1,
        }
        self.storage.set_runtime(RECENT_ROOM_TRANSITION_RUNTIME_KEY, receipt)
        reconciled = dict(observation)
        look = observation.get("look")
        look = dict(look) if isinstance(look, dict) else {}
        look["room"] = dict(room)
        reconciled["look"] = look
        self.storage.emit_event(
            "action.movement_observation_reconciled",
            "Reconciled a stale next-turn room from the recent successful movement receipt",
            severity="info",
            interesting=False,
            goal_id=receipt.get("goal_id"),
            data={
                "tool": receipt.get("tool"),
                "stale_observed_room": observed_room,
                "receipt_room": receipt_room,
                "scope": "next_controller_observation",
            },
        )
        return reconciled

    def _remember_successful_inventory_creation(
        self,
        tool: str,
        result: Any,
        before: dict[str, Any],
        *,
        goal_id: str | None,
    ) -> None:
        """Retain broker-observed creation deltas across one stale inventory read."""

        created = result.get("created") if isinstance(result, dict) else None
        if tool != "cast" or not isinstance(created, list) or not created:
            return
        before_items = deep_get(before, "inventory.items", [])
        expected: list[dict[str, Any]] = []
        for item in created:
            if not isinstance(item, dict):
                continue
            name = " ".join(str(item.get("name") or "").split())
            amount = item.get("amount", 1)
            if not name or not isinstance(amount, (int, float)) or amount <= 0:
                continue
            expected.append(
                {
                    "name": name,
                    "minimum_count": CriteriaEvaluator.inventory_count(
                        before_items, name
                    )
                    + int(amount),
                }
            )
        if not expected:
            return
        self.storage.set_runtime(
            RECENT_INVENTORY_CREATION_RUNTIME_KEY,
            {
                "tool": tool,
                "goal_id": goal_id,
                "expected": expected,
                "recorded_at": timestamp(),
                "expires_unix": time.time() + 180,
                "stale_observations_reconciled": 0,
            },
        )

    def _reconcile_recent_inventory_creation(
        self, observation: dict[str, Any], *, emit_event: bool = True
    ) -> dict[str, Any]:
        """Apply a recent positive creation delta when inventory briefly regresses."""

        receipt = self.storage.get_runtime(RECENT_INVENTORY_CREATION_RUNTIME_KEY)
        if not isinstance(receipt, dict):
            return observation
        expires_unix = receipt.get("expires_unix")
        expected = receipt.get("expected")
        if (
            not isinstance(expires_unix, (int, float))
            or expires_unix < time.time()
            or not isinstance(expected, list)
        ):
            self.storage.set_runtime(RECENT_INVENTORY_CREATION_RUNTIME_KEY, None)
            return observation
        raw_items = deep_get(observation, "inventory.items", [])
        items = [dict(item) for item in raw_items if isinstance(item, dict)] if isinstance(raw_items, list) else []
        missing = [
            item
            for item in expected
            if isinstance(item, dict)
            and CriteriaEvaluator.inventory_count(items, item.get("name"))
            < int(item.get("minimum_count", 0) or 0)
        ]
        if not missing:
            self.storage.set_runtime(RECENT_INVENTORY_CREATION_RUNTIME_KEY, None)
            return observation
        stale_count = int(receipt.get("stale_observations_reconciled", 0) or 0)
        if stale_count >= 3:
            self.storage.set_runtime(RECENT_INVENTORY_CREATION_RUNTIME_KEY, None)
            return observation
        for expected_item in missing:
            name = " ".join(str(expected_item.get("name") or "").split())
            minimum = int(expected_item.get("minimum_count", 0) or 0)
            current = CriteriaEvaluator.inventory_count(items, name)
            deficit = max(0, minimum - current)
            target = next(
                (
                    item
                    for item in items
                    if " ".join(str(item.get("name") or "").split()).casefold()
                    == name.casefold()
                ),
                None,
            )
            if target is None:
                items.append(
                    {
                        "name": name,
                        "amount": deficit,
                        "source": "successful_creation_receipt",
                    }
                )
            else:
                current_amount = target.get("amount", 1)
                current_amount = (
                    int(current_amount)
                    if isinstance(current_amount, (int, float))
                    else 1
                )
                target["amount"] = current_amount + deficit
        receipt = {
            **receipt,
            "stale_observations_reconciled": stale_count + 1,
        }
        self.storage.set_runtime(RECENT_INVENTORY_CREATION_RUNTIME_KEY, receipt)
        reconciled = dict(observation)
        inventory = observation.get("inventory")
        inventory = dict(inventory) if isinstance(inventory, dict) else {}
        inventory["items"] = items
        reconciled["inventory"] = inventory
        if emit_event:
            self.storage.emit_event(
                "action.inventory_observation_reconciled",
                "Reconciled stale inventory from a successful creation delta",
                severity="info",
                interesting=False,
                goal_id=receipt.get("goal_id"),
                data={
                    "tool": receipt.get("tool"),
                    "expected": redact(expected),
                    "stale_observations_reconciled": stale_count + 1,
                },
            )
        return reconciled

    def _repair_position_unknown_lessons(self) -> list[dict[str, Any]]:
        """Resolve route lessons that only captured transient client/protocol loss."""

        def is_transient(value: Any) -> bool:
            return self._transient_movement_failure_text(value) is not None

        repaired: list[dict[str, Any]] = []
        affected_goal_ids: set[str] = set()
        for lesson in self.storage.goal_lessons(
            statuses=["deferred", "unlocked"], limit=200
        ):
            if lesson.get("scope") != "tactic" or not is_transient(
                lesson.get("summary")
            ):
                continue
            goal_id = str(lesson.get("goal_id") or "")
            if goal_id:
                affected_goal_ids.add(goal_id)
            repaired.append(
                self.storage.update_goal_lesson(
                    lesson["id"],
                    "resolved",
                    evidence={
                        "repair": (
                            "controller now refreshes live position and retries transient "
                            "movement reply loss once without treating it as route evidence"
                        ),
                        "at": timestamp(),
                    },
                )
            )
        blocked_actions = self.storage.get_runtime("blocked_actions", [])
        if isinstance(blocked_actions, list):
            retained = [
                item
                for item in blocked_actions
                if not (
                    isinstance(item, dict)
                    and is_transient(item.get("reason"))
                )
            ]
            if len(retained) != len(blocked_actions):
                self.storage.set_runtime("blocked_actions", retained)

        raw_stagnations = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
        stagnations = dict(raw_stagnations) if isinstance(raw_stagnations, dict) else {}
        removed_stagnations: list[dict[str, Any]] = []
        for key, item in list(stagnations.items()):
            if not isinstance(item, dict) or not is_transient(item.get("last_error")):
                continue
            removed_stagnations.append(item)
            stagnations.pop(key, None)
            goal_id = str(item.get("goal_id") or str(key).split("|", 1)[0])
            if goal_id:
                affected_goal_ids.add(goal_id)
        if removed_stagnations:
            self.storage.set_runtime("farm_tactic_stagnation_v1", stagnations)

        exhaustion = self.storage.get_runtime(
            RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, {}
        )
        exhaustion = dict(exhaustion) if isinstance(exhaustion, dict) else {}
        exhaustion_changed = False
        for goal_id in affected_goal_ids:
            self.storage.set_runtime(
                f"background_farm_route_failure_handled_v1:{goal_id}", False
            )
            if exhaustion.pop(goal_id, None) is not None:
                exhaustion_changed = True
            run = self.storage.campaign_run(goal_id)
            blocker = run.get("external_blocker") if isinstance(run, dict) else None
            if (
                isinstance(blocker, dict)
                and blocker.get("kind") == "no_usable_farm_recipe"
            ):
                self.storage.clear_campaign_external_blocker(str(run["id"]))
        if exhaustion_changed:
            self.storage.set_runtime(RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, exhaustion)
        if repaired or removed_stagnations:
            self.storage.emit_event(
                "movement.transient_evidence_repaired",
                "Removed durable route evidence created from transient client reply loss",
                severity="notice",
                interesting=True,
                data={
                    "lesson_ids": [item.get("id") for item in repaired],
                    "stagnation_count": len(removed_stagnations),
                    "goal_ids": sorted(affected_goal_ids),
                },
            )
        return repaired

    def _repair_transient_cast_evidence(self) -> list[dict[str, Any]]:
        """Remove legacy tactic blocks written for non-durable cast outcomes."""

        transient_signatures: set[tuple[str, str]] = set()
        source_event_ids: list[str] = []
        for event in self.storage.latest_events(
            limit=200,
            kinds=["action.no_progress", "action.transient_failure"],
        ):
            data = event.get("data")
            data = data if isinstance(data, dict) else {}
            result = data.get("result")
            if self._transient_cast_failure_reason(
                str(data.get("tool") or ""), result
            ) is None:
                continue
            arguments = data.get("arguments")
            arguments = arguments if isinstance(arguments, dict) else {}
            transient_signatures.add(
                (
                    str(event.get("goal_id") or ""),
                    canonical_json({"tool": "cast", "arguments": arguments}),
                )
            )
            if event.get("id"):
                source_event_ids.append(str(event["id"]))
        removed_blocks: list[dict[str, Any]] = []
        blocked_actions = self.storage.get_runtime("blocked_actions", [])
        if isinstance(blocked_actions, list):
            retained: list[Any] = []
            for item in blocked_actions:
                key = (
                    str(item.get("goal_id") or ""),
                    str(item.get("signature") or ""),
                ) if isinstance(item, dict) else None
                legacy_unverified_creation = (
                    isinstance(item, dict)
                    and item.get("tool") == "cast"
                    and "produced no verified carried item"
                    in str(item.get("reason") or "").casefold()
                    and not is_inventory_capacity_refusal(item.get("reason"))
                )
                if key in transient_signatures or legacy_unverified_creation:
                    removed_blocks.append(item)
                else:
                    retained.append(item)
            if removed_blocks:
                self.storage.set_runtime("blocked_actions", retained)

        repaired_lessons: list[dict[str, Any]] = []
        for lesson in self.storage.goal_lessons(
            statuses=["deferred", "unlocked"], limit=200
        ):
            failed_tactic = deep_get(lesson, "failed_state.failed_tactic", {})
            failed_tactic = (
                failed_tactic if isinstance(failed_tactic, dict) else {}
            )
            tool = str(failed_tactic.get("tool") or "")
            arguments = failed_tactic.get("arguments")
            arguments = arguments if isinstance(arguments, dict) else {}
            key = (
                str(lesson.get("goal_id") or ""),
                canonical_json({"tool": tool, "arguments": arguments}),
            )
            legacy_misclassified_cast = (
                lesson.get("scope") == "tactic"
                and tool == "cast"
                and " ".join(
                    str(arguments.get("spell") or "").casefold().split()
                )
                in {"create food", "create weapon"}
                and lesson.get("classification") == "insufficient_combat_power"
            )
            if lesson.get("scope") != "tactic" or (
                key not in transient_signatures and not legacy_misclassified_cast
            ):
                continue
            repaired_lessons.append(
                self.storage.update_goal_lesson(
                    lesson["id"],
                    "resolved",
                    evidence={
                        "repair": (
                            "zero-cost, half-cost, and unverified creation-cast outcomes "
                            "are not durable evidence against the tactic; cast failures "
                            "also cannot be classified as insufficient combat power"
                        ),
                        "source_event_ids": source_event_ids,
                        "at": timestamp(),
                    },
                )
            )
        if removed_blocks or repaired_lessons:
            self.storage.emit_event(
                "cast.transient_evidence_repaired",
                "Removed durable tactic evidence created from non-durable cast outcomes",
                severity="notice",
                interesting=False,
                data={
                    "blocked_action_count": len(removed_blocks),
                    "lesson_ids": [item.get("id") for item in repaired_lessons],
                    "source_event_ids": source_event_ids,
                },
            )
        return repaired_lessons

    def _repair_unscoped_evidence_lookup_lessons(self) -> list[dict[str, Any]]:
        """Resolve lookup blocks created before evidence caches were phase-scoped."""

        marker = "repeated identical evidence lookup returned no new evidence"
        evidence_tools = {
            "map",
            "merchants",
            "prey",
            "hunting_grounds",
            KNOWLEDGE_TOOL_NAME,
        }

        def is_legacy_lookup(value: Any, *, tool: Any = None) -> bool:
            return marker in str(value or "").casefold() and (
                tool is None or str(tool or "") in evidence_tools
            )

        repaired: list[dict[str, Any]] = []
        for lesson in self.storage.goal_lessons(
            statuses=["deferred", "unlocked"], limit=200
        ):
            failed_tactic = deep_get(lesson, "failed_state.failed_tactic", {})
            failed_tactic = (
                failed_tactic if isinstance(failed_tactic, dict) else {}
            )
            if lesson.get("scope") != "tactic" or not is_legacy_lookup(
                lesson.get("summary"), tool=failed_tactic.get("tool")
            ):
                continue
            repaired.append(
                self.storage.update_goal_lesson(
                    lesson["id"],
                    "resolved",
                    evidence={
                        "repair": (
                            "static evidence replay detection is now scoped to one "
                            "bounded campaign phase"
                        ),
                        "at": timestamp(),
                    },
                )
            )
        blocked_actions = self.storage.get_runtime("blocked_actions", [])
        if isinstance(blocked_actions, list):
            retained = [
                item
                for item in blocked_actions
                if not (
                    isinstance(item, dict)
                    and is_legacy_lookup(
                        item.get("reason"), tool=item.get("tool")
                    )
                )
            ]
            if len(retained) != len(blocked_actions):
                self.storage.set_runtime("blocked_actions", retained)
        return repaired

    def _repair_invalid_farm_contract_lessons(self) -> list[dict[str, Any]]:
        """Release legacy goal gates caused only by repairable note syntax.

        Static game-reference failures remain durable. A malformed executable
        recipe is different: the corrected goal can be validated immediately,
        so waiting for a corpus or character-state change would make the lesson
        impossible to unlock.
        """
        repaired: list[dict[str, Any]] = []
        for lesson in self.storage.goal_lessons(statuses=["deferred"], limit=200):
            if lesson.get("scope") != "goal":
                continue
            original = self.storage.goal(str(lesson.get("goal_id") or ""))
            if not original:
                continue
            validation = self.knowledge.validate_goal(original)
            codes = {
                str(error.get("code") or "")
                for error in validation.get("errors", [])
                if isinstance(error, dict)
            }
            if codes != {"INVALID_FARM_OPERATOR_NOTES"}:
                continue
            repaired.append(
                self.storage.update_goal_lesson(
                    lesson["id"],
                    "resolved",
                    evidence={
                        "repair": "corrected farm key=value notes are validated before submission",
                        "at": timestamp(),
                    },
                )
            )
        return repaired

    def _repair_transit_goal_lessons(self) -> list[dict[str, Any]]:
        """Retire legacy whole-goal gates caused before a farm was reached."""
        repaired: list[dict[str, Any]] = []
        for lesson in self.storage.goal_lessons(
            statuses=["deferred", "unlocked"], limit=200
        ):
            summary = str(lesson.get("summary") or "").casefold()
            if not (
                lesson.get("scope") == "goal"
                and lesson.get("classification") == "insufficient_combat_power"
                and "hazardous transit" in summary
                and "before arrival" in summary
            ):
                continue
            repaired.append(
                self.storage.update_goal_lesson(
                    lesson["id"],
                    "resolved",
                    evidence={
                        "repair": (
                            "pre-arrival withdrawal is route/tactic evidence, not proof that the HP outcome is impossible"
                        ),
                        "at": timestamp(),
                    },
                )
            )
        return repaired

    def _repair_controller_goal_blocks(self) -> list[dict[str, Any]]:
        """Requeue legacy controller blocks under the preserve-goals policy.

        Tactical evidence remains available through lessons, quarantines, and
        campaign memory.  The blocked lifecycle state itself is obsolete: it
        discards the campaign's ability to choose a different tactic and leaves
        no active owner to pursue supporting work.
        """

        repaired: list[dict[str, Any]] = []
        for goal in self.storage.goals(["blocked"]):
            result = self.storage.manage_goal(
                {
                    "request_id": f"controller-preserve-blocked-goal-{goal['id']}-{uuid7()}",
                    "goal_id": goal["id"],
                    "expected_version": goal.get("version"),
                    "action": "resume",
                    "reason": (
                        "controller-owned goal blocks are obsolete; preserve the "
                        "strategic outcome and replan around retained tactic evidence"
                    ),
                }
            )["goal"]
            repaired.append(self.storage.goal(goal["id"]) or result)
        if repaired:
            self.storage.emit_event(
                "goal.blocks.repaired",
                "Requeued legacy controller-blocked strategic goals",
                severity="notice",
                interesting=True,
                data={
                    "goal_ids": [goal["id"] for goal in repaired],
                    "count": len(repaired),
                },
            )
        return repaired

    def _record_bank_receipt(
        self,
        goal: dict[str, Any],
        before: dict[str, Any],
        after: dict[str, Any],
    ) -> dict[str, Any] | None:
        before_currency = self._carried_currency(before)
        after_currency = self._carried_currency(after)
        if not (
            after_currency < before_currency
            or after_currency <= BROKER_WALKING_MONEY
        ):
            return None
        value = {
            "goal_id": goal["id"],
            "carried_currency_after": after_currency,
            "carried_currency_before": before_currency,
            "room": self._observation_room(after),
            "recorded_at": timestamp(),
        }
        self.storage.set_runtime("bank_before_hazard_receipt_v1", value)
        return value

    def _banking_resolved(
        self, goal: dict[str, Any], observation: dict[str, Any]
    ) -> bool:
        receipt = self.storage.get_runtime("bank_before_hazard_receipt_v1")
        if not isinstance(receipt, dict):
            return False
        # A successful deposit is verified character state, not intent owned by
        # one goal. Successor phases may reuse the walking float until carried
        # currency rises above the recorded post-bank amount.
        allowed = receipt.get("carried_currency_after")
        return isinstance(allowed, (int, float)) and self._carried_currency(
            observation
        ) <= int(allowed)

    def _complete_already_satisfied_bank_deposit(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        plan: dict[str, Any],
        arguments: dict[str, Any],
    ) -> dict[str, Any]:
        """Turn a zero-currency deposit into verified preparation success."""
        result = {
            "action": "deposit",
            "amount": 0,
            "skipped": True,
            "already_satisfied": True,
            "reason": "no carried shillings; bank-before-hazard is already satisfied",
        }
        self._record_bank_receipt(goal, observation, observation)
        self._record_plan_action(
            goal,
            step_id=str(plan.get("plan_step_id") or "controller-owned-step"),
            tool="bank",
            arguments=arguments,
            result=result,
        )
        self.storage.emit_event(
            "action.succeeded",
            "Bank deposit preparation was already satisfied",
            interesting=False,
            goal_id=goal["id"],
            data={
                "tool": "bank",
                "arguments": redact(arguments),
                "result": result,
                "synthetic": True,
            },
        )
        self._clear_planner_feedback()
        self._clear_safety_suppression(goal["id"])
        self.last_observation = observation
        completion = self.criteria.evaluate(goal, observation)
        done = self._complete_goal_if_safe(goal, observation, completion)
        if done is None:
            checkpoint = self._goal_completion_checkpoint(goal)
            self.storage.set_goal_completion(
                goal["id"],
                checkpoint["completion"] if checkpoint is not None else completion,
            )
        return {
            "action": "bank",
            "result": result,
            "already_satisfied": True,
            "completion": completion,
        }

    def _repair_bank_receipt(self) -> dict[str, Any] | None:
        """Adopt a verified pre-deployment bank deposit at the walking float."""
        goal = self.storage.active_goal()
        if goal is None:
            paused = self.storage.goals(["paused"])
            goal = (
                max(paused, key=lambda item: str(item.get("updated_at") or ""))
                if paused
                else None
            )
        observation = self.last_observation or {}
        room_name = str(deep_get(observation, "look.room.name", "")).casefold()
        carried = self._carried_currency(observation)
        if not goal or "bank" not in room_name or carried > BROKER_WALKING_MONEY:
            return None
        bank_events = self.storage.goal_events(
            goal["id"], kinds=["action.succeeded"], limit=50
        )
        has_goal_bank_event = any(
            isinstance(event.get("data"), dict)
            and event["data"].get("tool") == "bank"
            for event in bank_events
        )
        existing = self.storage.get_runtime("bank_before_hazard_receipt_v1")
        if has_goal_bank_event:
            value = {
                "goal_id": goal["id"],
                "carried_currency_after": carried,
                "carried_currency_before": None,
                "room": self._observation_room(observation),
                "recorded_at": timestamp(),
                "reconciled_after_restart": True,
            }
        elif self._banking_resolved(goal, observation) and isinstance(existing, dict):
            value = {**existing, "adopted_by_goal_id": goal["id"]}
        else:
            return None
        self.storage.set_runtime("bank_before_hazard_receipt_v1", value)
        suppression = self.storage.get_runtime("safety_suppression_v1")
        matching_false_stall = (
            isinstance(suppression, dict)
            and suppression.get("goal_id") == goal["id"]
            and suppression.get("blocker_kinds") == ["bank_before_hazard"]
        )
        if matching_false_stall:
            self.storage.set_runtime("safety_suppression_v1", None)
            self._clear_planner_feedback()
            if goal.get("status") == "paused":
                pauses = self.storage.goal_events(
                    goal["id"], kinds=["goal.paused"], limit=1
                )
                reason = str(
                    pauses[-1].get("data", {}).get("reason") if pauses else ""
                ).casefold()
                if "controller paused the goal after the same safety blocker" in reason:
                    resumed = self.storage.manage_goal(
                        {
                            "request_id": f"controller-bank-repair-{uuid7()}",
                            "goal_id": goal["id"],
                            "action": "resume",
                            "reason": (
                                "resumed after verified bank receipt proved the 400-shilling "
                                "walking float was already bank-safe"
                            ),
                        }
                    )["goal"]
                    value["resumed_goal_id"] = resumed.get("id")
        if self._banking_resolved(goal, observation):
            for lesson in self.storage.goal_lessons(
                statuses=["deferred"], limit=200
            ):
                summary = str(lesson.get("summary") or "").casefold()
                if (
                    lesson.get("scope") == "tactic"
                    and "deterministic safety suppression" in summary
                    and "bank" in summary
                ):
                    self.storage.update_goal_lesson(lesson["id"], "resolved")
            feedback = self.storage.get_runtime("planner_feedback")
            message = (
                str(feedback.get("message") or "").casefold()
                if isinstance(feedback, dict)
                else ""
            )
            blocked_tool = deep_get(feedback or {}, "blocked_action.tool")
            if blocked_tool == "autopilot" and "bank" in message:
                self._clear_planner_feedback()
        return value

    def _goal_advisories(
        self, goal: dict[str, Any], observation: dict[str, Any]
    ) -> list[dict[str, Any]]:
        values = self.policy.advisories(observation)
        if self._banking_resolved(goal, observation):
            values = [
                item
                for item in values
                if item.get("kind") not in {"bank_before_hazard", "consider_banking"}
            ]
        return values

    def startup(self, *, connect_game: bool = True) -> None:
        self.offline_diagnostics = not connect_game
        self.state = "reconciling"
        self.storage.upgrade_legacy_pvp_goal_criteria()
        self.storage.upgrade_legacy_raza_exit_goal_criteria()
        if connect_game:
            health = self.broker.ensure_started()
            self.broker.capabilities(refresh=True)
            self.dependencies["broker"] = "healthy"
            if self.config.game.autojoin:
                self.broker.ensure_joined()
            self._set_fallback()
            if self.config.controller.conversation_enabled:
                self._start_conversation_listener()
            self.last_observation = self._reconcile_recent_inventory_creation(
                self._reconcile_recent_room_transition(self.broker.observe())
            )
            self._record_character_progress(self.last_observation)
            self._repair_bank_receipt()
        else:
            health = {"sessions": []}
            self.dependencies["broker"] = "skipped"
            self.dependencies["social"] = "disabled"
        self.dependencies["journal"] = "healthy" if self.config.notifications.obsidian_enabled else "disabled"
        self.state = "running"
        if connect_game:
            self._account_planned_phase_downtime()
        self._repair_false_faction_troop_quarantines()
        previous_corpus = self.storage.get_runtime("knowledge_corpus_version")
        if previous_corpus != self.knowledge.corpus_version:
            self.storage.emit_event(
                "knowledge.corpus.updated",
                "Meridian 59 knowledge corpus is ready",
                severity="notice",
                interesting=True,
                data={
                    "previous_version": previous_corpus,
                    "corpus_version": self.knowledge.corpus_version,
                    "entity_count": self.knowledge.metadata().get("entity_count", 0),
                    "harness_revision": self.knowledge.metadata().get("harness_revision"),
                },
            )
            self.storage.set_runtime("knowledge_corpus_version", self.knowledge.corpus_version)
        if connect_game and self.last_observation:
            self.learning.repair_preparation_goal_lessons()
            self._repair_transit_goal_lessons()
            self._repair_open_goal_contracts()
            self._reconcile_inactive_goal_completions(self.last_observation)
            self.learning.backfill(self.last_observation)
            self._repair_controller_goal_blocks()
            self.learning.repair_regressive_capability_unlocks(
                self.last_observation
            )
            self._repair_gentle_overlevel_farm_quarantines(
                self.last_observation
            )
            self._repair_capability_unlocked_farm_quarantines(self.last_observation)
            self._repair_policy_obsolete_farm_quarantines()
            self._repair_overbroad_safe_spot_quarantines()
            self._repair_disproved_farm_route_stagnations()
            self._repair_recovered_farm_route_evidence(self.last_observation)
            self._repair_transient_farm_stagnations()
            self._repair_ambiguous_breakoff_stagnations()
            self._repair_gentle_cap_stagnations(self.last_observation)
            self._repair_position_unknown_lessons()
            self._repair_transient_cast_evidence()
            self._repair_unscoped_evidence_lookup_lessons()
            self._repair_invalid_farm_contract_lessons()
            self.learning.refresh_unlocks(self.last_observation)
            self.learning.release_unlocked_farm_quarantines()
            self._reconcile_blocked_farm_exhaustion(self.last_observation)
        if self.config.notifications.obsidian_enabled:
            try:
                self.notifications.refresh_executive_summary()
            except (OSError, ValueError) as exc:
                self.dependencies["journal"] = "unhealthy"
                self.warnings.append(f"executive summary refresh failed: {exc}")
        self.storage.emit_event(
            "controller.started",
            "Meridian 59 bot controller started",
            interesting=True,
            data={
                "version": self.VERSION,
                "broker_sessions": health.get("sessions", []),
                "knowledge_corpus_version": self.knowledge.corpus_version,
            },
        )
        self._start_notification_worker()
        if connect_game and self.config.controller.conversation_enabled:
            self._start_social_worker()

    def _repair_open_goal_contracts(self) -> dict[str, list[str]]:
        """Cancel invalid open goals and collapse equivalent live retries."""
        invalid: list[str] = []
        for goal in self.storage.goals(["active", "queued", "paused", "blocked"]):
            validation = self.knowledge.validate_goal(goal)
            if validation.get("valid") is not False:
                continue
            invalid.append(goal["id"])
            messages = [
                str(item.get("message") or item.get("code"))
                for item in validation.get("errors", [])[:3]
                if isinstance(item, dict)
            ]
            self.storage.manage_goal(
                {
                    "request_id": f"controller-invalid-contract-{goal['id']}-{uuid7()}",
                    "goal_id": goal["id"],
                    "action": "cancel",
                    "reason": (
                        "controller retired an invalid stored goal contract: "
                        + "; ".join(messages)
                    )[:1000],
                }
            )

        groups: dict[str, list[dict[str, Any]]] = {}
        for goal in self.storage.goals(["active", "queued", "paused", "blocked"]):
            groups.setdefault(self.learning.goal_family(goal), []).append(goal)
        duplicates: list[str] = []
        status_rank = {"active": 0, "queued": 1, "paused": 2, "blocked": 3}
        for family, goals in groups.items():
            if len(goals) < 2:
                continue
            best_rank = min(status_rank.get(str(item.get("status")), 9) for item in goals)
            keepers = [
                item
                for item in goals
                if status_rank.get(str(item.get("status")), 9) == best_rank
            ]
            keeper = max(
                keepers,
                key=lambda item: str(item.get("updated_at") or item.get("created_at") or ""),
            )
            retired: list[str] = []
            for goal in goals:
                if goal["id"] == keeper["id"]:
                    continue
                self.storage.manage_goal(
                    {
                        "request_id": f"controller-duplicate-goal-{goal['id']}-{uuid7()}",
                        "goal_id": goal["id"],
                        "action": "cancel",
                        "reason": f"superseded by canonical equivalent goal {keeper['id']}",
                    }
                )
                duplicates.append(goal["id"])
                retired.append(goal["id"])
            if retired:
                self.storage.emit_event(
                    "goal.duplicates_consolidated",
                    "Collapsed equivalent open goals into one canonical goal",
                    severity="notice",
                    interesting=True,
                    goal_id=keeper["id"],
                    data={
                        "goal_family": family,
                        "canonical_goal_id": keeper["id"],
                        "retired_goal_ids": retired,
                    },
                )
        return {"invalid": invalid, "duplicates": duplicates}

    def _reconcile_inactive_goal_completions(
        self, observation: dict[str, Any]
    ) -> list[dict[str, Any]]:
        """Latch inactive outcomes and retire only at their planned safe ending.

        This pass remains model-free. Paused work can achieve its public
        outcome while another goal changes the world, but it becomes terminal
        only if the same observation also verifies its previously selected
        source-safe plan ending. Otherwise the outcome stays latched for a
        later resume and safe return.
        """
        completed: list[dict[str, Any]] = []
        for goal in self.storage.goals(["paused", "blocked"]):
            completion = self.criteria.evaluate(goal, observation)
            if not completion["all_met"]:
                continue
            prior_status = str(goal.get("status") or "inactive")
            done = self._complete_goal_if_safe(goal, observation, completion)
            if done is None:
                self.storage.set_goal_completion(goal["id"], completion)
                continue
            self.storage.emit_event(
                "goal.inactive_completion_reconciled",
                f"Inactive goal completed at its planned safe ending: {goal['title']}",
                interesting=False,
                goal_id=goal["id"],
                data={"reconciled_from": prior_status, "model_used": False},
            )
            completed.append(done)
        return completed

    @staticmethod
    def _keeper_is_inert(status: Any) -> bool:
        """Return whether a live keeper has yielded all game mutations.

        Newer harness builds keep the telemetry/watchdog loop alive after
        ``autopilot stop`` and expose that yielded state as ``inert``.  The
        legacy shape omitted the field and changed ``running`` to false.
        Accept both without mistaking an observing keeper for a competing
        controller.
        """
        if not isinstance(status, dict):
            return False
        inert = status.get("inert")
        return inert is True or (
            isinstance(inert, dict) and inert.get("inert") is True
        )

    @classmethod
    def _keeper_is_driving(cls, status: Any) -> bool:
        return (
            isinstance(status, dict)
            and status.get("running") is True
            and not cls._keeper_is_inert(status)
        )

    def _higher_priority_queued_goal(
        self, active_goal: dict[str, Any]
    ) -> dict[str, Any] | None:
        """Return the first queued goal that may cooperatively preempt this one."""

        try:
            active_priority = int(active_goal.get("priority", 50))
        except (TypeError, ValueError):
            active_priority = 50
        return next(
            (
                item
                for item in self.storage.goals(["queued"])
                if int(item.get("priority", 50)) > active_priority
            ),
            None,
        )

    def _preempt_at_safe_campaign_boundary(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        phase: dict[str, Any] | None,
        *,
        keeper_released: bool | None = None,
    ) -> dict[str, Any] | None:
        """Yield completed bounded work to strictly higher-priority queued work."""

        if not isinstance(phase, dict) or phase.get("status") != "succeeded":
            return None
        candidate = self._higher_priority_queued_goal(goal)
        if candidate is None:
            return None
        room_id = deep_get(
            observation,
            "look.room.num",
            deep_get(observation, "look.room_id"),
        )
        safe_room = self._verified_safe_staging(room_id)
        if safe_room is None:
            # A succeeded phase proves that its ending was safe when committed,
            # but a surviving keeper may have moved since then. Do not hand
            # control to another goal from a now-unsafe observation.
            return None

        release_result: Any = None
        if keeper_released is not True:
            try:
                status = self.broker.call_tool(
                    "autopilot",
                    {"agent": self.config.game.agent, "action": "status"},
                    timeout=10,
                    mutation=False,
                )
                release_result = status
                if self._keeper_is_driving(status):
                    release_result = self.broker.call_tool(
                        "autopilot",
                        {
                            "agent": self.config.game.agent,
                            "action": "stop",
                            # The phase boundary is already source-verified
                            # safe. Leave the inert telemetry/watchdog loop
                            # alive while scheduler ownership changes.
                            "hard": False,
                            "why": (
                                "yielding at a verified safe campaign boundary to "
                                "strictly higher-priority queued work"
                            ),
                        },
                        timeout=20,
                        mutation=True,
                    )
                keeper_released = isinstance(release_result, dict) and not (
                    self._keeper_is_driving(release_result)
                )
            except (BrokerError, ValueError):
                keeper_released = False
        if keeper_released is not True:
            return {
                "goal_preemption_pending": True,
                "queued_goal": {
                    key: candidate.get(key)
                    for key in ("id", "title", "priority")
                },
                "phase_id": phase.get("id"),
                "safe_room": redact(safe_room),
                "keeper": redact(release_result),
            }

        result = self.storage.preempt_for_higher_priority(
            str(goal["id"]),
            reason=(
                f"completed campaign phase {phase.get('id')} at verified safe "
                f"room {safe_room['room_id']}"
            ),
            phase_id=str(phase.get("id") or "") or None,
        )
        if result is None:
            # The queue may have changed between the read-only candidate check
            # and the atomic scheduler transaction. That is a normal race.
            return None
        return {
            "goal_preempted": True,
            "priority_preemption": result,
            "safe_room": redact(safe_room),
            "keeper": redact(release_result),
        }

    def _set_fallback(self) -> None:
        mode = self.config.controller.fallback_mode
        # A controller restart must not clobber a healthy, goal-owned farming
        # keeper that survived the process boundary. Re-adopt it when its target,
        # room, and safe-spot strategy still match the durable active goal; the
        # regular monitor will then resume evidence and safety supervision.
        if mode != "off":
            try:
                running = self.broker.call_tool(
                    "autopilot",
                    {"agent": self.config.game.agent, "action": "status"},
                    timeout=20,
                )
            except (BrokerError, ValueError):
                running = None
            active = self.storage.active_goal()
            if (
                self._keeper_is_driving(running)
                and running.get("mode") == "farm"
                and active
                and self._background_farm_mismatch(active, running) is None
            ):
                self.storage.emit_event(
                    "background_farm.recovered",
                    "Re-adopted the active goal's farming keeper after controller restart",
                    goal_id=active["id"],
                    data={
                        "activity": running.get("activity"),
                        "assigned_room": self._farm_assigned_room(running),
                        "hunt": self._farm_target(running),
                    },
                )
                return
        action = "stop" if mode == "off" else "start"
        args: dict[str, Any] = {"agent": self.config.game.agent, "action": action}
        if action == "stop":
            args.update(
                {
                    # Off mode relinquishes gameplay mutations but is not a
                    # process teardown. Preserve the upstream telemetry loop.
                    "hard": False,
                    "why": "controller fallback mode is off",
                }
            )
        if action == "start":
            args.update(
                {
                    "mode": mode,
                    "rest_below": self.config.policy.rest_health_fraction,
                    "flee_below": max(0.75, self.config.policy.rest_health_fraction),
                    "break_out_via_logoff": False,
                }
            )
            if mode in {"survive", "idle"}:
                # The upstream keeper intentionally preserves policy fields
                # across mode changes. A retained farm hunt/assignment can make
                # survive mode continue routing toward a hazardous room, so a
                # non-farming fallback must clear both explicitly.
                args.update({"hunt": "", "assigned_room": None, "bank_above": 0})
        self.broker.call_tool("autopilot", args, timeout=20, mutation=True)

    def _start_conversation_listener(self) -> None:
        self.broker.call_tool(
            "converse",
            {
                "agent": self.config.game.agent,
                "action": "start",
                # Every real speaker, including NPCs, should reach the configured persona
                # instead of being consumed by generic deterministic acknowledgements.
                "ack": False,
                "small_talk": False,
                "face_speaker": False,
                "escalate": True,
                "answer_peers": False,
                "replies_per_min": 20,
                "speaker_cooldown_ms": 2500,
                "per_speaker_per_min": 12,
            },
            timeout=15,
            mutation=True,
        )

    def _start_social_worker(self) -> None:
        if self.offline_diagnostics or not self.config.controller.conversation_enabled:
            self.dependencies["social"] = "disabled"
            return
        if self._social_thread and self._social_thread.is_alive():
            return
        self._social_thread = threading.Thread(
            target=self._social_loop,
            name="meridian-social-loop",
            daemon=True,
        )
        self._social_thread.start()

    def _start_notification_worker(self) -> None:
        enabled = self.config.notifications.windows_enabled or (
            self.config.notifications.obsidian_enabled
            and self.config.notifications.obsidian_vault_path is not None
        )
        if not enabled:
            self.dependencies["notifier"] = "disabled"
            return
        if self._notification_thread and self._notification_thread.is_alive():
            return
        self.dependencies["notifier"] = "starting"
        self._notification_thread = threading.Thread(
            target=self._notification_loop,
            name="meridian-notification-loop",
            daemon=True,
        )
        self._notification_thread.start()

    def _notification_loop(self) -> None:
        while not self.stop_event.is_set():
            try:
                delivered = self.notifications.dispatch_pending()
                state = "healthy" if not delivered["failed"] else "degraded"
                self.dependencies["notifier"] = state
                if self.config.notifications.obsidian_enabled:
                    self.dependencies["journal"] = state
                    if (
                        state == "healthy"
                        and time.monotonic() - self._last_executive_refresh_at >= 60.0
                    ):
                        # Keep the project note useful even when no milestone is
                        # emitted. This is an in-place current-state projection,
                        # not another journal entry.
                        self.notifications.refresh_executive_summary()
                        self._last_executive_refresh_at = time.monotonic()
            except Exception as exc:
                LOG.exception("notification dispatch failed")
                self.dependencies["notifier"] = "degraded"
                if self.config.notifications.obsidian_enabled:
                    self.dependencies["journal"] = "degraded"
                self.warnings = [*self.warnings[-9:], f"notification: {str(exc)[:300]}"]
            self.stop_event.wait(15.0)

    def _planner_tools(
        self, phase: dict[str, Any] | None = None
    ) -> list[dict[str, Any]]:
        tools = [tool for tool in self.broker.planner_tools() if tool.get("name") not in PVP_TOOL_NAMES]
        tools.extend(self.pvp.planner_tools())
        tools.append(self.knowledge.planner_tool())
        tools = self.campaign.tools_for_phase(phase, tools) if phase is not None else tools
        observation = self.last_observation
        if isinstance(observation, dict):
            # These tools have no planner-owned arguments, so an active tactic
            # lesson proves that every identical call in the same equipment
            # state would be redundant. Omitting the tool also prevents the planner
            # from replacing a still-actionable recovery plan with the exact
            # equip_best/wear_best call the lesson system will suppress.
            deferred_no_argument_tools = {
                name
                for name in ("equip_best", "wear_best")
                if self.learning.check_action(name, {}, observation) is not None
            }
            if deferred_no_argument_tools:
                tools = [
                    tool
                    for tool in tools
                    if str(tool.get("name") or "") not in deferred_no_argument_tools
                ]
        return tools

    @staticmethod
    def _observation_only_act_step(step: dict[str, Any]) -> bool:
        """Identify plans that misuse the mutating ``act`` tool as a read."""

        if step.get("tool") != "act":
            return False
        outcome = " ".join(str(step.get("outcome") or "").split()).casefold()
        return bool(
            re.match(
                r"^(?:look|observe|inspect|survey|check|confirm|verify|refresh)\b",
                outcome,
            )
        )

    @staticmethod
    def _autopilot_launch_step(step: dict[str, Any]) -> bool:
        """Distinguish a keeper launch from a later stop/cleanup step."""

        if step.get("tool") != "autopilot":
            return False
        outcome = " ".join(str(step.get("outcome") or "").split()).casefold()
        return bool(
            re.search(r"\b(?:start|launch|begin|run|activate)\b", outcome)
            or re.match(r"^farm\b", outcome)
        )

    @staticmethod
    def _commerce_step_error(step: dict[str, Any]) -> str | None:
        """Return a corrective error when a plan assigns commerce to the wrong tool."""

        tool = str(step.get("tool") or "")
        outcome = " ".join(str(step.get("outcome") or "").split()).casefold()
        verification = " ".join(
            str(step.get("verification") or "").split()
        ).casefold()
        if tool == "shop" and (
            re.match(r"^(?:sell|liquidate|dispose)\b", outcome)
            or re.search(r"\b(?:item|loot|property) (?:was |is )?sold\b", verification)
            or re.search(r"\bmerchant (?:bought|buys)\b", verification)
            or re.search(r"\bshillings? (?:increased|received|gained)\b", verification)
        ):
            return (
                "assigns a player-inventory sale to shop. Purpose: shop only reads "
                "merchant stock or buys from it, so this step cannot produce its stated "
                "outcome; use sell for a targeted quote/sale or guarded sell_all for "
                "ordinary excess loot"
            )
        if tool in {"sell", "sell_all"} and re.match(
            r"^(?:buy|purchase)\b", outcome
        ):
            return (
                f"assigns a merchant-stock purchase to {tool}. Purpose: sell tools only "
                "transfer player inventory to a merchant; use shop for a purchase"
            )
        if tool == "merchants" and (
            re.search(r"\b(?:then|and)\s+(?:travel|go|walk|move)\b", outcome)
            or re.search(
                r"\b(?:status|current)\s*\.?(?:room|location)\b.*\b(?:matches|equals|is)\b",
                verification,
            )
        ):
            return (
                "assigns room movement to merchants. Purpose: merchants is a read-only "
                "buyer/catalogue discovery tool and cannot move the character; keep the "
                "lookup as one step and add a following travel step bound to its numeric "
                "room result"
            )
        follow_on = re.search(
            r"\b(?:then|and\s+then|otherwise|if\s+not)\s*[,;:]?\s+(?:the\s+)?(?P<verb>buy|purchase|sell|liquidate|equip|wield|wear|cast|travel|go|walk|move)\b",
            outcome,
        )
        if follow_on is not None:
            verb = follow_on.group("verb")
            compatible_tools = {
                "buy": {"shop"},
                "purchase": {"shop"},
                "sell": {"sell", "sell_all"},
                "liquidate": {"sell", "sell_all"},
                "equip": {"equip_best", "wear_best"},
                "wield": {"equip_best"},
                "wear": {"equip_best", "wear_best"},
                "cast": {"cast"},
                "travel": MOVEMENT_TOOLS,
                "go": MOVEMENT_TOOLS,
                "walk": MOVEMENT_TOOLS,
                "move": MOVEMENT_TOOLS,
            }[verb]
            if tool not in compatible_tools:
                expected = "/".join(sorted(compatible_tools))
                return (
                    f"combines a follow-on {verb} action with {tool}. Purpose: one "
                    "execution-plan step can invoke only its declared broker tool; "
                    f"add a separate {expected} step for the {verb} outcome"
                )
        return None

    @staticmethod
    def _phase_keep_candidates(phase: dict[str, Any] | None) -> list[str]:
        context = (
            phase.get("context")
            if isinstance(phase, dict) and isinstance(phase.get("context"), dict)
            else {}
        )
        candidates = context.get("keep_candidates")
        if not isinstance(candidates, list):
            return []
        return sorted(
            {
                str(candidate).strip().casefold()
                for candidate in candidates
                if str(candidate).strip()
            }
        )

    @classmethod
    def _protected_phase_sale_step_error(
        cls,
        phase: dict[str, Any] | None,
        step: dict[str, Any],
    ) -> str | None:
        """Reject plans that explicitly target phase-retained property for sale."""

        if str((phase or {}).get("kind") or "") != "liquidate_inventory":
            return None
        if str(step.get("tool") or "") != "sell":
            return None
        outcome = " ".join(str(step.get("outcome") or "").split()).casefold()
        sale_cues = tuple(re.finditer(r"\b(?:sell|quote|offer|liquidate|dispose)\b", outcome))
        if not sale_cues:
            return None
        for candidate in cls._phase_keep_candidates(phase):
            for match in re.finditer(re.escape(candidate), outcome):
                prior_cues = [cue for cue in sale_cues if cue.start() < match.start()]
                if not prior_cues:
                    continue
                phrase = outcome[prior_cues[-1].start() : match.end()]
                if re.search(r"\b(?:keep|keeping|retain|retaining|preserve|except|excluding)\b", phrase):
                    continue
                return (
                    f"targets retained keep_candidate {candidate!r} for sale. Purpose: "
                    "liquidation may dispose of ordinary excess loot but must preserve the "
                    "phase's explicitly retained equipment and valuables"
                )
        return None

    @classmethod
    def _map_step_error(
        cls,
        phase: dict[str, Any] | None,
        step: dict[str, Any],
    ) -> str | None:
        """Reject plans that mistake room-name search for creature grounding."""

        if str(step.get("tool") or "") != "map":
            return None
        text = " ".join(
            (
                str(step.get("outcome") or ""),
                str(step.get("verification") or ""),
            )
        ).casefold()
        if not re.search(r"\b(?:find|search|locate|discover|identify|list)\b", text):
            return None
        context = (
            phase.get("context")
            if isinstance(phase, dict) and isinstance(phase.get("context"), dict)
            else {}
        )
        target = str(context.get("target") or "").strip().casefold()
        target_pattern = (
            re.compile(rf"\b{re.escape(target)}s?\b") if target else None
        )
        creature_discovery = bool(
            re.search(
                r"\b(?:creature|monster|prey|spawn|hunting ground|farm target)\b",
                text,
            )
            or (target_pattern is not None and target_pattern.search(text))
        )
        if not creature_discovery:
            return None
        return (
            "uses map to discover creature occupancy. Purpose: map.search only "
            "matches room names and cannot prove that prey spawns there; call "
            "hunting_grounds for the exact creature, then use map with the returned "
            "numeric room id to verify a route"
        )

    @staticmethod
    def _is_plan_purchase_step(step: dict[str, Any]) -> bool:
        if step.get("tool") != "shop":
            return False
        outcome = " ".join(str(step.get("outcome") or "").split()).casefold()
        verification = " ".join(
            str(step.get("verification") or "").split()
        ).casefold()
        return bool(
            re.search(r"\b(?:buy|purchase|acquire|obtain)\b", outcome)
            or re.search(r"\b(?:bought|purchased|acquired)\b", verification)
        )

    @staticmethod
    def _is_plan_funding_step(step: dict[str, Any]) -> bool:
        tool = step.get("tool")
        if tool in {"sell", "sell_all"}:
            return True
        return tool == "bank" and bool(
            re.search(
                r"\bwithdraw\b",
                str(step.get("outcome") or ""),
                re.IGNORECASE,
            )
        )

    @staticmethod
    def _remaining_plan_steps(
        steps: list[dict[str, Any]],
        completed_through_step_id: str | None,
    ) -> list[dict[str, Any]]:
        """Return only work after the latest verified ordered plan step."""

        if not completed_through_step_id:
            return steps
        completed_index = next(
            (
                index
                for index, step in enumerate(steps)
                if str(step.get("id") or "") == completed_through_step_id
            ),
            None,
        )
        return steps[completed_index + 1 :] if completed_index is not None else steps

    @classmethod
    def _plan_funding_error(
        cls,
        steps: list[dict[str, Any]],
        observation: dict[str, Any],
    ) -> str | None:
        inventory = observation.get("inventory")
        if not isinstance(inventory, dict) or not isinstance(
            inventory.get("items"), list
        ):
            # Startup validates persisted structure before the first broker
            # observation.  Missing inventory is unknown, not proof of zero
            # funds; enforce this live prerequisite after observation arrives.
            return None
        carry = inventory.get("carry")
        if isinstance(carry, dict) and carry.get("known") is False:
            return None
        if cls._carried_currency(observation) > 0:
            return None
        funding_seen = False
        for step in steps:
            if cls._is_plan_funding_step(step):
                funding_seen = True
            if cls._is_plan_purchase_step(step) and not funding_seen:
                return (
                    f"execution_plan step {step.get('id')} purchases from a shop with "
                    "zero carried shillings and no preceding funding step. Purpose: an "
                    "unfunded purchase cannot change inventory; precede it with sell, "
                    "guarded sell_all, or a verified bank withdrawal, or replace the "
                    "purchase with a verified castable self-production capability"
                )
        return None

    def _recent_shop_catalogues(self) -> list[dict[str, Any]]:
        """Return the newest non-empty live catalogue for each exact seller."""

        catalogues: list[dict[str, Any]] = []
        seen_sellers: set[str] = set()
        for event in reversed(
            self.storage.latest_events(limit=200, kinds=["action.succeeded"])
        ):
            data = event.get("data")
            result = data.get("result") if isinstance(data, dict) else None
            raw_catalogue = result.get("items") if isinstance(result, dict) else None
            seller = result.get("seller") if isinstance(result, dict) else None
            seller_key = str(seller)
            if (
                not isinstance(data, dict)
                or data.get("tool") != "shop"
                or seller is None
                or seller_key in seen_sellers
                or not isinstance(raw_catalogue, list)
            ):
                continue
            items: dict[str, dict[str, Any]] = {}
            for item in raw_catalogue:
                if not isinstance(item, dict):
                    continue
                name = " ".join(str(item.get("name") or "").split()).casefold()
                cost = item.get("cost")
                if (
                    name
                    and isinstance(cost, (int, float))
                    and not isinstance(cost, bool)
                    and cost >= 0
                    and name not in items
                ):
                    items[name] = {"id": item.get("id"), "cost": int(cost)}
            if not items:
                continue
            seen_sellers.add(seller_key)
            aliases = {seller_key.casefold()}
            seller_identity = (
                self.knowledge.merchant_identity(object_id=seller)
                if hasattr(self.knowledge, "merchant_identity")
                else None
            )
            if isinstance(seller_identity, dict):
                aliases.update(
                    " ".join(str(value or "").split()).casefold()
                    for value in (
                        seller_identity.get("merchant_class"),
                        deep_get(seller_identity, "instance.name"),
                    )
                    if str(value or "").strip()
                )
            catalogues.append(
                {
                    "seller": seller,
                    "aliases": aliases,
                    "items": items,
                    "observed_at": str(event.get("occurred_at") or ""),
                }
            )
        return catalogues

    def _shop_plan_affordability_error(
        self,
        steps: list[dict[str, Any]],
        observation: dict[str, Any],
    ) -> str | None:
        """Compare quantified planned baskets with recent live catalogue prices."""

        inventory = observation.get("inventory")
        if not isinstance(inventory, dict) or not isinstance(
            inventory.get("items"), list
        ):
            return None
        catalogues = self._recent_shop_catalogues()
        if not catalogues:
            return None

        number_words = {
            "one": 1,
            "two": 2,
            "three": 3,
            "four": 4,
            "five": 5,
            "six": 6,
            "seven": 7,
            "eight": 8,
            "nine": 9,
            "ten": 10,
        }

        def item_pattern(name: str) -> str:
            if name.endswith("y"):
                return re.escape(name[:-1]) + r"(?:y|ies)"
            return re.escape(name) + r"(?:s|es)?"

        available = self._carried_currency(observation)
        funds_unknown = False
        for step in steps:
            if self._is_plan_funding_step(step):
                funds_unknown = True
                continue
            if not self._is_plan_purchase_step(step):
                continue
            outcome = " ".join(str(step.get("outcome") or "").split()).casefold()
            matching_catalogue = next(
                (
                    catalogue
                    for catalogue in catalogues
                    if any(
                        re.search(
                            rf"(?<![a-z0-9]){re.escape(alias)}(?![a-z0-9])",
                            outcome,
                        )
                        for alias in catalogue["aliases"]
                        if alias
                    )
                ),
                None,
            )
            if matching_catalogue is None:
                # Do not apply one merchant's prices to an unrelated seller.
                # A quote-first plan remains legal until its exact seller has
                # produced a catalogue; persisted plans are revalidated after
                # that read-only action.
                continue
            catalog = matching_catalogue["items"]
            catalog_event_at = matching_catalogue["observed_at"]
            catalog_seller = matching_catalogue["seller"]
            purchase_match = re.search(
                r"\b(?:buy|purchase|obtain|acquire)\s+(.+?)"
                r"(?=\s+from\b|\s+using\b|[.;]|$)",
                outcome,
            )
            requested_items: list[str] = []
            if purchase_match is not None:
                for component in re.split(
                    r"\s*,\s*|\s+and\s+", purchase_match.group(1)
                ):
                    quantified = re.match(
                        rf"^(?:\d+|{'|'.join(number_words)})\s+(?:x\s+)?(.+?)$",
                        component.strip(),
                    )
                    if quantified is not None:
                        requested_items.append(quantified.group(1).strip())
            missing_items = [
                requested
                for requested in requested_items
                if not any(
                    re.fullmatch(item_pattern(name), requested) is not None
                    for name in catalog
                )
            ]
            if missing_items:
                return (
                    f"execution_plan step {step.get('id')!r} claims the already-observed "
                    f"seller offers {', '.join(repr(item) for item in missing_items)}, but "
                    "those quantified items are absent from that seller's live shop "
                    f"catalogue observed at {catalog_event_at}. Purpose: a shop action "
                    "cannot buy stock the named merchant does not carry; use actual "
                    "catalogue items or choose a different grounded acquisition route"
                )
            basket: list[dict[str, Any]] = []
            for name, item in catalog.items():
                match = re.search(
                    rf"\b(\d+|{'|'.join(number_words)})\s+(?:x\s+)?{item_pattern(name)}\b",
                    outcome,
                )
                if not match:
                    continue
                raw_quantity = match.group(1)
                quantity = (
                    int(raw_quantity)
                    if raw_quantity.isdigit()
                    else number_words[raw_quantity]
                )
                basket.append(
                    {
                        "item": name,
                        "quantity": quantity,
                        "unit_cost": item["cost"],
                        "subtotal": quantity * item["cost"],
                    }
                )
            if not basket:
                return (
                    f"execution_plan step {step.get('id')!r} names live seller "
                    f"{catalog_seller} but does not quantify an exact basket from its "
                    f"catalogue observed at {catalog_event_at}. Purpose: words such as "
                    "'enough' or 'some' cannot prove stock, nutrition, or affordability; "
                    "after a live quote, name the exact quantity of each catalogue item "
                    "before attempting a purchase"
                )
            if funds_unknown:
                continue
            basket_cost = sum(item["subtotal"] for item in basket)
            if basket_cost > available:
                account = next(
                    (
                        account
                        for account in self._latest_bank_balance_context()
                        if account.get("last_known_balance", 0) > 0
                    ),
                    None,
                )
                funding_route = (
                    f" Durable bank evidence shows {account['last_known_balance']} "
                    f"shillings in {account['account']!r}; add travel to bank room "
                    f"{TOS_BANK_ROOM_ID} and a bank check/withdrawal before this purchase."
                    if account is not None
                    else " Add a verified funding step before this purchase."
                )
                return (
                    f"execution_plan step {step.get('id')!r} has a grounded basket cost "
                    f"of {basket_cost} shillings from the live shop catalogue, but only "
                    f"{available} are carried. Basket: "
                    + ", ".join(
                        f"{item['quantity']} {item['item']} @ {item['unit_cost']}"
                        for item in basket
                    )
                    + f". Catalogue observed at {catalog_event_at}. Purpose: a positive "
                    "cash balance is not proof that the full basket is affordable; "
                    "fund the exact known cost before purchase."
                    + funding_route
                )
            available -= basket_cost
        return None

    def _quantified_shop_action_error(
        self,
        step: dict[str, Any],
        arguments: dict[str, Any],
    ) -> str | None:
        """Bind a quantified purchase step to the exact live catalogue basket."""

        if not self._is_plan_purchase_step(step):
            return None
        catalog_by_name: dict[str, dict[str, Any]] = {}
        for event in reversed(
            self.storage.latest_events(limit=200, kinds=["action.succeeded"])
        ):
            data = event.get("data")
            result = data.get("result") if isinstance(data, dict) else None
            raw_catalog = result.get("items") if isinstance(result, dict) else None
            if data.get("tool") != "shop" or not isinstance(raw_catalog, list):
                continue
            for item in raw_catalog:
                if not isinstance(item, dict) or item.get("id") is None:
                    continue
                name = " ".join(str(item.get("name") or "").split()).casefold()
                if name:
                    catalog_by_name[name] = {
                        "id": str(item["id"]),
                        "seller": result.get("seller"),
                    }
            if catalog_by_name:
                break
        if not catalog_by_name:
            return None

        number_words = {
            "one": 1,
            "two": 2,
            "three": 3,
            "four": 4,
            "five": 5,
            "six": 6,
            "seven": 7,
            "eight": 8,
            "nine": 9,
            "ten": 10,
        }

        def item_pattern(name: str) -> str:
            if name.endswith("y"):
                return re.escape(name[:-1]) + r"(?:y|ies)"
            return re.escape(name) + r"(?:s|es)?"

        outcome = " ".join(str(step.get("outcome") or "").split()).casefold()
        expected: dict[str, int] = {}
        labels: dict[str, str] = {}
        expected_seller: Any = None
        for name, item in catalog_by_name.items():
            match = re.search(
                rf"\b(\d+|{'|'.join(number_words)})\s+(?:x\s+)?{item_pattern(name)}\b",
                outcome,
            )
            if not match:
                continue
            raw_quantity = match.group(1)
            quantity = (
                int(raw_quantity)
                if raw_quantity.isdigit()
                else number_words[raw_quantity]
            )
            item_id = item["id"]
            expected[item_id] = expected.get(item_id, 0) + quantity
            labels[item_id] = name
            expected_seller = expected_seller or item.get("seller")
        if not expected:
            return None

        raw_buy_ids = arguments.get("buy_ids")
        actual: dict[str, int] = {}
        for item_id in raw_buy_ids if isinstance(raw_buy_ids, list) else []:
            key = str(item_id)
            actual[key] = actual.get(key, 0) + 1
        seller_mismatch = (
            expected_seller is not None
            and str(arguments.get("seller")) != str(expected_seller)
        )
        if actual == expected and not seller_mismatch:
            return None

        def describe(basket: dict[str, int]) -> str:
            return ", ".join(
                f"{quantity} {labels.get(item_id, 'item')} (id {item_id})"
                for item_id, quantity in basket.items()
            ) or "no items"

        seller_detail = (
            f" and seller {expected_seller}"
            if expected_seller is not None
            else ""
        )
        return (
            f"execution_plan step {step.get('id')!r} requires exactly "
            f"{describe(expected)}{seller_detail}, but the selected shop arguments "
            f"request {describe(actual)} from seller {arguments.get('seller')!r}. "
            "Purpose: a quantified plan outcome is not satisfied by a smaller or "
            "different basket; send the exact repeated live item ids, or revise the "
            "plan if the required quantity is no longer available"
        )

    @staticmethod
    def _bank_plan_error(
        steps: list[dict[str, Any]],
        observation: dict[str, Any],
        *,
        completed_through_step_id: str | None = None,
    ) -> str | None:
        """Require an explicit bank-room prerequisite before each bank call."""

        remaining_steps = steps
        if completed_through_step_id:
            completed_index = next(
                (
                    index
                    for index, step in enumerate(steps)
                    if str(step.get("id") or "") == completed_through_step_id
                ),
                None,
            )
            if completed_index is not None:
                # Stored plans are ordered.  Revalidation happens after each
                # successful action, so prerequisites in the completed prefix
                # must not be reinterpreted against the character's new room.
                remaining_steps = steps[completed_index + 1 :]

        current_room_id = deep_get(
            observation,
            "look.room.num",
            deep_get(observation, "look.room_id"),
        )
        current_room_name = str(deep_get(observation, "look.room.name", ""))
        if current_room_id is None and not current_room_name.strip():
            # Startup can load and structurally validate a stored plan before
            # the first authoritative broker observation.  Unknown location is
            # not evidence that the character is outside a bank; defer this
            # live prerequisite check until a room has actually been observed.
            return None
        at_bank = (
            str(current_room_id) == str(TOS_BANK_ROOM_ID)
            or "bank" in current_room_name.casefold()
        )
        for step in remaining_steps:
            tool = str(step.get("tool") or "")
            text = " ".join(
                str(step.get(field) or "")
                for field in ("outcome", "verification")
            ).casefold()
            if tool in MOVEMENT_TOOLS:
                at_bank = bool(
                    "bank" in text
                    or re.search(rf"\broom\s+{TOS_BANK_ROOM_ID}\b", text)
                    or re.search(rf"\b{TOS_BANK_ROOM_ID}\b", text)
                )
                continue
            if tool == "bank" and not at_bank:
                return (
                    f"execution_plan step {step.get('id')} calls bank before reaching a "
                    "verified bank room. Purpose: bank cannot move the character; add a "
                    "separate preceding travel step to the selected bank (for Tos, room "
                    f"{TOS_BANK_ROOM_ID})"
                )
        return None

    @staticmethod
    def _live_spell_readiness(
        observation: dict[str, Any], spell_name: str
    ) -> dict[str, Any] | None:
        """Return the live typed spell row for an exact normalized name."""

        wanted = " ".join(str(spell_name).split()).casefold()
        rows = deep_get(observation, "spells.spells", [])
        for row in rows if isinstance(rows, list) else []:
            if (
                isinstance(row, dict)
                and " ".join(str(row.get("name") or "").split()).casefold()
                == wanted
            ):
                return row
        return None

    def _farm_weapon_plan_error(
        self,
        steps: list[dict[str, Any]],
        observation: dict[str, Any],
        *,
        launch_index: int,
    ) -> str | None:
        """Require a causal weapon path before a known-unarmed farm launch."""

        readiness = self.learning.readiness_summary(observation)
        if (
            readiness.get("equipment_state") != "known"
            or readiness.get("wielded_weapons")
        ):
            return None

        prior = steps[:launch_index]

        def step_text(step: dict[str, Any]) -> str:
            return " ".join(
                str(step.get(field) or "")
                for field in ("outcome", "verification")
            ).casefold()

        acquisition_index = -1
        if not readiness.get("carried_weapons"):
            create_weapon = self._live_spell_readiness(
                observation, "create weapon"
            )
            cast_index = next(
                (
                    index
                    for index, step in enumerate(prior)
                    if step.get("tool") == "cast"
                    and "create weapon" in step_text(step)
                ),
                None,
            )
            if create_weapon is not None and create_weapon.get("castable") is True:
                if cast_index is None:
                    return (
                        "the character is known unarmed with no carried weapon, while "
                        "live Create Weapon is castable; add a Create Weapon cast step "
                        "before the farm launch. Create Food, travel, or another "
                        "non-weapon action cannot satisfy this combat prerequisite"
                    )
                acquisition_index = cast_index
            else:
                acquisition_index = next(
                    (
                        index
                        for index, step in enumerate(prior)
                        if step.get("tool") in {"cast", "shop", "act"}
                        and re.search(
                            r"\b(?:weapon|mace|sword|axe|hammer|scimitar)\b",
                            step_text(step),
                        )
                    ),
                    -1,
                )
                if acquisition_index < 0:
                    return (
                        "the character is known unarmed with no carried weapon; the "
                        "farm plan must acquire or create a weapon before launch"
                    )

        equip_index = next(
            (
                index
                for index, step in enumerate(prior)
                if index > acquisition_index
                and (
                    step.get("tool") == "equip_best"
                    or (
                        step.get("tool") == "act"
                        and re.search(
                            r"\b(?:equip|wield|use)\b.{0,80}"
                            r"\b(?:weapon|mace|sword|axe|hammer|scimitar)\b",
                            step_text(step),
                        )
                    )
                )
            ),
            None,
        )
        if equip_index is None:
            return (
                "the character is known unarmed; add a verified equip_best or exact "
                "weapon-use step after weapon acquisition and before the farm launch"
            )
        return None

    @staticmethod
    def _direct_phase_capabilities(
        phase: dict[str, Any] | None,
        observation: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Make directly useful live capabilities conspicuous to the tactical model."""

        if str((phase or {}).get("kind") or "") != "prepare_combat":
            return None
        phase_text = canonical_json(
            {
                "objective": (phase or {}).get("objective"),
                "context": (phase or {}).get("context"),
            }
        ).casefold()
        needs_weapon = bool(
            re.search(r"\b(?:weapon|damage|wield|equip)\b", phase_text)
        )
        needs_food = bool(
            re.search(r"\b(?:food|snack|consumable|healing suppl)\w*\b", phase_text)
        )
        if not needs_weapon and not needs_food:
            # Preserve the longstanding generic prepare_combat behavior when a
            # legacy phase has no descriptive objective/context.
            needs_weapon = True
        spells = deep_get(observation, "spells.spells", [])
        direct: list[dict[str, Any]] = []
        for spell in spells if isinstance(spells, list) else []:
            if not isinstance(spell, dict):
                continue
            name = " ".join(str(spell.get("name") or "").split())
            normalized_name = name.casefold()
            is_weapon = bool(
                needs_weapon
                and spell.get("castable") is True
                and re.search(r"\b(?:create|conjure|summon)\s+weapon\b", name, re.I)
            )
            is_food = normalized_name == "create food" and needs_food
            if not (is_weapon or is_food):
                continue
            capability = {
                key: spell.get(key)
                for key in ("name", "mana", "reagents", "castable", "blocked_by")
                if spell.get(key) is not None
            }
            if is_weapon:
                capability.update(
                    {
                        "npc_transferable": False,
                        "funding_eligible": False,
                        "server_semantics": (
                            "Create Weapon marks its product IA_MADE. Item.CanBeGivenToNPC "
                            "therefore rejects it before merchant preference is evaluated."
                        ),
                    }
                )
            elif is_food:
                blockers = (
                    list(capability.get("blocked_by", []))
                    if isinstance(capability.get("blocked_by"), list)
                    else []
                )
                remaining_blockers: list[str] = []
                inventory_items = deep_get(observation, "inventory.items", [])
                for blocker in blockers:
                    match = re.match(
                        r"\s*needs\s+(\d+)\s+x\s+(.+?),\s*carrying\s+\d+\s*$",
                        str(blocker),
                        re.I,
                    )
                    if (
                        match
                        and CriteriaEvaluator.inventory_count(
                            inventory_items,
                            match.group(2),
                        )
                        >= int(match.group(1))
                    ):
                        continue
                    remaining_blockers.append(str(blocker))
                if blockers and not remaining_blockers:
                    capability["castable"] = True
                    capability.pop("blocked_by", None)
                    capability["availability_reconciled_from_inventory"] = True
                elif remaining_blockers != blockers:
                    capability["blocked_by"] = remaining_blockers
                ability = next(
                    (
                        entry.get("ability")
                        for entry in deep_get(observation, "abilities.spells", [])
                        if isinstance(entry, dict)
                        and str(entry.get("name") or "").strip().casefold()
                        == "create food"
                    ),
                    None,
                )
                try:
                    numeric_ability = int(ability)
                except (TypeError, ValueError):
                    numeric_ability = None
                possible_products = ["apple"]
                if numeric_ability is not None and numeric_ability >= 30:
                    low = numeric_ability // 2
                    possible_products = []
                    for lower, upper, product in (
                        (0, 29, "apple"),
                        (30, 39, "loaf of bread"),
                        (40, 59, "bunch of grapes"),
                        (60, 69, "turkey leg"),
                        (70, 79, "meat pie"),
                        (80, 99, "wheel of cheese or inky cap"),
                    ):
                        if low <= upper and numeric_ability >= lower:
                            possible_products.append(product)
                phase_food = next(
                    (
                        criterion
                        for criterion in (phase or {}).get("success_criteria", [])
                        if isinstance(criterion, dict)
                        and criterion.get("kind") == "inventory_contains"
                        and str(criterion.get("item") or "").strip().casefold()
                        in {"food", "edible food"}
                    ),
                    None,
                )
                inventory_items = deep_get(observation, "inventory.items", [])
                current_food = CriteriaEvaluator.inventory_count(
                    inventory_items, "food"
                )
                required_food = int((phase_food or {}).get("count", 1) or 1)
                missing_food = max(0, required_food - current_food)
                reagent_totals: list[str] = []
                for reagent in spell.get("reagents", []):
                    match = re.fullmatch(
                        r"\s*(\d+)\s*x\s*(.+?)\s*", str(reagent), re.I
                    )
                    if match and missing_food:
                        reagent_totals.append(
                            f"{int(match.group(1)) * missing_food} x {match.group(2)}"
                        )
                capability["server_semantics"] = (
                    "The live spell record is authoritative for Create Food costs. "
                    + (
                        "It has no reagent prerequisite; cast it directly."
                        if spell.get("reagents") == []
                        else "Acquire exactly its listed reagents before casting; do not "
                        "invent, omit, or substitute reagent requirements."
                    )
                )
                capability["production"] = {
                    "category": "food",
                    "possible_products_at_current_ability": possible_products,
                    "quantity_per_cast": 1,
                    "restores": "vigor, not health",
                    **(
                        {"ability": numeric_ability}
                        if numeric_ability is not None
                        else {}
                    ),
                }
                if phase_food is not None:
                    capability["phase_requirement"] = {
                        "criterion_id": phase_food.get("id"),
                        "required_total": required_food,
                        "currently_carried": current_food,
                        "remaining": missing_food,
                        "casts_required": missing_food,
                        "reagents_required_for_remaining_casts": reagent_totals,
                        "verification_category": "food",
                    }
            direct.append(capability)
        if not direct:
            return None
        return {
            "purpose": (
                "These verified capabilities and their live prerequisites directly apply "
                "to requirements named by the current preparation phase. Prefer direct "
                "use when castable and obey the listed server semantics."
            ),
            "preferred_tool": "cast",
            "capabilities": direct,
        }

    @classmethod
    def _direct_capability_plan_error(
        cls,
        phase: dict[str, Any] | None,
        steps: list[dict[str, Any]],
        observation: dict[str, Any],
        assumptions: list[str] | None = None,
    ) -> str | None:
        """Reject commerce invented ahead of a verified zero-input capability."""

        direct = cls._direct_phase_capabilities(phase, observation)
        capabilities = direct.get("capabilities") if isinstance(direct, dict) else []
        capabilities = capabilities if isinstance(capabilities, list) else []
        create_food = next(
            (
                item
                for item in capabilities
                if isinstance(item, dict)
                and str(item.get("name") or "").strip().casefold() == "create food"
            ),
            None,
        )
        if create_food is not None and create_food.get("reagents") == []:
            cast_index = next(
                (
                    index
                    for index, step in enumerate(steps)
                    if step.get("tool") == "cast"
                    and "create food"
                    in " ".join(
                        str(step.get(field) or "")
                        for field in ("outcome", "verification")
                    ).casefold()
                ),
                None,
            )
            if cast_index is None:
                return (
                    "the active phase explicitly requires food and live Create Food is "
                    "castable with an empty reagent list; include a direct cast step "
                    "instead of inventing a commerce prerequisite"
                )
            detours = [
                step
                for step in steps[:cast_index]
                if step.get("tool") in {"sell", "sell_all"}
                or cls._is_plan_purchase_step(step)
            ]
            if detours:
                return (
                    "live Create Food is castable with no reagents, so the proposed "
                    "pre-cast sale/purchase detour cannot be a prerequisite; remove the "
                    "commerce steps and cast Create Food directly"
                )
            assumption_text = " ".join(assumptions or []).casefold()
            if "create food" in assumption_text and re.search(
                r"\b(?:reagent|elderberry|herbs?)\b", assumption_text
            ):
                return (
                    "the plan invents Create Food reagents even though the verified live "
                    "spell record has an empty reagent list; cast it directly"
                )

        create_weapon_indexes = [
            index
            for index, step in enumerate(steps)
            if step.get("tool") == "cast"
            and "create weapon"
            in " ".join(
                str(step.get(field) or "")
                for field in ("outcome", "verification")
            ).casefold()
        ]
        for cast_index in create_weapon_indexes:
            cast_step_id = str(steps[cast_index].get("id") or "").casefold()
            for step in steps[cast_index + 1 :]:
                if step.get("tool") not in {"sell", "sell_all"}:
                    continue
                sale_text = " ".join(
                    str(step.get(field) or "")
                    for field in ("outcome", "verification")
                ).casefold()
                created_item_reference = bool(
                    re.search(
                        r"\b(?:created|conjured|summoned|newly created)\b.{0,100}"
                        r"\b(?:weapon|mace|sword|axe|hammer|scimitar)\b",
                        sale_text,
                    )
                    or (
                        cast_step_id
                        and re.search(
                            rf"\b(?:from|produced by|created in)\s+{re.escape(cast_step_id)}\b",
                            sale_text,
                        )
                    )
                )
                if created_item_reference:
                    return (
                        "Create Weapon products are marked IA_MADE and cannot be given "
                        "to any NPC; use the created weapon as equipment, never as a "
                        "sale or funding step"
                    )
        assumption_text = " ".join(assumptions or []).casefold()
        if create_weapon_indexes and re.search(
            r"\b(?:created|conjured|summoned|newly created)\b.{0,100}"
            r"\b(?:weapon|mace|sword|axe|hammer|scimitar)\b.{0,100}"
            r"\b(?:sell|sale|sellable|buyer|merchant|fund)\w*\b",
            assumption_text,
        ):
            return (
                "the plan assumes a Create Weapon product is sellable, but every such "
                "product is marked IA_MADE and cannot be given to any NPC; use it only "
                "as equipment and choose a non-sale funding route"
            )
        return None

    @staticmethod
    def _phase_inventory_plan_error(
        phase: dict[str, Any] | None,
        steps: list[dict[str, Any]],
        observation: dict[str, Any],
    ) -> str | None:
        """Require plans to cover the exact remaining inventory phase outcome."""

        inventory = observation.get("inventory")
        if not isinstance(inventory, dict) or not isinstance(
            inventory.get("items"), list
        ):
            # Stored plans can be loaded before the first live observation.
            return None
        number_words = {
            1: "one",
            2: "two",
            3: "three",
            4: "four",
            5: "five",
            6: "six",
            7: "seven",
            8: "eight",
            9: "nine",
            10: "ten",
        }

        def names_item(text: str, item_name: str) -> bool:
            if item_name in {"food", "edible food"}:
                return bool(
                    re.search(r"\b(?:food|edible|snacks?)\b", text)
                    or any(marker in text for marker in EDIBLE_FOOD_NAME_MARKERS)
                )
            return item_name in text

        def names_count(text: str, value: int) -> bool:
            tokens = [re.escape(str(value))]
            if value in number_words:
                tokens.append(number_words[value])
            return bool(re.search(rf"\b(?:{'|'.join(tokens)})\b", text))

        def amount_before(text: str, item_pattern: str) -> list[int]:
            word_values = {word: value for value, word in number_words.items()}
            matches = re.findall(
                rf"\b(\d+|{'|'.join(word_values)})\s+(?:x\s+)?(?:{item_pattern})\b",
                text,
            )
            return [
                int(match) if match.isdigit() else word_values[match]
                for match in matches
            ]

        def planned_repetitions(step: dict[str, Any]) -> int:
            """Read a typed repeat count, with a legacy prose fallback."""

            typed = step.get("repeat_count")
            if (
                isinstance(typed, int)
                and not isinstance(typed, bool)
                and typed > 0
            ):
                return typed
            text = str(step.get("outcome") or "").casefold()
            word_values = {word: value for value, word in number_words.items()}
            quantity = rf"(\d+|{'|'.join(word_values)})"
            matches: list[str] = []
            for pattern in (
                rf"\bcast\b.{{0,60}}\bcreate\s+food\b.{{0,40}}?\b{quantity}\s+(?:times?|casts?)\b",
                rf"\b{quantity}\s+create\s+food\s+casts?\b",
                rf"\bcreate\s+food\b.{{0,20}}?\bx\s*{quantity}\b",
            ):
                matches.extend(re.findall(pattern, text))
            values = [
                int(match) if match.isdigit() else word_values[match]
                for match in matches
            ]
            return max(values) if values else 1

        for criterion in (phase or {}).get("success_criteria", []):
            if not isinstance(criterion, dict) or criterion.get("kind") != "inventory_contains":
                continue
            item_name = " ".join(str(criterion.get("item") or "").split()).casefold()
            required = int(criterion.get("count", 1) or 1)
            current = CriteriaEvaluator.inventory_count(
                inventory.get("items"), item_name
            )
            if current >= required:
                continue
            semantic_food = item_name in {"food", "edible food"}
            if semantic_food:
                food_entries = [
                    entry
                    for entry in inventory["items"]
                    if isinstance(entry, dict)
                    and any(
                        marker
                        in " ".join(
                            str(entry.get("name") or "").split()
                        ).casefold()
                        for marker in EDIBLE_FOOD_NAME_MARKERS
                    )
                ]
                removed_keys: set[str] = set()
                planned_removals = 0
                for step in steps:
                    tool = str(step.get("tool") or "")
                    outcome = str(step.get("outcome") or "").casefold()
                    if tool == "sell_all" and not re.search(
                        r"\b(?:keep|preserve|retain)\b.{0,80}\b(?:food|edible|snacks?)\b",
                        outcome,
                    ):
                        candidates = food_entries
                    elif tool == "sell" or (
                        tool == "act"
                        and re.match(r"\s*(?:eat|drop|use)\b", outcome)
                    ):
                        candidates = [
                            entry
                            for entry in food_entries
                            if (
                                entry.get("id", entry.get("object_id")) is not None
                                and re.search(
                                    rf"\b{re.escape(str(entry.get('id', entry.get('object_id'))))}\b",
                                    outcome,
                                )
                            )
                            or re.search(
                                rf"\b{re.escape(str(entry.get('name') or '').casefold())}s?\b",
                                outcome,
                            )
                        ]
                    else:
                        candidates = []
                    for entry in candidates:
                        key = str(
                            entry.get(
                                "id",
                                entry.get("object_id", entry.get("name")),
                            )
                        )
                        if key in removed_keys:
                            continue
                        removed_keys.add(key)
                        try:
                            planned_removals += max(
                                1, int(entry.get("amount", 1) or 1)
                            )
                        except (TypeError, ValueError):
                            planned_removals += 1

                preserved = max(0, current - planned_removals)
                needed_units = required - preserved
                cast_steps = [
                    step
                    for step in steps
                    if step.get("tool") == "cast"
                    and "create food"
                    in str(step.get("outcome") or "").casefold()
                ]
                repeat_to_target = any(
                    re.search(
                        r"\b(?:until|as needed|repeat)\b",
                        str(step.get("outcome") or "").casefold(),
                    )
                    and names_item(
                        str(step.get("verification") or "").casefold(),
                        item_name,
                    )
                    and names_count(
                        str(step.get("verification") or "").casefold(),
                        required,
                    )
                    for step in cast_steps
                )
                planned_casts = max(
                    sum(planned_repetitions(step) for step in cast_steps),
                    needed_units if repeat_to_target else 0,
                )
                planned_food_purchases = 0
                for step in steps:
                    if step.get("tool") != "shop":
                        continue
                    outcome = str(step.get("outcome") or "").casefold()
                    if not re.search(r"\b(?:buy|purchase|acquire)\b", outcome):
                        continue
                    if "reagent" in outcome:
                        continue
                    food_pattern = (
                        r"food(?:\s+items?)?|edible(?:\s+food)?|snacks?|"
                        + "|".join(
                            re.escape(marker) + "s?"
                            for marker in EDIBLE_FOOD_NAME_MARKERS
                        )
                    )
                    amounts = amount_before(outcome, food_pattern)
                    planned_food_purchases += max(amounts) if amounts else 0
                projected = preserved + planned_casts + planned_food_purchases
                if projected < required:
                    return (
                        f"execution_plan does not cover active phase criterion {criterion.get('id')!r}: "
                        f"it starts with {current} edible food item(s), plans to remove "
                        f"{planned_removals}, and adds only {planned_casts + planned_food_purchases}; "
                        f"projected total {projected} is below required {required}. Purpose: "
                        "plan verification cannot assume an item remains after selling, eating, "
                        "or dropping it; preserve the existing food or add enough concrete "
                        "acquisition/cast actions"
                    )

                create_food = next(
                    (
                        spell
                        for spell in deep_get(observation, "spells.spells", [])
                        if isinstance(spell, dict)
                        and str(spell.get("name") or "").strip().casefold()
                        == "create food"
                    ),
                    None,
                )
                for reagent in (
                    create_food.get("reagents", [])
                    if isinstance(create_food, dict)
                    else []
                ):
                    match = re.fullmatch(
                        r"\s*(\d+)\s*x\s*(.+?)\s*", str(reagent), re.I
                    )
                    if not match or planned_casts <= 0:
                        continue
                    per_cast = int(match.group(1))
                    reagent_name = " ".join(match.group(2).split()).casefold()
                    reagent_pattern = (
                        r"elder\s*berr(?:y|ies)"
                        if reagent_name == "elderberry"
                        else r"herbs?"
                        if reagent_name in {"herb", "herbs"}
                        else re.escape(reagent_name) + "s?"
                    )
                    available = CriteriaEvaluator.inventory_count(
                        inventory["items"], reagent_name
                    )
                    projected_reagents = available
                    for step in steps:
                        if step.get("tool") != "shop":
                            continue
                        outcome = str(step.get("outcome") or "").casefold()
                        verification = str(
                            step.get("verification") or ""
                        ).casefold()
                        if re.search(r"\b(?:buy|purchase|acquire)\b", outcome):
                            additions = amount_before(outcome, reagent_pattern)
                            projected_reagents += max(additions) if additions else 0
                        verified_totals = amount_before(
                            verification, reagent_pattern
                        )
                        if verified_totals:
                            projected_reagents = max(
                                projected_reagents, max(verified_totals)
                            )
                    reagent_required = per_cast * planned_casts
                    if projected_reagents < reagent_required:
                        return (
                            f"execution_plan cannot support its {planned_casts} planned "
                            f"Create Food cast(s): {reagent_name} is {per_cast} per cast, "
                            f"so {reagent_required} is required, but authoritative inventory "
                            f"plus quantified purchase steps provides only {projected_reagents}. "
                            "Purpose: acquire the exact live reagent total before relying on "
                            "the casts; verification text cannot manufacture missing reagents"
                        )
                continue
            remaining = required - current
            relevant_mutations = 0
            explicitly_covered = False
            for step in steps:
                outcome = str(step.get("outcome") or "").casefold()
                verification = str(step.get("verification") or "").casefold()
                verification_covers = names_item(verification, item_name) and (
                    names_count(verification, required)
                    or (
                        names_count(verification, remaining)
                        and re.search(
                            r"\b(?:more|additional|remaining)\b", verification
                        )
                    )
                )
                acquisition_step = step.get("tool") in {"cast", "shop"} or (
                    step.get("tool") == "act"
                    and bool(re.search(r"\b(?:get|take|pick\s+up|acquire)\b", outcome))
                )
                outcome_covers = (
                    acquisition_step
                    and names_item(outcome, item_name)
                    and (
                        names_count(outcome, required)
                        or (
                            names_count(outcome, remaining)
                            and re.search(
                                r"\b(?:more|additional|remaining)\b", outcome
                            )
                        )
                    )
                )
                if verification_covers or outcome_covers:
                    explicitly_covered = True
                    break
                if (
                    acquisition_step
                    and names_item(outcome, item_name)
                ):
                    relevant_mutations += planned_repetitions(step)
            if explicitly_covered or relevant_mutations >= remaining:
                continue
            display_item = "edible food" if item_name in {"food", "edible food"} else item_name
            unit_note = (
                "; each Create Food cast produces one item"
                if item_name in {"food", "edible food"}
                else ""
            )
            return (
                f"execution_plan does not cover active phase criterion {criterion.get('id')!r}: "
                f"authoritative inventory has {current} {display_item} item(s), but the "
                f"phase requires {required}. Purpose: a successful tool call is not phase "
                "completion. Include mutation step(s) whose outcome or verification "
                f"explicitly reaches {required} total {display_item} item(s), or "
                f"{remaining} additional{unit_note}"
            )

        for criterion in (phase or {}).get("success_criteria", []):
            if not isinstance(criterion, dict):
                continue
            kind = criterion.get("kind")
            if kind == "equipment_count":
                category = str(criterion.get("category") or "").casefold()
                required = int(criterion.get("count", 1) or 1)
                current = CriteriaEvaluator.equipment_count(observation, category)
                if current >= required:
                    continue
                remaining = required - current
                mutations = 0
                for step in steps:
                    tool = str(step.get("tool") or "")
                    outcome = str(step.get("outcome") or "").casefold()
                    if category == "weapon" and tool == "cast" and "create weapon" in outcome:
                        mutations += planned_repetitions(step)
                    elif tool == "shop" and (
                        category in outcome
                        or any(
                            word in outcome
                            for word in (WEAPON_WORDS if category == "weapon" else ARMOR_WORDS)
                        )
                    ):
                        mutations += planned_repetitions(step)
                if mutations < remaining:
                    return (
                        f"execution_plan does not cover active phase equipment_count criterion "
                        f"{criterion.get('id')!r}: verified {category} count is {current}, required "
                        f"{required}, but the plan has only {mutations} grounded acquisition(s). "
                        "Purpose: equipment categories are verified semantic state, not literal "
                        "inventory names; add enough Create Weapon or grounded purchase actions"
                    )
            elif kind == "equipment_wielding":
                if CriteriaEvaluator.equipment_wielding(
                    observation,
                    item=criterion.get("item"),
                    category=criterion.get("category"),
                ):
                    continue
                requested = " ".join(
                    str(criterion.get("item") or criterion.get("category") or "").split()
                ).casefold()
                covered = any(
                    str(step.get("tool") or "") in {"equip_best", "act"}
                    and (
                        criterion.get("category") == "weapon"
                        or requested in str(step.get("outcome") or "").casefold()
                    )
                    for step in steps
                )
                if not covered:
                    return (
                        f"execution_plan does not cover active phase equipment_wielding criterion "
                        f"{criterion.get('id')!r}: {requested!r} is not currently wielded and no "
                        "equipment mutation explicitly selects it. Purpose: creating or carrying a "
                        "weapon does not prove that it was wielded"
                    )
        return None

    def _phase_required_sale_plan_error(
        self,
        phase: dict[str, Any] | None,
        steps: list[dict[str, Any]],
        observation: dict[str, Any],
    ) -> str | None:
        """Prefer known bank funds over liquidating an active phase outcome."""

        positive_accounts = [
            account
            for account in self._latest_bank_balance_context()
            if isinstance(account.get("last_known_balance"), (int, float))
            and account["last_known_balance"] > 0
        ]
        if not positive_accounts:
            return None
        raw_items = deep_get(observation, "inventory.items", [])
        items = [item for item in raw_items if isinstance(item, dict)] if isinstance(raw_items, list) else []
        for criterion in (phase or {}).get("success_criteria", []):
            if not isinstance(criterion, dict) or criterion.get("kind") != "inventory_contains":
                continue
            requested = " ".join(
                str(criterion.get("item") or "").split()
            ).casefold()
            semantic_food = requested in {"food", "edible food"}
            matching = [
                item
                for item in items
                if (
                    any(
                        marker
                        in " ".join(
                            str(item.get("name") or "").split()
                        ).casefold()
                        for marker in EDIBLE_FOOD_NAME_MARKERS
                    )
                    if semantic_food
                    else requested
                    in " ".join(
                        str(item.get("name") or "").split()
                    ).casefold()
                )
            ]
            if not matching:
                continue
            for step in steps:
                tool = str(step.get("tool") or "")
                if tool not in {"sell", "sell_all"}:
                    continue
                text = " ".join(
                    str(step.get(field) or "")
                    for field in ("outcome", "verification")
                ).casefold()
                if tool == "sell_all":
                    targets_required_item = not re.search(
                        r"\b(?:keep|preserve|retain)\b.{0,80}"
                        + (
                            r"\b(?:food|edible|snacks?)\b"
                            if semantic_food
                            else rf"\b{re.escape(requested)}s?\b"
                        ),
                        text,
                    )
                    target = "required inventory"
                else:
                    selected = next(
                        (
                            item
                            for item in matching
                            if (
                                item.get("id", item.get("object_id")) is not None
                                and re.search(
                                    rf"\b{re.escape(str(item.get('id', item.get('object_id'))))}\b",
                                    text,
                                )
                            )
                            or re.search(
                                rf"\b{re.escape(str(item.get('name') or '').casefold())}s?\b",
                                text,
                            )
                        ),
                        None,
                    )
                    targets_required_item = selected is not None
                    target = (
                        f"{selected.get('name')} id "
                        f"{selected.get('id', selected.get('object_id'))}"
                        if isinstance(selected, dict)
                        else "required inventory"
                    )
                if not targets_required_item:
                    continue
                richest = max(
                    positive_accounts,
                    key=lambda account: float(account["last_known_balance"]),
                )
                return (
                    f"execution_plan step {step.get('id')!r} sells {target}, which "
                    f"currently contributes to active phase criterion {criterion.get('id')!r}, "
                    f"while durable bank evidence shows {richest['last_known_balance']} "
                    f"shillings in account {richest['account']!r}. Purpose: do not consume "
                    "the outcome being assembled when a non-destructive grounded funding "
                    f"route exists; preserve the {requested} inventory and precede the "
                    f"purchase with travel to bank room {TOS_BANK_ROOM_ID} plus a live bank "
                    "check/withdrawal"
                )
        return None

    def _targeted_sale_grounding_error(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any] | None,
        steps: list[dict[str, Any]],
        observation: dict[str, Any],
    ) -> str | None:
        """Require exact identity when a sale name could select the wrong instance."""

        if str((phase or {}).get("kind") or "") not in {
            "prepare_combat",
            "liquidate_inventory",
        }:
            return None
        raw_items = deep_get(observation, "inventory.items", [])
        items = [item for item in raw_items if isinstance(item, dict)] if isinstance(raw_items, list) else []
        ids = {
            str(item.get("id", item.get("object_id"))).strip().casefold()
            for item in items
            if item.get("id", item.get("object_id")) is not None
        }
        counts: dict[str, int] = {}
        for item in items:
            name = " ".join(str(item.get("name") or "").split()).casefold()
            if name:
                counts[name] = counts.get(name, 0) + 1
        duplicates = {name for name, count in counts.items() if count > 1}
        restricted = self._intrinsically_unsellable_item_ids(goal, observation)
        restricted_names = self._intrinsically_unsellable_item_names(
            goal, observation
        )
        for step in steps:
            if step.get("tool") != "sell":
                continue
            sale_text = " ".join(
                str(step.get(field) or "")
                for field in ("outcome", "verification")
            ).casefold()
            mentioned_ids = {
                item_id
                for item_id in ids
                if re.search(rf"\b{re.escape(item_id)}\b", sale_text)
            }
            ambiguous_names = sorted(
                name
                for name in duplicates
                if re.search(rf"\b{re.escape(name)}s?\b", sale_text)
            )
            blocked_names = sorted(
                name
                for name in restricted_names
                if re.search(rf"\b{re.escape(name)}s?\b", sale_text)
            )
            if blocked_names:
                return (
                    "the unchanged semantic inventory has verified every carried "
                    "instance of "
                    + ", ".join(repr(name) for name in blocked_names)
                    + " non-transferable across item-id churn; do not plan another sale "
                    "until inventory materially changes"
                )
            if ambiguous_names and not mentioned_ids:
                return (
                    "the targeted sale names duplicate inventory item(s) "
                    + ", ".join(repr(name) for name in ambiguous_names)
                    + " without an exact current item id. Bind the sale to the intended "
                    "unequipped inventory id so a protected or non-transferable duplicate "
                    "cannot be selected"
                )
            if restricted and not mentioned_ids:
                return (
                    "the targeted sale does not name an exact current inventory id while "
                    "another carried instance is verified non-transferable; bind the plan "
                    "to a specific different id before choosing a buyer"
                )
        return None

    @staticmethod
    def _stored_empty_merchant_lookup(last_action: Any) -> bool:
        if (
            not isinstance(last_action, dict)
            or last_action.get("tool") != "merchants"
            or last_action.get("status") != "succeeded"
        ):
            return False
        summary = " ".join(str(last_action.get("result_summary") or "").split())
        return bool(
            re.search(r"['\"]matches['\"]\s*:\s*\[\s*\]", summary)
            or (
                all(
                    re.search(
                        rf"['\"]{field}['\"]\s*:\s*\[\s*\]",
                        summary,
                    )
                    for field in ("buys_anything", "rules_mentioning")
                )
            )
        )

    def _execution_plan(self, goal: dict[str, Any]) -> dict[str, Any] | None:
        values = self.storage.get_runtime(EXECUTION_PLAN_RUNTIME_KEY, {})
        if not isinstance(values, dict):
            return None
        value = values.get(str(goal.get("id") or ""))
        contract = canonical_json(
            {
                key: goal.get(key)
                for key in ("title", "objective", "success_criteria", "constraints")
            }
        )
        if (
            not isinstance(value, dict)
            or value.get("schema_version") != EXECUTION_PLAN_SCHEMA_VERSION
            or value.get("goal_contract") != contract
        ):
            return None
        run = self.storage.campaign_run(str(goal.get("id") or ""))
        phase = self.storage.active_campaign_phase(run["id"]) if run else None
        if phase is not None and value.get("phase_id") != phase["id"]:
            phase_context = phase.get("context") if isinstance(phase.get("context"), dict) else {}
            if value.get("phase_id") is None and phase_context.get("compatibility_phase") is True:
                value = {
                    **value,
                    "campaign_run_id": run.get("id") if run else None,
                    "phase_id": phase["id"],
                    "phase_kind": phase.get("kind"),
                    "updated_at": timestamp(),
                }
                values[str(goal.get("id") or "")] = value
                self.storage.set_runtime(EXECUTION_PLAN_RUNTIME_KEY, values)
            else:
                return None
        if phase is not None:
            phase_tools = {
                str(tool.get("name") or "") for tool in self._planner_tools(phase)
            }
            invalid_phase_step = next(
                (
                    step
                    for step in value.get("steps", [])
                    if isinstance(step, dict)
                    and isinstance(step.get("tool"), str)
                    and step.get("tool") not in phase_tools
                ),
                None,
            )
            if invalid_phase_step is not None:
                self._invalidate_execution_plan(
                    goal,
                    "stored step "
                    f"{invalid_phase_step.get('id')!r} uses tool "
                    f"{invalid_phase_step.get('tool')!r} outside active phase "
                    f"{phase.get('kind')!r}",
                )
                return None
        steps = value.get("steps")
        if isinstance(steps, list):
            repaired_steps = [
                step
                for step in steps
                if isinstance(step, dict) and step.get("tool") is not None
            ]
            constraints = goal.get("constraints") if isinstance(goal.get("constraints"), dict) else {}
            if constraints.get("bank_before_hazard") is True and self._carried_currency(
                self.last_observation or {}
            ) <= 0:
                repaired_steps = [
                    step
                    for step in repaired_steps
                    if not (
                        step.get("tool") == "bank"
                        and "deposit" in str(step.get("outcome") or "").casefold()
                    )
                ]
            if repaired_steps and len(repaired_steps) != len(steps):
                prior_normalizations = value.get("normalizations")
                normalizations = (
                    list(prior_normalizations)
                    if isinstance(prior_normalizations, list)
                    else []
                )
                normalizations.append(
                    {
                        "kind": "repaired_legacy_controller_owned_steps",
                        "before": len(steps),
                        "after": len(repaired_steps),
                    }
                )
                value = {
                    **value,
                    "steps": repaired_steps,
                    "normalizations": normalizations[-20:],
                    "updated_at": timestamp(),
                }
                values[str(goal.get("id") or "")] = value
                self.storage.set_runtime(EXECUTION_PLAN_RUNTIME_KEY, values)
        invalid_observation_step = next(
            (
                step
                for step in value.get("steps", [])
                if isinstance(step, dict) and self._observation_only_act_step(step)
            ),
            None,
        )
        if invalid_observation_step is not None:
            self._invalidate_execution_plan(
                goal,
                "stored step "
                f"{invalid_observation_step.get('id')!r} uses act for an observation-only outcome",
            )
            return None
        invalid_commerce_step = next(
            (
                (step, error)
                for step in value.get("steps", [])
                if isinstance(step, dict)
                if (error := self._commerce_step_error(step)) is not None
            ),
            None,
        )
        if invalid_commerce_step is not None:
            step, error = invalid_commerce_step
            self._invalidate_execution_plan(
                goal,
                f"stored step {step.get('id')!r} {error}",
            )
            return None
        invalid_protected_sale_step = next(
            (
                (step, error)
                for step in value.get("steps", [])
                if isinstance(step, dict)
                if (
                    error := self._protected_phase_sale_step_error(phase, step)
                )
                is not None
            ),
            None,
        )
        if invalid_protected_sale_step is not None:
            step, error = invalid_protected_sale_step
            self._invalidate_execution_plan(
                goal,
                f"stored step {step.get('id')!r} {error}",
            )
            return None
        invalid_map_step = next(
            (
                (step, error)
                for step in value.get("steps", [])
                if isinstance(step, dict)
                if (error := self._map_step_error(phase, step)) is not None
            ),
            None,
        )
        if invalid_map_step is not None:
            step, error = invalid_map_step
            self._invalidate_execution_plan(
                goal,
                f"stored step {step.get('id')!r} {error}",
            )
            return None
        stored_steps = [
            step for step in value.get("steps", []) if isinstance(step, dict)
        ]
        last_action = value.get("last_action")
        if self._stored_empty_merchant_lookup(last_action):
            reason = (
                "the completed merchants step returned no candidate merchants, so "
                "the stored plan has no grounded seller or destination"
            )
            self._invalidate_execution_plan(goal, reason)
            self._set_planner_feedback(
                goal,
                reason,
                failure_context={
                    "kind": "merchant_lookup_no_candidates",
                    "purpose": (
                        "Retire a legacy plan that incorrectly recorded an empty "
                        "merchant result as a successful prerequisite."
                    ),
                    "required_response": (
                        "Use an exact source-grounded item query, actual known catalogue "
                        "stock, or a different acquisition prerequisite; do not continue "
                        "to travel or shop without a returned merchant."
                    ),
                },
            )
            return None
        completed_through_step_id = (
            str(last_action.get("step_id") or "")
            if isinstance(last_action, dict)
            and last_action.get("status") == "succeeded"
            else None
        )
        remaining_steps = self._remaining_plan_steps(
            stored_steps,
            completed_through_step_id,
        )
        sale_recovery_error = self._sale_recovery_plan_error(
            goal, remaining_steps
        )
        bank_error = self._bank_plan_error(
            remaining_steps,
            self.last_observation or {},
        )
        if bank_error is not None:
            self._invalidate_execution_plan(goal, bank_error)
            self._set_planner_feedback(
                goal,
                bank_error
                + ". Build a replacement plan with travel and bank as separate ordered steps.",
                failure_context={
                    "kind": "bank_location_prerequisite_missing",
                    "purpose": "Prevent a bank call from being executed outside a bank room.",
                    "required_response": (
                        "Add a preceding travel step to a verified bank room before bank."
                    ),
                },
            )
            return None
        direct_capability_error = self._direct_capability_plan_error(
            phase,
            remaining_steps,
            self.last_observation or {},
            value.get("assumptions")
            if isinstance(value.get("assumptions"), list)
            else [],
        )
        if direct_capability_error is not None:
            self._invalidate_execution_plan(goal, direct_capability_error)
            return None
        phase_required_sale_error = self._phase_required_sale_plan_error(
            phase, remaining_steps, self.last_observation or {}
        )
        if phase_required_sale_error is not None:
            self._invalidate_execution_plan(goal, phase_required_sale_error)
            self._set_planner_feedback(
                goal,
                phase_required_sale_error,
                failure_context={
                    "kind": "phase_required_inventory_sale",
                    "purpose": (
                        "Preserve inventory already satisfying the active phase when "
                        "durably known bank funds provide a non-destructive route."
                    ),
                    "required_response": (
                        "Replace the sale with separate travel-to-bank and bank "
                        "check/withdrawal steps before the purchase."
                    ),
                },
            )
            return None
        phase_inventory_error = self._phase_inventory_plan_error(
            phase, remaining_steps, self.last_observation or {}
        )
        if phase_inventory_error is not None:
            self._invalidate_execution_plan(goal, phase_inventory_error)
            self._set_planner_feedback(
                goal,
                phase_inventory_error,
                failure_context={
                    "kind": "phase_outcome_not_covered",
                    "purpose": (
                        "Keep a tool-level success from being mistaken for the active "
                        "phase's exact verified outcome."
                    ),
                    "required_response": (
                        "Build a replacement plan that explicitly reaches the remaining "
                        "typed phase criterion before its safe-ending step."
                    ),
                },
            )
            return None
        sale_grounding_error = self._targeted_sale_grounding_error(
            goal,
            phase,
            remaining_steps,
            self.last_observation or {},
        )
        if sale_grounding_error is not None:
            self._invalidate_execution_plan(goal, sale_grounding_error)
            return None
        if sale_recovery_error is not None:
            self._invalidate_execution_plan(goal, sale_recovery_error)
            intrinsic_item_reused = "cannot be given to any NPC" in sale_recovery_error
            discovery_already_completed = (
                "buyer discovery" in sale_recovery_error
                and "already completed" in sale_recovery_error
            )
            sale_evidence_exhausted = (
                "exhausting its source-catalogue sale hypothesis"
                in sale_recovery_error
            )
            required_response = (
                "Build a replacement plan that selects a different exact inventory "
                "item id or uses a non-sale funding route; merchant discovery cannot "
                "make the rejected item transferable."
                if intrinsic_item_reused
                else (
                    "Build a replacement plan that does not sell or run buyer discovery "
                    "for this exact item id; use a non-sale prerequisite or materially "
                    "change inventory."
                    if sale_evidence_exhausted
                    else (
                        "Build a replacement plan that omits the repeated merchants lookup, "
                        "uses a different candidate from its completed result, and preserves "
                        "a separate travel step before the sale."
                        if discovery_already_completed
                        else "Build a replacement plan that discovers a compatible buyer "
                        "before attempting another sale."
                    )
                )
            )
            self._set_planner_feedback(
                goal,
                sale_recovery_error
                + ". "
                + required_response,
                failure_context={
                    "kind": (
                        "item_not_npc_transferable"
                        if intrinsic_item_reused
                        else (
                            "sale_evidence_exhausted"
                            if sale_evidence_exhausted
                            else "merchant_rejected_sale"
                        )
                    ),
                    "purpose": (
                        "Retire a persisted plan that reused an exact inventory item "
                        "the server proved cannot be given to any NPC."
                        if intrinsic_item_reused
                        else (
                            "Retire only the exact carried item as a funding route after "
                            "bounded independent live refusals, without blocking rooms, "
                            "other items, or the strategic goal."
                            if sale_evidence_exhausted
                            else "Retire a persisted pre-enforcement commerce plan after "
                            "durable evidence disproved its assumed buyer."
                        )
                    ),
                    "required_response": required_response,
                },
            )
            return None
        funding_error = self._plan_funding_error(
            remaining_steps,
            self.last_observation or {},
        )
        if funding_error is not None:
            self._invalidate_execution_plan(goal, funding_error)
            return None
        affordability_error = self._shop_plan_affordability_error(
            remaining_steps, self.last_observation or {}
        )
        if affordability_error is not None:
            self._invalidate_execution_plan(goal, affordability_error)
            stock_absent = (
                "absent from that seller's live shop catalogue"
                in affordability_error
            )
            self._set_planner_feedback(
                goal,
                affordability_error,
                failure_context={
                    "kind": (
                        "named_seller_missing_stock"
                        if stock_absent
                        else "known_basket_unaffordable"
                    ),
                    "purpose": (
                        "Prevent travel or purchase based on items absent from the named "
                        "seller's already-observed live catalogue."
                        if stock_absent
                        else "Prevent a known shop basket from executing when carried cash "
                        "cannot cover its live catalogue price."
                    ),
                    "required_response": (
                        "Use items actually listed by that seller or choose a different "
                        "source-grounded seller/acquisition prerequisite; more money does "
                        "not make missing stock available."
                        if stock_absent
                        else "Add a preceding grounded funding route for the exact known "
                        "shortfall; preserve active-phase inventory."
                    ),
                },
            )
            return None
        try:
            self._validate_direct_pvp_plan(
                goal,
                remaining_steps,
                self.criteria.evaluate(goal, self.last_observation or {}),
            )
        except ModelError:
            # Retire a pre-enforcement plan silently. The next tactical turn
            # receives no verified plan and must produce a contract-conforming
            # replacement before any mutation can run.
            values.pop(str(goal.get("id") or ""), None)
            self.storage.set_runtime(EXECUTION_PLAN_RUNTIME_KEY, values)
            return None
        plan_normalizations = value.get("normalizations")
        repaired_legacy_steps = any(
            isinstance(item, dict)
            and item.get("kind") == "repaired_legacy_controller_owned_steps"
            for item in (
                plan_normalizations if isinstance(plan_normalizations, list) else []
            )
        )
        if repaired_legacy_steps:
            feedback = self._planner_feedback(goal)
            feedback_message = str((feedback or {}).get("message") or "").casefold()
            if "selected action tool did not match" in feedback_message:
                self._clear_planner_feedback()
        return value

    @staticmethod
    def _goal_contract(goal: dict[str, Any]) -> str:
        return canonical_json(
            {
                key: goal.get(key)
                for key in ("title", "objective", "success_criteria", "constraints")
            }
        )

    @staticmethod
    def _goal_requires_raza_exit(goal: dict[str, Any]) -> bool:
        criteria = goal.get("success_criteria")
        if isinstance(criteria, list) and any(
            isinstance(item, dict)
            and (
                item.get("event_kind") == "raza.left"
                or (
                    item.get("kind") == "operator_confirmed"
                    and "raza"
                    in str(item.get("id") or "").casefold().replace("-", "_")
                )
            )
            for item in criteria
        ):
            return True
        text = f"{goal.get('title', '')} {goal.get('objective', '')}".casefold()
        return "raza" in text and any(
            marker in text
            for marker in ("leave raza", "left raza", "out of raza", "outside raza")
        )

    @staticmethod
    def _observation_room_name(observation: dict[str, Any]) -> str:
        return str(
            deep_get(
                observation,
                "look.room.name",
                deep_get(
                    observation,
                    "status.room.name",
                    deep_get(observation, "status.where.name", ""),
                ),
            )
            or ""
        )

    @classmethod
    def _in_raza_zone(cls, observation: dict[str, Any]) -> bool:
        name = cls._observation_room_name(observation).casefold()
        return "raza" in name or "mausoleum" in name

    def _raza_exit_event_recorded(self, goal: dict[str, Any]) -> bool:
        return bool(
            self.storage.events(
                after_cursor=int(self.storage.goal_event_anchor(goal["id"]) or 0),
                limit=1,
                kinds=["raza.left"],
                goal_id=goal["id"],
            ).get("events")
        )

    def _goal_completion_checkpoint(
        self, goal: dict[str, Any]
    ) -> dict[str, Any] | None:
        values = self.storage.get_runtime(
            GOAL_COMPLETION_CHECKPOINT_RUNTIME_KEY, {}
        )
        if not isinstance(values, dict):
            return None
        value = values.get(str(goal.get("id") or ""))
        if (
            not isinstance(value, dict)
            or value.get("goal_contract") != self._goal_contract(goal)
            or not isinstance(value.get("completion"), dict)
        ):
            return None
        return value

    def _latch_goal_completion(
        self, goal: dict[str, Any], completion: dict[str, Any]
    ) -> dict[str, Any] | None:
        existing = self._goal_completion_checkpoint(goal)
        if existing is not None:
            return existing
        if completion.get("all_met") is not True:
            return None
        values = self.storage.get_runtime(
            GOAL_COMPLETION_CHECKPOINT_RUNTIME_KEY, {}
        )
        values = dict(values) if isinstance(values, dict) else {}
        value = {
            "goal_id": goal["id"],
            "goal_contract": self._goal_contract(goal),
            "completion": completion,
            "verified_at": timestamp(),
        }
        values[goal["id"]] = value
        self.storage.set_runtime(GOAL_COMPLETION_CHECKPOINT_RUNTIME_KEY, values)
        self.storage.emit_event(
            "goal.outcome_verified",
            f"Goal outcome verified; returning to the planned safe ending: {goal['title']}",
            interesting=False,
            goal_id=goal["id"],
            data={"completion": completion, "terminal_deferred": True},
        )
        return value

    def _clear_goal_completion_checkpoint(self, goal_id: str) -> None:
        values = self.storage.get_runtime(
            GOAL_COMPLETION_CHECKPOINT_RUNTIME_KEY, {}
        )
        if not isinstance(values, dict) or goal_id not in values:
            return
        values = dict(values)
        values.pop(goal_id, None)
        self.storage.set_runtime(GOAL_COMPLETION_CHECKPOINT_RUNTIME_KEY, values)

    @staticmethod
    def _phase_contract(phase: dict[str, Any]) -> str:
        return canonical_json(
            {
                key: phase.get(key)
                for key in (
                    "id",
                    "goal_id",
                    "kind",
                    "objective",
                    "success_criteria",
                    "abandon_predicates",
                    "parent_phase_id",
                )
            }
        )

    def _phase_completion_checkpoint(
        self, phase: dict[str, Any] | None
    ) -> dict[str, Any] | None:
        if not isinstance(phase, dict):
            return None
        values = self.storage.get_runtime(
            PHASE_COMPLETION_CHECKPOINT_RUNTIME_KEY, {}
        )
        if not isinstance(values, dict):
            return None
        value = values.get(str(phase.get("id") or ""))
        if (
            not isinstance(value, dict)
            or value.get("phase_contract") != self._phase_contract(phase)
            or not isinstance(value.get("completion"), dict)
        ):
            return None
        return value

    def _latch_phase_completion(
        self,
        goal: dict[str, Any],
        run: dict[str, Any],
        phase: dict[str, Any],
        completion: dict[str, Any],
    ) -> dict[str, Any] | None:
        existing = self._phase_completion_checkpoint(phase)
        if existing is not None:
            return existing
        if completion.get("all_met") is not True:
            return None
        values = self.storage.get_runtime(
            PHASE_COMPLETION_CHECKPOINT_RUNTIME_KEY, {}
        )
        values = dict(values) if isinstance(values, dict) else {}
        latched_completion = {
            key: value
            for key, value in completion.items()
            if key != "completion_deferred"
        }
        value = {
            "goal_id": goal["id"],
            "run_id": run["id"],
            "phase_id": phase["id"],
            "phase_contract": self._phase_contract(phase),
            "completion": latched_completion,
            "verified_at": timestamp(),
        }
        values[phase["id"]] = value
        self.storage.set_runtime(PHASE_COMPLETION_CHECKPOINT_RUNTIME_KEY, values)
        self.storage.emit_event(
            "campaign.phase.outcome_verified",
            "Campaign phase outcome verified; returning to its planned safe ending",
            interesting=False,
            goal_id=goal["id"],
            data={
                "run_id": run["id"],
                "phase_id": phase["id"],
                "phase_kind": phase.get("kind"),
                "completion": latched_completion,
                "terminal_deferred": True,
            },
        )
        return value

    def _clear_phase_completion_checkpoint(self, phase_id: str) -> None:
        values = self.storage.get_runtime(
            PHASE_COMPLETION_CHECKPOINT_RUNTIME_KEY, {}
        )
        if not isinstance(values, dict) or phase_id not in values:
            return
        values = dict(values)
        values.pop(phase_id, None)
        self.storage.set_runtime(PHASE_COMPLETION_CHECKPOINT_RUNTIME_KEY, values)

    def _phase_exhaustion_checkpoint(
        self, phase: dict[str, Any] | None
    ) -> dict[str, Any] | None:
        """Return a durable budget-exhaustion boundary for an active phase."""

        if not isinstance(phase, dict):
            return None
        values = self.storage.get_runtime(
            PHASE_EXHAUSTION_CHECKPOINT_RUNTIME_KEY, {}
        )
        if not isinstance(values, dict):
            return None
        value = values.get(str(phase.get("id") or ""))
        if (
            not isinstance(value, dict)
            or value.get("phase_contract") != self._phase_contract(phase)
            or not isinstance(value.get("budget"), dict)
        ):
            return None
        return value

    def _phase_exhaustion_destination(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Choose a source-verified evacuation room without another model call."""

        plan = self._execution_plan(goal)
        ending = plan.get("safe_ending") if isinstance(plan, dict) else None
        if isinstance(ending, dict):
            verified = self._verified_safe_staging(ending.get("room_id"))
            if verified is not None:
                return {
                    **verified,
                    "basis": "retained_model_selected_safe_ending",
                }

        context = self._safe_ending_context(observation)
        candidates = context.get("candidates")
        if not isinstance(candidates, list):
            return None
        for candidate in candidates:
            if not isinstance(candidate, dict):
                continue
            verified = self._verified_safe_staging(candidate.get("room_id"))
            if verified is None:
                continue
            return {
                **verified,
                "distance": candidate.get("distance"),
                "basis": "controller_selected_emergency_safe_ending",
            }
        return None

    def _latch_phase_exhaustion(
        self,
        goal: dict[str, Any],
        run: dict[str, Any],
        phase: dict[str, Any],
        exhausted: dict[str, Any],
        observation: dict[str, Any],
    ) -> dict[str, Any]:
        existing = self._phase_exhaustion_checkpoint(phase)
        if existing is not None:
            return existing
        values = self.storage.get_runtime(
            PHASE_EXHAUSTION_CHECKPOINT_RUNTIME_KEY, {}
        )
        values = dict(values) if isinstance(values, dict) else {}
        destination = self._phase_exhaustion_destination(goal, observation)
        value = {
            "goal_id": goal["id"],
            "run_id": run["id"],
            "phase_id": phase["id"],
            "phase_contract": self._phase_contract(phase),
            "budget": exhausted,
            "safe_ending": destination,
            "exhausted_at": timestamp(),
        }
        values[phase["id"]] = value
        self.storage.set_runtime(PHASE_EXHAUSTION_CHECKPOINT_RUNTIME_KEY, values)
        self.storage.emit_event(
            "campaign.phase.budget_exhausted",
            "Campaign phase budget exhausted; preserving survival control until safe",
            severity="warning",
            interesting=False,
            goal_id=goal["id"],
            data={
                "run_id": run["id"],
                "phase_id": phase["id"],
                "phase_kind": phase.get("kind"),
                "budget": exhausted,
                "safe_ending": redact(destination),
                "terminal_deferred": True,
                "strategic_goal_preserved": True,
            },
        )
        return value

    def _clear_phase_exhaustion_checkpoint(self, phase_id: str) -> None:
        values = self.storage.get_runtime(
            PHASE_EXHAUSTION_CHECKPOINT_RUNTIME_KEY, {}
        )
        if not isinstance(values, dict) or phase_id not in values:
            return
        values = dict(values)
        values.pop(phase_id, None)
        self.storage.set_runtime(PHASE_EXHAUSTION_CHECKPOINT_RUNTIME_KEY, values)

    def _phase_abandonment_checkpoint(
        self, phase: dict[str, Any] | None
    ) -> dict[str, Any] | None:
        """Return a durable terminal outcome awaiting a verified safe boundary."""

        if not isinstance(phase, dict):
            return None
        values = self.storage.get_runtime(
            PHASE_ABANDONMENT_CHECKPOINT_RUNTIME_KEY, {}
        )
        if not isinstance(values, dict):
            return None
        value = values.get(str(phase.get("id") or ""))
        if (
            not isinstance(value, dict)
            or value.get("phase_contract") != self._phase_contract(phase)
            or not str(value.get("reason") or "").strip()
            or not isinstance(value.get("abandonment"), dict)
        ):
            return None
        return value

    def _latch_phase_abandonment(
        self,
        goal: dict[str, Any],
        run: dict[str, Any],
        phase: dict[str, Any],
        detail: dict[str, Any],
        observation: dict[str, Any],
    ) -> dict[str, Any]:
        """Preserve a failed combat phase until survival reaches sanctuary."""

        existing = self._phase_abandonment_checkpoint(phase)
        if existing is not None:
            return existing
        values = self.storage.get_runtime(
            PHASE_ABANDONMENT_CHECKPOINT_RUNTIME_KEY, {}
        )
        values = dict(values) if isinstance(values, dict) else {}
        destination = self._phase_exhaustion_destination(goal, observation)
        value = {
            "goal_id": goal["id"],
            "run_id": run["id"],
            "phase_id": phase["id"],
            "phase_contract": self._phase_contract(phase),
            "reason": str(
                detail.get("reason")
                or "a phase abandonment predicate was verified"
            ),
            "abandonment": redact(detail.get("abandonment", {})),
            "safe_ending": destination,
            "abandoned_at": timestamp(),
        }
        values[phase["id"]] = value
        self.storage.set_runtime(
            PHASE_ABANDONMENT_CHECKPOINT_RUNTIME_KEY, values
        )
        self.storage.emit_event(
            "campaign.phase.abandonment_latched",
            "Campaign phase abandonment verified; preserving survival control until safe",
            severity="warning",
            interesting=True,
            goal_id=goal["id"],
            data={
                "run_id": run["id"],
                "phase_id": phase["id"],
                "phase_kind": phase.get("kind"),
                "reason": value["reason"],
                "safe_ending": redact(destination),
                "terminal_deferred": True,
                "strategic_goal_preserved": True,
            },
        )
        return value

    def _clear_phase_abandonment_checkpoint(self, phase_id: str) -> None:
        values = self.storage.get_runtime(
            PHASE_ABANDONMENT_CHECKPOINT_RUNTIME_KEY, {}
        )
        if not isinstance(values, dict) or phase_id not in values:
            return
        values = dict(values)
        values.pop(phase_id, None)
        self.storage.set_runtime(
            PHASE_ABANDONMENT_CHECKPOINT_RUNTIME_KEY, values
        )

    def _phase_abandonment_safety(
        self,
        phase: dict[str, Any],
        observation: dict[str, Any],
    ) -> dict[str, Any]:
        """Accept only a source-verified sanctuary as terminalization safety."""

        current = self._observation_room(observation)
        verified = self._verified_safe_staging(current)
        checkpoint = self._phase_abandonment_checkpoint(phase)
        destination = (
            checkpoint.get("safe_ending")
            if isinstance(checkpoint, dict)
            and isinstance(checkpoint.get("safe_ending"), dict)
            else None
        )
        if verified is not None:
            return {
                "met": True,
                "current_room_id": current,
                "safe_ending": redact(verified),
                "verified_room": redact(verified),
            }
        return {
            "met": False,
            "reason": (
                "phase abandonment is verified and the current room is not a "
                "source-verified sanctuary"
            ),
            "current_room_id": current,
            "safe_ending": redact(destination),
        }

    def _phase_exhaustion_safety(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any],
        observation: dict[str, Any],
    ) -> dict[str, Any]:
        """Accept any current verified sanctuary as a safe exhaustion boundary."""

        current = self._observation_room(observation)
        verified = self._verified_safe_staging(current)
        if verified is not None:
            return {
                "met": True,
                "current_room_id": current,
                "safe_ending": redact(verified),
                "verified_room": redact(verified),
            }
        checkpoint = self._phase_exhaustion_checkpoint(phase)
        destination = (
            checkpoint.get("safe_ending")
            if isinstance(checkpoint, dict)
            and isinstance(checkpoint.get("safe_ending"), dict)
            else None
        )
        return {
            "met": False,
            "reason": (
                "phase budget is exhausted and the current room is not a "
                "source-verified sanctuary"
            ),
            "current_room_id": current,
            "safe_ending": redact(destination),
        }

    def _ensure_phase_exhaustion_plan(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any],
        observation: dict[str, Any],
        *,
        grounding: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Install a one-step, source-verified evacuation plan when needed."""

        checkpoint = self._phase_exhaustion_checkpoint(phase)
        if checkpoint is None:
            return None
        destination = (
            checkpoint.get("safe_ending")
            if isinstance(checkpoint.get("safe_ending"), dict)
            else None
        )
        if destination is None:
            destination = self._phase_exhaustion_destination(goal, observation)
            if destination is not None:
                values = self.storage.get_runtime(
                    PHASE_EXHAUSTION_CHECKPOINT_RUNTIME_KEY, {}
                )
                if isinstance(values, dict):
                    values = dict(values)
                    values[phase["id"]] = {
                        **checkpoint,
                        "safe_ending": destination,
                    }
                    self.storage.set_runtime(
                        PHASE_EXHAUSTION_CHECKPOINT_RUNTIME_KEY, values
                    )
                    checkpoint = values[phase["id"]]
        if not isinstance(destination, dict):
            return None
        verified = self._verified_safe_staging(destination.get("room_id"))
        if verified is None:
            return None
        room_id = int(verified["room_id"])

        existing = self._execution_plan(goal)
        ending = existing.get("safe_ending") if isinstance(existing, dict) else None
        if (
            isinstance(ending, dict)
            and str(ending.get("room_id")) == str(room_id)
            and str(ending.get("step_id") or "")
        ):
            return existing

        step_id = "phase-exhaustion-safe-return"
        return self._store_execution_plan(
            goal,
            {
                "summary": (
                    "Return to source-verified safety before closing the exhausted "
                    "campaign phase."
                ),
                "steps": [
                    {
                        "id": step_id,
                        "outcome": (
                            f"Reach source-verified safe room {room_id} before the "
                            "exhausted phase is finalized."
                        ),
                        "tool": "travel",
                        "verification": f"Current room id is {room_id}.",
                    }
                ],
                "safe_ending": {
                    "room_id": room_id,
                    "step_id": step_id,
                    "rationale": (
                        "Budget exhaustion is a controller safety boundary; use the "
                        "nearest retained source-verified sanctuary before replanning."
                    ),
                },
                "assumptions": [],
                "revision_reason": "Campaign phase budget exhausted outside safety.",
            },
            grounding=grounding,
            revision=existing is not None,
        )

    def _structured_phase_exhaustion_return_action(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any] | None,
        observation: dict[str, Any],
        execution_plan: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Return directly to safety without waiting on another model round trip."""

        checkpoint = self._phase_exhaustion_checkpoint(phase)
        if checkpoint is None or not isinstance(phase, dict):
            return None
        if self._phase_exhaustion_safety(goal, phase, observation).get("met") is True:
            return None
        if not isinstance(execution_plan, dict):
            return None
        ending = execution_plan.get("safe_ending")
        if not isinstance(ending, dict):
            return None
        destination = self._verified_safe_staging(ending.get("room_id"))
        step_id = str(ending.get("step_id") or "")
        if destination is None or not step_id:
            return None
        return {
            "tool": "travel",
            "arguments": {"to": int(destination["room_id"])},
            "rationale": (
                "The phase budget is exhausted; return directly to the retained "
                "source-verified sanctuary before finalizing the phase."
            ),
            "expected_observation": {"room_id": int(destination["room_id"])},
            "plan_step_id": step_id,
            "safety_recovery": True,
        }

    def _ensure_phase_abandonment_plan(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any],
        observation: dict[str, Any],
        *,
        grounding: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Install the sole allowed plan while abandonment awaits safety."""

        checkpoint = self._phase_abandonment_checkpoint(phase)
        if checkpoint is None:
            return None
        destination = (
            checkpoint.get("safe_ending")
            if isinstance(checkpoint.get("safe_ending"), dict)
            else None
        )
        if destination is None:
            destination = self._phase_exhaustion_destination(goal, observation)
            if destination is not None:
                values = self.storage.get_runtime(
                    PHASE_ABANDONMENT_CHECKPOINT_RUNTIME_KEY, {}
                )
                if isinstance(values, dict):
                    values = dict(values)
                    values[phase["id"]] = {
                        **checkpoint,
                        "safe_ending": destination,
                    }
                    self.storage.set_runtime(
                        PHASE_ABANDONMENT_CHECKPOINT_RUNTIME_KEY, values
                    )
                    checkpoint = values[phase["id"]]
        if not isinstance(destination, dict):
            return None
        verified = self._verified_safe_staging(destination.get("room_id"))
        if verified is None:
            return None
        room_id = int(verified["room_id"])

        existing = self._execution_plan(goal)
        ending = existing.get("safe_ending") if isinstance(existing, dict) else None
        existing_steps = (
            existing.get("steps", []) if isinstance(existing, dict) else []
        )
        if (
            isinstance(ending, dict)
            and str(ending.get("room_id")) == str(room_id)
            and str(ending.get("step_id") or "")
            and isinstance(existing_steps, list)
            and len(existing_steps) == 1
            and isinstance(existing_steps[0], dict)
            and str(existing_steps[0].get("id") or "")
            == str(ending.get("step_id") or "")
            and existing_steps[0].get("tool") == "travel"
        ):
            return existing

        step_id = "phase-abandonment-safe-return"
        return self._store_execution_plan(
            goal,
            {
                "summary": (
                    "Return to source-verified safety before closing the abandoned "
                    "campaign phase."
                ),
                "steps": [
                    {
                        "id": step_id,
                        "outcome": (
                            f"Reach source-verified safe room {room_id} before the "
                            "abandoned phase is finalized."
                        ),
                        "tool": "travel",
                        "verification": f"Current room id is {room_id}.",
                    }
                ],
                "safe_ending": {
                    "room_id": room_id,
                    "step_id": step_id,
                    "rationale": (
                        "Verified abandonment is a controller safety boundary; "
                        "survival and safe return precede terminal phase state."
                    ),
                },
                "assumptions": [],
                "revision_reason": (
                    "Campaign phase abandonment was verified outside safety."
                ),
            },
            grounding=grounding,
            revision=existing is not None,
        )

    def _structured_phase_abandonment_return_action(
        self,
        phase: dict[str, Any] | None,
        observation: dict[str, Any],
        execution_plan: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Return directly to safety while a terminal failure is deferred."""

        checkpoint = self._phase_abandonment_checkpoint(phase)
        if checkpoint is None or not isinstance(phase, dict):
            return None
        if self._phase_abandonment_safety(phase, observation).get("met") is True:
            return None
        if not isinstance(execution_plan, dict):
            return None
        ending = execution_plan.get("safe_ending")
        if not isinstance(ending, dict):
            return None
        destination = self._verified_safe_staging(ending.get("room_id"))
        step_id = str(ending.get("step_id") or "")
        if destination is None or not step_id:
            return None
        return {
            "tool": "travel",
            "arguments": {"to": int(destination["room_id"])},
            "rationale": (
                "The phase abandonment is verified; return directly to the "
                "retained source-verified sanctuary before finalizing it."
            ),
            "expected_observation": {"room_id": int(destination["room_id"])},
            "plan_step_id": step_id,
            "safety_recovery": True,
        }

    def _evaluate_campaign_phase(
        self,
        goal: dict[str, Any],
        run: dict[str, Any],
        phase: dict[str, Any] | None,
        observation: dict[str, Any],
    ) -> PhaseOutcome:
        """Latch a phase outcome until its model-selected safe ending is reached."""

        if phase is None:
            return self.campaign.evaluate_phase(goal, run, phase, observation)
        safety = self._safe_ending_reached(goal, observation)
        abandonment_allowed = self._verified_safe_staging(
            self._observation_room(observation)
        ) is not None
        abandonment_checkpoint = self._phase_abandonment_checkpoint(phase)
        if abandonment_checkpoint is not None:
            abandonment_safety = self._phase_abandonment_safety(
                phase, observation
            )
            if abandonment_safety.get("met") is not True:
                return PhaseOutcome(
                    False,
                    False,
                    phase,
                    {
                        "reason": abandonment_checkpoint.get("reason"),
                        "abandonment": abandonment_checkpoint.get("abandonment"),
                        "abandonment_deferred": True,
                        "safe_ending": abandonment_safety,
                        "checkpoint": redact(abandonment_checkpoint),
                    },
                )
            finished = self.storage.transition_campaign_phase(
                str(phase["id"]),
                "failed",
                reason=str(abandonment_checkpoint.get("reason")),
                resume_parent=False,
            )
            self._clear_phase_abandonment_checkpoint(str(phase["id"]))
            return PhaseOutcome(
                False,
                True,
                finished,
                {
                    "reason": abandonment_checkpoint.get("reason"),
                    "abandonment": abandonment_checkpoint.get("abandonment"),
                    "safe_ending": abandonment_safety,
                    "terminal_deferred": False,
                },
            )
        persisted_blocker = self._campaign_phase_grounding_blocker(
            phase,
            observation,
            goal_id=str(goal.get("id") or ""),
        )
        if (
            isinstance(persisted_blocker, dict)
            and persisted_blocker.get("kind")
            in {
                "invalid_farm_phase_outcome",
                "invalid_combat_training_phase_outcome",
                "invalid_prepare_combat_phase_outcome",
            }
        ):
            # This guard must run before completion-checkpoint reconciliation.
            # Older controller builds could persist and latch a farm whose sole
            # outcome was "autopilot launched"; otherwise the checkpoint path
            # keeps stopping the keeper before the normal grounding gate runs.
            self._clear_phase_completion_checkpoint(str(phase["id"]))
            reason = str(
                persisted_blocker.get("guidance")
                or "persisted keeper phase has no observable outcome"
            )
            finished = self.storage.transition_campaign_phase(
                str(phase["id"]),
                "failed",
                reason=reason,
                resume_parent=False,
            )
            self.storage.emit_event(
                "campaign.phase.grounding_rejected",
                "Retired a persisted phase whose action-only outcome was not observable",
                severity="warning",
                interesting=False,
                goal_id=goal.get("id"),
                data={
                    "phase_id": phase.get("id"),
                    "blocker": redact(persisted_blocker),
                    "strategic_goal_preserved": True,
                },
            )
            return PhaseOutcome(
                False,
                True,
                finished,
                {
                    "reason": reason,
                    "grounding_blocker": redact(persisted_blocker),
                },
            )
        support_completion = self._research_exhaustion_support_completion(
            goal, phase, observation
        )
        if support_completion is not None:
            # Old controller builds could latch this controller-owned fallback
            # merely because a read-only equipment call returned successfully.
            # Its only legitimate completion is a material retry-state delta.
            stale_checkpoint = self._phase_completion_checkpoint(phase)
            if (
                stale_checkpoint is not None
                and stale_checkpoint.get("completion") != support_completion
            ):
                self._clear_phase_completion_checkpoint(str(phase["id"]))
            if support_completion.get("all_met") is not True:
                return PhaseOutcome(False, False, phase, support_completion)
            checkpoint = self._phase_completion_checkpoint(phase)
            safety = self._safe_ending_reached(goal, observation)
            if checkpoint is not None:
                if safety.get("met") is True:
                    outcome = self.campaign.complete_phase(
                        run, phase, checkpoint["completion"]
                    )
                    self._clear_phase_completion_checkpoint(str(phase["id"]))
                    return outcome
                return PhaseOutcome(
                    False,
                    False,
                    phase,
                    {
                        **checkpoint["completion"],
                        "completion_deferred": True,
                        "safe_ending": safety,
                    },
                )
            if safety.get("met") is True:
                return self.campaign.complete_phase(run, phase, support_completion)
            checkpoint = self._latch_phase_completion(
                goal, run, phase, support_completion
            )
            return PhaseOutcome(
                False,
                False,
                phase,
                {
                    **support_completion,
                    "completion_deferred": True,
                    "safe_ending": safety,
                    "checkpoint": redact(checkpoint),
                },
            )
        if self._research_phase_requires_farm_recipe(phase):
            # ``phase_action_succeeded`` proves only that the adapter returned.
            # A progression-research phase is useful only when that result can
            # be converted into an executable farm recipe which does not
            # contradict retained route, stagnation, or survivability evidence.
            # Previewing with completion disabled preserves normal criterion and
            # abandonment evaluation without letting a successful lookup end the
            # phase prematurely.
            preview = self.campaign.evaluate_phase(
                goal,
                run,
                phase,
                observation,
                allow_completion=False,
                allow_abandonment=abandonment_allowed,
            )
            if preview.detail.get("abandonment_deferred") is True:
                checkpoint = self._latch_phase_abandonment(
                    goal, run, phase, preview.detail, observation
                )
                return PhaseOutcome(
                    False,
                    False,
                    phase,
                    {
                        **preview.detail,
                        "safe_ending": self._phase_abandonment_safety(
                            phase, observation
                        ),
                        "checkpoint": redact(checkpoint),
                    },
                )
            if preview.failed:
                return preview
            phase = preview.phase if isinstance(preview.phase, dict) else phase
            if preview.detail.get("all_met") is True:
                validation = self._research_farm_recipe_validation(
                    goal, run, phase, observation
                )
                phase = self._persist_research_recipe_validation(phase, validation)
                if validation.get("status") != "selected":
                    # A checkpoint written by the old lookup-only behavior must
                    # not survive the migration and complete this phase later.
                    self._clear_phase_completion_checkpoint(str(phase["id"]))
                    exhaustion = self._record_research_recipe_exhaustion(
                        goal, run, phase, validation, observation
                    )
                    reason = (
                        "progression lookup returned no executable non-quarantined "
                        "farm recipe"
                    )
                    finished = self.storage.transition_campaign_phase(
                        str(phase["id"]),
                        "failed",
                        reason=reason,
                        resume_parent=False,
                    )
                    return PhaseOutcome(
                        False,
                        True,
                        finished,
                        {
                            **preview.detail,
                            "all_met": False,
                            "action_criteria_met": True,
                            "completion_deferred": False,
                            "reason": reason,
                            "recipe_validation": redact(validation),
                            "research_exhaustion": redact(exhaustion),
                            "external_blocker_verified": (
                                int(exhaustion.get("repeat_count", 0) or 0) >= 2
                            ),
                        },
                    )
        checkpoint = self._phase_completion_checkpoint(phase)
        safety = self._safe_ending_reached(goal, observation)
        if checkpoint is not None:
            if safety.get("met") is True:
                outcome = self.campaign.complete_phase(
                    run, phase, checkpoint["completion"]
                )
                self._clear_phase_completion_checkpoint(phase["id"])
                return outcome
            return PhaseOutcome(
                False,
                False,
                phase,
                {
                    **checkpoint["completion"],
                    "completion_deferred": True,
                    "safe_ending": safety,
                },
            )
        outcome = self.campaign.evaluate_phase(
            goal,
            run,
            phase,
            observation,
            allow_completion=safety.get("met") is True,
            allow_abandonment=abandonment_allowed,
        )
        if outcome.detail.get("abandonment_deferred") is True:
            checkpoint = self._latch_phase_abandonment(
                goal, run, phase, outcome.detail, observation
            )
            return PhaseOutcome(
                False,
                False,
                phase,
                {
                    **outcome.detail,
                    "safe_ending": self._phase_abandonment_safety(
                        phase, observation
                    ),
                    "checkpoint": redact(checkpoint),
                },
            )
        if outcome.detail.get("completion_deferred") is not True:
            return outcome
        current_phase = outcome.phase if isinstance(outcome.phase, dict) else phase
        checkpoint = self._latch_phase_completion(
            goal, run, current_phase, outcome.detail
        )
        return PhaseOutcome(
            False,
            False,
            current_phase,
            {
                **outcome.detail,
                "safe_ending": safety,
                "checkpoint": redact(checkpoint),
            },
        )

    @staticmethod
    def _research_phase_requires_farm_recipe(
        phase: dict[str, Any] | None,
    ) -> bool:
        """Whether successful research must yield a typed farm handoff."""

        if not isinstance(phase, dict) or phase.get("kind") != "research_progression":
            return False
        return any(
            isinstance(criterion, dict)
            and criterion.get("kind") == "phase_action_succeeded"
            and "hunting_grounds" in criterion.get("tools", [])
            for criterion in phase.get("success_criteria", [])
        )

    def _research_farm_candidates(
        self, phase: dict[str, Any]
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        """Extract ordered room/prey pairs from successful research attempts."""

        attempts = [
            attempt
            for attempt in self.storage.phase_attempts(str(phase["id"]), limit=200)
            if attempt.get("status") == "succeeded"
            and attempt.get("semantic_action") == "hunting_grounds"
            and isinstance(attempt.get("result"), dict)
        ]
        candidates: list[dict[str, Any]] = []
        seen: set[tuple[int, str]] = set()

        def room_id(value: Any) -> int | None:
            if isinstance(value, dict):
                value = next(
                    (
                        value.get(key)
                        for key in ("room", "room_id", "id", "num")
                        if value.get(key) is not None
                    ),
                    None,
                )
            try:
                parsed = int(value)
            except (TypeError, ValueError):
                return None
            return parsed if parsed > 0 else None

        def add_candidate(
            *,
            target: Any,
            room: Any,
            attempt: dict[str, Any],
            source: dict[str, Any],
        ) -> None:
            parsed_room = room_id(room)
            parsed_target = " ".join(str(target or "").casefold().split())
            if parsed_room is None or not parsed_target:
                return
            identity = (parsed_room, parsed_target)
            if identity in seen:
                return
            seen.add(identity)
            candidates.append(
                {
                    "room": parsed_room,
                    "target": parsed_target,
                    "attempt_id": attempt.get("id"),
                    "source": redact(source),
                }
            )

        # The newest lookup represents the character's newest level and world
        # evidence. Retain its advertised ordering: best_room first, followed
        # by the adapter's alternate rooms for that same prey.
        for attempt in reversed(attempts):
            result = dict(attempt["result"])
            for wrapper in ("result", "data"):
                nested = result.get(wrapper)
                if isinstance(nested, dict) and not any(
                    key in result
                    for key in ("prey", "candidates", "grounds", "best_room", "room")
                ):
                    result = nested
                    break
            entries = next(
                (
                    result.get(key)
                    for key in ("prey", "candidates", "grounds")
                    if isinstance(result.get(key), list)
                ),
                None,
            )
            if isinstance(entries, list):
                for entry in entries:
                    if not isinstance(entry, dict):
                        continue
                    target = next(
                        (
                            entry.get(key)
                            for key in ("creature", "target", "prey", "name")
                            if entry.get(key)
                        ),
                        None,
                    )
                    rooms: list[Any] = [
                        entry.get(key)
                        for key in ("best_room", "bestRoom", "room", "room_id")
                        if entry.get(key) is not None
                    ]
                    if isinstance(entry.get("rooms"), list):
                        rooms.extend(entry["rooms"])
                    for candidate_room in rooms:
                        add_candidate(
                            target=target,
                            room=candidate_room,
                            attempt=attempt,
                            source=entry,
                        )
                continue

            direct_target = next(
                (
                    result.get(key)
                    for key in ("creature", "target", "prey", "name")
                    if result.get(key)
                ),
                None,
            )
            direct_room = next(
                (
                    result.get(key)
                    for key in ("best_room", "bestRoom", "room", "room_id")
                    if result.get(key) is not None
                ),
                None,
            )
            if direct_target is not None:
                add_candidate(
                    target=direct_target,
                    room=direct_room,
                    attempt=attempt,
                    source=result,
                )
            generates = result.get("generates")
            if direct_room is not None and isinstance(generates, list):
                for generated in generates:
                    if not isinstance(generated, dict):
                        continue
                    add_candidate(
                        target=next(
                            (
                                generated.get(key)
                                for key in ("creature", "target", "name")
                                if generated.get(key)
                            ),
                            None,
                        ),
                        room=direct_room,
                        attempt=attempt,
                        source=generated,
                    )
        return candidates, attempts

    def _research_farm_recipe_validation(
        self,
        goal: dict[str, Any],
        run: dict[str, Any],
        phase: dict[str, Any],
        observation: dict[str, Any],
    ) -> dict[str, Any]:
        """Select a grounded research candidate using success-aware preferences.

        Research ``avoid_rooms`` are diversity hints, not safety evidence. A finite
        progression table will naturally return the same useful rooms at adjacent
        levels, so hard-excluding those rooms eventually makes every valid recipe
        disappear. Prefer a recently successful exact room/prey tactic, then a new
        room, then a soft-avoided room; retained safety and route evidence still
        rejects any candidate through the ordinary grounding gate.
        """

        candidates, attempts = self._research_farm_candidates(phase)
        context = phase.get("context")
        context = context if isinstance(context, dict) else {}
        avoid_rooms = self._recent_research_avoid_rooms(run)
        explicit_avoid = context.get("avoid_rooms")
        if isinstance(explicit_avoid, list):
            avoid_rooms.update(
                str(value)
                for value in explicit_avoid
                if isinstance(value, (int, str)) and str(value).strip()
            )
        successful_tactics = self._recent_successful_farm_tactics(run)
        successful_rooms = {room for room, _target in successful_tactics}
        # Successful evidence is stronger than an older diversity hint. The exact
        # tactic is ranked first below, while a different prey in the same room
        # remains only a soft preference question.
        avoid_rooms.difference_update(successful_rooms)

        def preference(
            indexed: tuple[int, dict[str, Any]],
        ) -> tuple[int, int, int]:
            index, candidate = indexed
            key = (
                str(candidate.get("room")),
                normalize(str(candidate.get("target") or "")),
            )
            if key in successful_tactics:
                return (0, successful_tactics[key], index)
            if str(candidate.get("room")) not in avoid_rooms:
                return (1, 0, index)
            return (2, 0, index)

        ordered_candidates = [
            candidate
            for _index, candidate in sorted(
                enumerate(candidates), key=preference
            )
        ]
        rejected: list[dict[str, Any]] = []
        selected: dict[str, Any] | None = None
        for candidate in ordered_candidates:
            proposed = {
                "kind": "farm",
                "context": {
                    "room": candidate["room"],
                    "target": candidate["target"],
                    "use_safe_spots": True,
                    "flee_below": FARM_FLEE_THRESHOLD,
                    "fight_above_vigor": FARM_FIGHT_VIGOR,
                },
            }
            blocker = self._campaign_phase_grounding_blocker(
                proposed,
                observation,
                avoid_rooms=avoid_rooms,
                goal_id=str(goal.get("id") or ""),
            )
            if blocker is None:
                selected = {
                    **proposed["context"],
                    "research_phase_id": phase.get("id"),
                    "research_attempt_id": candidate.get("attempt_id"),
                    "source_evidence": candidate.get("source"),
                    "selection_basis": (
                        "recent_successful_tactic"
                        if (
                            str(candidate.get("room")),
                            normalize(str(candidate.get("target") or "")),
                        )
                        in successful_tactics
                        else (
                            "grounded_new_room"
                            if str(candidate.get("room")) not in avoid_rooms
                            else "grounded_soft_avoided_room"
                        )
                    ),
                }
                break
            rejected.append(
                {
                    "room": candidate["room"],
                    "target": candidate["target"],
                    "blocker": redact(blocker),
                }
            )

        semantic_outcome = {
            "status": "selected" if selected is not None else (
                "no_usable_candidate" if attempts else "awaiting_hunting_grounds"
            ),
            "candidate_count": len(candidates),
            "rejected": [
                {
                    "room": item.get("room"),
                    "target": normalize(str(item.get("target") or "")),
                    "kind": str(deep_get(item, "blocker.kind") or ""),
                }
                for item in sorted(
                    rejected,
                    key=lambda item: (
                        str(item.get("room")),
                        normalize(str(item.get("target") or "")),
                        str(deep_get(item, "blocker.kind") or ""),
                    ),
                )
            ],
            "selected": (
                {
                    key: selected.get(key)
                    for key in (
                        "room",
                        "target",
                        "use_safe_spots",
                        "flee_below",
                        "fight_above_vigor",
                    )
                }
                if selected is not None
                else None
            ),
        }
        # Research identity describes the decision-relevant candidate outcome.
        # Raw adapter payloads, ordering, timestamps, and soft avoid-room hints
        # must not let an equivalent empty/rejected set masquerade as new work.
        fingerprint = json_hash(semantic_outcome)
        if selected is not None:
            self._clear_research_recipe_exhaustion(str(goal.get("id") or ""))
            return {
                "status": "selected",
                "fingerprint": fingerprint,
                "recipe": selected,
                "candidate_count": len(candidates),
                "rejected": rejected,
            }
        return {
            "status": semantic_outcome["status"],
            "fingerprint": fingerprint,
            "candidate_count": len(candidates),
            "rejected": rejected,
            "attempt_ids": [attempt.get("id") for attempt in attempts],
        }

    @staticmethod
    def _research_exhaustion_identity(value: dict[str, Any]) -> dict[str, Any]:
        """Canonicalize only the semantic reason research produced no recipe."""

        try:
            candidate_count = max(0, int(value.get("candidate_count", 0) or 0))
        except (TypeError, ValueError):
            candidate_count = 0
        rejected = sorted(
            [
                {
                    "room": item.get("room"),
                    "target": normalize(str(item.get("target") or "")),
                    "kind": str(deep_get(item, "blocker.kind") or ""),
                }
                for item in value.get("rejected", [])
                if isinstance(item, dict)
            ],
            key=canonical_json,
        )
        status = str(value.get("status") or "").strip()
        if not status:
            status = "no_usable_candidate"
        return {
            "status": status,
            "candidate_count": candidate_count,
            "rejected": rejected,
        }

    def _persist_research_recipe_validation(
        self, phase: dict[str, Any], validation: dict[str, Any]
    ) -> dict[str, Any]:
        """Durably bind research evidence to its validation result once."""

        context = phase.get("context")
        context = dict(context) if isinstance(context, dict) else {}
        prior = context.get("recipe_validation")
        comparable = {
            key: validation.get(key)
            for key in ("status", "fingerprint", "candidate_count", "recipe", "rejected")
            if key in validation
        }
        if prior == comparable:
            return phase
        context["recipe_validation"] = comparable
        if validation.get("status") == "selected":
            context["farm_recipe"] = validation.get("recipe")
        else:
            context.pop("farm_recipe", None)
        return self.storage.update_campaign_phase_guardrails(
            str(phase["id"]),
            abandon_predicates=list(phase.get("abandon_predicates", [])),
            context=context,
            reason="validated hunting-ground evidence into an executable farm recipe",
        )

    def _record_research_recipe_exhaustion(
        self,
        goal: dict[str, Any],
        run: dict[str, Any],
        phase: dict[str, Any],
        validation: dict[str, Any],
        observation: dict[str, Any],
    ) -> dict[str, Any]:
        """Count identical exhausted research results across replacement phases."""

        rejection_kinds = {
            str(deep_get(item, "blocker.kind") or "")
            for item in validation.get("rejected", [])
            if isinstance(item, dict)
        }
        if rejection_kinds and rejection_kinds <= {"recent_research_avoid_room"}:
            # Defensive compatibility for a validation produced by an older
            # controller. Novelty alone can never prove progression impossible.
            return {
                "fingerprint": str(validation.get("fingerprint") or ""),
                "repeat_count": 0,
                "phase_ids": [],
                "candidate_count": validation.get("candidate_count", 0),
                "rejected": redact(validation.get("rejected", [])),
                "recorded_at": timestamp(),
                "suppressed": True,
                "guidance": (
                    "Recent-room avoidance is a soft diversity preference; retry "
                    "a grounded candidate unless durable safety or route evidence blocks it."
                ),
            }

        goal_id = str(goal.get("id") or "")
        semantic_identity = self._research_exhaustion_identity(validation)
        fingerprint = json_hash(semantic_identity)
        values = self.storage.get_runtime(
            RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, {}
        )
        values = dict(values) if isinstance(values, dict) else {}
        prior = values.get(goal_id)
        prior = prior if isinstance(prior, dict) else {}
        prior_identity = (
            prior.get("semantic_identity")
            if isinstance(prior.get("semantic_identity"), dict)
            else self._research_exhaustion_identity(prior)
        )
        retry_state = self._research_retry_state(goal, observation)
        retry_state_fingerprint = json_hash(retry_state)
        phase_ids = (
            list(prior.get("phase_ids", []))
            if prior_identity == semantic_identity
            and isinstance(prior.get("phase_ids"), list)
            else []
        )
        phase_id = str(phase.get("id") or "")
        if phase_id and phase_id not in phase_ids:
            phase_ids.append(phase_id)
        record = {
            "fingerprint": fingerprint,
            "semantic_identity": semantic_identity,
            "repeat_count": len(phase_ids),
            "phase_ids": phase_ids[-10:],
            "candidate_count": validation.get("candidate_count", 0),
            "rejected": redact(validation.get("rejected", [])),
            "retry_state_schema": RESEARCH_RETRY_STATE_SCHEMA_VERSION,
            "retry_state": retry_state,
            "retry_state_fingerprint": retry_state_fingerprint,
            "recorded_at": timestamp(),
            "guidance": (
                "Every source-derived room/prey candidate conflicts with retained "
                "quarantine, stagnation, or route evidence. New world, route, or "
                "survivability evidence is required before retrying this lookup."
            ),
        }
        values[goal_id] = record
        self.storage.set_runtime(RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, values)
        blocker = {
            "status": (
                "verified" if record["repeat_count"] >= 2 else "candidate"
            ),
            "kind": "no_usable_farm_recipe",
            **record,
        }
        self.storage.update_campaign_memory(run["id"], external_blocker=blocker)
        self.storage.emit_event(
            "campaign.research.exhausted",
            (
                "Progression research repeated the same fully excluded candidate set"
                if record["repeat_count"] >= 2
                else "Progression research returned only excluded farm candidates"
            ),
            severity="warning",
            interesting=record["repeat_count"] >= 2,
            goal_id=goal_id,
            data={
                "run_id": run.get("id"),
                "phase_id": phase.get("id"),
                "external_blocker": redact(blocker),
                "strategic_goal_preserved": True,
            },
        )
        return record

    def _researched_farm_phase(
        self,
        goal: dict[str, Any],
        research_phase: dict[str, Any],
        recipe: dict[str, Any],
        observation: dict[str, Any],
    ) -> dict[str, Any]:
        """Build a bounded deterministic farm phase from a validated recipe."""

        current = deep_get(
            observation,
            "status.vitals.health.max",
            deep_get(observation, "look.vitals.health.max"),
        )
        context = research_phase.get("context")
        context = context if isinstance(context, dict) else {}
        milestone = context.get("next_hp_milestone")
        if not isinstance(milestone, (int, float)) or isinstance(milestone, bool):
            milestone = int(current) + 1 if isinstance(current, (int, float)) else 1
        public_targets = [
            criterion.get("value")
            for criterion in goal.get("success_criteria", [])
            if isinstance(criterion, dict)
            and criterion.get("kind") == "numeric_threshold"
            and str(criterion.get("metric") or "")
            in {
                "max_health",
                "status.vitals.health.max",
                "look.vitals.health.max",
            }
            and isinstance(criterion.get("value"), (int, float))
            and not isinstance(criterion.get("value"), bool)
        ]
        if public_targets:
            milestone = min(float(milestone), min(float(value) for value in public_targets))
        if isinstance(current, int) and float(milestone).is_integer():
            milestone = int(milestone)
        return {
            "kind": "farm",
            "objective": (
                f"Farm {recipe['target']} in room {recipe['room']} until maximum HP "
                f"reaches {milestone}."
            ),
            "success_criteria": [
                {
                    "id": f"researched-farm-hp-{milestone}",
                    "kind": "numeric_threshold",
                    "metric": "status.vitals.health.max",
                    "operator": ">=",
                    "value": milestone,
                }
            ],
            "abandon_predicates": [],
            "budget": {"max_actions": 120, "max_minutes": 180},
            "context": {
                **recipe,
                "research_fingerprint": deep_get(
                    research_phase, "context.recipe_validation.fingerprint"
                ),
                "next_hp_milestone": milestone,
                "deterministic_research_handoff": True,
            },
            "rationale": (
                "Use the first source-derived hunting-ground candidate that passed "
                "the controller's retained quarantine, stagnation, and route checks."
            ),
        }

    def _handoff_completed_research_phase(
        self,
        goal: dict[str, Any],
        run: dict[str, Any],
        research_phase: dict[str, Any] | None,
        observation: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Start the validated farm directly, without another model decision."""

        if not self._research_phase_requires_farm_recipe(research_phase):
            return None
        assert isinstance(research_phase, dict)
        context = research_phase.get("context")
        context = context if isinstance(context, dict) else {}
        recipe = context.get("farm_recipe")
        if not isinstance(recipe, dict):
            validation = self._research_farm_recipe_validation(
                goal, run, research_phase, observation
            )
            if validation.get("status") != "selected":
                return None
            recipe = validation["recipe"]
        proposed = self._researched_farm_phase(
            goal, research_phase, recipe, observation
        )
        blocker = self._campaign_phase_grounding_blocker(
            proposed,
            observation,
            avoid_rooms=self._recent_research_avoid_rooms(run),
            goal_id=str(goal.get("id") or ""),
        )
        if blocker is not None:
            return None
        next_phase = self.campaign.apply_manager_decision(
            run,
            goal,
            {
                "decision": "start_phase",
                "phase": proposed,
                "rationale": "Deterministic handoff from validated progression research.",
            },
            observation=observation,
        )
        if next_phase is not None:
            self.storage.emit_event(
                "campaign.research.recipe_selected",
                (
                    f"Selected {recipe['target']} in room {recipe['room']} from "
                    "validated progression research"
                ),
                severity="notice",
                interesting=False,
                goal_id=goal.get("id"),
                data={
                    "research_phase_id": research_phase.get("id"),
                    "farm_phase_id": next_phase.get("id"),
                    "recipe": redact(recipe),
                    "model_decision_required": False,
                },
            )
        return next_phase

    def _safe_ending_reached(
        self, goal: dict[str, Any], observation: dict[str, Any]
    ) -> dict[str, Any]:
        current = deep_get(
            observation,
            "look.room.num",
            deep_get(observation, "look.room_id"),
        )
        # Raza graduation is one-way, and the adapter can land in any of
        # several source-safe mainland rooms.  Once the goal-scoped exit event
        # exists, the current verified safe room outside Raza is the terminal
        # safe ending; an older model plan that says to return to Raza Inn must
        # never pull the character back toward the tutorial zone.
        if (
            self._goal_requires_raza_exit(goal)
            and self._raza_exit_event_recorded(goal)
            and not self._in_raza_zone(observation)
        ):
            verified = self._verified_safe_staging(current)
            if verified is not None:
                return {
                    "met": True,
                    "current_room_id": current,
                    "safe_ending": {
                        "room_id": current,
                        "name": self._observation_room_name(observation),
                        "basis": "verified_one_way_raza_exit",
                    },
                    "verified_room": redact(verified),
                }
        plan = self._execution_plan(goal)
        ending = plan.get("safe_ending") if isinstance(plan, dict) else None
        if not isinstance(ending, dict):
            return {"met": False, "reason": "no verified safe ending plan"}
        target = ending.get("room_id")
        if str(current) != str(target):
            return {
                "met": False,
                "reason": "planned safe ending has not been reached",
                "current_room_id": current,
                "safe_ending": redact(ending),
            }
        verified = self._verified_safe_staging(current)
        if verified is None:
            return {
                "met": False,
                "reason": "current room no longer has source-verified safe flags",
                "current_room_id": current,
                "safe_ending": redact(ending),
            }
        return {
            "met": True,
            "current_room_id": current,
            "safe_ending": redact(ending),
            "verified_room": redact(verified),
        }

    def _complete_goal_if_safe(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        completion: dict[str, Any],
    ) -> dict[str, Any] | None:
        checkpoint = self._latch_goal_completion(goal, completion)
        if checkpoint is None:
            return None
        safety = self._safe_ending_reached(goal, observation)
        if safety.get("met") is not True:
            return None
        latched_completion = checkpoint["completion"]
        done = self.storage.set_goal_completion(
            goal["id"],
            latched_completion,
            terminal="succeeded",
            reason="all criteria verified and the model-selected safe ending reached",
        )
        self.storage.complete_campaign_run(goal["id"], status="succeeded")
        self.storage.emit_event(
            "goal.succeeded",
            f"Goal succeeded safely: {goal['title']}",
            interesting=True,
            goal_id=goal["id"],
            data={"completion": latched_completion, "safe_ending": safety},
        )
        self.learning.record_success(done)
        self._clear_goal_completion_checkpoint(goal["id"])
        return done

    def _invalidate_execution_plan(self, goal: dict[str, Any], reason: str) -> bool:
        """Retire a plan that is no longer a valid basis for execution."""
        values = self.storage.get_runtime(EXECUTION_PLAN_RUNTIME_KEY, {})
        if not isinstance(values, dict):
            return False
        removed = values.pop(str(goal.get("id") or ""), None)
        if not isinstance(removed, dict):
            return False
        self.storage.set_runtime(EXECUTION_PLAN_RUNTIME_KEY, values)
        self.storage.emit_event(
            "planner.plan.invalidated",
            "Invalidated an execution plan that requires replanning",
            severity="warning",
            interesting=False,
            goal_id=goal.get("id"),
            data={
                "reason": str(reason)[:500],
                "plan_summary": str(removed.get("summary") or "")[:500],
                "last_action": redact(removed.get("last_action")),
            },
        )
        return True

    def _store_execution_plan(
        self,
        goal: dict[str, Any],
        raw_plan: Any,
        *,
        grounding: dict[str, Any],
        revision: bool,
    ) -> dict[str, Any]:
        if not isinstance(raw_plan, dict):
            raise ModelError("decision=plan requires an execution_plan object")
        summary = str(raw_plan.get("summary") or "").strip()
        steps = raw_plan.get("steps")
        assumptions = raw_plan.get("assumptions", [])
        plan_normalizations: list[dict[str, Any]] = []
        if isinstance(steps, list):
            actionable_steps = [
                step
                for step in steps
                if isinstance(step, dict) and step.get("tool") is not None
            ]
            if (
                len(actionable_steps) != len(steps)
                and 1 <= len(actionable_steps) <= EXECUTION_PLAN_MAX_STEPS
            ):
                plan_normalizations.append(
                    {
                        "kind": "removed_controller_owned_monitoring_steps",
                        "before": len(steps),
                        "after": len(actionable_steps),
                    }
                )
                steps = actionable_steps
            constraints = goal.get("constraints") if isinstance(goal.get("constraints"), dict) else {}
            if constraints.get("bank_before_hazard") is True and self._carried_currency(
                self.last_observation or {}
            ) <= 0:
                necessary_steps = [
                    step
                    for step in steps
                    if not (
                        isinstance(step, dict)
                        and step.get("tool") == "bank"
                        and "deposit" in str(step.get("outcome") or "").casefold()
                    )
                ]
                if len(necessary_steps) != len(steps) and necessary_steps:
                    plan_normalizations.append(
                        {
                            "kind": "removed_already_satisfied_zero_currency_deposit",
                            "before": len(steps),
                            "after": len(necessary_steps),
                        }
                    )
                    steps = necessary_steps
            ending = raw_plan.get("safe_ending")
            final_step = steps[-1] if steps and isinstance(steps[-1], dict) else None
            ending_step_id = (
                str(ending.get("step_id") or "").strip()
                if isinstance(ending, dict)
                else ""
            )
            final_step_id = (
                str(final_step.get("id") or "").strip()
                if isinstance(final_step, dict)
                else ""
            )
            final_outcome = (
                str(final_step.get("outcome") or "")
                if isinstance(final_step, dict)
                else ""
            )
            final_arguments = (
                final_step.get("arguments")
                if isinstance(final_step, dict)
                and isinstance(final_step.get("arguments"), dict)
                else {}
            )
            keeper_stop = (
                isinstance(final_step, dict)
                and final_step.get("tool") == "autopilot"
                and (
                    str(final_arguments.get("action") or "").casefold() == "stop"
                    or re.search(r"\bstop\b", final_outcome, re.IGNORECASE) is not None
                )
            )
            room_id = ending.get("room_id") if isinstance(ending, dict) else None
            if (
                keeper_stop
                and ending_step_id
                and ending_step_id == final_step_id
                and isinstance(room_id, int)
                and not isinstance(room_id, bool)
                and room_id > 0
                and len(steps) < EXECUTION_PLAN_MAX_STEPS
            ):
                existing_ids = {
                    str(step.get("id") or "")
                    for step in steps
                    if isinstance(step, dict)
                }
                safe_step_id = f"{ending_step_id}-safe-travel"
                suffix = 2
                while safe_step_id in existing_ids:
                    safe_step_id = f"{ending_step_id}-safe-travel-{suffix}"
                    suffix += 1
                steps = [
                    *steps,
                    {
                        "id": safe_step_id,
                        "outcome": f"Travel to source-verified safe room {room_id}.",
                        "tool": "travel",
                        "verification": f"Current room id is {room_id}.",
                    },
                ]
                raw_plan = {
                    **raw_plan,
                    "safe_ending": {**ending, "step_id": safe_step_id},
                }
                plan_normalizations.append(
                    {
                        "kind": "separated_keeper_stop_from_safe_ending",
                        "keeper_step_id": ending_step_id,
                        "safe_step_id": safe_step_id,
                        "room_id": room_id,
                    }
                )
        if (
            not summary
            or not isinstance(steps, list)
            or not 1 <= len(steps) <= EXECUTION_PLAN_MAX_STEPS
        ):
            count = len(steps) if isinstance(steps, list) else "non-array"
            raise ModelError(
                "execution_plan requires a summary and "
                f"1-{EXECUTION_PLAN_MAX_STEPS} ordered steps; received {count} step(s)"
            )
        if not isinstance(assumptions, list) or any(not isinstance(value, str) for value in assumptions):
            raise ModelError("execution_plan.assumptions must be an array of strings")
        run = self.storage.campaign_run(str(goal.get("id") or ""))
        phase = self.storage.active_campaign_phase(run["id"]) if run else None
        known_tools = {
            str(tool.get("name") or "") for tool in self._planner_tools(phase)
        }
        globally_known_tools = {
            str(tool.get("name") or "") for tool in self.broker.planner_tools()
        }
        globally_known_tools.update(PVP_TOOL_NAMES)
        globally_known_tools.add("knowledge_search")
        out_of_phase = [
            {
                "id": str(step.get("id") or f"step_{index + 1}"),
                "tool": step.get("tool"),
            }
            for index, step in enumerate(steps)
            if isinstance(step, dict)
            and isinstance(step.get("tool"), str)
            and step.get("tool") in globally_known_tools
            and step.get("tool") not in known_tools
        ]
        if out_of_phase:
            phase_kind = str(phase.get("kind") or "none") if phase else "none"
            rejected = ", ".join(
                f"{item['id']}={item['tool']}" for item in out_of_phase
            )
            raise ModelError(
                f"execution_plan crosses the active {phase_kind!r} phase boundary: "
                f"{rejected}; allowed tools for this phase: "
                + ", ".join(sorted(known_tools))
            )
        normalized_steps: list[dict[str, Any]] = []
        ids: set[str] = set()
        for index, raw_step in enumerate(steps):
            if not isinstance(raw_step, dict):
                raise ModelError(f"execution_plan step {index + 1} must be an object")
            step_id = str(raw_step.get("id") or "").strip()
            outcome = str(raw_step.get("outcome") or "").strip()
            verification = str(raw_step.get("verification") or "").strip()
            tool = raw_step.get("tool")
            repeat_count = raw_step.get("repeat_count", 1)
            if repeat_count is None:
                repeat_count = 1
            if not step_id or step_id in ids or not outcome or not verification:
                raise ModelError(
                    "execution_plan steps require unique non-empty id, outcome, and verification"
                )
            if (
                not isinstance(repeat_count, int)
                or isinstance(repeat_count, bool)
                or not 1 <= repeat_count <= 100
            ):
                raise ModelError(
                    f"execution_plan step {step_id} repeat_count must be an integer from 1 to 100"
                )
            if tool is not None and (not isinstance(tool, str) or tool not in known_tools):
                raise ModelError(f"execution_plan step {step_id} names unknown tool {tool!r}")
            if self._observation_only_act_step(
                {"tool": tool, "outcome": outcome}
            ):
                raise ModelError(
                    f"execution_plan step {step_id} uses act for an observation-only outcome; "
                    "use the appropriate read-only tool (such as look, status, or inventory), "
                    "and reserve act for use, unuse, get, drop, activate, eat, or go"
                )
            commerce_error = self._commerce_step_error(
                {
                    "tool": tool,
                    "outcome": outcome,
                    "verification": verification,
                }
            )
            if commerce_error is not None:
                raise ModelError(
                    f"execution_plan step {step_id} {commerce_error}"
                )
            protected_sale_error = self._protected_phase_sale_step_error(
                phase,
                {"tool": tool, "outcome": outcome, "verification": verification},
            )
            if protected_sale_error is not None:
                raise ModelError(
                    f"execution_plan step {step_id} {protected_sale_error}"
                )
            map_error = self._map_step_error(
                phase,
                {"tool": tool, "outcome": outcome, "verification": verification},
            )
            if map_error is not None:
                raise ModelError(f"execution_plan step {step_id} {map_error}")
            ids.add(step_id)
            normalized_step = {
                "id": step_id,
                "outcome": outcome[:600],
                "tool": tool,
                "verification": verification[:600],
            }
            if repeat_count > 1:
                normalized_step["repeat_count"] = repeat_count
            normalized_steps.append(normalized_step)
        sale_recovery_error = self._sale_recovery_plan_error(
            goal, normalized_steps
        )
        bank_error = self._bank_plan_error(
            normalized_steps, self.last_observation or {}
        )
        if bank_error is not None:
            raise ModelError(bank_error)
        direct_capability_error = self._direct_capability_plan_error(
            phase,
            normalized_steps,
            self.last_observation or {},
            assumptions,
        )
        if direct_capability_error is not None:
            raise ModelError(direct_capability_error)
        phase_required_sale_error = self._phase_required_sale_plan_error(
            phase, normalized_steps, self.last_observation or {}
        )
        if phase_required_sale_error is not None:
            raise ModelError(phase_required_sale_error)
        phase_inventory_error = self._phase_inventory_plan_error(
            phase, normalized_steps, self.last_observation or {}
        )
        if phase_inventory_error is not None:
            raise ModelError(phase_inventory_error)
        sale_grounding_error = self._targeted_sale_grounding_error(
            goal,
            phase,
            normalized_steps,
            self.last_observation or {},
        )
        if sale_grounding_error is not None:
            raise ModelError(sale_grounding_error)
        if sale_recovery_error is not None:
            raise ModelError(sale_recovery_error)
        funding_error = self._plan_funding_error(
            normalized_steps,
            self.last_observation or {},
        )
        if funding_error is not None:
            raise ModelError(funding_error)
        affordability_error = self._shop_plan_affordability_error(
            normalized_steps, self.last_observation or {}
        )
        if affordability_error is not None:
            raise ModelError(affordability_error)
        purchase = grounding.get("purchase_verification")
        if isinstance(purchase, dict) and not purchase.get("static_verified"):
            raise ModelError("execution plan cannot be verified because purchase feasibility is invalid")
        farm_intent = self._effective_farm_intent(goal)
        current_completion = self.criteria.evaluate(goal, self.last_observation or {})
        phase_exhaustion_pending = self._phase_exhaustion_checkpoint(phase) is not None
        phase_abandonment_pending = (
            self._phase_abandonment_checkpoint(phase) is not None
        )
        phase_terminal_pending = (
            phase_exhaustion_pending or phase_abandonment_pending
        )
        if not phase_terminal_pending:
            self._validate_direct_pvp_plan(goal, normalized_steps, current_completion)
        farm_work_remains = (
            False
            if phase_terminal_pending
            else self._keeper_combat_work_remains(goal, current_completion)
        )
        launch_indexes = [
            index
            for index, step in enumerate(normalized_steps)
            if self._autopilot_launch_step(step)
        ]
        if (
            isinstance(phase, dict)
            and phase.get("kind") == "train_ability"
            and self._campaign_phase_farm_intent(phase).get("assigned_room")
            is not None
            and any(step.get("tool") == "fight" for step in normalized_steps)
        ):
            raise ModelError(
                "a grounded combat-training phase cannot contain foreground fight; "
                "use one autopilot launch so the keeper owns combat between model turns"
            )
        if not farm_work_remains and launch_indexes:
            raise ModelError(
                "the bounded keeper-combat criterion is already met; the plan must not relaunch the farm keeper"
            )
        if (
            farm_work_remains
            and farm_intent.get("assigned_room") is not None
            and farm_intent.get("hunt")
        ):
            if not launch_indexes:
                raise ModelError(
                    "a structured farm goal plan requires one explicit autopilot launch step"
                )
            launch_index = launch_indexes[0]
            launch_text = canonical_json(normalized_steps[launch_index])
            assigned_room = str(farm_intent["assigned_room"])
            hunt_words = [
                word for word in normalize(farm_intent["hunt"]).split() if len(word) > 2
            ]
            if assigned_room not in launch_text or any(word not in normalize(launch_text) for word in hunt_words):
                raise ModelError(
                    "the farm launch step must name the goal-owned prey and exact assigned room"
                )
            observation = self.last_observation or {}
            weapon_error = self._farm_weapon_plan_error(
                normalized_steps,
                observation,
                launch_index=launch_index,
            )
            if weapon_error is not None:
                raise ModelError(weapon_error)
            current_room = deep_get(
                observation,
                "look.room.num",
                deep_get(observation, "look.room_id"),
            )
            launch_origin = self._farm_launch_origin(goal, observation, farm_intent)
            if launch_origin is None:
                raise ModelError(
                    "the farm plan has no source-verified safe staging room; "
                    "observe or reach a ROOM_SANCTUARY/ROOM_NO_COMBAT location first"
                )
            launch_room = int(launch_origin["room_id"])
            if str(current_room) != str(launch_room):
                prior_steps = normalized_steps[:launch_index]
                launch_origin_name = str(launch_origin["name"])
                has_return_to_inn = any(
                    step.get("tool") == "travel"
                    and (
                        str(launch_room) in canonical_json(step)
                        or normalize(launch_origin_name) in normalize(canonical_json(step))
                    )
                    for step in prior_steps
                )
                if not has_return_to_inn:
                    raise ModelError(
                        "the farm plan must travel to the source-verified safe "
                        f"staging room ({launch_origin_name}, room {launch_room}) "
                        "before its autopilot launch step"
                    )
        safe_ending = self._validated_safe_ending(raw_plan, normalized_steps)
        if phase_exhaustion_pending and (
            len(normalized_steps) != 1
            or str(normalized_steps[0].get("id") or "")
            != str(safe_ending.get("step_id") or "")
        ):
            raise ModelError(
                "an exhausted campaign phase accepts only its one final "
                "source-verified safe-ending travel step"
            )
        if self._goal_requires_raza_exit(goal) and (
            "raza" in str(safe_ending.get("name") or "").casefold()
            or "mausoleum" in str(safe_ending.get("name") or "").casefold()
        ):
            raise ModelError(
                "a one-way Raza graduation goal cannot use a Raza room as its "
                "safe ending; use leave_raza and finish in a source-verified "
                "safe mainland room"
            )
        value = {
            "schema_version": EXECUTION_PLAN_SCHEMA_VERSION,
            "goal_id": goal["id"],
            "goal_version": goal["version"],
            "campaign_run_id": run.get("id") if run else None,
            "phase_id": phase.get("id") if phase else None,
            "phase_kind": phase.get("kind") if phase else None,
            "goal_contract": canonical_json(
                {
                    key: goal.get(key)
                    for key in ("title", "objective", "success_criteria", "constraints")
                }
            ),
            "summary": summary[:1000],
            "steps": normalized_steps,
            "safe_ending": safe_ending,
            "assumptions": [str(value).strip()[:500] for value in assumptions if str(value).strip()][:20],
            "normalizations": plan_normalizations,
            "revision_reason": str(raw_plan.get("revision_reason") or "").strip()[:1000] or None,
            "verification": {
                "status": "verified",
                "verified_at": timestamp(),
                "goal_contract_valid": bool(grounding.get("valid")),
                "knowledge_corpus": deep_get(grounding, "corpus.corpus_version"),
                "purchase_static_verified": (
                    bool(purchase.get("static_verified")) if isinstance(purchase, dict) else None
                ),
                "live_state_required_before_each_action": True,
            },
            "last_action": None,
            "updated_at": timestamp(),
        }
        values = self.storage.get_runtime(EXECUTION_PLAN_RUNTIME_KEY, {})
        values = dict(values) if isinstance(values, dict) else {}
        values[goal["id"]] = value
        active_ids = {
            item["id"]
            for item in self.storage.goals(["active", "queued", "paused", "blocked"])
        }
        values = {
            key: item
            for key, item in values.items()
            if key in active_ids or key == goal["id"]
        }
        self.storage.set_runtime(EXECUTION_PLAN_RUNTIME_KEY, values)
        self.storage.emit_event(
            "planner.plan.revised" if revision else "planner.plan.verified",
            ("Revised" if revision else "Verified") + f" execution plan: {summary[:180]}",
            interesting=False,
            goal_id=goal["id"],
            data={"plan": redact(value)},
        )
        return value

    def _sale_recovery_plan_error(
        self,
        goal: dict[str, Any],
        steps: list[dict[str, Any]],
    ) -> str | None:
        """Require live buyer discovery after a verified sale refusal.

        The durable blocked-action ledger is authoritative because unrelated
        planner feedback can replace the immediate refusal message. Applying
        the same check while loading a stored plan also retires plans persisted
        by an older controller version before they can replay a blind sale.
        """

        sale_failure_kinds = {
            "merchant_rejected_sale",
            "bulk_sale_transferred_nothing",
        }
        feedback = self._planner_feedback(goal)
        failure_kind = str(
            deep_get(feedback or {}, "failure_context.kind", "")
        )
        next_sale = next(
            (
                index
                for index, step in enumerate(steps)
                if step.get("tool") in {"sell", "sell_all"}
            ),
            None,
        )
        if next_sale is None:
            return None
        sale_step = steps[next_sale]
        sale_text = " ".join(
            str(sale_step.get(field) or "")
            for field in ("outcome", "verification")
        ).casefold()
        restricted_item_ids = self._intrinsically_unsellable_item_ids(
            goal, self.last_observation or {}
        )
        restricted_item_names = self._intrinsically_unsellable_item_names(
            goal, self.last_observation or {}
        )
        reused_restricted_names = sorted(
            name
            for name in restricted_item_names
            if re.search(rf"\b{re.escape(name)}s?\b", sale_text)
        )
        if reused_restricted_names:
            return (
                "the unchanged semantic inventory has already proved every carried "
                "instance of "
                + ", ".join(repr(name) for name in reused_restricted_names)
                + " non-transferable despite server item-id churn; use a non-sale "
                "funding route or materially change inventory"
            )
        reused_restricted_ids = sorted(
            item_id
            for item_id in restricted_item_ids
            if re.search(rf"\b{re.escape(item_id)}\b", sale_text)
        )
        if reused_restricted_ids:
            return (
                "the proposed sale reuses exact item id(s) "
                + ", ".join(reused_restricted_ids)
                + ", which the live server already proved cannot be given to any "
                "NPC; choose a different exact inventory item or a non-sale funding route"
            )
        if failure_kind == "item_not_npc_transferable":
            # The item failed Monster.ReqOffer's CanBeGivenToNPC check before
            # ObjectDesired/buyer preference. Buyer discovery cannot repair it.
            return None

        observation = self.last_observation or {}
        exhausted_items = self._sale_exhausted_items(
            self._merchant_sale_refusals(goal, observation)
        )
        planned_sales_text = canonical_json(
            [
                step
                for step in steps
                if step.get("tool") in {"sell", "sell_all"}
            ]
        ).casefold()
        for exhausted in exhausted_items:
            item_id = str(exhausted.get("item_id") or "").casefold()
            if not item_id or re.search(
                rf"\b{re.escape(item_id)}\b", planned_sales_text
            ) is None:
                continue
            return (
                f"exact carried item {item_id} has been rejected by "
                f"{exhausted.get('distinct_refusing_buyers')} independent live "
                "buyers, exhausting its source-catalogue sale hypothesis for the "
                "unchanged inventory; use a non-sale funding route or materially "
                "change inventory instead of visiting another merchant"
            )
        for sale_index, planned_sale in enumerate(steps):
            if planned_sale.get("tool") not in {"sell", "sell_all"}:
                continue
            sale_text = canonical_json(planned_sale).casefold()
            preceding_movements = [
                step
                for step in steps[:sale_index]
                if step.get("tool") in MOVEMENT_TOOLS
            ]
            destination_text = canonical_json(
                [*(preceding_movements[-1:] or []), planned_sale]
            ).casefold()
            for refusal in self._merchant_sale_refusals(goal, observation):
                item_ids = {
                    str(value).casefold()
                    for value in refusal.get("item_ids", [])
                    if str(value).strip()
                }
                item_names = {
                    " ".join(str(value).split()).casefold()
                    for value in refusal.get("item_names", [])
                    if str(value).strip()
                }
                same_item = any(
                    re.search(rf"\b{re.escape(item_id)}\b", sale_text)
                    for item_id in item_ids
                ) or any(
                    re.search(rf"\b{re.escape(item_name)}s?\b", sale_text)
                    for item_name in item_names
                )
                if not same_item:
                    continue
                aliases = {
                    str(value).casefold()
                    for value in deep_get(refusal, "merchant.aliases", [])
                    if str(value).strip()
                }
                alias_match = next(
                    (alias for alias in aliases if alias in sale_text),
                    None,
                )
                refused_room = refusal.get("room")
                room_match = (
                    refused_room is not None
                    and re.search(
                        rf"(?<!\d){re.escape(str(refused_room))}(?!\d)",
                        destination_text,
                    )
                    is not None
                )
                if alias_match is None and not room_match:
                    continue
                if alias_match is None:
                    finances = self._financial_context(observation)
                    distinct_buyer_named = any(
                        str(candidate.get("merchant") or "").casefold()
                        in sale_text
                        for item_row in finances.get("buyer_candidates", [])
                        if isinstance(item_row, dict)
                        and " ".join(
                            str(item_row.get("item") or "").split()
                        ).casefold()
                        in item_names
                        for candidate in item_row.get("candidates", [])
                        if isinstance(candidate, dict)
                        and any(
                            str(room) == str(refused_room)
                            for room in candidate.get("room_ids", [])
                        )
                    )
                    if distinct_buyer_named:
                        continue
                    return (
                        f"the proposed sale routes the same item back to room "
                        f"{refused_room} without naming a grounded merchant distinct "
                        "from the buyer that already refused it there; identify the "
                        "different merchant explicitly or use another candidate room/item"
                    )
                item = next(iter(sorted(item_names or item_ids)), "offered item")
                live_name = deep_get(refusal, "merchant.live_name")
                source_classes = deep_get(
                    refusal, "merchant.source_classes", []
                )
                buyer_names = [
                    str(value)
                    for value in [
                        live_name,
                        *(source_classes if isinstance(source_classes, list) else []),
                    ]
                    if value
                ]
                buyer = "/".join(dict.fromkeys(buyer_names)) or str(
                    deep_get(refusal, "merchant.object_id", "that merchant")
                )
                object_id = deep_get(refusal, "merchant.object_id")
                if object_id is not None:
                    buyer += f" (merchant {object_id})"
                rejected_identity = (
                    f"merchant {object_id}" if object_id is not None else buyer
                )
                return (
                    f"the proposed sale reuses {item!r} with buyer {buyer} in "
                    f"room {refused_room}; {rejected_identity} already rejected that exact "
                    "item/buyer placement live. Choose a candidate in a different "
                    "room or offer a materially different unprotected item"
                )
        sale_recovery_required = failure_kind in sale_failure_kinds
        if not sale_recovery_required:
            blocked_actions = self.storage.get_runtime("blocked_actions", [])
            sale_recovery_required = any(
                isinstance(entry, dict)
                and entry.get("goal_id") == goal.get("id")
                and str(
                    deep_get(
                        self._failure_context(
                            str(entry.get("tool") or ""),
                            str(entry.get("reason") or ""),
                            self.last_observation or {},
                        )
                        or {},
                        "kind",
                        "",
                    )
                )
                in sale_failure_kinds
                for entry in (
                    blocked_actions if isinstance(blocked_actions, list) else []
                )
            )
        if not sale_recovery_required:
            return None
        prior_discovery = self._recent_buyer_discovery_evidence(
            goal, sale_text=sale_text
        )
        lookups = [
            step
            for step in steps[:next_sale]
            if step.get("tool") == "merchants"
        ]
        if lookups:
            if prior_discovery is not None:
                query = str(prior_discovery.get("query") or "").casefold()
                repeated = any(
                    query
                    and query
                    in " ".join(
                        str(step.get(field) or "")
                        for field in ("outcome", "verification")
                    ).casefold()
                    for step in lookups
                )
                if repeated:
                    return (
                        f"buyer discovery for {query!r} already completed with candidate "
                        "results; consume that verified result and proceed to a different "
                        "candidate instead of repeating the same merchants lookup"
                    )
            return None
        if prior_discovery is not None:
            return None
        return (
            "the previous merchant rejected the sale; a replacement plan must "
            "include a merchants buyer-discovery step before its next sell or "
            "sell_all step, or consume a recent completed targeted buyer lookup, "
            "rather than assuming another buyer exists"
        )

    def _recent_buyer_discovery_evidence(
        self,
        goal: dict[str, Any],
        *,
        sale_text: str,
    ) -> dict[str, Any] | None:
        """Find a completed targeted buyer lookup with usable candidates."""

        blocked_actions = self.storage.get_runtime("blocked_actions", [])
        sale_failures = [
            entry
            for entry in (
                blocked_actions if isinstance(blocked_actions, list) else []
            )
            if isinstance(entry, dict)
            and entry.get("goal_id") == goal.get("id")
            and entry.get("tool") in {"sell", "sell_all"}
        ]
        latest_failure_at = max(
            (str(entry.get("updated_at") or "") for entry in sale_failures),
            default="",
        )
        events = self.storage.goal_events(
            str(goal.get("id") or ""),
            kinds=["action.succeeded", "action.no_progress"],
            limit=120,
        )
        for event in reversed(events):
            if (
                latest_failure_at
                and str(event.get("occurred_at") or "") < latest_failure_at
            ):
                continue
            data = event.get("data")
            data = data if isinstance(data, dict) else {}
            if data.get("tool") != "merchants":
                continue
            arguments = data.get("arguments")
            arguments = arguments if isinstance(arguments, dict) else {}
            query = " ".join(str(arguments.get("buys") or "").split())
            if not query or query.casefold() not in sale_text:
                continue
            result = data.get("result")
            result = result if isinstance(result, dict) else {}
            broad = result.get("buys_anything")
            mentioned = result.get("rules_mentioning")
            candidates = [
                item
                for item in (
                    (broad if isinstance(broad, list) else [])
                    + (mentioned if isinstance(mentioned, list) else [])
                )
                if isinstance(item, dict)
                and item.get("room") is not None
                and item.get("excludes_it") is not True
            ]
            refusals = self._merchant_sale_refusals(
                goal, self.last_observation or {}
            )
            candidates = [
                candidate
                for candidate in candidates
                if not any(
                    query.casefold()
                    in {
                        " ".join(str(value).split()).casefold()
                        for value in refusal.get("item_names", [])
                    }
                    and str(candidate.get("room")) == str(refusal.get("room"))
                    and str(candidate.get("merchant") or "").casefold()
                    in {
                        str(value).casefold()
                        for value in deep_get(
                            refusal, "merchant.aliases", []
                        )
                    }
                    for refusal in refusals
                )
            ]
            if candidates:
                return {
                    "query": query,
                    "occurred_at": event.get("occurred_at"),
                    "event_id": event.get("id"),
                    "candidates": candidates[:20],
                }
        return None

    def _record_plan_action(
        self,
        goal: dict[str, Any],
        *,
        step_id: str,
        tool: str,
        arguments: dict[str, Any],
        result: Any,
        status: str | None = None,
    ) -> None:
        values = self.storage.get_runtime(EXECUTION_PLAN_RUNTIME_KEY, {})
        if not isinstance(values, dict) or not isinstance(values.get(goal["id"]), dict):
            return
        value = dict(values[goal["id"]])
        value["last_action"] = {
            "step_id": step_id,
            "tool": tool,
            "arguments": redact(arguments),
            "observed_at": timestamp(),
            "result_summary": str(redact(result))[:1000],
            **({"status": status} if status else {}),
        }
        value["updated_at"] = timestamp()
        values = dict(values)
        values[goal["id"]] = value
        self.storage.set_runtime(EXECUTION_PLAN_RUNTIME_KEY, values)

    @staticmethod
    def _purchase_plan(goal: dict[str, Any]) -> dict[str, Any] | None:
        constraints = goal.get("constraints")
        value = constraints.get("purchase_plan") if isinstance(constraints, dict) else None
        return value if isinstance(value, dict) else None

    def _purchase_preflight(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        *,
        force: bool = False,
    ) -> dict[str, Any] | None:
        purchase = self._purchase_plan(goal)
        if purchase is None:
            return None
        values = self.storage.get_runtime(PURCHASE_PREFLIGHT_RUNTIME_KEY, {})
        values = dict(values) if isinstance(values, dict) else {}
        prior = values.get(goal["id"])
        prior = prior if isinstance(prior, dict) else {}
        room_id = deep_get(observation, "look.room.num", deep_get(observation, "look.room_id"))
        target_room = int(purchase["room_id"])
        now_unix = time.time()
        base = {
            "goal_id": goal["id"],
            "goal_version": goal["version"],
            "offering_kind": purchase.get("offering_kind", "item"),
            "item": purchase["item"],
            "merchant_class": purchase["merchant_class"],
            "room_id": target_room,
            "maximum_price": purchase.get("maximum_price"),
            "static_verified": True,
            "live_verified": False,
            "checked_at": timestamp(),
            "checked_unix": now_unix,
        }
        if room_id != target_room:
            value = {**base, "status": "travel_required", "current_room_id": room_id}
            values[goal["id"]] = value
            self.storage.set_runtime(PURCHASE_PREFLIGHT_RUNTIME_KEY, values)
            return value
        if (
            not force
            and prior.get("status") == "live_verified"
            and now_unix - float(prior.get("checked_unix", 0) or 0) <= 60
        ):
            return prior
        if (
            not force
            and prior.get("status") in {"merchant_not_visible", "item_not_quoted"}
            and now_unix - float(prior.get("checked_unix", 0) or 0) < 5
        ):
            return prior
        attempts = int(prior.get("failed_checks", 0) or 0)
        try:
            local = self.broker.call_tool(
                "merchants",
                {"agent": self.config.game.agent, "here": True},
                timeout=10,
                mutation=False,
            )
            here = local.get("here", []) if isinstance(local, dict) else []
            merchant = next(
                (
                    value
                    for value in here
                    if isinstance(value, dict)
                    and str(value.get("merchant") or "").casefold()
                    == str(purchase["merchant_class"]).casefold()
                ),
                None,
            )
            if merchant is None and len(here) == 1 and isinstance(here[0], dict):
                merchant = here[0]
            if not isinstance(merchant, dict) or merchant.get("id") is None:
                value = {
                    **base,
                    "status": "merchant_not_visible",
                    "failed_checks": attempts + 1,
                    "reason": "the statically placed merchant is not visible in the target room",
                    "live_merchants": redact(here),
                }
            else:
                quote = self.broker.call_tool(
                    "shop",
                    {"agent": self.config.game.agent, "seller": merchant["id"]},
                    timeout=10,
                    mutation=False,
                )
                items = quote.get("items", []) if isinstance(quote, dict) else []
                quoted = [
                    item
                    for item in items
                    if isinstance(item, dict)
                    and normalize(item.get("name")) == normalize(purchase["item"])
                ]
                if not quoted:
                    value = {
                        **base,
                        "status": "item_not_quoted",
                        "failed_checks": attempts + 1,
                        "reason": "the exact planned item was absent from the fresh live shop quote",
                        "seller_id": merchant["id"],
                        "quoted_items": redact(items),
                    }
                else:
                    costs = [
                        item.get("cost")
                        for item in quoted
                        if isinstance(item.get("cost"), int) and not isinstance(item.get("cost"), bool)
                    ]
                    maximum = purchase.get("maximum_price")
                    over_limit = bool(
                        isinstance(maximum, int) and costs and min(costs) > maximum
                    )
                    value = {
                        **base,
                        "status": "price_exceeds_limit" if over_limit else "live_verified",
                        "live_verified": not over_limit,
                        "failed_checks": attempts + 1 if over_limit else 0,
                        "seller_id": merchant["id"],
                        "quoted_items": redact(quoted),
                        "authorized_buy_ids": [item.get("id") for item in quoted],
                        "minimum_price": min(costs) if costs else None,
                        "reason": "fresh live price exceeds purchase_plan.maximum_price"
                        if over_limit
                        else None,
                    }
        except (BrokerError, ToolCallError, TypeError, ValueError) as exc:
            value = {
                **base,
                "status": "verification_error",
                "failed_checks": attempts + 1,
                "reason": str(exc)[:500],
            }
        values[goal["id"]] = value
        self.storage.set_runtime(PURCHASE_PREFLIGHT_RUNTIME_KEY, values)
        return value

    def _purchase_action_blockers(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        tool: str,
        arguments: dict[str, Any],
    ) -> list[dict[str, Any]]:
        purchase = self._purchase_plan(goal)
        if purchase is None or tool != "shop" or not arguments.get("buy_ids"):
            return []
        preflight = self._purchase_preflight(goal, observation, force=False) or {}
        if preflight.get("status") != "live_verified":
            return [
                {
                    "kind": "purchase_plan_unverified",
                    "guidance": "reach the verified merchant room and obtain a fresh live merchant/stock/price quote before buying",
                    "preflight": redact(preflight),
                }
            ]
        if str(arguments.get("seller")) != str(preflight.get("seller_id")):
            return [
                {
                    "kind": "purchase_seller_mismatch",
                    "guidance": "use only the seller id from the fresh verified quote",
                }
            ]
        authorized = {int(value) for value in preflight.get("authorized_buy_ids", []) if isinstance(value, int)}
        requested = {int(value) for value in arguments.get("buy_ids", []) if isinstance(value, int)}
        if not requested or not requested.issubset(authorized):
            return [
                {
                    "kind": "purchase_item_mismatch",
                    "guidance": "buy_ids must refer only to the exact item authorized by purchase_plan and the fresh quote",
                }
            ]
        minimum_price = preflight.get("minimum_price")
        if isinstance(minimum_price, int) and self._carried_currency(observation) < minimum_price:
            return [
                {
                    "kind": "purchase_funds_insufficient",
                    "guidance": f"obtain at least {minimum_price} carried shillings before buying",
                    "required": minimum_price,
                    "carried": self._carried_currency(observation),
                }
            ]
        return []

    def _emit_shop_property_transaction(
        self,
        goal: dict[str, Any],
        result: dict[str, Any],
        *,
        correlation_id: str | None = None,
        policy_decision_id: str | None = None,
        recovered_from_event_id: str | None = None,
    ) -> dict[str, Any] | None:
        """Record a verified shop purchase as a durable property transaction."""

        bought = result.get("bought")
        acquired = result.get("got")
        bought = bought if isinstance(bought, list) else []
        acquired = acquired if isinstance(acquired, list) else []
        if not bought and not acquired:
            return None
        item_count = len(acquired) or len(bought)
        return self.storage.emit_event(
            "property.transaction",
            f"Shop purchase completed: {item_count} item(s) acquired",
            severity="notice",
            interesting=True,
            goal_id=goal["id"],
            data={
                "transaction": "shop_buy",
                "seller": result.get("seller"),
                "buy_ids": redact(bought),
                "items_acquired": redact(acquired),
                "item_count": item_count,
                "protected_or_valuable": True,
                "approval_required": False,
                "recovered_from_event_id": recovered_from_event_id,
            },
            correlation_id=correlation_id,
            policy_decision_id=policy_decision_id,
        )

    def _reconcile_purchase_transaction(self, goal: dict[str, Any]) -> None:
        """Backfill the transaction event if a crash followed a successful shop call."""

        if self._purchase_plan(goal) is None:
            return
        transaction_criteria = [
            criterion
            for criterion in goal.get("success_criteria", [])
            if isinstance(criterion, dict)
            and criterion.get("kind") == "event_occurred"
            and criterion.get("event_kind") == "property.transaction"
        ]
        if not transaction_criteria:
            return
        goal_anchor = self.storage.goal_event_anchor(str(goal.get("id") or ""))
        effective_cursors = []
        for criterion in transaction_criteria:
            requested = int(criterion.get("after_cursor", 0) or 0)
            effective_cursors.append(
                min(requested, goal_anchor)
                if goal_anchor is not None
                else requested
            )
        after_cursor = max(effective_cursors, default=0)
        existing = self.storage.events(
            after_cursor=after_cursor,
            limit=1,
            kinds=["property.transaction"],
            goal_id=goal["id"],
        )
        if existing.get("events"):
            return
        successful_actions = self.storage.events(
            after_cursor=after_cursor,
            limit=200,
            kinds=["action.succeeded"],
            goal_id=goal["id"],
        ).get("events", [])
        shop_event = next(
            (
                event
                for event in reversed(successful_actions)
                if isinstance(event, dict)
                and deep_get(event, "data.tool") == "shop"
                and isinstance(deep_get(event, "data.result"), dict)
                and (
                    deep_get(event, "data.result.bought")
                    or deep_get(event, "data.result.got")
                )
            ),
            None,
        )
        if shop_event is None:
            return
        self._emit_shop_property_transaction(
            goal,
            deep_get(shop_event, "data.result"),
            correlation_id=shop_event.get("correlation_id"),
            policy_decision_id=shop_event.get("policy_decision_id"),
            recovered_from_event_id=shop_event.get("id"),
        )

    @staticmethod
    def _purchase_result_met(
        goal: dict[str, Any], completion: dict[str, Any]
    ) -> bool:
        """Whether the exact transaction outcome, rather than a visit, is verified."""

        constraints = goal.get("constraints")
        purchase = constraints.get("purchase_plan") if isinstance(constraints, dict) else None
        if not isinstance(purchase, dict):
            return False
        offering_kind = str(purchase.get("offering_kind", "item")).casefold()
        offering_name = normalize(purchase.get("item"))
        results = completion.get("criteria", [])
        results = results if isinstance(results, list) else []

        # A replacement-purchase goal can legitimately start with a broken copy
        # of the named item already in the pack.  In that case a goal-scoped
        # property.transaction criterion is the durable proof that a new copy
        # was actually bought.  Do not let the pre-existing inventory match
        # short-circuit funding, travel, and shopping before that event occurs.
        transaction_results = [
            results[index]
            for index, criterion in enumerate(goal.get("success_criteria", []))
            if isinstance(criterion, dict)
            and criterion.get("kind") == "event_occurred"
            and criterion.get("event_kind") == "property.transaction"
            and index < len(results)
            and isinstance(results[index], dict)
        ]
        transaction_verified = not transaction_results or all(
            result.get("met") is True for result in transaction_results
        )
        for index, criterion in enumerate(goal.get("success_criteria", [])):
            if not isinstance(criterion, dict) or index >= len(results):
                continue
            result = results[index]
            if not isinstance(result, dict) or result.get("met") is not True:
                continue
            if (
                offering_kind == "item"
                and criterion.get("kind") == "inventory_contains"
                and normalize(criterion.get("item")) == offering_name
            ):
                return transaction_verified
            parsed = parse_ability_metric(criterion.get("metric"))
            if (
                offering_kind in {"skill", "spell"}
                and parsed is not None
                and parsed[0] == offering_kind
                and normalize(parsed[1]) == offering_name
            ):
                return transaction_verified
        return False

    def _goal_completion_location(
        self, goal: dict[str, Any]
    ) -> dict[str, Any] | None:
        """Return only a destination explicitly approved in goal criteria."""

        for index, criterion in enumerate(goal.get("success_criteria", [])):
            if not isinstance(criterion, dict) or criterion.get("kind") != "location_reached":
                continue
            room_id = criterion.get("room_id")
            name = str(
                criterion.get("location") or criterion.get("room") or ""
            ).strip()
            if room_id is None and name:
                resolver = getattr(self.knowledge, "resolve", None)
                if not callable(resolver):
                    continue
                resolved = resolver(name, kinds=["location"])
                entity = (
                    resolved.get("entity")
                    if resolved.get("status") in {"found", "found_fuzzy"}
                    else None
                )
                facts = entity.get("facts") if isinstance(entity, dict) else None
                if isinstance(facts, dict):
                    room_id = facts.get("room_id")
                    name = str(entity.get("canonical_name") or name)
            try:
                numeric_room_id = int(room_id)
            except (TypeError, ValueError):
                # Travel is numeric and the controller may not invent a room
                # from prose. The ordinary planner can gather more evidence.
                continue
            return {
                "criterion_id": str(criterion.get("id") or f"criterion_{index + 1}"),
                "room_id": numeric_room_id,
                "name": name or f"room {numeric_room_id}",
            }
        return None

    @staticmethod
    def _goal_completion_position(goal: dict[str, Any]) -> dict[str, int] | None:
        """Read an exact finish square only from explicit state criteria."""

        position: dict[str, int] = {}
        accepted_paths = {
            "status.position.col": "col",
            "look.position.col": "col",
            "status.position.row": "row",
            "look.position.row": "row",
        }
        for criterion in goal.get("success_criteria", []):
            if not isinstance(criterion, dict) or criterion.get("kind") != "state_equals":
                continue
            coordinate = accepted_paths.get(str(criterion.get("path") or ""))
            value = criterion.get("value")
            if coordinate is None or not isinstance(value, int) or isinstance(value, bool):
                continue
            position[coordinate] = value
        return position if {"col", "row"}.issubset(position) else None

    @staticmethod
    def _with_selected_safe_ending(
        plan: dict[str, Any], selected_plan: dict[str, Any]
    ) -> dict[str, Any]:
        """Preserve the model's safe destination when deterministic adapters add steps."""

        ending = selected_plan.get("safe_ending")
        source_steps = selected_plan.get("steps")
        if not isinstance(ending, dict) or not isinstance(source_steps, list):
            raise ModelError("a verified model-selected safe ending is required")
        step_id = str(ending.get("step_id") or "")
        ending_step = next(
            (
                dict(step)
                for step in source_steps
                if isinstance(step, dict) and str(step.get("id") or "") == step_id
            ),
            None,
        )
        if ending_step is None:
            raise ModelError("the selected safe-ending step is missing from the verified plan")
        steps = [
            dict(step)
            for step in plan.get("steps", [])
            if isinstance(step, dict) and str(step.get("id") or "") != step_id
        ]
        optional_recovery_ids = {
            "recover-purchase-go-exit",
            "recover-purchase-route-hop",
        }
        while len(steps) >= EXECUTION_PLAN_MAX_STEPS:
            removable = next(
                (
                    index
                    for index, step in enumerate(steps)
                    if str(step.get("id") or "") in optional_recovery_ids
                ),
                None,
            )
            if removable is None:
                raise ModelError(
                    "controller-owned plan cannot preserve the required safe ending "
                    f"within {EXECUTION_PLAN_MAX_STEPS} steps"
                )
            steps.pop(removable)
        return {
            **plan,
            "steps": [*steps, ending_step],
            "safe_ending": {
                "room_id": ending.get("room_id"),
                "step_id": step_id,
                "rationale": ending.get("rationale"),
            },
        }

    def _structured_purchase_controller_plan(
        self,
        goal: dict[str, Any],
        completion: dict[str, Any] | None = None,
        *,
        selected_plan: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        purchase = self._purchase_plan(goal) or {}
        offering_kind = str(purchase.get("offering_kind", "item"))
        offering = str(purchase.get("item") or "planned offering")
        merchant = str(purchase.get("merchant_class") or "verified merchant")
        room_id = int(purchase.get("room_id") or 0)
        budget = purchase.get("maximum_price")
        budget_text = f"{budget} shillings" if isinstance(budget, int) else "the bounded price"
        destination = self._goal_completion_location(goal)
        position = self._goal_completion_position(goal)
        steps = [
            {
                "id": "travel-to-purchase-bank",
                "outcome": f"Reach First Royal Bank of Tos (room {TOS_BANK_ROOM_ID}) if {budget_text} is not carried.",
                "tool": "travel",
                "verification": f"Current room id is {TOS_BANK_ROOM_ID}.",
            },
            {
                "id": "withdraw-purchase-funds",
                "outcome": f"Withdraw only the shortfall needed to carry at most {budget_text} for {offering}.",
                "tool": "bank",
                "verification": f"Carried shillings are at least {budget if isinstance(budget, int) else 'the authorized amount'}.",
            },
            {
                "id": "travel-to-purchase-merchant",
                "outcome": f"Travel with the bounded funds to {merchant} in exact room {room_id}.",
                "tool": "travel",
                "verification": f"Current room id is {room_id} and the expected merchant is visible.",
            },
            {
                "id": "buy-planned-offering",
                "outcome": f"Use a fresh quote and buy only exact {offering_kind} {offering} within {budget_text}.",
                "tool": "shop",
                "verification": (
                    f"The live {'ability list reports ' + offering + ' at 1 or above' if offering_kind in {'skill', 'spell'} else 'inventory contains ' + offering}."
                ),
            },
            {
                "id": "recover-purchase-go-exit",
                "outcome": "If ordinary travel stalls while already standing on a reachable go exit, explicitly activate that exit once.",
                "tool": "act",
                "verification": "The current room changes through the externally directed reachable go exit.",
            },
            {
                "id": "recover-purchase-route-hop",
                "outcome": "If travel selects an unusable duplicate exit, use a live reachable go exit to the exact failed next-hop room.",
                "tool": "go_through",
                "verification": "The current room changes to the same next-hop room named by the failed travel log.",
            },
        ]
        plan = {
            "summary": (
                f"Fund, live-verify, and acquire the exact {offering_kind} {offering} from {merchant}, "
                "then verify the actual item/ability result and only the finish state named by the goal."
            ),
            "steps": steps,
            "assumptions": [],
            "revision_reason": (
                "Use controller-owned funding and exact live quote binding instead of conversational trial and error."
            ),
        }
        farm_intent = self._effective_farm_intent(goal)
        farm_work_remains = completion is None or any(
            item["result"].get("met") is not True
            for item in self._health_progress_criteria(goal, completion)
        )
        if (
            farm_work_remains
            and farm_intent.get("assigned_room") is not None
            and farm_intent.get("hunt")
        ):
            staging = self._farm_launch_origin(
                goal, self.last_observation or {}, farm_intent
            )
            if staging is None:
                raise ModelError(
                    "no source-verified safe staging room is available for the farm launch"
                )
            # A combined acquire-then-farm goal still needs to prove both the
            # safe launch boundary and the hazardous phase's goal ownership.
            # Route-repair steps are optional and omitted to stay within the
            # bounded execution-plan contract.
            plan["steps"] = [
                step
                for step in plan["steps"]
                if step["id"]
                not in {"recover-purchase-go-exit", "recover-purchase-route-hop"}
            ]
            plan["steps"].append(
                {
                    "id": "reach-farm-staging",
                    "outcome": (
                        f"Reach source-verified safe staging {staging['name']} "
                        f"(room {staging['room_id']}) before keeper launch."
                    ),
                    "tool": "travel",
                    "verification": (
                        f"Current room id is {staging['room_id']} and source flags include "
                        "ROOM_SANCTUARY or ROOM_NO_COMBAT."
                    ),
                }
            )
            plan["steps"].append(
                {
                    "id": "launch-goal-keeper",
                    "outcome": (
                        "After buying and equipping the mace, launch the grounded farm "
                        f"for {farm_intent['hunt']} in assigned room "
                        f"{farm_intent['assigned_room']}."
                    ),
                    "tool": "autopilot",
                    "verification": (
                        "Keeper status reports the exact goal-owned prey and assigned room."
                    ),
                }
            )
            plan["summary"] = (
                f"Acquire the exact {offering_kind} {offering}, reach source-verified "
                f"safe staging, then launch the grounded {farm_intent['hunt']} farm phase."
            )
            plan["revision_reason"] = (
                "Compose the controller-owned purchase prerequisite with the explicit "
                "goal-owned farm launch required by this combined goal."
            )
        if destination is not None:
            plan["steps"].append(
                {
                    "id": "finish-purchase-at-goal-location",
                    "outcome": (
                        "After prerequisite work is verified, travel to the goal's "
                        f"explicit destination {destination['name']} "
                        f"(room {destination['room_id']})."
                    ),
                    "tool": "travel",
                    "verification": f"Current room id is {destination['room_id']}.",
                }
            )
        if position is not None:
            plan["steps"].append(
                {
                    "id": "finish-purchase-at-goal-position",
                    "outcome": (
                        "Walk to the goal's explicit finish square "
                        f"({position['col']},{position['row']})."
                    ),
                    "tool": "walk_to",
                    "verification": (
                        f"Position is column {position['col']}, row {position['row']}."
                    ),
                }
            )
        return (
            self._with_selected_safe_ending(plan, selected_plan)
            if selected_plan is not None
            else plan
        )

    def _structured_purchase_preparation_action(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        completion: dict[str, Any],
        preflight: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Fund and execute a grounded purchase/training transaction deterministically."""

        purchase = self._purchase_plan(goal)
        if purchase is None:
            return None
        current_room = deep_get(
            observation, "look.room.num", deep_get(observation, "look.room_id")
        )

        def action(
            tool: str,
            arguments: dict[str, Any],
            step_id: str,
            rationale: str,
        ) -> dict[str, Any]:
            return {
                "decision": "act",
                "tool": tool,
                "arguments": arguments,
                "rationale": rationale,
                "expected_observation": {},
                "proposal": None,
                "plan_step_id": step_id,
            }

        if self._purchase_result_met(goal, completion):
            farm_intent = self._effective_farm_intent(goal)
            farm_work_remains = any(
                item["result"].get("met") is not True
                for item in self._health_progress_criteria(goal, completion)
            )
            if (
                farm_work_remains
                and farm_intent.get("assigned_room") is not None
                and farm_intent.get("hunt")
            ):
                # The farm preparation path owns safe staging. An acquisition
                # must not smuggle an unrelated implicit return-home trip in
                # front of that goal-owned hazardous phase.
                return None

            destination = self._goal_completion_location(goal)
            if destination is not None and str(current_room) != str(
                destination["room_id"]
            ):
                destination_room = int(destination["room_id"])
                blocked_actions = self.storage.get_runtime("blocked_actions", [])
                blocked_actions = (
                    blocked_actions if isinstance(blocked_actions, list) else []
                )
                stalled_on_go_exit = any(
                    isinstance(blocked, dict)
                    and blocked.get("goal_id") == goal.get("id")
                    and blocked.get("tool") in {"travel", "go_through"}
                    and str(blocked.get("room")) == str(current_room)
                    and (
                        blocked.get("tool") == "go_through"
                        or str(deep_get(blocked, "arguments.to"))
                        == str(destination_room)
                    )
                    and "stood on the exit square and nothing happened"
                    in str(blocked.get("reason") or "").casefold()
                    for blocked in blocked_actions
                )
                exits = deep_get(observation, "look.exits", [])
                exits = exits if isinstance(exits, list) else []
                explicit_go_exit = next(
                    (
                        value
                        for value in exits
                        if isinstance(value, dict)
                        and value.get("kind") == "go"
                        and value.get("reachable") is True
                        and value.get("steps_away") == 0
                        and str(value.get("to")) != str(current_room)
                    ),
                    None,
                )
                if stalled_on_go_exit and explicit_go_exit is not None:
                    return action(
                        "act",
                        {"verb": "go"},
                        "recover-purchase-go-exit",
                        "Travel proved that the character is already on a reachable go exit; activate that exact exit once before resuming the route.",
                    )
                latest_route_failure = next(
                    (
                        event
                        for event in reversed(
                            self.storage.goal_events(
                                goal["id"], kinds=["action.no_progress"], limit=40
                            )
                        )
                        if isinstance(event, dict)
                        and deep_get(event, "data.tool") == "travel"
                        and str(deep_get(event, "data.arguments.to"))
                        == str(destination_room)
                        and str(deep_get(event, "data.room.num", deep_get(event, "data.room.id")))
                        == str(current_room)
                    ),
                    None,
                )
                route_log = deep_get(latest_route_failure or {}, "data.result.log", [])
                route_log = route_log if isinstance(route_log, list) else []
                failed_hop = next(
                    (
                        value
                        for value in route_log
                        if isinstance(value, dict)
                        and value.get("ok") is False
                        and str(value.get("to") or "").strip()
                    ),
                    None,
                )
                failed_hop_name = normalize(
                    failed_hop.get("to") if isinstance(failed_hop, dict) else ""
                )
                alternate_go_exits = [
                    value
                    for value in exits
                    if isinstance(value, dict)
                    and value.get("kind") == "go"
                    and value.get("reachable") is True
                    and isinstance(value.get("to"), int)
                    and normalize(value.get("to_name")) == failed_hop_name
                    and isinstance(value.get("stand_on"), dict)
                    and isinstance(value["stand_on"].get("col"), (int, float))
                    and isinstance(value["stand_on"].get("row"), (int, float))
                ]
                alternate_go_exits.sort(
                    key=lambda value: float(value.get("steps_away") or 1_000_000)
                )
                if alternate_go_exits:
                    alternate = alternate_go_exits[0]
                    return action(
                        "go_through",
                        {
                            "to": alternate["to"],
                            "col": alternate["stand_on"]["col"],
                            "row": alternate["stand_on"]["row"],
                        },
                        "recover-purchase-route-hop",
                        "Use the nearest live reachable go exit to the exact next-hop room that ordinary travel selected through an unusable duplicate edge.",
                    )
                return action(
                    "travel",
                    {"to": destination_room},
                    "finish-purchase-at-goal-location",
                    "The exact acquisition is verified; travel only to the destination explicitly named by the approved goal.",
                )
            position = self._goal_completion_position(goal)
            if position is None:
                return None
            col = deep_get(
                observation,
                "status.position.col",
                deep_get(observation, "look.position.col"),
            )
            row = deep_get(
                observation,
                "status.position.row",
                deep_get(observation, "look.position.row"),
            )
            if str(col) != str(position["col"]) or str(row) != str(position["row"]):
                return action(
                    "walk_to",
                    {"col": position["col"], "row": position["row"]},
                    "finish-purchase-at-goal-position",
                    "Finish at the exact coordinates explicitly named by the approved goal.",
                )
            return None

        budget = purchase.get("maximum_price")
        if not isinstance(budget, int) or isinstance(budget, bool) or budget <= 0:
            # Physical purchases may intentionally omit a cap. Paid abilities
            # cannot: goal validation rejects them before reaching this path.
            return None
        carried = self._carried_currency(observation)

        if carried < budget:
            if str(current_room) != str(TOS_BANK_ROOM_ID):
                return action(
                    "travel",
                    {"to": TOS_BANK_ROOM_ID},
                    "travel-to-purchase-bank",
                    "Obtain the authorized training/purchase budget before traveling to the merchant.",
                )
            return action(
                "bank",
                {"action": "withdraw", "amount": budget - carried},
                "withdraw-purchase-funds",
                "Withdraw exactly the remaining authorized budget before leaving the bank.",
            )

        target_room = int(purchase["room_id"])
        if str(current_room) != str(target_room):
            return action(
                "travel",
                {"to": target_room},
                "travel-to-purchase-merchant",
                "Carry the prepared bounded funds to the grounded merchant room.",
            )
        if not isinstance(preflight, dict) or preflight.get("status") != "live_verified":
            return None
        seller = preflight.get("seller_id")
        authorized = [
            value
            for value in preflight.get("authorized_buy_ids", [])
            if isinstance(value, int) and not isinstance(value, bool)
        ]
        if not isinstance(seller, int) or not authorized:
            return None
        purchase_arguments = {
            "agent": self.config.game.agent,
            "seller": seller,
            "buy_ids": [authorized[0]],
        }
        prior_purchase_failure = self._blocked_action(
            goal,
            observation,
            "shop",
            purchase_arguments,
        )
        if prior_purchase_failure and is_inventory_capacity_refusal(
            prior_purchase_failure.get("reason")
        ):
            # The deterministic purchase fast path owns ordinary funding,
            # travel, quote binding, and the first transaction attempt. Once
            # the server disproves that transaction in the current load state,
            # yield to the tactical planner. Its context contains the observed
            # refusal and carry evidence, but no controller-authored remedy.
            return None
        return action(
            "shop",
            {"seller": seller, "buy_ids": [authorized[0]]},
            "buy-planned-offering",
            "Buy only the exact offering bound to the fresh seller, item id, and price quote.",
        )

    def _available_tools(self) -> dict[str, Any]:
        tools = dict(self.broker.capabilities())
        # These intentionally shadow any future broker tools with the same
        # names: both are controller-owned compositions of ordinary calls.
        for name in PVP_TOOL_NAMES:
            tools[name] = self.pvp.tool_for(name)
        knowledge_tool = self.knowledge.planner_tool()
        tools[KNOWLEDGE_TOOL_NAME] = Tool(
            KNOWLEDGE_TOOL_NAME,
            str(knowledge_tool["description"]),
            dict(knowledge_tool["input_schema"]),
        )
        return tools

    def _normalize_combat_arguments(
        self,
        tool: str,
        arguments: dict[str, Any],
        observation: dict[str, Any] | None = None,
        *,
        allow_open_field: bool = False,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        normalized = dict(arguments)
        before = dict(arguments)
        if tool == "fight":
            # The harness checks health between rounds, not between swings. One
            # swing per one-round call makes the controller's next observation
            # the safety boundary instead of allowing a four-hit burst.
            normalized.update(
                {
                    "rounds": 1,
                    "swings_per_round": 1,
                    "disengage_at": max(
                        self.config.policy.rest_health_fraction,
                        float(arguments.get("disengage_at", self.config.policy.rest_health_fraction)),
                    ),
                    "equip": True,
                    "loot": arguments.get("loot", True) is not False,
                }
            )
        elif tool == "autopilot" and arguments.get("action") == "start" and arguments.get("mode") == "farm":
            # Farming runs between controller turns, so its deterministic
            # keeper must carry the same safety envelope as a bounded fight.
            inventory_items = deep_get(observation or {}, "inventory.items", [])
            carried_slots = len(inventory_items) if isinstance(inventory_items, list) else 0
            requested_max_carry = int(arguments.get("max_carry", 14))
            # Override the upstream keeper default.  Omission means no special
            # cash-triggered trip; a positive threshold is used only when the
            # planner deliberately selected it from the disclosed finances.
            requested_bank_above = arguments.get("bank_above", 0)
            effective_bank_above = int(requested_bank_above)
            if 0 < effective_bank_above < BROKER_WALKING_MONEY:
                effective_bank_above = BROKER_WALKING_MONEY
            eat_before_fighting = arguments.get("eat_before_fighting") is True
            buy_food = arguments.get("buy_food") is True
            try:
                requested_fight_vigor = float(
                    arguments.get("fight_above_vigor", FARM_FIGHT_VIGOR)
                )
            except (TypeError, ValueError):
                requested_fight_vigor = float(FARM_FIGHT_VIGOR)
            # Rested vigor is the viable default. A higher target is accepted
            # only as part of an explicit planner-owned eating tactic; merely
            # carrying food can never raise the keeper's hidden launch floor.
            effective_fight_vigor: int | float = FARM_FIGHT_VIGOR
            if eat_before_fighting:
                effective_fight_vigor = min(
                    200, max(FARM_FIGHT_VIGOR, requested_fight_vigor)
                )
                if float(effective_fight_vigor).is_integer():
                    effective_fight_vigor = int(effective_fight_vigor)
            normalized.update(
                {
                    "rest_below": max(
                        self.config.policy.rest_health_fraction,
                        float(arguments.get("rest_below", self.config.policy.rest_health_fraction)),
                    ),
                    # This is an operator policy, not a model-selected risk
                    # preference. Normalize old queued recipes that still say
                    # 75-80% as well as overly aggressive lower proposals.
                    "flee_below": FARM_FLEE_THRESHOLD,
                    "fight_above_vigor": effective_fight_vigor,
                    # Food automation is opt-in. These explicit false values
                    # also clear legacy keeper policy restored by the broker.
                    "eat_before_fighting": eat_before_fighting,
                    "buy_food": buy_food,
                    # Open-field farming is permitted only when durable state
                    # chose it as a materially different tactic: either an
                    # operator-authored public goal or the planner's persisted
                    # internal campaign phase. A one-turn model-only false
                    # value is still normalized to the wall strategy.
                    "use_safe_spots": False if allow_open_field else True,
                    "hold_resume_above": max(0.9, float(arguments.get("hold_resume_above", 0.9))),
                    # max_carry counts occupied inventory entries, not only new
                    # loot.  A well-supplied character can already exceed the
                    # broker default before the keeper starts, causing an
                    # immediate false stop.  Preserve at least six free entries
                    # for loot and consumable churn while retaining any larger
                    # deliberate limit.
                    "max_carry": max(requested_max_carry, carried_slots + 6),
                    # The keeper cannot deposit below its non-configurable
                    # 400-shilling float.  Preserve 0 as the documented way to
                    # disable special bank trips; otherwise never authorize a
                    # trip whose deposit condition cannot be met.
                    "bank_above": effective_bank_above,
                    # The current keeper can reconnect immediately after a room
                    # transition and restore the prior dangerous saved room.
                    # Keep reconnect breakout disabled until the broker provides
                    # a stable-room/save acknowledgement.
                    "break_out_via_logoff": False,
                }
            )
        elif tool == "autopilot" and arguments.get("action") == "start" and arguments.get("mode") in {"survive", "idle"}:
            normalized.update(
                {
                    "hunt": "",
                    "assigned_room": None,
                    # A retained low farm threshold can trap even survival mode
                    # in bank travel.  Survival is for recovery, not special
                    # money runs; ordinary incidental banking still works.
                    "bank_above": 0,
                    "break_out_via_logoff": False,
                }
            )
        elif tool in PVP_TOOL_NAMES:
            normalized["swings_per_round"] = 1
            normalized["disengage_at"] = max(
                self.config.policy.rest_health_fraction,
                float(arguments.get("disengage_at", self.config.policy.rest_health_fraction)),
            )
        changes = {
            key: {"requested": before.get(key), "applied": value}
            for key, value in normalized.items()
            if before.get(key) != value
        }
        return normalized, changes

    @staticmethod
    def _underworld(observation: dict[str, Any]) -> bool:
        room = deep_get(observation, "look.room.name", deep_get(observation, "look.room", ""))
        return "underworld" in str(room or "").casefold()

    @staticmethod
    def _vital_fraction(observation: dict[str, Any], name: str) -> float | None:
        vital = deep_get(observation, f"status.vitals.{name}", deep_get(observation, f"look.vitals.{name}"))
        if not isinstance(vital, dict):
            return None
        current = vital.get("current", vital.get("value"))
        maximum = vital.get("max")
        try:
            return float(current) / float(maximum) if float(maximum) > 0 else None
        except (TypeError, ValueError, ZeroDivisionError):
            return None

    @staticmethod
    def _vital_value(observation: dict[str, Any], name: str) -> float | None:
        vital = deep_get(
            observation,
            f"status.vitals.{name}",
            deep_get(observation, f"look.vitals.{name}"),
        )
        current = vital.get("current", vital.get("value")) if isinstance(vital, dict) else vital
        try:
            return float(current)
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _required_mana_from_refusal(reason: Any) -> float | None:
        text = " ".join(str(reason or "").split()).casefold()
        patterns = (
            r"costs?\s+(\d+(?:\.\d+)?)\s+mana",
            r"(?:need|requires?|required)\s+(\d+(?:\.\d+)?)\s+mana",
            r"mana[^\d]{0,20}(?:need|requires?|required)[^\d]{0,8}(\d+(?:\.\d+)?)",
        )
        for pattern in patterns:
            match = re.search(pattern, text)
            if match:
                try:
                    return float(match.group(1))
                except (TypeError, ValueError):
                    pass
        return None

    def _live_overlevel_hostiles(
        self,
        observation: dict[str, Any],
        *,
        danger_margin: int = FARM_DANGER_MARGIN,
    ) -> list[dict[str, Any]]:
        """Join live attackable room objects to source-derived creature levels.

        Generator tables cannot describe temporary faction troops, summons, or
        other creatures created by live world state. The ordinary client does
        expose their names, and the pinned corpus knows their levels, so this
        join closes that gap without requiring an administrative game API.
        """
        maximum = deep_get(
            observation,
            "status.vitals.health.max",
            deep_get(observation, "look.vitals.health.max"),
        )
        try:
            level = int(maximum)
        except (TypeError, ValueError):
            return []
        limit = level + max(0, int(danger_margin))
        objects = deep_get(observation, "look.objects", [])
        objects = objects if isinstance(objects, list) else []
        resolved_by_name: dict[str, dict[str, Any] | None] = {}
        threats: list[dict[str, Any]] = []
        for item in objects:
            if not isinstance(item, dict) or item.get("is_player") is True:
                continue
            affordances = item.get("can") if isinstance(item.get("can"), list) else []
            if "attack" not in affordances:
                continue
            name = str(item.get("name") or "").strip()
            if not name:
                continue
            key = name.casefold()
            if key not in resolved_by_name:
                match = self.knowledge.resolve(
                    name, kinds=["creature"], allow_fuzzy=False
                )
                resolved_by_name[key] = (
                    match.get("entity")
                    if match.get("status") in {"found", "found_fuzzy"}
                    and isinstance(match.get("entity"), dict)
                    else None
                )
            entity = resolved_by_name[key]
            entity_id = entity.get("id") if isinstance(entity, dict) else None
            if (
                entity_id in POLITICAL_FACTION_TROOP_ENTITY_IDS
                and not self._has_live_hostility_evidence(item)
            ):
                # ATTACK in the ordinary-client affordance list says the character may
                # initiate a swing.  It does not mean this troop has targeted
                # her.  Neutral and same-faction players are allies in the game
                # source, so presence alone must not become a farm quarantine.
                continue
            facts = (
                entity.get("facts")
                if isinstance(entity, dict) and isinstance(entity.get("facts"), dict)
                else {}
            )
            try:
                creature_level = int(facts.get("level"))
            except (TypeError, ValueError):
                continue
            is_threat, attack_rating = _is_overlevel_farm_threat(
                creature_level,
                limit,
                difficulty=facts.get("difficulty"),
            )
            if not is_threat:
                continue
            threats.append(
                {
                    "object_id": item.get("id"),
                    "name": name,
                    "level": creature_level,
                    "difficulty": facts.get("difficulty"),
                    "attack_rating": attack_rating,
                    "character_level": level,
                    "danger_limit": limit,
                    "distance": item.get("distance"),
                    "reachable": item.get("reachable"),
                    "entity_id": entity_id,
                    "source_ref": deep_get(entity or {}, "evidence.source_ref"),
                }
            )
        return sorted(
            threats,
            key=lambda item: (-int(item["level"]), float(item.get("distance") or 0)),
        )

    def _combat_preflight(
        self,
        tool: str,
        arguments: dict[str, Any],
        observation: dict[str, Any],
        goal: dict[str, Any],
    ) -> list[dict[str, Any]]:
        if not self._is_combat_start(tool, arguments):
            return []
        blockers: list[dict[str, Any]] = []
        if self._underworld(observation):
            blockers.append({"kind": "recover_from_underworld", "guidance": "escape through a functioning portal before combat"})
        health = self._vital_fraction(observation, "health")
        if health is not None:
            if tool == "fight":
                try:
                    disengage_at = float(
                        arguments.get(
                            "disengage_at",
                            self.config.policy.rest_health_fraction,
                        )
                    )
                except (TypeError, ValueError):
                    disengage_at = self.config.policy.rest_health_fraction
                minimum_start = min(
                    0.99,
                    max(self.config.policy.rest_health_fraction, disengage_at)
                    + MANUAL_COMBAT_START_MARGIN,
                )
                if health <= minimum_start:
                    blockers.append(
                        {
                            "kind": "recover_health",
                            "health_fraction": health,
                            "minimum_start_fraction": minimum_start,
                            "disengage_at": disengage_at,
                            "guidance": (
                                "recover above the manual-combat start floor before "
                                f"another one-swing fight ({minimum_start:.0%}; the "
                                f"verified disengage floor is {disengage_at:.0%})"
                            ),
                        }
                    )
            elif health < 1.0:
                blockers.append(
                    {
                        "kind": "recover_health",
                        "health_fraction": health,
                        "guidance": "return to full health before launching autonomous combat",
                    }
                )
        mana = self._vital_fraction(observation, "mana")
        if mana is not None and mana < 1.0:
            blockers.append({"kind": "recover_mana", "mana_fraction": mana, "guidance": "return to full mana before a new hazardous encounter"})
        rested = deep_get(observation, "status.vitals.vigor.rested", deep_get(observation, "look.vitals.vigor.rested"))
        if rested is False:
            blockers.append(
                {
                    "kind": "recover_vigor",
                    "guidance": (
                        "rest until the game reports rested; food is an optional "
                        "planner-owned tactic, never a controller prerequisite"
                    ),
                }
            )
        if tool == "autopilot" and arguments.get("mode") == "farm":
            assigned_room = arguments.get("assigned_room")
            current_room = deep_get(observation, "look.room.num")
            if (
                assigned_room is not None
                and current_room is not None
                and str(assigned_room) == str(current_room)
            ):
                live_threats = self._live_overlevel_hostiles(observation)
                if live_threats:
                    blockers.append(
                        {
                            "kind": "live_room_overlevel_hostile",
                            "assigned_room": assigned_room,
                            "hostiles": live_threats,
                            "guidance": (
                                "Do not start the farm while these live, non-generator threats are present. "
                                "Recover under survival control and scout a different grounded room before launching."
                            ),
                        }
                    )
            quarantines = self.storage.get_runtime("farm_tactic_quarantine_v1", {})
            quarantines = quarantines if isinstance(quarantines, dict) else {}
            quarantine = quarantines.get(str(assigned_room)) if assigned_room is not None else None
            if isinstance(quarantine, dict) and self._farm_quarantine_matches(
                quarantine, arguments
            ):
                blockers.append(
                    {
                        "kind": "quarantined_farm_tactic",
                        "assigned_room": assigned_room,
                        "guidance": quarantine.get("guidance")
                        or "choose a different grounded farm room; this room/prey tactic failed survivability",
                        "evidence": quarantine,
                    }
                )
            stagnations = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
            stagnations = stagnations if isinstance(stagnations, dict) else {}
            stagnation_key = (
                f"{goal['id']}|{assigned_room}|{str(arguments.get('hunt') or '').strip().casefold()}"
            )
            stagnation = stagnations.get(stagnation_key)
            if isinstance(stagnation, dict) and self._farm_stagnation_blocks(
                stagnation
            ):
                blockers.append(
                    {
                        "kind": "stagnated_farm_tactic",
                        "assigned_room": assigned_room,
                        "hunt": arguments.get("hunt"),
                        "guidance": stagnation.get("guidance")
                        or "query hunting_grounds once and choose a different grounded room; do not restart this stalled room/prey tactic unchanged",
                        "evidence": stagnation,
                    }
                )
        if tool in PVP_TOOL_NAMES:
            if tool == PVP_SEEK_TOOL_NAME:
                route_failure = self.storage.get_runtime(
                    PVP_ROUTE_FAILURE_RUNTIME_KEY, {}
                )
                current_room = deep_get(
                    observation,
                    "look.room.num",
                    deep_get(observation, "look.room_id"),
                )
                if (
                    isinstance(route_failure, dict)
                    and str(route_failure.get("actual_room_id")) == str(current_room)
                    and route_failure.get("corpus_version") == self.knowledge.corpus_version
                ):
                    blockers.append(
                        {
                            "kind": "pvp_patrol_route_unavailable",
                            "room_id": current_room,
                            "failed_hop": route_failure.get("failed_hop"),
                            "reason": route_failure.get("reason"),
                            "guidance": (
                                "do not vary pvp_seek room pairs from this location: the prior patrol did not "
                                "complete because its shared route hop was unavailable. Relocate through a "
                                "verified working exit or wait for the route/map implementation to change"
                            ),
                        }
                    )
            maximum = deep_get(observation, "status.vitals.health.max", deep_get(observation, "look.vitals.health.max"))
            prior_pvp = self.storage.events(kinds=["pvp.engagement.completed"], limit=1)["events"]
            if isinstance(maximum, (int, float)) and maximum < 30 and not prior_pvp:
                blockers.append(
                    {
                        "kind": "new_player_pvp_protection",
                        "max_health": maximum,
                        "guidance": "progress to 30 max HP first unless fresh live evidence proves this server permits earlier PvP",
                    }
                )
        return blockers

    def _safety_preflight(
        self,
        tool: str,
        arguments: dict[str, Any],
        observation: dict[str, Any],
        goal: dict[str, Any],
    ) -> list[dict[str, Any]]:
        blockers = self._combat_preflight(tool, arguments, observation, goal)
        transition = self._foreground_room_transition(tool, arguments)
        if transition:
            farm_intent = self._effective_farm_intent(goal)
            assigned_room = farm_intent.get("assigned_room")
            destination_room_ids = transition.get("room_ids", [])
            enters_assigned_room = assigned_room is not None and any(
                str(room_id) == str(assigned_room) for room_id in destination_room_ids
            )
            if enters_assigned_room:
                blockers.append(
                    {
                        "kind": "keeper_owned_hazardous_travel",
                        "assigned_room": assigned_room,
                        "destination": transition,
                        "guidance": (
                            f"do not use foreground {tool} to enter assigned farm room {assigned_room}; "
                            "the executable tool arguments contradict the safe farm workflow. From a bank or inn, "
                            "start the bounded farm keeper and let it own the hazardous route and combat"
                        ),
                    }
                )

        if tool == "bank":
            room_name = str(deep_get(observation, "look.room.name", ""))
            if "bank" not in room_name.casefold():
                blockers.append(
                    {
                        "kind": "bank_location_required",
                        "room": room_name,
                        "guidance": "travel to a verified bank room before calling bank; never invoke a mutation merely to make it fail",
                    }
                )
        if tool == "bank" and arguments.get("action") == "deposit":
            goal_text = " ".join(
                (
                    str(goal.get("title", "")),
                    str(goal.get("objective", "")),
                    str(deep_get(goal, "constraints.operator_notes", "")),
                )
            ).casefold()
            shopping_goal = any(
                marker in goal_text
                for marker in ("buy", "purchase", "shopping", "merchant", "shop", "acquire")
            )
            if shopping_goal:
                completion = self.criteria.evaluate(goal, observation)
                result_by_id = {
                    str(item.get("id")): item
                    for item in completion.get("criteria", [])
                    if isinstance(item, dict)
                }
                unmet_inventory = []
                for index, criterion in enumerate(goal.get("success_criteria", [])):
                    if not isinstance(criterion, dict) or criterion.get("kind") != "inventory_contains":
                        continue
                    criterion_id = str(criterion.get("id") or f"criterion_{index + 1}")
                    if result_by_id.get(criterion_id, {}).get("met") is not True:
                        unmet_inventory.append(criterion.get("item"))
                if unmet_inventory:
                    blockers.append(
                        {
                            "kind": "retain_purchase_funds",
                            "unmet_inventory": unmet_inventory,
                            "guidance": "keep the money needed for the current safe shopping goal; deposit only after the purchase or before a genuinely hazardous phase",
                        }
                    )
        return blockers

    def _foreground_room_transition(
        self, tool: str, arguments: dict[str, Any]
    ) -> dict[str, Any] | None:
        """Ground a planner-owned destination against room ids and spawn facts.

        This check deliberately runs above the broker.  It prevents a model
        response whose prose says "bank first" while its executable arguments
        say ``travel(to=<farm room>)`` from moving the character even once.
        """
        if tool not in FOREGROUND_ROOM_TRANSITION_TOOLS or arguments.get("to") is None:
            return None
        raw_destination = arguments.get("to")
        room_ids: list[Any] = []
        if isinstance(raw_destination, (int, float)) and not isinstance(
            raw_destination, bool
        ):
            room_ids.append(int(raw_destination))
        elif isinstance(raw_destination, str) and raw_destination.strip().isdigit():
            room_ids.append(int(raw_destination.strip()))

        grounded_rooms: list[dict[str, Any]] = []
        hazardous = False
        try:
            resolved = self.knowledge.resolve(
                str(raw_destination), kinds=["location"], allow_fuzzy=False
            )
            candidates = []
            if isinstance(resolved.get("entity"), dict):
                candidates.append(resolved["entity"])
            for candidate in resolved.get("matches", []):
                if isinstance(candidate, dict) and candidate not in candidates:
                    candidates.append(candidate)
            for candidate in candidates:
                facts = candidate.get("facts") if isinstance(candidate.get("facts"), dict) else {}
                room_id = facts.get("room_id")
                if room_id is not None and room_id not in room_ids:
                    room_ids.append(room_id)
                detail = self.knowledge.get(str(candidate.get("id") or ""))
                entity = detail.get("entity") if isinstance(detail.get("entity"), dict) else {}
                spawn_table = (
                    entity.get("spawn_table")
                    if isinstance(entity.get("spawn_table"), dict)
                    else {}
                )
                hostile_spawns = [
                    spawn
                    for spawn in spawn_table.get("spawns", [])
                    if isinstance(spawn, dict) and self._spawn_is_hostile(spawn)
                ]
                if hostile_spawns:
                    hazardous = True
                grounded_rooms.append(
                    {
                        "room_id": room_id,
                        "name": candidate.get("canonical_name"),
                        "hostile_spawn_count": len(hostile_spawns),
                    }
                )
        except (OSError, sqlite3.Error, TypeError, ValueError):
            # Knowledge is decision support, not a new availability dependency.
            # Exact numeric keeper ownership remains enforceable when it is down.
            pass
        return {
            "requested": raw_destination,
            "room_ids": room_ids,
            "hazardous": hazardous,
            "grounded_rooms": grounded_rooms,
        }

    @staticmethod
    def _spawn_is_hostile(spawn: dict[str, Any]) -> bool:
        """Classify static spawns by source role, never by character level.

        Merchants, teachers, and other NPCs have levels in the compendium. A
        room is statically hazardous only when its source record identifies an
        actual monster; live aggression remains authoritative for surprises.
        """
        return str(spawn.get("role") or "").strip().casefold() == "monster"

    @staticmethod
    def _is_combat_start(tool: str, arguments: dict[str, Any]) -> bool:
        return tool in {"fight", "attack", *PVP_TOOL_NAMES} or (
            tool == "autopilot"
            and arguments.get("action") == "start"
            and arguments.get("mode") == "farm"
        )

    def _begin_foreground_action(
        self, tool: str, *, goal_id: str | None = None
    ) -> None:
        self._foreground_action = {
            "tool": tool,
            "goal_id": goal_id,
            "started_at": timestamp(),
        }
        self._game_action_active.set()

    def _end_foreground_action(self) -> None:
        self._game_action_active.clear()
        self._foreground_action = None

    def _reconcile_after_action_error(
        self,
        *,
        error: str,
    ) -> dict[str, Any] | None:
        try:
            self._begin_foreground_action("reconcile_after_action_error")
            if "not in game" in error.casefold() and self.config.game.autojoin:
                self.broker.ensure_joined()
            observation = self._reconcile_recent_inventory_creation(
                self._reconcile_recent_room_transition(self.broker.observe())
            )
            self.last_observation = observation
            self._remember_safe_staging(observation)
            self.storage.record_snapshot(redact(observation))
            self.dependencies["broker"] = "healthy"
            return observation
        except BrokerError as exc:
            self.warnings = [*self.warnings[-9:], f"action reconciliation: {str(exc)[:300]}"]
            return None
        finally:
            self._end_foreground_action()

    def _record_death(
        self,
        goal: dict[str, Any],
        *,
        tool: str,
        arguments: dict[str, Any],
        before: dict[str, Any],
        after: dict[str, Any],
        result: Any = None,
        error: str | None = None,
        correlation_id: str | None = None,
        policy_decision_id: str | None = None,
    ) -> dict[str, Any]:
        combat = self.learning.record_combat_outcome(
            tool=tool,
            arguments=arguments,
            before=before,
            result=result,
            after=after,
            error=error,
            died=True,
        )
        event = self.storage.emit_event(
            "character.died",
            f"The character died during {tool}",
            severity="critical",
            interesting=True,
            goal_id=goal["id"],
            data={
                "tool": tool,
                "target": arguments.get("target"),
                "before": {
                    "room": redact(deep_get(before, "look.room")),
                    "vitals": redact(deep_get(before, "status.vitals", deep_get(before, "look.vitals", {}))),
                    "inventory": redact(deep_get(before, "inventory.items", [])),
                },
                "after": {
                    "room": redact(deep_get(after, "look.room")),
                    "vitals": redact(deep_get(after, "status.vitals", deep_get(after, "look.vitals", {}))),
                    "inventory": redact(deep_get(after, "inventory.items", [])),
                },
                "broker_result": redact(result),
                "broker_error": str(error or "")[:500] or None,
                "combat_memory": combat,
            },
            correlation_id=correlation_id,
            policy_decision_id=policy_decision_id,
        )
        deferred = self.learning.defer_goal(
            goal,
            after,
            tool=tool,
            arguments=arguments,
            reason=(
                "Observed death invalidates this exact combat tactic in the "
                "current room and character state"
            ),
            event_kind="character.died",
            evidence_event_ids=[event["id"]],
            classification="insufficient_combat_power",
            scope="tactic",
            block=False,
        )
        return {"event": event, "strategic_goal_preserved": True, **deferred}

    def _goal_draft_character_state(self) -> dict[str, Any]:
        observation = self.last_observation or {}
        inventory = deep_get(observation, "inventory.items", [])
        abilities = observation.get("abilities")
        active = self.storage.active_goal()
        ability_summary: dict[str, list[dict[str, Any]]] = {}
        for group in ("skills", "spells"):
            rows = abilities.get(group) if isinstance(abilities, dict) else None
            if isinstance(rows, list):
                ability_summary[group] = [
                    {
                        "name": item.get("name"),
                        "ability": item.get("ability"),
                    }
                    for item in rows[:40]
                    if isinstance(item, dict)
                ]
        return redact(
            {
                "character": self._character_name(observation),
                "location": {
                    "name": deep_get(
                        observation,
                        "look.room.name",
                        deep_get(observation, "look.room"),
                    ),
                    "room_id": deep_get(
                        observation,
                        "look.room.num",
                        deep_get(observation, "look.room_id"),
                    ),
                },
                "vitals": deep_get(
                    observation,
                    "status.vitals",
                    deep_get(observation, "look.vitals", {}),
                ),
                "inventory": [
                    {
                        "name": item.get("name"),
                        "amount": item.get("amount", 1),
                    }
                    for item in inventory[:40]
                    if isinstance(item, dict)
                ]
                if isinstance(inventory, list)
                else [],
                "abilities": ability_summary,
                "active_goal": {
                    key: active.get(key)
                    for key in ("id", "title", "objective", "priority", "status")
                }
                if active
                else None,
            }
        )

    def _goal_draft_grounding_hints(
        self, prompt: str, current_goal: dict[str, Any] | None
    ) -> list[dict[str, Any]]:
        query = " ".join(
            part
            for part in (
                prompt,
                str((current_goal or {}).get("title") or ""),
                str((current_goal or {}).get("objective") or ""),
            )
            if part
        )[:4000]
        if not query or not self.knowledge.available:
            return []
        matches = self.knowledge.search(query, limit=8).get("matches", [])
        ability_matches = self.knowledge.search(
            query, kinds=["skill", "spell"], limit=8
        ).get("matches", [])
        current_plan = (
            (current_goal or {}).get("constraints", {}).get("purchase_plan")
            if isinstance((current_goal or {}).get("constraints"), dict)
            else None
        )
        if isinstance(current_plan, dict) and current_plan.get("offering_kind") in {
            "skill",
            "spell",
        }:
            exact = self.knowledge.resolve(
                str(current_plan.get("item") or ""),
                kinds=[str(current_plan["offering_kind"])],
            )
            if exact.get("status") == "found":
                ability_matches.append(exact["entity"])
        hints = [
            {
                "id": item.get("id"),
                "kind": item.get("kind"),
                "canonical_name": item.get("canonical_name"),
                "summary": item.get("summary"),
                "facts": self.knowledge._compact_entity(item).get("facts", {}),
            }
            for item in matches
            if isinstance(item, dict)
        ]
        seen_abilities: set[str] = set()
        for item in ability_matches:
            if not isinstance(item, dict) or str(item.get("kind")) not in {
                "skill",
                "spell",
            }:
                continue
            entity_id = str(item.get("id") or "")
            if not entity_id or entity_id in seen_abilities:
                continue
            seen_abilities.add(entity_id)
            training = self.knowledge.training_candidates(
                str(item["kind"]), str(item.get("canonical_name") or "")
            )
            hints.append(
                {
                    "id": f"training:{entity_id}",
                    "kind": "training_options",
                    "offering_kind": item["kind"],
                    "canonical_name": item.get("canonical_name"),
                    "purchase_plan_candidates": training.get("candidates", []),
                    "selection_rule": (
                        "Copy one complete purchase_plan candidate exactly; do not infer a teacher from a room name."
                    ),
                }
            )
        return hints

    @staticmethod
    def _unique_grounded_training_plan(
        candidate: dict[str, Any], grounding_hints: list[dict[str, Any]]
    ) -> dict[str, Any] | None:
        """Select a sole complete catalogue plan for the draft's named ability."""

        requested: set[tuple[str, str]] = set()
        constraints = candidate.get("constraints")
        plan = constraints.get("purchase_plan") if isinstance(constraints, dict) else None
        if isinstance(plan, dict) and plan.get("offering_kind") in {"skill", "spell"}:
            requested.add(
                (
                    str(plan["offering_kind"]),
                    normalize(plan.get("item")),
                )
            )
        for criterion in candidate.get("success_criteria", []):
            if not isinstance(criterion, dict):
                continue
            parsed = parse_ability_metric(criterion.get("metric"))
            if parsed is not None:
                requested.add((parsed[0], normalize(parsed[1])))

        options = [
            hint
            for hint in grounding_hints
            if isinstance(hint, dict) and hint.get("kind") == "training_options"
        ]
        selected = [
            option
            for option in options
            if (
                str(option.get("offering_kind")),
                normalize(option.get("canonical_name")),
            )
            in requested
        ]
        if (
            not selected
            and len(options) == 1
            and KnowledgeBase._ability_acquisition_intent(candidate)
        ):
            selected = options
        if len(selected) != 1:
            return None
        complete = [
            value
            for value in selected[0].get("purchase_plan_candidates", [])
            if isinstance(value, dict)
            and value.get("complete") is True
            and isinstance(value.get("maximum_price"), int)
        ]
        if len(complete) != 1:
            return None
        chosen = complete[0]
        return {
            key: chosen[key]
            for key in (
                "offering_kind",
                "item",
                "merchant_class",
                "room_id",
                "maximum_price",
            )
        }

    def draft_goal(self, payload: dict[str, Any]) -> dict[str, Any]:
        """Create and statically validate an inert model-authored goal draft."""

        allowed_request_fields = {"prompt", "current_goal"}
        unknown = sorted(set(payload) - allowed_request_fields)
        if unknown:
            raise ValueError(
                f"unknown goal draft field(s): {', '.join(unknown)}"
            )
        prompt_value = payload.get("prompt")
        if not isinstance(prompt_value, str):
            raise ValueError("goal draft prompt must be a string")
        prompt = prompt_value.strip()
        if not prompt:
            raise ValueError("goal draft prompt is required")
        if len(prompt) > 4000:
            raise ValueError("goal draft prompt must be at most 4000 characters")
        current_value = payload.get("current_goal")
        if current_value is not None and not isinstance(current_value, dict):
            raise ValueError("current_goal must be an object")
        if current_value is not None and len(canonical_json(current_value)) > 32_000:
            raise ValueError("current_goal is too large")

        draft_fields = {
            "title",
            "objective",
            "success_criteria",
            "constraints",
            "priority",
            "activation",
        }
        unknown_current_fields = (
            sorted(set(current_value) - draft_fields)
            if isinstance(current_value, dict)
            else []
        )
        if unknown_current_fields:
            raise ValueError(
                "unknown current_goal field(s): "
                + ", ".join(unknown_current_fields)
            )
        current_goal = (
            {key: value for key, value in current_value.items() if key in draft_fields}
            if isinstance(current_value, dict)
            else None
        )
        character_state = self._goal_draft_character_state()
        grounding_hints = self._goal_draft_grounding_hints(prompt, current_goal)
        validation_feedback: list[dict[str, Any]] = []
        validation: dict[str, Any] | None = None
        candidate = current_goal
        for _ in range(3):
            generated = self.model.draft_goal(
                prompt=prompt,
                current_goal=candidate,
                validation_feedback=validation_feedback,
                verified_character_state=character_state,
                grounding_hints=grounding_hints,
            )
            candidate = {
                key: value for key, value in generated.items() if key in draft_fields
            }
            grounded_plan = self._unique_grounded_training_plan(
                candidate, grounding_hints
            )
            grounded_plan_applied = False
            if grounded_plan is not None:
                constraints = candidate.get("constraints")
                constraints = dict(constraints) if isinstance(constraints, dict) else {}
                if constraints.get("purchase_plan") != grounded_plan:
                    constraints["purchase_plan"] = grounded_plan
                    candidate["constraints"] = constraints
                    grounded_plan_applied = True
            validation = self.knowledge.validate_goal(candidate)
            if validation.get("valid"):
                warnings = list(validation.get("warnings", []))
                if grounded_plan_applied:
                    warnings.append(
                        {
                            "code": "TRAINING_PLAN_GROUNDED",
                            "message": (
                                "Replaced the model's training destination and budget with the sole complete catalogue candidate."
                            ),
                        }
                    )
                return {
                    "goal": validation["canonical_goal"],
                    "validation": {
                        "warnings": warnings,
                        "resolved_entities": validation.get("resolved_entities", []),
                        "corpus": validation.get("corpus", {}),
                    },
                    "model": self.config.model.name,
                }
            validation_feedback = [
                item
                for item in validation.get("errors", [])
                if isinstance(item, dict)
            ]
        assert validation is not None
        raise KnowledgeValidationError(validation)

    def submit_goal(self, payload: dict[str, Any]) -> dict[str, Any]:
        if self._shutdown_requested.is_set():
            raise InvalidTransition(
                "controller shutdown is draining; new gameplay goals are not accepted"
            )
        onboarding = self._onboarding_status(self.last_observation or {})
        if not onboarding.get("ready_for_goals"):
            raise OnboardingRequired(
                f"character onboarding is {onboarding.get('status')}; "
                f"{onboarding.get('next_action')}"
            )
        grounding = self.knowledge.require_valid_goal(payload)
        canonical = grounding["canonical_goal"]
        replay = self.storage.idempotent_result(str(canonical.get("request_id", "")), "submit_goal", canonical)
        if replay is not None:
            result = replay
        else:
            family = self.learning.goal_family(canonical)
            existing = next(
                (
                    goal
                    for status in ("active", "queued", "paused")
                    for goal in self.storage.goals([status])
                    if self.learning.goal_family(goal) == family
                ),
                None,
            )
            if existing is not None:
                result = {
                    "goal": existing,
                    "queue_position": None,
                    "deduplicated": True,
                    "warnings": [
                        {
                            "code": "GOAL_ALREADY_IN_PROGRESS",
                            "message": (
                                f"An equivalent goal is already {existing['status']}; supervise or resume it "
                                "instead of creating another retry."
                            ),
                            "goal_id": existing["id"],
                            "goal_family": family,
                        }
                    ],
                }
            else:
                review = self.learning.require_goal_eligible(canonical, self.last_observation or {})
                result = self.storage.submit_goal(
                    canonical,
                    retry_of_goal_id=review.get("retry_of_goal_id"),
                    preserve_replaced_active=True,
                )
                if review.get("lesson_id"):
                    self.storage.mark_retry_started(review["lesson_id"], result["goal"]["id"])
        result["grounding"] = {
            "corpus": grounding["corpus"],
            "resolved_entities": grounding["resolved_entities"],
            "warnings": grounding["warnings"],
        }
        return result

    def persona(self) -> dict[str, Any]:
        """Return the active persona together with its character-setup state."""

        return {
            **self.storage.persona(),
            "onboarding": self._onboarding_status(self.last_observation or {}),
        }

    def set_persona(self, payload: dict[str, Any]) -> dict[str, Any]:
        """Persist a persona and request goal-independent character onboarding."""

        allowed = {
            "request_id",
            "expected_version",
            "persona",
            "replace_existing_character",
        }
        unknown = sorted(set(payload) - allowed)
        if unknown:
            raise ValueError(f"unknown persona fields: {', '.join(unknown)}")
        replace_existing = payload.get("replace_existing_character", False)
        if not isinstance(replace_existing, bool):
            raise ValueError("replace_existing_character must be a boolean")
        stored = self.storage.set_persona(
            {
                key: value
                for key, value in payload.items()
                if key
                in {
                    "request_id",
                    "expected_version",
                    "persona",
                }
            }
        )
        if self.config.onboarding.enabled and self.config.onboarding.create_from_persona:
            previous = self.storage.get_runtime(ONBOARDING_RUNTIME_KEY, {})
            request_id = str(payload.get("request_id", ""))
            already_recorded = bool(
                isinstance(previous, dict)
                and previous.get("request_id") == request_id
                and int(previous.get("persona_version", 0)) == int(stored["version"])
            )
            if not already_recorded:
                state = {
                    "status": "pending",
                    "request_id": request_id,
                    "persona_version": stored["version"],
                    "desired_name": stored["name"],
                    "replace_existing_character": replace_existing,
                    "requested_at": timestamp(),
                }
                self.storage.set_runtime(ONBOARDING_RUNTIME_KEY, state)
                self.storage.emit_event(
                    "onboarding.requested",
                    f"Character onboarding requested for {stored['name']}",
                    severity="notice",
                    interesting=True,
                    data={
                        "persona_version": stored["version"],
                        "desired_name": stored["name"],
                        "replace_existing_character": replace_existing,
                    },
                )
        return {**stored, "onboarding": self._onboarding_status(self.last_observation or {})}

    def _onboarding_status(
        self, observation: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        """Project the durable setup state without performing game mutations."""

        if not self.config.onboarding.enabled:
            return {
                "status": "disabled",
                "ready_for_goals": True,
                "next_action": "Submit a goal when ready.",
            }
        persona = self.storage.persona()
        if int(persona.get("version", 0)) == 0:
            return {
                "status": "awaiting_persona",
                "ready_for_goals": False,
                "next_action": (
                    "Set the character name and complete persona through the persona tool."
                ),
            }
        state = self.storage.get_runtime(ONBOARDING_RUNTIME_KEY, {})
        state = dict(state) if isinstance(state, dict) else {}
        current_name = str(
            self._character_name(observation or self.last_observation or {}) or ""
        ).strip()
        desired_name = str(persona.get("name") or state.get("desired_name") or "").strip()
        if current_name and desired_name and current_name.casefold() == desired_name.casefold():
            return {
                **state,
                "status": "ready",
                "ready_for_goals": True,
                "desired_name": desired_name,
                "current_name": current_name,
                "next_action": "Submit the first strategic goal.",
            }
        status = str(state.get("status") or "pending")
        next_actions = {
            "pending": "The configured LLM will choose and create the character build.",
            "planning": "The configured LLM is choosing the character build.",
            "creating": "The controller is creating and verifying the character.",
            "awaiting_existing_character_confirmation": (
                "Set the persona again with replace_existing_character=true to replace the established character."
            ),
            "failed": (
                "Review the onboarding error, then set the persona again with a new request_id to retry."
            ),
        }
        return {
            **state,
            "status": status,
            "ready_for_goals": False,
            "desired_name": desired_name,
            "current_name": current_name or None,
            "next_action": next_actions.get(
                status, "Wait for the controller to complete character onboarding."
            ),
        }

    def _set_onboarding_state(self, **updates: Any) -> dict[str, Any]:
        current = self.storage.get_runtime(ONBOARDING_RUNTIME_KEY, {})
        value = dict(current) if isinstance(current, dict) else {}
        value.update(updates)
        value["updated_at"] = timestamp()
        self.storage.set_runtime(ONBOARDING_RUNTIME_KEY, value)
        return value

    def _onboarding_turn(self, observation: dict[str, Any]) -> dict[str, Any]:
        """Create the persona-named character before accepting ordinary goals."""

        status = self._onboarding_status(observation)
        if status.get("ready_for_goals") or status.get("status") in {
            "awaiting_persona",
            "awaiting_existing_character_confirmation",
            "failed",
        }:
            return status

        persona_record = self.storage.persona()
        desired_name = str(persona_record.get("name") or "").strip()
        current_name = str(self._character_name(observation) or "").strip()
        state = self.storage.get_runtime(ONBOARDING_RUNTIME_KEY, {})
        state = dict(state) if isinstance(state, dict) else {}
        generated_placeholder = bool(
            current_name and GENERATED_CHARACTER_NAME_RE.fullmatch(current_name)
        )
        may_replace = bool(state.get("replace_existing_character")) or generated_placeholder
        if (
            current_name
            and current_name.casefold() != desired_name.casefold()
            and self.config.onboarding.preserve_existing_character
            and not may_replace
        ):
            first_notice = state.get("status") != "awaiting_existing_character_confirmation"
            state = self._set_onboarding_state(
                status="awaiting_existing_character_confirmation",
                current_name=current_name,
            )
            if first_notice:
                self.storage.emit_event(
                    "onboarding.existing_character_preserved",
                    f"Preserved established character {current_name} during onboarding",
                    severity="warning",
                    interesting=True,
                    data={"current_name": current_name, "desired_name": desired_name},
                )
            return self._onboarding_status(observation)

        capabilities = self.broker.capabilities()
        if "reroll" not in capabilities:
            self._set_onboarding_state(
                status="failed",
                error="the pinned harness does not expose the reroll capability",
            )
            return self._onboarding_status(observation)

        self._set_onboarding_state(status="planning", current_name=current_name or None)
        choice = self.model.plan_character(
            persona=persona_record,
            current_character={
                "name": current_name or None,
                "generated_placeholder": generated_placeholder,
                "vitals": redact(deep_get(observation, "status.vitals", {})),
            },
        )
        self.dependencies["model"] = "healthy"
        arguments = {
            "action": "reroll",
            "agent": self.config.game.agent,
            "name": desired_name,
            "stats": choice["stats"],
            "loadout": choice["loadout"],
        }
        preview = self.broker.call_tool(
            "reroll",
            {**arguments, "action": "plan"},
            timeout=30,
            mutation=False,
        )
        if not isinstance(preview, dict) or preview.get("ok") is not True:
            self._set_onboarding_state(
                status="failed",
                build=choice,
                error="the harness rejected the character creation plan",
                preview=redact(preview),
            )
            self.storage.emit_event(
                "onboarding.character_plan_rejected",
                "Harness rejected the LLM-selected character build",
                severity="warning",
                interesting=True,
                data={"build": choice, "preview": redact(preview)},
            )
            return self._onboarding_status(observation)

        synthetic_goal = {
            "id": None,
            "title": f"Onboard character {desired_name}",
            "objective": "Create the persona-defined character before goal-driven play.",
        }
        decision = self.policy.evaluate(
            "reroll",
            arguments,
            observation,
            synthetic_goal,
            known_tools=set(capabilities),
        )
        if decision.decision == "deny":
            self._set_onboarding_state(status="failed", error=decision.summary)
            return self._onboarding_status(observation)

        correlation_id = uuid7()
        attempt_id = self.storage.create_action_attempt(
            None,
            observation.get("id"),
            "reroll",
            arguments,
            choice["rationale"],
            decision.id,
            correlation_id,
        )
        assessment_id: str | None = None
        if decision.decision == "allow_with_caution":
            assessment = self.policy.consequence_assessment(
                decision, synthetic_goal, choice["rationale"]
            )
            assessment["action_attempt_id"] = attempt_id
            assessment_id = self.storage.record_consequence(assessment)["id"]

        self._set_onboarding_state(status="creating", build=choice, attempt_id=attempt_id)
        self.storage.update_action_attempt(attempt_id, "sent")
        self.storage.emit_event(
            "onboarding.character_creation.started",
            f"Creating persona-defined character {desired_name}",
            severity="notice",
            interesting=True,
            data={"build": choice, "replacing": current_name or None},
            correlation_id=correlation_id,
            policy_decision_id=decision.id,
        )
        try:
            result = self.broker.call_tool(
                "reroll",
                {**arguments, "confirm": True},
                timeout=max(90, self.config.model.planner_timeout_seconds),
                mutation=True,
            )
            after = self.broker.observe()
            self.last_observation = after
            created_name = str(self._character_name(after) or "").strip()
            verified = bool(
                isinstance(result, dict)
                and result.get("done") is True
                and created_name.casefold() == desired_name.casefold()
            )
            self.storage.update_action_attempt(
                attempt_id,
                "succeeded" if verified else "failed",
                result={"broker": redact(result), "created_name": created_name},
                error_code=None if verified else "ONBOARDING_VERIFICATION_FAILED",
            )
            if assessment_id:
                self.storage.complete_consequence(
                    assessment_id,
                    outcome={"created_name": created_name, "verified": verified},
                    succeeded=verified,
                )
            if not verified:
                self._set_onboarding_state(
                    status="failed",
                    error="character creation did not return the requested verified name",
                    result=redact(result),
                    created_name=created_name or None,
                )
                return self._onboarding_status(after)
            self._set_fallback()
            self._set_onboarding_state(
                status="ready",
                completed_at=timestamp(),
                current_name=created_name,
                result={"done": True, "stats_as_asked": result.get("stats_as_asked")},
            )
            self.storage.emit_event(
                "onboarding.completed",
                f"Character {created_name} is ready for strategic goals",
                severity="notice",
                interesting=True,
                data={"persona_version": persona_record["version"], "build": choice},
                correlation_id=correlation_id,
                policy_decision_id=decision.id,
            )
            return self._onboarding_status(after)
        except (BrokerError, ValueError) as exc:
            self.storage.update_action_attempt(
                attempt_id,
                "failed",
                result={"error": str(exc)[:500]},
                error_code=getattr(exc, "code", "ONBOARDING_FAILED"),
            )
            if assessment_id:
                self.storage.complete_consequence(
                    assessment_id,
                    outcome={"error": str(exc)[:500]},
                    succeeded=False,
                )
            self._set_onboarding_state(status="failed", error=str(exc)[:500])
            raise

    def manage_goal(self, payload: dict[str, Any]) -> dict[str, Any]:
        if (
            self._shutdown_requested.is_set()
            and payload.get("action") == "resume"
        ):
            raise InvalidTransition(
                "controller shutdown is draining; goals cannot be resumed"
            )
        goal = self.storage.goal(str(payload.get("goal_id", "")))
        if goal is None:
            # Preserve the storage layer's stable NOT_FOUND response.
            return self.storage.manage_goal(payload)
        assessment: dict[str, Any] | None = None
        if payload.get("action") == "cancel" and goal.get("status") == "active":
            assessment = self._active_goal_cancellation_assessment(goal, payload)
            if not assessment["allowed"]:
                self.storage.emit_event(
                    "goal.cancellation.guarded",
                    f"Protected active goal from premature cancellation: {goal['title']}",
                    severity="warning",
                    interesting=False,
                    goal_id=goal["id"],
                    data=assessment,
                )
                raise InvalidTransition(
                    "GOAL_COMMITMENT_GUARD: active goal cancellation was refused because the goal is fresh or "
                    "still making verified progress. Pause it for reversible replanning, or provide a controller-"
                    "verifiable cause (safety, invalid, durably_stalled, opportunity_ended); use operator_requested only when the "
                    "human explicitly asked to cancel. "
                    + str(assessment.get("detail") or "")
                )
        result = self.storage.manage_goal(payload)
        resulting_goal = result.get("goal") if isinstance(result, dict) else None
        if (
            payload.get("action") == "confirm_complete"
            and isinstance(resulting_goal, dict)
            and isinstance(self.last_observation, dict)
        ):
            completion = self.criteria.evaluate(
                resulting_goal, self.last_observation
            )
            done = self._complete_goal_if_safe(
                resulting_goal, self.last_observation, completion
            )
            if done is not None:
                result["goal"] = done
                result["completed_at_safe_ending"] = True
                resulting_goal = done
            else:
                checkpoint = self._goal_completion_checkpoint(resulting_goal)
                result["goal"] = self.storage.set_goal_completion(
                    resulting_goal["id"],
                    checkpoint["completion"] if checkpoint is not None else completion,
                )
                result["safe_ending_pending"] = checkpoint is not None
                resulting_goal = result["goal"]
        if payload.get("action") == "resume":
            # Resume is an explicit request to try the strategic outcome again,
            # not to replay the tactical plan and feedback that led to the
            # pause/block. A fresh or preserved campaign phase will require a
            # newly verified plan against current state on its next turn.
            self._invalidate_execution_plan(
                goal, "goal resumed; require a fresh tactical plan from current state"
            )
            if self._planner_feedback(goal) is not None:
                self._clear_planner_feedback()
            self._clear_safety_suppression(goal["id"])
        elif payload.get("action") == "pause":
            # Durable goal/run/phase state is paused atomically by Storage.
            # Retire transient tactical state as well so a later resume cannot
            # replay the exact plan or suppression counter that preceded it.
            self._invalidate_execution_plan(
                goal, "goal paused; retire transient tactical execution state"
            )
            if self._planner_feedback(goal) is not None:
                self._clear_planner_feedback()
            self._clear_safety_suppression(goal["id"])
            keeper_handoff = self._handoff_paused_goal_keeper(goal)
            if keeper_handoff is not None:
                result["keeper_handoff"] = keeper_handoff
        if isinstance(resulting_goal, dict) and resulting_goal.get("status") == "cancelled":
            self.storage.complete_campaign_run(resulting_goal["id"], status="cancelled")
        if assessment is not None:
            result["cancellation_assessment"] = assessment
        return result

    def _handoff_paused_goal_keeper(
        self, goal: dict[str, Any]
    ) -> dict[str, Any] | None:
        """Revoke a paused goal's background keeper without abandoning the character."""
        owner = self.storage.get_runtime("background_farm_owner_v1", {})
        owner = owner if isinstance(owner, dict) else {}
        if owner.get("goal_id") != goal.get("id"):
            return None

        try:
            handoff = self._ensure_survival_keeper()
        except (BrokerError, ValueError) as exc:
            failure = {
                "attempted": True,
                "switched_to_survival": False,
                "error": str(exc)[:500],
            }
            # Keep the ownership record: it is authoritative evidence that a
            # goal-owned keeper may still be driving and must be reconciled.
            self.storage.emit_event(
                "goal.pause_keeper_handoff_failed",
                "Paused the goal, but could not hand its keeper to survival",
                severity="error",
                interesting=True,
                goal_id=goal["id"],
                data=redact(failure),
            )
            return failure

        self.storage.set_runtime("background_farm_owner_v1", {})
        response = {
            "attempted": True,
            "switched_to_survival": True,
            "result": redact(handoff),
        }
        self.storage.emit_event(
            "goal.pause_keeper_handoff",
            "Paused goal handed its background keeper to survival",
            severity="info",
            interesting=True,
            goal_id=goal["id"],
            data=response,
        )
        return response

    def _active_goal_cancellation_assessment(
        self, goal: dict[str, Any], payload: dict[str, Any]
    ) -> dict[str, Any]:
        cause = str(payload.get("cause") or "").strip()
        valid_causes = {
            "operator_requested",
            "safety",
            "invalid",
            "durably_stalled",
            "superseded",
            "opportunity_ended",
        }
        if cause and cause not in valid_causes:
            raise ValueError(f"unknown cancellation cause: {cause}")
        age = self._age_seconds(goal.get("activated_at") or goal.get("created_at")) or 0.0
        liveness = self._compact_liveness(goal)
        since_progress = liveness.get("seconds_since_verified_progress")
        since_action = liveness.get("seconds_since_successful_action")
        since_progress = age if since_progress is None else float(since_progress)
        since_action = age if since_action is None else float(since_action)
        committed = age >= self.config.controller.minimum_goal_commitment_seconds
        quiet_long_enough = min(since_progress, since_action) >= self.config.controller.minimum_stall_seconds
        verified_stall = liveness.get("state") == "stalled" or (committed and quiet_long_enough)
        observation = self.last_observation or {}
        safety_verified = self._underworld(observation) or self._risk(observation) == "critical"
        validation = self.knowledge.validate_goal(
            {
                "title": goal.get("title"),
                "objective": goal.get("objective"),
                "success_criteria": goal.get("success_criteria"),
                "constraints": goal.get("constraints", {}),
                "priority": goal.get("priority", 50),
                "activation": "queue",
            }
        )
        invalid_verified = validation.get("valid") is False
        superseded_verified = committed and bool(self.storage.goals(["queued"]))
        direct_pvp = self._direct_pvp_contract(goal)
        direct_completion = self.criteria.evaluate(goal, observation)
        observation_age = self._age_seconds(observation.get("observed_at"))
        opportunity_ended_verified = bool(
            direct_pvp
            and direct_pvp.get("cancel_if_absent") is True
            and not self._pvp_phase_criterion_met(goal, direct_completion)
            and not self._visible_player_matches(observation, str(direct_pvp["target"]))
            and observation_age is not None
            and observation_age <= 30.0
        )
        allowed = (
            cause == "operator_requested"
            or (cause == "safety" and safety_verified)
            or (cause == "invalid" and invalid_verified)
            or (cause in {"", "durably_stalled"} and verified_stall)
            or (cause == "superseded" and superseded_verified)
            or (cause == "opportunity_ended" and opportunity_ended_verified)
        )
        return {
            "allowed": allowed,
            "cause": cause or None,
            "goal_age_seconds": round(age, 1),
            "minimum_commitment_seconds": self.config.controller.minimum_goal_commitment_seconds,
            "minimum_stall_seconds": self.config.controller.minimum_stall_seconds,
            "seconds_since_verified_progress": round(since_progress, 1),
            "seconds_since_successful_action": round(since_action, 1),
            "liveness_state": liveness.get("state"),
            "verified": {
                "durably_stalled": verified_stall,
                "safety": safety_verified,
                "invalid": invalid_verified,
                "superseded": superseded_verified,
                "opportunity_ended": opportunity_ended_verified,
            },
            "detail": (
                "Current liveness is not a verified durable stall; elapsed criterion time alone is not enough."
                if not allowed
                else "Cancellation cause passed the controller commitment guard."
            ),
        }

    def decide_proposal(self, payload: dict[str, Any]) -> dict[str, Any]:
        request_id = str(payload.get("request_id", ""))
        if request_id and payload.get("action") in {"accept", "reject"}:
            replay = self.storage.idempotent_result(request_id, "decide_proposal", payload)
            if replay is not None:
                return replay
        review: dict[str, Any] = {"allowed": True}
        if payload.get("action") == "accept":
            onboarding = self._onboarding_status(self.last_observation or {})
            if not onboarding.get("ready_for_goals"):
                raise OnboardingRequired(
                    f"character onboarding is {onboarding.get('status')}; "
                    f"{onboarding.get('next_action')}"
                )
            proposal = self.storage.proposal(str(payload.get("proposal_id", "")))
            if proposal:
                grounding = self.knowledge.require_valid_goal(proposal.get("goal_draft", {}))
                review = self.learning.require_goal_eligible(grounding["canonical_goal"], self.last_observation or {})
        result = self.storage.decide_proposal(payload, retry_of_goal_id=review.get("retry_of_goal_id"))
        if review.get("lesson_id") and result.get("goal"):
            self.storage.mark_retry_started(review["lesson_id"], result["goal"]["id"])
        return result

    def validate_goal(self, payload: dict[str, Any]) -> dict[str, Any]:
        return self.knowledge.validate_goal(payload)

    def progression_context(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = payload if isinstance(payload, dict) else {}
        detail = str(payload.get("detail", "compact"))
        if detail not in {"compact", "full"}:
            raise ValueError("detail must be compact or full")
        state = payload.get("character_state") if isinstance(payload.get("character_state"), dict) else (self.last_observation or {})
        result = self.knowledge.progression_context(state, limit=int(payload.get("limit", 8)))
        result["combat_readiness"] = self.learning.readiness_summary(state)
        result["empirical_combat_history"] = self.learning.combat_summary(state, limit=8)
        if not self.offline_diagnostics and self.dependencies.get("broker") == "healthy":
            level = result.get("character", {}).get("max_health")
            capabilities = self.broker.capabilities()
            live_warnings: list[str] = []

            def add_live_result(key: str, tool: str, arguments: dict[str, Any]) -> None:
                try:
                    result[key] = self.broker.call_tool(tool, arguments, timeout=15)
                except (BrokerError, ValueError) as exc:
                    live_warnings.append(f"{tool}: {str(exc)[:300]}")

            if "abilities" in capabilities:
                add_live_result(
                    "live_abilities",
                    "abilities",
                    {"agent": self.config.game.agent, "known_only": True},
                )
            if "spells" in capabilities:
                add_live_result(
                    "live_spell_readiness",
                    "spells",
                    {"agent": self.config.game.agent},
                )
            if level is not None:
                advancement_tool = "progress" if "progress" in capabilities else "advancement"
                if advancement_tool in capabilities:
                    add_live_result(
                        "live_advancement",
                        advancement_tool,
                        {"agent": self.config.game.agent},
                    )
                if "hunting_grounds" in capabilities:
                    grounds: dict[str, Any] = {
                        "for_level": level,
                        "limit": min(12, max(1, int(payload.get("limit", 8)))),
                    }
                    if payload.get("karma") in {"evil", "good", "neutral"}:
                        grounds["karma"] = payload["karma"]
                    add_live_result(
                        "live_hunting_grounds",
                        "hunting_grounds",
                        grounds,
                    )
            if "prey" in capabilities:
                prey: dict[str, Any] = {
                    "agent": self.config.game.agent,
                    "purpose": "advance",
                    "goals": [{"kind": "hp"}],
                    "limit": min(12, max(1, int(payload.get("limit", 8)))),
                }
                if payload.get("karma") in {"evil", "good", "neutral"}:
                    prey["karma"] = payload["karma"]
                add_live_result("live_prey", "prey", prey)
            if live_warnings:
                result["live_warning"] = "; ".join(live_warnings)[:500]
        return result if detail == "full" else self._compact_progression_context(result, state)

    def _compact_progression_context(
        self, result: dict[str, Any], state: dict[str, Any]
    ) -> dict[str, Any]:
        candidates = []
        for item in result.get("candidates", []):
            if not isinstance(item, dict):
                continue
            evidence = item.get("evidence") if isinstance(item.get("evidence"), dict) else {}
            candidates.append(
                {
                    key: item.get(key)
                    for key in (
                        "id",
                        "name",
                        "level",
                        "level_above",
                        "karma",
                        "difficulty",
                        "vulnerabilities",
                        "resistances",
                        "attack_type",
                        "locations",
                    )
                }
                | {
                    "evidence": {
                        "source_tier": evidence.get("source_tier"),
                        "corpus_version": evidence.get("corpus_version"),
                    }
                }
            )

        room_options = []
        for option in result.get("room_options_by_candidate", []):
            if not isinstance(option, dict):
                continue
            target = option.get("target") if isinstance(option.get("target"), dict) else {}
            target_facts = target.get("facts") if isinstance(target.get("facts"), dict) else {}
            rooms = []
            for room in option.get("rooms", []):
                if not isinstance(room, dict):
                    continue
                safe = room.get("safe_spot_evidence") if isinstance(room.get("safe_spot_evidence"), dict) else {}
                rooms.append(
                    {
                        key: room.get(key)
                        for key in (
                            "room",
                            "generator_chance_total",
                            "population_cap",
                            "target",
                            "target_level",
                            "target_chance",
                            "target_how",
                            "target_eligible_for_hp",
                            "preferred",
                        )
                    }
                    | {
                        # The complete mix is the safety-critical part. Omit only
                        # repeated citations; the corpus version remains above.
                        "spawns": [
                            {
                                key: spawn.get(key)
                                for key in (
                                    "creature_id",
                                    "creature",
                                    "level",
                                    "difficulty",
                                    "karma",
                                    "role",
                                    "faction",
                                    "chance",
                                    "cap",
                                    "how",
                                )
                            }
                            for spawn in room.get("spawns", [])
                            if isinstance(spawn, dict)
                        ],
                        "safe_spot_evidence": {
                            key: safe.get(key)
                            for key in (
                                "tested_squares",
                                "proven_clean_squares",
                                "discredited_squares",
                                "clean_hold_seconds",
                            )
                        }
                        | {
                            "best_clean_spots": [
                                {
                                    key: spot.get(key)
                                    for key in (
                                        "col",
                                        "row",
                                        "held",
                                        "failed",
                                        "held_seconds",
                                        "most_attackers",
                                    )
                                }
                                for spot in safe.get("best_clean_spots", [])[:2]
                                if isinstance(spot, dict)
                            ]
                        },
                    }
                )
            room_options.append(
                {
                    "status": option.get("status"),
                    "target": {
                        "id": target.get("id"),
                        "canonical_name": target.get("canonical_name"),
                        "facts": target_facts,
                    },
                    "rooms": rooms,
                    "selection_note": option.get("selection_note"),
                }
            )

        history = (
            result.get("empirical_combat_history")
            if isinstance(result.get("empirical_combat_history"), dict)
            else {}
        )
        compact_history = {
            "by_target": history.get("by_target", [])[:8],
            "recent": [
                {
                    key: item.get(key)
                    for key in (
                        "occurred_at",
                        "target",
                        "outcome",
                        "died",
                        "room",
                        "health_after",
                    )
                }
                for item in history.get("recent", [])[-4:]
                if isinstance(item, dict)
            ],
            "total_deaths": history.get("total_deaths"),
        }
        compact = {
            key: result.get(key)
            for key in (
                "character",
                "new_player_doctrine",
                "verified_rule",
                "guidance",
                "corpus",
                "live_advancement",
                "live_hunting_grounds",
                "live_prey",
                "live_warning",
            )
            if key in result
        }
        compact.update(
            {
                "detail": "compact",
                "candidates": candidates,
                "room_options_by_candidate": room_options,
                "combat_readiness": self._compact_readiness(state),
                "empirical_combat_history": compact_history,
            }
        )
        if "live_abilities" in result or "live_spell_readiness" in result:
            compact["live_development"] = self._compact_character_development(
                {
                    "abilities": result.get("live_abilities"),
                    "spells": result.get("live_spell_readiness"),
                }
            )
        return compact

    def run_forever(self) -> None:
        backoff = 1.0
        while not self.stop_event.is_set():
            self.last_heartbeat_at = timestamp()
            if self._shutdown_requested.is_set():
                self._perform_safe_shutdown()
                continue
            try:
                self.turn()
                backoff = 1.0
                onboarding_ready = self._onboarding_status().get("ready_for_goals")
                cadence = (
                    self.config.controller.active_cadence_seconds
                    if self.storage.active_goal() or onboarding_ready is False
                    else self.config.controller.idle_cadence_seconds
                )
            except BrokerError as exc:
                self.dependencies["broker"] = "unhealthy"
                self._degrade("broker", exc)
                try:
                    self.broker.ensure_started()
                    self.broker.capabilities(refresh=True)
                    if self.config.game.autojoin:
                        self.broker.ensure_joined()
                    self._set_fallback()
                    if self.config.controller.conversation_enabled:
                        self._start_conversation_listener()
                        self._start_social_worker()
                    self.dependencies["broker"] = "healthy"
                except BrokerError:
                    pass
                cadence = backoff
                backoff = min(backoff * 2, self.config.controller.error_backoff_max_seconds)
            except ModelError as exc:
                self.dependencies["model"] = "unhealthy"
                self._degrade("model", exc)
                cadence = backoff
                backoff = min(backoff * 2, self.config.controller.error_backoff_max_seconds)
            except Exception as exc:
                LOG.exception("controller turn failed")
                self._degrade("controller", exc)
                cadence = backoff
                backoff = min(backoff * 2, self.config.controller.error_backoff_max_seconds)
            else:
                if (
                    not self._shutdown_requested.is_set()
                    and self.dependencies.get("broker") == "healthy"
                    and self.dependencies.get("model") != "unhealthy"
                ):
                    self.state = "running"
                    self.warnings = []
                    self._active_degradations.clear()
            self._wake_event.wait(cadence)
            self._wake_event.clear()
        self.state = "stopped"

    @staticmethod
    def _health_progress_criteria(
        goal: dict[str, Any],
        completion: dict[str, Any],
    ) -> list[dict[str, Any]]:
        """Return max-health criteria paired with their latest verifier result."""
        results = {
            str(item.get("id")): item
            for item in completion.get("criteria", [])
            if isinstance(item, dict) and item.get("id") is not None
        }
        matched: list[dict[str, Any]] = []
        for index, criterion in enumerate(goal.get("success_criteria", [])):
            if not isinstance(criterion, dict) or criterion.get("kind") != "numeric_threshold":
                continue
            if str(criterion.get("metric", "")) != "status.vitals.health.max":
                continue
            criterion_id = str(criterion.get("id") or f"criterion_{index + 1}")
            matched.append({"criterion": criterion, "result": results.get(criterion_id, {})})
        return matched

    @staticmethod
    def _farm_counter(status: dict[str, Any], name: str) -> int:
        value = deep_get(status, f"did.{name}", 0)
        try:
            return max(0, int(value or 0))
        except (TypeError, ValueError):
            return 0

    @staticmethod
    def _farm_room(status: dict[str, Any], observation: dict[str, Any]) -> Any:
        return (
            deep_get(observation, "look.room.num")
            or deep_get(observation, "look.room.name")
            or deep_get(status, "placement.assigned_room")
            or deep_get(status, "policy.assignedRoom")
            or deep_get(status, "policy.assigned_room")
        )

    @staticmethod
    def _farm_assigned_room(status: dict[str, Any]) -> Any:
        return (
            deep_get(status, "placement.assigned_room")
            or deep_get(status, "policy.assignedRoom")
            or deep_get(status, "policy.assigned_room")
        )

    @staticmethod
    def _farm_target(status: dict[str, Any]) -> str:
        return str(deep_get(status, "policy.hunt") or status.get("hunting") or "unknown")

    @staticmethod
    def _goal_farm_intent(goal: dict[str, Any]) -> dict[str, Any]:
        """Recover the deliberately structured farm signature from operator notes.

        Runtime ownership is authoritative for launches made by this controller.
        The note fallback lets a newly deployed controller reject a legacy keeper
        job instead of silently adopting it for a different active goal.
        """
        constraints = goal.get("constraints", {})
        notes = str(constraints.get("operator_notes") or "") if isinstance(constraints, dict) else ""
        room_match = re.search(r"\bassigned_room\s*=\s*(\d+)\b", notes, re.IGNORECASE)
        hunt_match = re.search(
            r"\bhunt\s*=\s*[\"']?([a-z][a-z ]*?)(?=[\"',;]|\s+(?:assigned_room|max_carry|use_safe_spots|flee_below|hold_resume_above|rest_below|fight_above_vigor|eat_before_fighting|buy_food|bank_above|pull_within|break_out_via_logoff)\s*=|$)",
            notes,
            re.IGNORECASE,
        )
        intent: dict[str, Any] = {
            "assigned_room": int(room_match.group(1)) if room_match else None,
            "hunt": " ".join(hunt_match.group(1).casefold().split()) if hunt_match else None,
        }
        for field in (
            "use_safe_spots",
            "break_out_via_logoff",
            "eat_before_fighting",
            "buy_food",
        ):
            match = re.search(
                rf"\b{field}\s*=\s*(true|false)\b", notes, re.IGNORECASE
            )
            intent[field] = (
                match.group(1).casefold() == "true" if match else None
            )
        for field, converter in (
            ("max_carry", int),
            ("flee_below", float),
            ("hold_resume_above", float),
            ("rest_below", float),
            ("fight_above_vigor", int),
            ("bank_above", int),
            ("pull_within", int),
        ):
            match = re.search(
                rf"\b{field}\s*(?:>=|<=|=)\s*(\d+(?:\.\d+)?)\b",
                notes,
                re.IGNORECASE,
            )
            intent[field] = converter(float(match.group(1))) if match else None
        return intent

    @staticmethod
    def _train_ability_uses_combat_keeper(
        phase: dict[str, Any] | None,
    ) -> bool:
        """Distinguish sustained combat training from teachers and casting."""

        if not isinstance(phase, dict) or phase.get("kind") != "train_ability":
            return False
        context = phase.get("context")
        context = context if isinstance(context, dict) else {}
        method = str(context.get("training_method") or "").strip().casefold()
        if method:
            return method == "combat"
        if context.get("hunt") is not None or context.get("prey") is not None:
            return True
        if any(
            context.get(field) is not None
            for field in (
                "teacher",
                "merchant",
                "merchant_class",
                "offering_kind",
                "spell",
            )
        ):
            return False
        room = context.get(
            "assigned_room", context.get("room", context.get("room_id"))
        )
        legacy_text = " ".join(
            str(value or "")
            for value in (
                phase.get("objective"),
                phase.get("rationale"),
                context.get("strategy"),
                context.get("notes"),
            )
        ).casefold()
        return bool(
            room is not None
            and context.get("target") is not None
            and any(
                marker in legacy_text
                for marker in (
                    "combat",
                    "fight",
                    "hunt",
                    "prey",
                    "open-field",
                    "open field",
                    "safe spot",
                )
            )
        )

    @staticmethod
    def _campaign_phase_farm_intent(
        phase: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Read the executable keeper-combat signature from a durable phase.

        The campaign manager owns long-running tactical decomposition for a
        strategic supervisor goal. New phases carry typed fields in ``context``;
        the short prose fallback keeps phases persisted by older prompts
        executable across an upgrade.
        """
        if not isinstance(phase, dict) or phase.get("kind") not in {
            "farm",
            "train_ability",
        }:
            return {}
        if (
            phase.get("kind") == "train_ability"
            and not BotController._train_ability_uses_combat_keeper(phase)
        ):
            return {}
        context = phase.get("context")
        context = context if isinstance(context, dict) else {}
        room = context.get(
            "assigned_room", context.get("room", context.get("room_id"))
        )
        # ``target`` is the established farm field. For train_ability it is
        # accepted only alongside a room, preserving old grounded phases while
        # avoiding confusion with an ability/teacher target.
        hunt = context.get("hunt", context.get("prey"))
        if hunt is None and (phase.get("kind") == "farm" or room is not None):
            hunt = context.get("target")
        intent: dict[str, Any] = {
            "assigned_room": room,
            "hunt": hunt,
        }
        for field in (
            "use_safe_spots",
            "break_out_via_logoff",
            "max_carry",
            "flee_below",
            "hold_resume_above",
            "rest_below",
            "fight_above_vigor",
            "eat_before_fighting",
            "buy_food",
            "bank_above",
            "pull_within",
        ):
            intent[field] = context.get(field)

        if not isinstance(intent.get("use_safe_spots"), bool):
            strategy = " ".join(
                str(value or "")
                for value in (
                    phase.get("objective"),
                    phase.get("rationale"),
                    context.get("strategy"),
                    context.get("notes"),
                )
            ).casefold()
            if any(
                marker in strategy
                for marker in ("open-field", "open field", "without safe spot")
            ):
                intent["use_safe_spots"] = False
            elif "safe spot" in strategy:
                intent["use_safe_spots"] = True

        room = intent.get("assigned_room")
        try:
            intent["assigned_room"] = int(room) if room is not None else None
        except (TypeError, ValueError):
            intent["assigned_room"] = None
        hunt = " ".join(str(intent.get("hunt") or "").casefold().split())
        intent["hunt"] = hunt or None
        return intent

    def _active_keeper_combat_phase(
        self, goal: dict[str, Any]
    ) -> dict[str, Any] | None:
        """Return an active farm/combat-training phase with a complete recipe."""

        run = self.storage.campaign_run(str(goal.get("id") or ""))
        phase = self.storage.active_campaign_phase(run["id"]) if run else None
        if not isinstance(phase, dict):
            return None
        intent = self._campaign_phase_farm_intent(phase)
        if intent.get("assigned_room") is None or not intent.get("hunt"):
            return None
        return phase

    def _keeper_combat_work_remains(
        self,
        goal: dict[str, Any],
        completion: dict[str, Any],
    ) -> bool:
        """Whether a public HP target or active keeper phase still needs combat."""

        if any(
            item["result"].get("met") is not True
            for item in self._health_progress_criteria(goal, completion)
        ):
            return True
        phase = self._active_keeper_combat_phase(goal)
        return bool(
            phase is not None
            and self._phase_completion_checkpoint(phase) is None
            and self._phase_exhaustion_checkpoint(phase) is None
            and self._phase_abandonment_checkpoint(phase) is None
        )

    def _effective_farm_intent(self, goal: dict[str, Any]) -> dict[str, Any]:
        """Merge operator-authored goal policy with the active campaign phase.

        Explicit public-goal fields remain authoritative.  The phase supplies
        the prey, room, and tactic for strategic goals such as "reach 45 HP"
        that intentionally leave those hour-to-hour choices to the configured planner.
        """
        goal_intent = self._goal_farm_intent(goal)
        run = self.storage.campaign_run(str(goal.get("id") or ""))
        phase = self.storage.active_campaign_phase(run["id"]) if run else None
        phase_intent = self._campaign_phase_farm_intent(phase)
        keys = set(goal_intent) | set(phase_intent)
        return {
            key: (
                goal_intent.get(key)
                if goal_intent.get(key) is not None
                else phase_intent.get(key)
            )
            for key in keys
        }

    def _farm_fight_vigor(self, goal: dict[str, Any]) -> int:
        intent = self._effective_farm_intent(goal)
        if intent.get("eat_before_fighting") is not True:
            return FARM_FIGHT_VIGOR
        try:
            requested = int(intent.get("fight_above_vigor") or FARM_FIGHT_VIGOR)
        except (TypeError, ValueError):
            return FARM_FIGHT_VIGOR
        return min(200, max(FARM_FIGHT_VIGOR, requested))

    def _farm_launch_origin(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        intent: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Choose safe farm staging from evidence, never a regional default."""

        farm_intent = intent or self._effective_farm_intent(goal)
        current_room = deep_get(
            observation,
            "look.room.num",
            deep_get(observation, "look.room_id"),
        )
        current = self._verified_safe_staging(current_room)
        if current is not None:
            value = {**current, "observed_at": timestamp()}
            self.storage.set_runtime(SAFE_STAGING_RUNTIME_KEY, value)
            return value

        remembered = self.storage.get_runtime(SAFE_STAGING_RUNTIME_KEY, {})
        remembered_room = (
            remembered.get("room_id") if isinstance(remembered, dict) else None
        )
        finder = getattr(self.knowledge, "nearest_safe_location", None)
        if callable(finder):
            for seed in (current_room, farm_intent.get("assigned_room")):
                try:
                    candidate = finder(
                        int(seed), preferred_room_id=remembered_room
                    )
                except (TypeError, ValueError):
                    continue
                if not isinstance(candidate, dict) or candidate.get("status") != "found":
                    continue
                verified = self._verified_safe_staging(candidate.get("room_id"))
                if verified is None:
                    continue
                return {
                    **verified,
                    "basis": candidate.get("basis") or "source_derived_safe_room",
                    "distance": candidate.get("distance"),
                    "from_room_id": candidate.get("from_room_id"),
                }

        # A source corpus can omit route edges. Reuse the last live-observed
        # safe room only when no source-connected or same-region candidate can
        # be established; live travel still verifies reachability.
        verified_remembered = self._verified_safe_staging(remembered_room)
        if verified_remembered is not None:
            return {
                **verified_remembered,
                "observed_at": remembered.get("observed_at"),
                "basis": "source_revalidated_last_observed_safe_room",
            }
        return None

    def _structured_farm_launch_plan(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        completion: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Turn an executable, goal-owned farm recipe into a keeper launch.

        The supervisor has already chosen and grounded the bounded phase. Requiring the
        exact machine-readable recipe keeps tactical identity in durable goal
        state, while this fast path prevents the tactical model from spending
        turns rediscovering ``prey`` and ``hunting_grounds`` after banking and
        equipment preparation are complete. Any unmet deterministic preflight
        falls back to the planner so it can perform the missing preparation.
        """
        if not self._keeper_combat_work_remains(goal, completion):
            return None
        intent = self._effective_farm_intent(goal)
        if intent.get("assigned_room") is None or not intent.get("hunt"):
            return None
        current_room = deep_get(observation, "look.room.num")
        launch_origin = self._farm_launch_origin(goal, observation, intent)
        if launch_origin is None or str(current_room) != str(launch_origin["room_id"]):
            return None

        readiness = self.learning.readiness_summary(observation)
        if (
            readiness.get("equipment_state") != "known"
            or not readiness.get("wielded_weapons")
        ):
            return None

        arguments: dict[str, Any] = {
            "action": "start",
            "mode": "farm",
            # Banking is a tactic selected in the durable recipe, not a
            # prerequisite for roaming or combat.  The keeper's special bank
            # trips stay disabled unless the planner/supervisor deliberately supplies a
            # positive bank_above value after assessing the live finances.
            "bank_above": 0,
        }
        arguments.update({key: value for key, value in intent.items() if value is not None})
        arguments, _ = self._normalize_combat_arguments(
            "autopilot",
            arguments,
            observation,
            allow_open_field=intent.get("use_safe_spots") is False,
        )
        if self._safety_preflight("autopilot", arguments, observation, goal):
            return None
        return {
            "decision": "act",
            "tool": "autopilot",
            "arguments": arguments,
            "rationale": (
                "Launch the goal-owned bounded keeper from a source-verified "
                "safe staging room using the grounded farm recipe; preparation and "
                "deterministic safety preflight are complete."
            ),
            "expected_observation": {
                "autopilot.running": True,
                "autopilot.mode": "farm",
                "autopilot.assigned_room": intent["assigned_room"],
            },
            "proposal": None,
        }

    def _structured_farm_controller_plan(
        self,
        goal: dict[str, Any],
        *,
        selected_plan: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        intent = self._effective_farm_intent(goal)
        observation = self.last_observation or {}
        launch_origin = self._farm_launch_origin(goal, observation, intent)
        if launch_origin is None:
            raise ModelError(
                "no source-verified safe staging room is available for the farm launch"
            )
        launch_room = int(launch_origin["room_id"])
        launch_name = str(launch_origin["name"])
        readiness = self.learning.readiness_summary(observation)
        needs_created_weapon = bool(
            readiness.get("equipment_state") == "known"
            and not readiness.get("wielded_weapons")
            and not readiness.get("carried_weapons")
            and self._live_spell_readiness(observation, "create weapon")
            is not None
        )
        steps: list[dict[str, Any]] = [
            {
                "id": "farm-staging-transit",
                "outcome": (
                    f"Reach source-verified safe staging {launch_name} "
                    f"(room {launch_room}) for the next preparation action."
                ),
                "tool": "travel",
                "verification": (
                    f"Current room id is {launch_room} and its source flags include "
                    "ROOM_SANCTUARY or ROOM_NO_COMBAT."
                ),
            }
        ]
        steps.extend(
            (
                [
                    {
                        "id": "create-weapon-before-farm",
                        "outcome": (
                            "Cast Create Weapon in safe staging because the character "
                            "has no wielded or carried weapon."
                        ),
                        "tool": "cast",
                        "verification": (
                            "Live inventory gains a usable weapon and mana decreases; "
                            "a silent zero-mana cast is not success."
                        ),
                    }
                ]
                if needs_created_weapon
                else []
            )
            + [
                {
                    "id": "rest-for-farm",
                    "outcome": "Rest safely to the ordinary 80-vigor ceiling and stand again.",
                    "tool": "rest_up",
                    "verification": "Live vigor is at least 80 and the character is standing.",
                },
                {
                    "id": "equip-before-farm",
                    "outcome": "Ensure the best carried weapon is equipped before leaving safe staging.",
                    "tool": "equip_best",
                    "verification": "The equipment list reports a wielded weapon.",
                },
                {
                    "id": "launch-goal-keeper",
                    "outcome": (
                        f"Launch the grounded goal-owned keeper from {launch_name} "
                        f"for {intent.get('hunt')} in assigned room "
                        f"{intent.get('assigned_room')}."
                    ),
                    "tool": "autopilot",
                    "verification": (
                        "Keeper status reports running with this goal id, prey "
                        f"{intent.get('hunt')}, and assigned room "
                        f"{intent.get('assigned_room')}."
                    ),
                },
            ]
        )
        plan = {
            "summary": (
                f"Prepare in source-verified safe staging {launch_name}, launch "
                "the goal-owned bounded keeper, then verify the HP outcome."
            ),
            "steps": steps,
            "assumptions": [],
            "revision_reason": (
                "Bind launch staging to source safety facts and live state. Food "
                "acquisition and consumption remain planner-owned optional tactics."
            ),
        }
        return (
            self._with_selected_safe_ending(plan, selected_plan)
            if selected_plan is not None
            else plan
        )

    def _structured_farm_preparation_action(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        completion: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Advance a grounded farm through safe preparation without an LLM turn."""

        if not self._keeper_combat_work_remains(goal, completion):
            return None
        intent = self._effective_farm_intent(goal)
        if intent.get("assigned_room") is None or not intent.get("hunt"):
            return None

        current_room = deep_get(observation, "look.room.num")
        launch_origin = self._farm_launch_origin(goal, observation, intent)
        if launch_origin is None:
            return None
        launch_room = int(launch_origin["room_id"])
        readiness = self.learning.readiness_summary(observation)

        def action(
            tool: str,
            arguments: dict[str, Any],
            step_id: str,
            rationale: str,
        ) -> dict[str, Any]:
            # A durable lesson is scoped to the exact tactic, not the desired
            # destination. The broker's route call supports an explicit hop
            # budget, which is a materially different retry after a stale
            # default-route lesson (and is especially useful after a broker
            # pathing update). Without this escalation, a controller-owned
            # preparation action would be re-suppressed every five seconds and
            # never give the repaired router a chance to move the character.
            if tool == "travel" and "max_hops" not in arguments:
                feedback = self._planner_feedback(goal)
                blocked_action = (
                    feedback.get("blocked_action")
                    if isinstance(feedback, dict)
                    else None
                )
                blocked_arguments = (
                    blocked_action.get("arguments")
                    if isinstance(blocked_action, dict)
                    else None
                )
                blocked_room = (
                    blocked_action.get("room")
                    if isinstance(blocked_action, dict)
                    else None
                )
                if (
                    isinstance(blocked_action, dict)
                    and blocked_action.get("tool") == "travel"
                    and isinstance(blocked_arguments, dict)
                    and str(blocked_arguments.get("to"))
                    == str(arguments.get("to"))
                    and str(blocked_room) == str(current_room)
                ):
                    arguments = {**arguments, "max_hops": 25}
                    rationale += (
                        " Retry with an explicit route budget because the "
                        "default-route tactic is durably deferred in this room."
                    )
            return {
                "decision": "act",
                "tool": tool,
                "arguments": arguments,
                "rationale": rationale,
                "expected_observation": {},
                "proposal": None,
                "plan_step_id": step_id,
            }

        if str(current_room) != str(launch_room):
            return action(
                "travel",
                {"to": launch_room},
                "farm-staging-transit",
                "Reach the source-verified safe staging room before the keeper launch.",
            )
        rested = deep_get(
            observation,
            "status.vitals.vigor.rested",
            deep_get(observation, "look.vitals.vigor.rested"),
        )
        if rested is False:
            return action(
                "rest_up",
                {"to": 0.4, "max_seconds": 30},
                "rest-for-farm",
                "Recover to the ordinary rest ceiling and stand before launch.",
            )
        if (
            readiness.get("equipment_state") != "known"
            or not readiness.get("wielded_weapons")
        ):
            if not readiness.get("carried_weapons"):
                create_weapon = self._live_spell_readiness(
                    observation, "create weapon"
                )
                if (
                    isinstance(create_weapon, dict)
                    and create_weapon.get("castable") is True
                ):
                    return action(
                        "cast",
                        {"spell": "create weapon", "observe_created": True},
                        "create-weapon-before-farm",
                        (
                            "Create a weapon deterministically while mana and safe "
                            "staging permit it; an unrelated food cast cannot repair "
                            "known-unarmed combat readiness."
                        ),
                    )
                return None
            if self.learning.check_action("equip_best", {}, observation) is not None:
                # The tactical campaign owns recovery once the ordinary
                # no-argument equip attempt is durably disproved.  Returning
                # None lets the planner use explicit inventory/property actions rather
                # than tripping the same lesson and ending another phase.
                return None
            return action(
                "equip_best",
                {},
                "equip-before-farm",
                "Equip the best carried weapon while still in sanctuary.",
            )
        return None

    @staticmethod
    def _farm_quarantine_matches(
        quarantine: dict[str, Any], arguments: dict[str, Any]
    ) -> bool:
        """Whether a quarantine applies to this exact room/prey/strategy.

        Old serious incident records intentionally remain room-wide.  A legacy
        record whose sole evidence was a disproved wall can be safely inferred
        to describe the wall strategy, allowing an explicit open-field retry.
        """
        recorded_target = str(quarantine.get("target") or "").strip().casefold()
        requested_target = str(arguments.get("hunt") or "").strip().casefold()
        if recorded_target and requested_target and recorded_target != requested_target:
            return False

        recorded_safe_spots = quarantine.get("use_safe_spots")
        if not isinstance(recorded_safe_spots, bool):
            reasons = [
                str(item).casefold()
                for item in quarantine.get("reasons", [])
                if item is not None
            ]
            if reasons and all("safe spot" in reason for reason in reasons):
                recorded_safe_spots = True
        requested_safe_spots = arguments.get("use_safe_spots")
        if isinstance(recorded_safe_spots, bool) and isinstance(
            requested_safe_spots, bool
        ):
            return recorded_safe_spots == requested_safe_spots
        return True

    @staticmethod
    def _keeper_stall_is_persistent(status: dict[str, Any]) -> bool:
        if status.get("last_error"):
            return True
        stalled = status.get("stalled")
        if not stalled:
            return False
        if not isinstance(stalled, dict):
            return True
        age = stalled.get("since_seconds")
        if not isinstance(age, (int, float)) or isinstance(age, bool):
            return True
        waiting = status.get("waiting_on")
        waiting = waiting if isinstance(waiting, dict) else {}
        expected_ms = waiting.get("expected_ms")
        since_ms = waiting.get("since")
        if (
            isinstance(expected_ms, (int, float))
            and not isinstance(expected_ms, bool)
            and float(expected_ms) > 0
            and isinstance(since_ms, (int, float))
            and not isinstance(since_ms, bool)
        ):
            elapsed_ms = max(0.0, time.time() * 1000 - float(since_ms))
            if elapsed_ms <= float(expected_ms) + FARM_TYPED_WAIT_GRACE_SECONDS * 1000:
                return False
        return float(age) >= FARM_STALL_GRACE_SECONDS

    def _farm_stagnation_blocks(self, stagnation: dict[str, Any]) -> bool:
        """Keep fresh/unsafe stalls blocked while allowing old proven farms a retry."""

        placement = (
            stagnation.get("placement")
            if isinstance(stagnation.get("placement"), dict)
            else {}
        )
        # Reaching the assignment disproves an assignment-route failure.  Older
        # controllers could combine a successful farm record naming the room
        # with an unrelated later "could not reach any inn" retreat record and
        # persist that cross-record match as a route stagnation.  Never let such
        # evidence block the already-proven destination, even before startup
        # repair has removed the legacy record.
        if (
            stagnation.get("kind")
            not in {"farm_assignment_deferred", "farm_transit_cycle"}
            and int(placement.get("returned_to_assignment", 0) or 0) > 0
            and int(placement.get("failed", 0) or 0) <= 0
        ):
            return False

        last_error = str(stagnation.get("last_error") or "").strip()
        if self._transient_movement_failure_text(last_error) is not None:
            return False
        # An explicit non-transient keeper error remains durable. Ordinary
        # inactivity is different: rooms repopulate and transit conditions
        # change, so it receives a bounded cooldown instead of a quarantine.
        if last_error:
            return True

        deltas = stagnation.get("deltas")
        deltas = deltas if isinstance(deltas, dict) else {}
        unsafe_launch = any(
            int(deltas.get(name, 0) or 0) > 0
            for name in (
                "deaths",
                "deaths_in_safe_spot",
                "deaths_in_proven_safe_spot",
            )
        )
        if unsafe_launch:
            return True
        age = self._age_seconds(stagnation.get("recorded_at"))
        return age is None or age < FARM_STAGNATION_RETRY_SECONDS

    def _repair_transient_farm_stagnations(self) -> list[dict[str, Any]]:
        """Remove legacy permanent blocks created from a brand-new live stall."""

        raw = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
        stagnations = dict(raw) if isinstance(raw, dict) else {}
        repaired: list[dict[str, Any]] = []
        for key, item in list(stagnations.items()):
            if not isinstance(item, dict):
                continue
            stalled = item.get("stalled")
            stalled = stalled if isinstance(stalled, dict) else {}
            since = stalled.get("since_seconds")
            did = item.get("did")
            did = did if isinstance(did, dict) else {}
            transient_productive_stall = (
                isinstance(since, (int, float))
                and not isinstance(since, bool)
                and float(since) < FARM_STALL_GRACE_SECONDS
                and int(did.get("kills", 0) or 0) > 0
                and int(did.get("deaths", 0) or 0) <= 0
                and not item.get("last_error")
                and not item.get("stalled_in_transit")
            )
            if not transient_productive_stall:
                continue
            repaired.append(item)
            stagnations.pop(key, None)
        if repaired:
            self.storage.set_runtime("farm_tactic_stagnation_v1", stagnations)
            self.storage.emit_event(
                "background_farm.stagnation_repaired",
                "Removed transient farm stalls that were recorded before their recovery grace elapsed",
                severity="notice",
                interesting=True,
                data={"count": len(repaired), "tactics": redact(repaired)},
            )
        return repaired

    def _repair_ambiguous_breakoff_stagnations(self) -> list[dict[str, Any]]:
        """Remove safe legacy stalls that discarded landed-hit evidence.

        Older keepers called every non-killing fight return ``broke off without
        a kill``.  That combined two materially different outcomes: an all-miss
        exchange and damage dealt to a retained quarry that moved out of melee
        reach.  The old record cannot reconstruct which occurred.  Give only
        death-free, on-assignment records with that exact obsolete reason one
        fresh measurement under the corrected keeper; explicit errors, route
        stalls, unsafe launches, and the new all-miss reason remain durable.
        """

        raw = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
        stagnations = dict(raw) if isinstance(raw, dict) else {}
        repaired: list[dict[str, Any]] = []
        affected_goal_ids: set[str] = set()
        for key, item in list(stagnations.items()):
            if not isinstance(item, dict):
                continue
            stalled = item.get("stalled")
            stalled = stalled if isinstance(stalled, dict) else {}
            deltas = item.get("deltas")
            if not isinstance(deltas, dict):
                continue
            obsolete_ambiguous_breakoff = (
                str(stalled.get("why") or "").strip().casefold()
                == "broke off without a kill"
                and item.get("stalled_in_transit") is False
                and not str(item.get("last_error") or "").strip()
                and all(
                    int(deltas.get(name, 0) or 0) <= 0
                    for name in (
                        "deaths",
                        "deaths_in_safe_spot",
                        "deaths_in_proven_safe_spot",
                        "withdrawals",
                        "mulligans",
                        "logoffs",
                    )
                )
            )
            if not obsolete_ambiguous_breakoff:
                continue
            repaired.append(item)
            stagnations.pop(key, None)
            goal_id = str(item.get("goal_id") or str(key).split("|", 1)[0])
            if goal_id:
                affected_goal_ids.add(goal_id)

        if not repaired:
            return []
        self.storage.set_runtime("farm_tactic_stagnation_v1", stagnations)
        for goal_id in affected_goal_ids:
            self._clear_research_recipe_exhaustion(goal_id)
            self._clear_safety_suppression(goal_id)
            self.storage.set_runtime(
                f"background_farm_route_failure_handled_v1:{goal_id}", False
            )
            run = self.storage.campaign_run(goal_id)
            blocker = run.get("external_blocker") if isinstance(run, dict) else None
            if (
                isinstance(blocker, dict)
                and blocker.get("kind") == "no_usable_farm_recipe"
            ):
                self.storage.clear_campaign_external_blocker(str(run["id"]))
        self.storage.emit_event(
            "background_farm.breakoff_stagnation_repaired",
            "Removed safe legacy stalls that could not distinguish landed damage from misses",
            severity="notice",
            interesting=False,
            data={
                "count": len(repaired),
                "goal_ids": sorted(affected_goal_ids),
                "reason": "the keeper now retains server-confirmed landed-hit evidence",
            },
        )
        return repaired

    def _repair_gentle_cap_stagnations(
        self, observation: dict[str, Any]
    ) -> list[dict[str, Any]]:
        """Release cap stalls caused by the keeper's obsolete level fallback.

        The old capped-room classifier could reject a source-known creature by
        level even after its gentle attack rating had passed.  The persisted
        record does not name the blocking creature, so prose alone is not proof.
        Re-read the room's current source table and remove only a death-free cap
        record whose non-prey overlevel spawn is affirmatively forgiven by rating
        and whose room contains no dangerous or unknown overlevel spawn.
        """

        raw = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
        stagnations = dict(raw) if isinstance(raw, dict) else {}
        repaired: list[dict[str, Any]] = []
        affected_goal_ids: set[str] = set()
        for key, item in list(stagnations.items()):
            if not isinstance(item, dict):
                continue
            stalled = item.get("stalled")
            stalled = stalled if isinstance(stalled, dict) else {}
            deltas = item.get("deltas")
            if (
                str(stalled.get("why") or "").strip().casefold()
                != "room capped by creatures we will not fight"
                or str(item.get("last_error") or "").strip()
                or not isinstance(deltas, dict)
                or any(
                    int(deltas.get(name, 0) or 0) > 0
                    for name in (
                        "deaths",
                        "deaths_in_safe_spot",
                        "deaths_in_proven_safe_spot",
                        "withdrawals",
                        "mulligans",
                        "logoffs",
                    )
                )
            ):
                continue
            assessment = self._source_room_overlevel_assessment(
                item.get("room", item.get("assigned_room")), observation
            )
            if (
                assessment is None
                or assessment["threats"]
                or not assessment["forgiven"]
            ):
                continue
            target = str(item.get("target") or "").strip().casefold()
            forgiven_blockers = [
                detail
                for detail in assessment["forgiven"]
                if target
                and target not in str(detail.get("name") or "").strip().casefold()
            ]
            if not forgiven_blockers:
                continue
            repaired.append(
                {
                    **item,
                    "repair_reason": (
                        "fresh source ratings prove the overlevel cap occupants are "
                        "gentle non-prey, not unsafe blockers"
                    ),
                    "forgiven_cap_blockers": forgiven_blockers,
                }
            )
            stagnations.pop(key, None)
            goal_id = str(item.get("goal_id") or str(key).split("|", 1)[0])
            if goal_id:
                affected_goal_ids.add(goal_id)

        if not repaired:
            return []
        self.storage.set_runtime("farm_tactic_stagnation_v1", stagnations)
        for goal_id in affected_goal_ids:
            self._clear_research_recipe_exhaustion(goal_id)
            self._clear_safety_suppression(goal_id)
            self.storage.set_runtime(
                f"background_farm_route_failure_handled_v1:{goal_id}", False
            )
            run = self.storage.campaign_run(goal_id)
            blocker = run.get("external_blocker") if isinstance(run, dict) else None
            if (
                isinstance(blocker, dict)
                and blocker.get("kind") == "no_usable_farm_recipe"
            ):
                self.storage.clear_campaign_external_blocker(str(run["id"]))
        self.storage.emit_event(
            "background_farm.cap_stagnation_repaired",
            "Removed capped-room stalls created by the obsolete level fallback",
            severity="notice",
            interesting=False,
            data={
                "count": len(repaired),
                "rooms": [item.get("room") for item in repaired],
                "goal_ids": sorted(affected_goal_ids),
                "reason": "fresh source attack ratings now drive every keeper path",
            },
        )
        return repaired

    def _repair_disproved_farm_route_stagnations(self) -> list[dict[str, Any]]:
        """Remove legacy route failures contradicted by placement counters.

        A keeper that reports successful returns to its assignment and zero
        placement failures has disproved a stored claim that the assignment
        route was unavailable. This specifically repairs records produced by
        the former cross-journal retreat/assignment text match.
        """

        raw = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
        stagnations = dict(raw) if isinstance(raw, dict) else {}
        repaired: list[dict[str, Any]] = []
        resolved_lesson_ids: list[str] = []
        for key, item in list(stagnations.items()):
            if not isinstance(item, dict):
                continue
            if item.get("kind") in {
                "farm_assignment_deferred",
                "farm_transit_cycle",
            }:
                # These typed outcomes are about exhausted placement or a
                # launch-scoped movement cycle. Cumulative successful-return
                # counters from an earlier assignment do not disprove them.
                continue
            placement = (
                item.get("placement")
                if isinstance(item.get("placement"), dict)
                else {}
            )
            returned = int(placement.get("returned_to_assignment", 0) or 0)
            failed = int(placement.get("failed", 0) or 0)
            why_not = placement.get("why_not")
            no_failures = not isinstance(why_not, (dict, list)) or not why_not
            if returned <= 0 or failed > 0 or not no_failures:
                continue

            goal_id = str(item.get("goal_id") or "")
            assigned_room = item.get(
                "assigned_room", item.get("requested_assigned_room")
            )
            for lesson in self.storage.goal_lessons(
                statuses=["deferred", "unlocked"],
                goal_id=goal_id or None,
                limit=200,
            ):
                if lesson.get("classification") != "route_unavailable":
                    continue
                arguments = deep_get(
                    lesson, "failed_state.failed_tactic.arguments", {}
                )
                arguments = arguments if isinstance(arguments, dict) else {}
                summary = str(lesson.get("summary") or "").casefold()
                if (
                    str(arguments.get("assigned_room")) != str(assigned_room)
                    or "keeper route placement failed" not in summary
                ):
                    continue
                self.storage.update_goal_lesson(
                    lesson["id"],
                    "resolved",
                    resolution_goal_id=goal_id or None,
                    evidence={
                        "repair": (
                            "keeper placement counters prove the assigned route "
                            "completed before an unrelated retreat-route failure"
                        ),
                        "assigned_room": assigned_room,
                        "returned_to_assignment": returned,
                        "placement_failures": failed,
                        "at": timestamp(),
                    },
                )
                resolved_lesson_ids.append(lesson["id"])

            stagnations.pop(key, None)
            if goal_id:
                self.storage.set_runtime(
                    f"background_farm_route_failure_handled_v1:{goal_id}", False
                )
            repaired.append(item)

        if not repaired:
            return []
        self.storage.set_runtime("farm_tactic_stagnation_v1", stagnations)
        feedback = self.storage.get_runtime("planner_feedback")
        feedback_text = canonical_json(feedback).casefold() if feedback else ""
        if "do not restart this assigned-room/prey route unchanged" in feedback_text:
            self._clear_planner_feedback()
        self.storage.emit_event(
            "background_farm.route_failure_repaired",
            "Removed farm route failures disproved by successful assignment returns",
            severity="notice",
            interesting=True,
            data={
                "count": len(repaired),
                "resolved_lesson_ids": resolved_lesson_ids,
                "tactics": redact(repaired),
            },
        )
        return repaired

    def _background_farm_mismatch(
        self, goal: dict[str, Any], status: dict[str, Any]
    ) -> dict[str, Any] | None:
        owner = self.storage.get_runtime("background_farm_owner_v1", {})
        owner = owner if isinstance(owner, dict) else {}
        intent = self._effective_farm_intent(goal)
        expected = {
            **intent,
            "fight_above_vigor": self._farm_fight_vigor(goal),
            "eat_before_fighting": intent.get("eat_before_fighting") is True,
            "buy_food": intent.get("buy_food") is True,
        }
        actual = {
            "assigned_room": self._farm_assigned_room(status),
            "hunt": self._farm_target(status).strip().casefold(),
            "use_safe_spots": deep_get(status, "policy.useSafeSpots", deep_get(status, "policy.use_safe_spots")),
            "fight_above_vigor": deep_get(
                status,
                "policy.fightAboveVigor",
                deep_get(status, "policy.fight_above_vigor"),
            ),
            "eat_before_fighting": deep_get(
                status,
                "policy.eatBeforeFighting",
                deep_get(status, "policy.eat_before_fighting"),
            ),
            "buy_food": deep_get(
                status,
                "policy.buyFood",
                deep_get(status, "policy.buy_food"),
            ),
        }
        reasons: list[str] = []
        if owner.get("goal_id") and owner.get("goal_id") != goal.get("id"):
            reasons.append("running keeper belongs to a different durable goal")
        active_phase = self._active_keeper_combat_phase(goal)
        if (
            owner.get("phase_id")
            and (
                active_phase is None
                or owner.get("phase_id") != active_phase.get("id")
            )
        ):
            reasons.append("running keeper belongs to a different campaign phase")
        for field in (
            "assigned_room",
            "hunt",
            "use_safe_spots",
            "fight_above_vigor",
            "eat_before_fighting",
            "buy_food",
        ):
            wanted = expected.get(field)
            if wanted is not None and str(actual.get(field)) != str(wanted):
                reasons.append(f"{field} is {actual.get(field)!r}, expected {wanted!r}")
        if not reasons:
            return None
        return {
            "reasons": reasons,
            "owner": redact(owner),
            "expected": expected,
            "actual": actual,
        }

    def _stopped_farm_route_failure(
        self, goal: dict[str, Any], observation: dict[str, Any], status: dict[str, Any]
    ) -> dict[str, Any] | None:
        """Turn an authoritative keeper route-placement error into durable evidence.

        The keeper can keep reporting ``running`` after its route planner has
        proved that no graph path exists, or it can become inert after the
        controller asks it to stop.  Neither state should hide the exact route
        failure and let the foreground planner start the same trip again. Only
        fresh, route-specific failures for this goal's exact assignment qualify
        while the keeper is still driving; a genuinely stopped legacy keeper
        may carry the terminal placement record without a timestamped journal.
        """
        handled_key = f"background_farm_route_failure_handled_v1:{goal['id']}"
        if self.storage.get_runtime(handled_key, False) is True:
            return None

        owner = self.storage.get_runtime("background_farm_owner_v1", {})
        owner = owner if isinstance(owner, dict) else {}
        intent = self._effective_farm_intent(goal)
        owner_matches = owner.get("goal_id") == goal.get("id")
        assigned_room = (
            owner.get("assigned_room") if owner_matches else intent.get("assigned_room")
        )
        target = str(
            (owner.get("hunt") if owner_matches else intent.get("hunt")) or ""
        ).strip().casefold()
        if assigned_room is None or not target:
            return None

        placement = status.get("placement")
        placement = placement if isinstance(placement, dict) else {}
        # The broker keeps cumulative placement failures in status. A failed
        # square/exit from an earlier pass is not terminal route evidence after
        # the character is visibly in the assigned room.
        if str(self._observation_room(observation)) == str(assigned_room) or (
            placement.get("standing_where_assigned") is True
            and str(placement.get("assigned_room")) == str(assigned_room)
        ):
            return None
        raw_failures = placement.get("why_not", [])
        if isinstance(raw_failures, dict):
            raw_failures = [
                {"room": room, **(value if isinstance(value, dict) else {"why": value})}
                for room, value in raw_failures.items()
            ]
        failures = [item for item in raw_failures if isinstance(item, dict)]
        matching_failures = [
            item
            for item in failures
            if item.get("room") is not None
            and str(item.get("room")) == str(assigned_room)
            and self._transient_movement_failure_text(
                item.get("why") or item.get("reason") or item.get("detail")
            )
            is None
        ]
        reason_parts = [
            str(item.get("why") or item.get("reason") or item.get("detail") or "")
            for item in matching_failures
        ]
        snapshot = self.storage.get_runtime(
            f"background_farm_snapshot_v2:{goal['id']}", {}
        )
        snapshot = snapshot if isinstance(snapshot, dict) else {}
        transit_cycle = self._farm_transit_cycle_failure(
            goal,
            observation,
            status,
            assigned_room=assigned_room,
            target=target,
            owner=owner if owner_matches else {},
            snapshot=snapshot,
        )
        if transit_cycle is not None:
            return transit_cycle
        pass_floor = snapshot.get("pass_floor")
        pass_floor = int(pass_floor) if isinstance(pass_floor, (int, float)) else None
        assignment_route_records = self._farm_assignment_route_failure_records(
            status,
            assigned_room=assigned_room,
            minimum_pass=pass_floor,
        )
        # Placement counters and why_not are cumulative across keeper restarts.
        # Require a journal record from this launch even after the keeper has
        # become inert; otherwise the next turn can reinterpret old placement
        # prose as the cause of an unrelated stop.
        if not assignment_route_records:
            return None
        # Without a live ownership record, require the failed placement record
        # itself to name the room in the active goal. This prevents an old
        # journal entry from pausing an unrelated later goal.
        if not owner_matches and not matching_failures:
            return None

        return {
            "kind": "farm_route_failure",
            "assigned_room": assigned_room,
            "target": target,
            "origin_room": (
                owner.get("origin_room")
                if owner_matches
                else snapshot.get("origin_room")
            ),
            "current_room": self._observation_room(observation),
            "placement": redact(placement),
            "reason": next(
                (part for part in reason_parts if part),
                next(
                    (
                        str(
                            record.get("why")
                            or record.get("reason")
                            or record.get("detail")
                            or record.get("what")
                            or ""
                        )
                        for record in assignment_route_records
                        if isinstance(record, dict)
                    ),
                    "keeper route placement failed",
                ),
            ),
        }

    @staticmethod
    def _farm_placement_signature(value: Any) -> dict[str, Any]:
        """Normalize cumulative keeper placement counters for launch deltas."""

        placement = value if isinstance(value, dict) else {}
        raw_rooms = placement.get("drifted_to")
        room_counts: dict[str, int] = {}
        if isinstance(raw_rooms, dict):
            for room, count in raw_rooms.items():
                try:
                    room_counts[str(room)] = max(0, int(count or 0))
                except (TypeError, ValueError):
                    continue
        elif isinstance(raw_rooms, list):
            for item in raw_rooms:
                if isinstance(item, dict):
                    room = item.get("room", item.get("id"))
                    count = item.get("count", 1)
                else:
                    match = re.match(r"^\s*(.+?)\s+x(\d+)\s*$", str(item))
                    room = match.group(1) if match else item
                    count = match.group(2) if match else 1
                if room is None:
                    continue
                try:
                    room_counts[str(room)] = room_counts.get(str(room), 0) + max(
                        0, int(count or 0)
                    )
                except (TypeError, ValueError):
                    continue
        return {
            name: int(placement.get(name, 0) or 0)
            for name in (
                "relocations",
                "drifted",
                "failed",
                "returned_to_assignment",
            )
        } | {"drifted_to": room_counts}

    def _farm_transit_cycle_failure(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        status: dict[str, Any],
        *,
        assigned_room: Any,
        target: str,
        owner: dict[str, Any],
        snapshot: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Recognize a bounded low-cardinality room cycle during assignment travel."""

        if owner.get("goal_id") != goal.get("id"):
            return None
        placement = status.get("placement")
        placement = placement if isinstance(placement, dict) else {}
        current_room = self._observation_room(observation)
        if (
            status.get("running") is not True
            or placement.get("standing_where_assigned") is True
            or str(current_room) == str(assigned_room)
            or placement.get("assignment_deferred") is True
        ):
            return None
        launch_age = self._age_seconds(
            owner.get("started_at") or snapshot.get("launch_started_at")
        )
        if (
            launch_age is None
            or launch_age < FARM_TRANSIT_CYCLE_GRACE_SECONDS
        ):
            return None
        baseline = snapshot.get("launch_placement")
        if not isinstance(baseline, dict):
            return None
        current = self._farm_placement_signature(placement)
        drift_delta = max(
            0, int(current.get("drifted", 0)) - int(baseline.get("drifted", 0) or 0)
        )
        relocation_delta = max(
            0,
            int(current.get("relocations", 0))
            - int(baseline.get("relocations", 0) or 0),
        )
        current_rooms = current.get("drifted_to", {})
        current_rooms = current_rooms if isinstance(current_rooms, dict) else {}
        baseline_rooms = baseline.get("drifted_to", {})
        baseline_rooms = baseline_rooms if isinstance(baseline_rooms, dict) else {}
        cycle_rooms = {
            room: max(0, int(count or 0) - int(baseline_rooms.get(room, 0) or 0))
            for room, count in current_rooms.items()
        }
        cycle_rooms = {room: count for room, count in cycle_rooms.items() if count > 0}
        repeated_visits = sum(count for count in cycle_rooms.values() if count >= 2)
        if (
            drift_delta < FARM_TRANSIT_CYCLE_MIN_DRIFTS
            or relocation_delta < FARM_TRANSIT_CYCLE_MIN_DRIFTS
            or not cycle_rooms
            or len(cycle_rooms) > FARM_TRANSIT_CYCLE_MAX_ROOMS
            or repeated_visits < FARM_TRANSIT_CYCLE_MIN_DRIFTS
        ):
            return None
        room_summary = ", ".join(
            f"{room} x{count}" for room, count in sorted(cycle_rooms.items())
        )
        return {
            "kind": "farm_transit_cycle",
            "assigned_room": assigned_room,
            "target": target,
            "origin_room": owner.get("origin_room"),
            "current_room": current_room,
            "placement": redact(placement),
            "launch_age_seconds": launch_age,
            "drift_delta": drift_delta,
            "relocation_delta": relocation_delta,
            "cycle_rooms": cycle_rooms,
            "reason": (
                f"keeper repeatedly cycled among {room_summary} for {int(launch_age)}s "
                f"without reaching assigned_room={assigned_room}"
            ),
        }

    def _farm_assignment_route_failure_records(
        self,
        status: dict[str, Any],
        *,
        assigned_room: Any,
        minimum_pass: int | None,
    ) -> list[dict[str, Any]]:
        """Return route failures explicitly tied to the assigned destination.

        Record boundaries matter. A retreat can fail to reach an inn after a
        productive farm session, while another record in the same journal names
        the assigned hunting room. Joining the whole journal into one string
        turns those unrelated facts into a false assignment-route failure.
        """

        route_markers = (
            "every square for that exit refused",
            "exit refused",
            "route failed",
            "failed to reach",
            "could not reach",
            "no route",
            "unreachable",
        )
        assignment_markers = (
            "assigned room",
            "assigned_room",
            "assignment",
        )
        found: list[dict[str, Any]] = []
        seen: set[str] = set()
        for key in ("journal", "recent"):
            values = status.get(key)
            if not isinstance(values, list):
                continue
            for value in values[-20:]:
                if not isinstance(value, dict):
                    continue
                record_pass = value.get("pass")
                if minimum_pass is not None and (
                    not isinstance(record_pass, (int, float))
                    or int(record_pass) < minimum_pass
                ):
                    continue
                text = canonical_json(value).casefold()
                if self._transient_movement_failure_text(text) is not None:
                    continue
                if not any(marker in text for marker in route_markers):
                    continue
                destinations = [
                    value.get(field)
                    for field in (
                        "going_to",
                        "assigned_room",
                        "assignedRoom",
                        "destination",
                        "to",
                    )
                    if value.get(field) is not None
                ]
                exact_destination = any(
                    str(destination) == str(assigned_room)
                    for destination in destinations
                )
                names_assignment = (
                    str(assigned_room) in text
                    and any(marker in text for marker in assignment_markers)
                )
                if not exact_destination and not names_assignment:
                    continue
                identity = canonical_json(value)
                if identity in seen:
                    continue
                seen.add(identity)
                found.append(value)
        return found

    def _handle_stopped_farm_route_failure(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        status: dict[str, Any],
        completion: dict[str, Any],
    ) -> dict[str, Any] | None:
        failure = self._stopped_farm_route_failure(goal, observation, status)
        if failure is None:
            return None

        stopped = None
        recovery = None
        if self._keeper_is_driving(status):
            # The broker can remain nominally running while retrying a graph
            # route that it has already proved impossible. Outside a verified
            # sanctuary, retask that same keeper to survival in place before
            # retiring the tactic. At safety, an ordinary inert stop is enough.
            current_room = self._observation_room(observation)
            if self._verified_safe_staging(current_room) is None:
                recovery = self._ensure_survival_keeper()
            else:
                stopped = self._request_background_farm_stop(
                    goal, "the assigned farm route was authoritatively disproved"
                )

        assigned_room = failure["assigned_room"]
        target = str(failure["target"])
        stagnations = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
        stagnations = dict(stagnations) if isinstance(stagnations, dict) else {}
        stagnation_key = f"{goal['id']}|{assigned_room}|{target}"
        prior = stagnations.get(stagnation_key)
        count = int(prior.get("count", 0) or 0) + 1 if isinstance(prior, dict) else 1
        failure_kind = str(failure.get("kind") or "farm_route_failure")
        stagnation = {
            "kind": failure_kind,
            "goal_id": goal["id"],
            "room": failure.get("current_room"),
            "assigned_room": assigned_room,
            "requested_assigned_room": assigned_room,
            "origin_room": failure.get("origin_room"),
            "stalled_in_transit": str(failure.get("current_room")) != str(assigned_room),
            "target": target,
            "count": count,
            "recorded_at": timestamp(),
            "placement": failure.get("placement"),
            # An observed low-cardinality cycle is strong enough to retire this
            # launch, but unlike a graph's explicit no-route result it receives
            # a bounded cooldown rather than becoming permanent evidence.
            "last_error": (
                ""
                if failure_kind == "farm_transit_cycle"
                else failure.get("reason")
            ),
            "reason": failure.get("reason"),
            "cycle_rooms": failure.get("cycle_rooms"),
            "guidance": (
                "Do not restart this assigned-room/prey route unchanged. Choose a different "
                "grounded hunting room or wait for verified route/placement evidence to change."
            ),
        }
        stagnations[stagnation_key] = stagnation
        self.storage.set_runtime("farm_tactic_stagnation_v1", stagnations)

        farm_arguments = {
            "action": "start",
            "mode": "farm",
            "hunt": target,
            "assigned_room": assigned_room,
        }
        reason = (
            f"The keeper could not route from room {failure.get('origin_room') or failure.get('current_room')} "
            f"to assigned_room={assigned_room}: {failure.get('reason')}"
        )
        deferred = self.learning.defer_goal(
            goal,
            observation,
            tool="autopilot",
            arguments=farm_arguments,
            reason=reason,
            event_kind="background_farm.route_failed",
            classification="route_unavailable",
            scope="tactic",
            block=False,
        )
        current_goal = self.storage.goal(goal["id"])
        paused = None
        failed_phase = self._fail_active_campaign_phase(goal, reason)
        if (
            failed_phase is None
            and current_goal
            and current_goal.get("status") == "active"
        ):
            paused = self.storage.manage_goal(
                {
                    "request_id": f"controller-farm-route-failed-{uuid7()}",
                    "goal_id": goal["id"],
                    "expected_version": current_goal.get("version"),
                    "action": "pause",
                    "reason": reason,
                }
            ).get("goal")
        self.storage.set_runtime(
            f"background_farm_route_failure_handled_v1:{goal['id']}", True
        )
        self.storage.set_runtime("background_farm_owner_v1", {})
        health_fraction = self._vital_fraction(observation, "health")
        if (
            recovery is None
            and health_fraction is not None
            and health_fraction < 1.0
        ):
            recovery = self._ensure_survival_keeper()
        self.storage.emit_event(
            "background_farm.route_failed",
            "Paused a farm phase after its exact keeper route failed",
            severity="warning",
            interesting=True,
            goal_id=goal["id"],
            data={
                **stagnation,
                "lesson_id": deep_get(deferred, "lesson.id"),
                "goal_paused": paused is not None,
                "campaign_phase_failed": failed_phase.get("id") if failed_phase else None,
                "strategic_goal_preserved": failed_phase is not None,
                "next_active_goal_id": deep_get(self.storage.active_goal() or {}, "id"),
                "recovery": redact(recovery),
                "keeper_stop": redact(stopped),
            },
        )
        return {
            "background_farm_route_failed": True,
            "goal_paused": paused is not None,
            "campaign_phase_failed": failed_phase,
            "strategic_goal_preserved": failed_phase is not None,
            "failure": stagnation,
            "next_active_goal": self.storage.active_goal(),
            "recovery": recovery,
            "keeper_stop": stopped,
            "completion": completion,
            **deferred,
        }

    def _handle_deferred_farm_assignment(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        status: dict[str, Any],
        completion: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Retire only the active tactic when the keeper exhausts its room.

        ``assignment_deferred`` is an authoritative, bounded keeper outcome:
        the requested prey/room combination has no remaining usable placement
        candidate in this session. It is not a generic stall and must not leave
        the campaign phase claiming ownership while the keeper relocates.
        """

        placement = status.get("placement")
        placement = placement if isinstance(placement, dict) else {}
        if placement.get("assignment_deferred") is not True:
            return None

        phase = self._active_keeper_combat_phase(goal)
        if phase is None:
            return None
        intent = self._campaign_phase_farm_intent(phase)
        assigned_room = placement.get("assigned_room") or intent.get(
            "assigned_room"
        )
        target = str(intent.get("hunt") or self._farm_target(status)).strip()
        if assigned_room is None or not target:
            return None

        detail = str(
            placement.get("assignment_deferred_reason")
            or "the keeper exhausted its bounded placement search"
        ).strip()
        reason = (
            f"Keeper deferred assigned_room={assigned_room} for hunt={target}: "
            f"{detail}"
        )
        current_room = self._observation_room(observation)
        stopped = None
        recovery = None
        if self._keeper_is_driving(status):
            if self._verified_safe_staging(current_room) is None:
                recovery = self._ensure_survival_keeper()
            else:
                stopped = self._request_background_farm_stop(
                    goal,
                    "the assigned farm room tactic was authoritatively exhausted",
                )
        self.storage.set_runtime("background_farm_owner_v1", {})

        stagnations = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
        stagnations = dict(stagnations) if isinstance(stagnations, dict) else {}
        stagnation_key = f"{goal['id']}|{assigned_room}|{target}"
        prior = stagnations.get(stagnation_key)
        count = int(prior.get("count", 0) or 0) + 1 if isinstance(prior, dict) else 1
        stagnation = {
            "kind": "farm_assignment_deferred",
            "goal_id": goal["id"],
            "room": current_room,
            "assigned_room": assigned_room,
            "requested_assigned_room": assigned_room,
            "stalled_in_transit": False,
            "target": target,
            "count": count,
            "recorded_at": timestamp(),
            "placement": redact(placement),
            # Keep the typed bounded outcome on the normal tactic cooldown.
            # ``last_error`` is reserved for durable keeper faults.
            "last_error": "",
            "reason": detail,
            "guidance": (
                "This exact room/prey placement search is exhausted. Choose a different "
                "grounded hunting room; do not restart the same assignment unchanged."
            ),
        }
        stagnations[stagnation_key] = stagnation
        self.storage.set_runtime("farm_tactic_stagnation_v1", stagnations)

        deferred = self.learning.defer_goal(
            goal,
            observation,
            tool="autopilot",
            arguments={
                "action": "start",
                "mode": "farm",
                "hunt": target,
                "assigned_room": assigned_room,
                "use_safe_spots": intent.get("use_safe_spots"),
            },
            reason=reason,
            event_kind="background_farm.assignment_deferred",
            classification="ineffective_tactic",
            scope="tactic",
            block=False,
        )
        failed_phase = self._fail_active_campaign_phase(goal, reason)
        self.storage.set_runtime(
            f"background_farm_route_failure_handled_v1:{goal['id']}", True
        )
        feedback_message = (
            f"The keeper exhausted its bounded placement search for {target} in "
            f"room {assigned_room}. The strategic goal remains active. Research and "
            "submit a replacement farm phase using a different grounded room; do not "
            "retry this room/prey assignment unchanged."
        )
        self._set_planner_feedback(
            goal,
            feedback_message,
            failure_context={
                "kind": "farm_assignment_deferred",
                "purpose": "replace_only_the_exhausted_farm_tactic",
                "assigned_room": assigned_room,
                "target": target,
                "reason": detail,
                "required_response": (
                    "Choose a different grounded hunting room for this prey, or choose "
                    "different grounded prey and room evidence."
                ),
            },
        )
        self.storage.emit_event(
            "background_farm.assignment_deferred",
            "Retired an exhausted farm assignment while preserving the strategic goal",
            severity="warning",
            interesting=True,
            goal_id=goal["id"],
            data={
                **stagnation,
                "lesson_id": deep_get(deferred, "lesson.id"),
                "campaign_phase_failed": (
                    failed_phase.get("id") if failed_phase else None
                ),
                "strategic_goal_preserved": True,
                "goal_blocked": False,
                "keeper_stop": redact(stopped),
                "recovery": redact(recovery),
            },
        )
        return {
            "background_farm_assignment_deferred": True,
            "campaign_phase_failed": failed_phase,
            "strategic_goal_preserved": True,
            "goal_blocked": False,
            "failure": stagnation,
            "keeper_stop": stopped,
            "recovery": recovery,
            "completion": completion,
            **deferred,
        }

    def _farm_flee_threshold(self, status: dict[str, Any]) -> float:
        raw = deep_get(status, "policy.fleeBelow", deep_get(status, "policy.flee_below"))
        try:
            requested = float(raw)
        except (TypeError, ValueError):
            requested = self.config.policy.rest_health_fraction
        # Report the keeper's actual boundary for evidence and quarantine
        # analysis. New launches are normalized to FARM_FLEE_THRESHOLD above,
        # but a keeper started by an older controller may still report a
        # historical value until it is stopped.
        return max(0.0, min(1.0, requested))

    @staticmethod
    def _farm_journal_text(
        status: dict[str, Any], *, minimum_pass: int | None = None
    ) -> str:
        records: list[Any] = []
        # Current harness status calls the compact tail `recent`; older builds
        # and full_journal responses use `journal`.  Trials also carry explicit
        # safe-spot verdicts.  Keep the operational journal available for
        # diagnosis, but do not equate an unavailable spot for one quarry with
        # a disproved spot. Only an observed idle hit disproves a wall.
        for key in ("journal", "recent", "trials"):
            values = status.get(key)
            if isinstance(values, list):
                for value in values[-20:]:
                    if minimum_pass is not None:
                        record_pass = value.get("pass") if isinstance(value, dict) else None
                        # A farm-session floor deliberately excludes unscoped
                        # historical prose. Current keeper safety verdicts carry
                        # a pass number; old no-pass records must not condemn a
                        # newly assigned room after a process restart.
                        if not isinstance(record_pass, (int, float)) or int(record_pass) < minimum_pass:
                            continue
                    records.append(value)
        return canonical_json(records).casefold() if records else ""

    @staticmethod
    def _farm_safe_spot_failure_ids(
        status: dict[str, Any], *, minimum_pass: int | None = None
    ) -> list[str]:
        """Return stable ids for distinct, observed held-wall failures.

        The keeper repeats the same journal entry in several status responses
        (and may mirror it between ``recent`` and ``trials``).  Treating the
        presence of that entry as a new incident on every controller heartbeat
        turns one harmless wall correction into an apparent degradation loop.
        """
        failures: set[str] = set()
        for key in ("journal", "recent", "trials"):
            values = status.get(key)
            if not isinstance(values, list):
                continue
            for value in values[-20:]:
                if not isinstance(value, dict):
                    continue
                record_pass = value.get("pass")
                if minimum_pass is not None and (
                    not isinstance(record_pass, (int, float))
                    or int(record_pass) < minimum_pass
                ):
                    continue
                what = str(value.get("what") or "").casefold()
                verdict = str(value.get("verdict") or "").casefold()
                try:
                    lost = float(value.get("lost") or value.get("lost_health") or 0)
                except (TypeError, ValueError):
                    lost = 0
                if not (
                    "this is not a safe spot" in what
                    or "safe spot failed" in what
                    or (lost > 0 and "does not work" in verdict)
                ):
                    continue

                where = value.get("where") if isinstance(value.get("where"), dict) else {}
                col = where.get("col", value.get("at_col"))
                row = where.get("row", value.get("at_row"))
                if isinstance(record_pass, (int, float)):
                    # Pass and square identify one keeper verdict even when its
                    # prose is mirrored into more than one status collection.
                    identity = f"pass:{int(record_pass)}|col:{col}|row:{row}"
                else:
                    identity = canonical_json(
                        {
                            "at": value.get("at"),
                            "col": col,
                            "row": row,
                            "lost": lost,
                            "what": what,
                            "verdict": verdict,
                        }
                    )
                failures.add(identity)
        return sorted(failures)

    @staticmethod
    def _farm_safe_spot_disproved(
        status: dict[str, Any], *, minimum_pass: int | None = None
    ) -> bool:
        """Return true only when the keeper observed a wall fail under attack."""
        return bool(
            BotController._farm_safe_spot_failure_ids(
                status, minimum_pass=minimum_pass
            )
        )

    def _record_farm_retreat_incident(
        self,
        goal: dict[str, Any],
        *,
        assigned_room: Any,
        target: str,
        use_safe_spots: bool | None,
        reasons: list[str],
    ) -> dict[str, Any]:
        """Count distinct retreat episodes for one exact farm tactic."""

        now = time.time()
        raw = self.storage.get_runtime("farm_tactic_retreat_incidents_v1", {})
        records = dict(raw) if isinstance(raw, dict) else {}
        key = canonical_json(
            {
                "goal_id": goal.get("id"),
                "assigned_room": assigned_room,
                "target": " ".join(str(target or "").casefold().split()),
                "use_safe_spots": use_safe_spots,
            }
        )
        prior = records.get(key)
        prior = prior if isinstance(prior, dict) else {}
        incidents = [
            item
            for item in prior.get("incidents", [])
            if isinstance(item, dict)
            and isinstance(item.get("at"), (int, float))
            and now - float(item["at"]) <= FARM_RETREAT_INCIDENT_WINDOW_SECONDS
        ]
        incidents.append(
            {
                "at": now,
                "occurred_at": timestamp(),
                "reasons": list(dict.fromkeys(str(item) for item in reasons)),
            }
        )
        record = {
            "goal_id": goal.get("id"),
            "assigned_room": assigned_room,
            "target": " ".join(str(target or "").casefold().split()),
            "use_safe_spots": use_safe_spots,
            "window_seconds": FARM_RETREAT_INCIDENT_WINDOW_SECONDS,
            "incidents": incidents[-20:],
            "count": len(incidents),
            "updated_at": timestamp(),
        }
        records[key] = record
        # Bound stale identities as well as incidents within an identity.
        records = dict(list(records.items())[-100:])
        self.storage.set_runtime("farm_tactic_retreat_incidents_v1", records)
        return record

    def _renew_farm_progress_lease(
        self,
        goal: dict[str, Any],
        *,
        kill_delta: int,
        cumulative_kills: int,
    ) -> dict[str, Any] | None:
        """Renew a long farm phase whenever the keeper verifies another kill."""

        if kill_delta <= 0:
            return None
        phase = self._active_keeper_combat_phase(goal)
        if not isinstance(phase, dict) or phase.get("kind") != "farm":
            return None
        leases = self.storage.get_runtime(
            CAMPAIGN_PHASE_PROGRESS_LEASE_RUNTIME_KEY, {}
        )
        leases = dict(leases) if isinstance(leases, dict) else {}
        downtime = self.storage.get_runtime(CAMPAIGN_PHASE_DOWNTIME_RUNTIME_KEY, {})
        downtime_seconds = 0.0
        if (
            isinstance(downtime, dict)
            and str(downtime.get("phase_id") or "") == str(phase.get("id") or "")
        ):
            try:
                downtime_seconds = max(
                    0.0, float(downtime.get("seconds", 0.0) or 0.0)
                )
            except (TypeError, ValueError):
                downtime_seconds = 0.0
        value = {
            "goal_id": goal.get("id"),
            "phase_id": phase.get("id"),
            "renewed_at": timestamp(),
            "progress_kind": "verified_keeper_kill",
            "kill_delta": int(kill_delta),
            "cumulative_kills": int(cumulative_kills),
            "downtime_seconds": downtime_seconds,
        }
        leases[str(phase["id"])] = value
        self.storage.set_runtime(
            CAMPAIGN_PHASE_PROGRESS_LEASE_RUNTIME_KEY,
            dict(list(leases.items())[-100:]),
        )
        return value

    @staticmethod
    def _farm_kill_records(
        status: dict[str, Any],
        *,
        minimum_pass: int | None = None,
        after_at: int | float | None = None,
    ) -> list[dict[str, Any]]:
        """Read deduplicated, explicitly named kills from the keeper journal."""
        found: dict[tuple[Any, Any, Any], dict[str, Any]] = {}
        for key in ("journal", "recent"):
            values = status.get(key)
            if not isinstance(values, list):
                continue
            for value in values:
                if not isinstance(value, dict) or str(value.get("what") or "").casefold() != "killed":
                    continue
                record_pass = value.get("pass")
                if minimum_pass is not None and (
                    not isinstance(record_pass, (int, float)) or int(record_pass) < minimum_pass
                ):
                    continue
                record_at = value.get("at")
                if not isinstance(record_at, (int, float)):
                    continue
                if after_at is not None and record_at <= after_at:
                    continue
                found[(record_at, record_pass, value.get("target"))] = value
        return sorted(found.values(), key=lambda item: float(item.get("at") or 0))

    def _farm_status_evidence(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        status: dict[str, Any],
    ) -> dict[str, Any]:
        """Turn cumulative keeper status into deltas and durable campaign evidence."""
        key = f"background_farm_snapshot_v2:{goal['id']}"
        previous = self.storage.get_runtime(key, {})
        previous = previous if isinstance(previous, dict) else {}
        did = status.get("did") if isinstance(status.get("did"), dict) else {}
        counters = {
            name: self._farm_counter(status, name)
            for name in (
                "kills",
                "deaths",
                "withdrawals",
                "mulligans",
                "logoffs",
                "deaths_in_safe_spot",
                "deaths_in_proven_safe_spot",
            )
        }
        prior_counters = previous.get("counters") if isinstance(previous.get("counters"), dict) else {}
        deltas = {
            name: max(0, value - int(prior_counters.get(name, 0) or 0))
            for name, value in counters.items()
        }
        launch_counters = previous.get("launch_counters")
        launch_counters = (
            launch_counters
            if isinstance(launch_counters, dict)
            else prior_counters
        )
        session_deltas = {
            name: max(0, value - int(launch_counters.get(name, 0) or 0))
            for name, value in counters.items()
        }
        profile = self.learning.profile(observation)
        current_supplies = int(profile.get("healing_supply_count", 0) or 0)
        prior_supplies = previous.get("healing_supply_count")
        supplies_used = (
            max(0, int(prior_supplies) - current_supplies)
            if isinstance(prior_supplies, (int, float))
            else 0
        )
        room = self._farm_room(status, observation)
        assigned_room = self._farm_assigned_room(status)
        at_assigned_room = (
            str(room) == str(assigned_room)
            if room is not None and assigned_room is not None
            else None
        )
        target = self._farm_target(status)
        use_safe_spots = deep_get(
            status,
            "policy.useSafeSpots",
            deep_get(status, "policy.use_safe_spots"),
        )
        use_safe_spots = use_safe_spots if isinstance(use_safe_spots, bool) else None

        pass_floor = previous.get("pass_floor")
        pass_floor = int(pass_floor) if isinstance(pass_floor, (int, float)) else None
        prior_kill_at = previous.get("last_kill_at")
        prior_kill_at = prior_kill_at if isinstance(prior_kill_at, (int, float)) else None
        kill_records = self._farm_kill_records(
            status, minimum_pass=pass_floor, after_at=prior_kill_at
        )
        if len(kill_records) > deltas["kills"]:
            kill_records = kill_records[-deltas["kills"] :] if deltas["kills"] else []
        kills_by_target: dict[str, int] = {}
        for record in kill_records[:20]:
            actual_target = str(record.get("target") or "unknown")
            kills_by_target[actual_target] = kills_by_target.get(actual_target, 0) + 1
            self.learning.record_combat_outcome(
                tool="autopilot",
                arguments={"target": actual_target, "hunt": target, "assigned_room": room},
                before=observation,
                result={
                    "killed": True,
                    "target": actual_target,
                    "source": "keeper_journal",
                    "pass": record.get("pass"),
                    "at": record.get("at"),
                },
                after=observation,
            )
        for _ in range(min(deltas["withdrawals"], 20)):
            self.learning.record_combat_outcome(
                tool="autopilot",
                arguments={"target": target, "hunt": target, "assigned_room": room},
                before=observation,
                result={"disengaged": True, "target": target, "source": "keeper_status_delta"},
                after=observation,
            )
        progress_lease = self._renew_farm_progress_lease(
            goal,
            kill_delta=deltas["kills"],
            cumulative_kills=counters["kills"],
        )

        observed_safe_spot_failures = self._farm_safe_spot_failure_ids(
            status, minimum_pass=pass_floor
        )
        prior_safe_spot_failures = previous.get("safe_spot_failure_ids")
        prior_safe_spot_failures = (
            [str(item) for item in prior_safe_spot_failures]
            if isinstance(prior_safe_spot_failures, list)
            else []
        )
        all_safe_spot_failures = sorted(
            set(prior_safe_spot_failures) | set(observed_safe_spot_failures)
        )
        safe_spot_disproved = bool(
            set(observed_safe_spot_failures) - set(prior_safe_spot_failures)
        )
        safe_spot_failure_count = len(all_safe_spot_failures)
        health_fraction = self._vital_fraction(observation, "health")
        threshold = self._farm_flee_threshold(status)
        risk_reasons: list[str] = []
        quarantine_reasons: list[str] = []
        recovery_reasons: list[str] = []
        tactic_warnings: list[str] = []
        prior_health_fraction = previous.get("health_fraction")
        same_tactic = (
            str(previous.get("assigned_room")) == str(assigned_room)
            and str(previous.get("target") or "").strip().casefold()
            == str(target or "").strip().casefold()
            and previous.get("use_safe_spots") == use_safe_spots
        )
        threshold_crossed = bool(
            health_fraction is not None
            and health_fraction <= threshold
            and (
                not same_tactic
                or not isinstance(prior_health_fraction, (int, float))
                or float(prior_health_fraction) > threshold
            )
        )
        noncritical_transit_damage = False
        if health_fraction is not None and health_fraction <= threshold:
            in_transit = (
                at_assigned_room is False
                and str(status.get("activity") or "").casefold() == "travelling"
            )
            if (
                in_transit
                and health_fraction > self.config.policy.critical_health_fraction
            ):
                # Travel can briefly cross a populated room. The keeper still
                # owns the route and may regenerate before the next observation;
                # a non-critical dip without a withdrawal is route evidence,
                # not proof that the destination farm failed.
                tactic_warnings.append(
                    "transient route damage reached the farm flee threshold while the keeper retained control"
                )
                noncritical_transit_damage = True
            else:
                recovery_reasons.append("health reached the keeper flee threshold")
        if deltas["withdrawals"]:
            recovery_reasons.append("the keeper had to withdraw")

        retreat_record = None
        if deltas["withdrawals"] or (threshold_crossed and not noncritical_transit_damage):
            retreat_record = self._record_farm_retreat_incident(
                goal,
                assigned_room=assigned_room,
                target=target,
                use_safe_spots=use_safe_spots,
                reasons=[
                    *(("the keeper had to withdraw",) if deltas["withdrawals"] else ()),
                    *(("health crossed the keeper flee threshold",)
                      if threshold_crossed and not noncritical_transit_damage
                      else ()),
                ],
            )
        last_death = status.get("last_death") if isinstance(status.get("last_death"), dict) else None
        death_at = str(last_death.get("at")) if last_death and last_death.get("at") is not None else None
        death_is_new = bool(
            death_at and self.storage.get_runtime("background_farm_last_death_at") != death_at
        )
        if deltas["deaths"] or death_is_new:
            quarantine_reasons.append("the keeper observed a death")
        if deltas["deaths_in_safe_spot"] or deltas["deaths_in_proven_safe_spot"]:
            quarantine_reasons.append("a claimed safe spot failed lethally")
        if safe_spot_disproved:
            tactic_warnings.append("live journal evidence disproved a safe spot")
        # A wall being disproved is useful coordinate-local learning. The
        # keeper already retires that exact square and selects another one;
        # neither three failed squares nor low carried supplies prove the rest
        # of the room unsafe. Routine health recovery and withdrawal cycles are
        # likewise telemetry; death and live over-level-hostile boundaries are
        # the fail-closed signals.
        if safe_spot_disproved and safe_spot_failure_count >= 3:
            tactic_warnings.append(
                "multiple safe-spot coordinates were retired; the room remains eligible"
            )
        if supplies_used and current_supplies == 0:
            tactic_warnings.append(
                "the last healing supply was consumed; replenish before a later hazardous launch"
            )
        if at_assigned_room is False:
            # Recovery before arrival is useful route evidence. Once at the
            # assignment, the same rest/withdraw/resume cycle is ordinary work.
            risk_reasons.extend(recovery_reasons)
            if (
                recovery_reasons
                and isinstance(retreat_record, dict)
                and int(retreat_record.get("count", 0) or 0) >= 2
            ):
                # Reaching safety twice without ever reaching the assignment
                # disproves only this launch route. It does not condemn the
                # destination room, quarry, strategic goal, or future combat
                # sessions that successfully arrive there.
                quarantine_reasons.append(
                    "repeated pre-arrival recovery could not reach the assigned room by the current route"
                )
        risk_reasons.extend(quarantine_reasons)

        snapshot = {
            "observed_at": timestamp(),
            "room": room,
            "assigned_room": assigned_room,
            "at_assigned_room": at_assigned_room,
            "target": target,
            "use_safe_spots": use_safe_spots,
            "counters": counters,
            "launch_counters": launch_counters,
            "launch_placement": (
                previous.get("launch_placement")
                if isinstance(previous.get("launch_placement"), dict)
                else self._farm_placement_signature(status.get("placement"))
            ),
            "launch_started_at": previous.get("launch_started_at"),
            "origin_room": previous.get("origin_room"),
            "healing_supply_count": current_supplies,
            "safe_spot": redact(status.get("safe_spot")),
            "activity": status.get("activity"),
            "health_fraction": health_fraction,
            "flee_threshold": threshold,
            "pass_floor": pass_floor,
            "last_kill_at": max(
                [float(record.get("at") or 0) for record in kill_records]
                + ([float(prior_kill_at)] if prior_kill_at is not None else [0])
            ),
            "safe_spot_failure_ids": all_safe_spot_failures[-50:],
            "safe_spot_failure_count": safe_spot_failure_count,
            "retreat_incident_count": (
                int(retreat_record.get("count", 0) or 0)
                if isinstance(retreat_record, dict)
                else 0
            ),
            "recovery_reasons": list(dict.fromkeys(recovery_reasons)),
            "quarantine_reasons": list(dict.fromkeys(quarantine_reasons)),
            "progress_lease": redact(progress_lease),
        }
        self.storage.set_runtime(key, snapshot)
        if any(deltas.values()) or supplies_used or safe_spot_disproved or tactic_warnings:
            history = self.storage.get_runtime("background_farm_history_v1", [])
            history = [item for item in history if isinstance(item, dict)] if isinstance(history, list) else []
            sample = {
                **snapshot,
                "goal_id": goal["id"],
                "deltas": deltas,
                "session_deltas": session_deltas,
                "kills_by_target": kills_by_target,
                "unattributed_kills": max(0, deltas["kills"] - len(kill_records)),
                "healing_supplies_used": supplies_used,
                "safe_spot_disproved": safe_spot_disproved,
                "safe_spot_failure_count": safe_spot_failure_count,
                "tactic_warnings": tactic_warnings,
                "risk_reasons": risk_reasons,
                "recovery_reasons": recovery_reasons,
                "quarantine_reasons": quarantine_reasons,
            }
            history.append(sample)
            self.storage.set_runtime("background_farm_history_v1", history[-100:])
            self.storage.emit_event(
                "background_farm.evidence",
                "Recorded background-farm progress and safety evidence",
                severity="warning" if risk_reasons else "info",
                interesting=bool(risk_reasons),
                goal_id=goal["id"],
                data=sample,
            )
        return {
            "room": room,
            "assigned_room": assigned_room,
            "at_assigned_room": at_assigned_room,
            "target": target,
            "use_safe_spots": use_safe_spots,
            "counters": counters,
            "deltas": deltas,
            "session_deltas": session_deltas,
            "kills_by_target": kills_by_target,
            "unattributed_kills": max(0, deltas["kills"] - len(kill_records)),
            "healing_supply_count": current_supplies,
            "healing_supplies_used": supplies_used,
            "health_fraction": health_fraction,
            "flee_threshold": threshold,
            "safe_spot_disproved": safe_spot_disproved,
            "safe_spot_failure_count": safe_spot_failure_count,
            "tactic_warnings": tactic_warnings,
            "death_is_new": death_is_new,
            "risk_reasons": list(dict.fromkeys(risk_reasons)),
            "recovery_reasons": list(dict.fromkeys(recovery_reasons)),
            "quarantine_reasons": list(dict.fromkeys(quarantine_reasons)),
            "retreat_incident_count": (
                int(retreat_record.get("count", 0) or 0)
                if isinstance(retreat_record, dict)
                else 0
            ),
            "progress_lease": redact(progress_lease),
        }

    def _quarantine_farm_tactic(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        evidence: dict[str, Any],
    ) -> dict[str, Any]:
        room = evidence.get("room")
        quarantines = self.storage.get_runtime("farm_tactic_quarantine_v1", {})
        quarantines = dict(quarantines) if isinstance(quarantines, dict) else {}
        record = {
            "room": room,
            "assigned_room": evidence.get("assigned_room"),
            "at_assigned_room": evidence.get("at_assigned_room"),
            "target": evidence.get("target"),
            "use_safe_spots": evidence.get("use_safe_spots"),
            "quarantined_at": timestamp(),
            "goal_id": goal["id"],
            "reasons": evidence.get("quarantine_reasons")
            or evidence.get("risk_reasons", []),
            "deltas": evidence.get("deltas", {}),
            "health_fraction": evidence.get("health_fraction"),
            "flee_threshold": evidence.get("flee_threshold"),
            "live_overlevel_hostiles": evidence.get("live_overlevel_hostiles", []),
            "quarantined": evidence.get("at_assigned_room") is True,
            "guidance": (
                "Do not reuse this room/prey farm unchanged; choose a different grounded room after a verified capability improvement."
                if evidence.get("at_assigned_room") is True
                else "The retreat occurred during transit before the assigned room; do not label the target farm room unsafe. Recover and meet the keeper's vigor gate before another launch."
            ),
        }
        if evidence.get("at_assigned_room") is True and evidence.get("assigned_room") is not None:
            quarantines[str(evidence.get("assigned_room"))] = record
            self.storage.set_runtime("farm_tactic_quarantine_v1", quarantines)
        return record

    @staticmethod
    def _background_farm_stop_key(goal_id: str) -> str:
        return f"background_farm_stop_pending_v1:{goal_id}"

    def _request_background_farm_stop(
        self, goal: dict[str, Any], reason: str
    ) -> dict[str, Any]:
        """Relinquish mutations while keeping the keeper's safety telemetry alive."""
        result = self.broker.call_tool(
            "autopilot",
            {
                "agent": self.config.game.agent,
                "action": "stop",
                # Ordinary phase/controller ownership changes must never turn
                # off the watchdog while the game session remains live.  The
                # upstream default is an inert keeper; a hard stop is reserved
                # for process teardown after logout.
                "hard": False,
                "why": reason,
            },
            timeout=20,
            mutation=True,
        )
        self.storage.set_runtime(
            self._background_farm_stop_key(str(goal["id"])),
            {
                "requested_at": timestamp(),
                "requested_at_epoch": time.time(),
                "reason": reason,
            },
        )
        return result if isinstance(result, dict) else {"result": redact(result)}

    def _pending_background_farm_stop(
        self,
        goal: dict[str, Any],
        status: dict[str, Any],
        completion: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Hold ownership while one cooperative stop unwinds."""
        key = self._background_farm_stop_key(str(goal["id"]))
        pending = self.storage.get_runtime(key, {})
        pending = pending if isinstance(pending, dict) else {}
        if not pending:
            return None
        if status.get("running") is not True or self._keeper_is_inert(status):
            self.storage.set_runtime(key, {})
            return None

        requested_at = pending.get("requested_at_epoch")
        age = (
            max(0.0, time.time() - float(requested_at))
            if isinstance(requested_at, (int, float))
            else 0.0
        )
        if age >= FARM_STOP_RETRY_SECONDS:
            self.storage.set_runtime(key, {})
            self.storage.emit_event(
                "background_farm.stop_retry",
                "Keeper did not finish a requested stop within the retry window",
                severity="warning",
                interesting=True,
                goal_id=goal["id"],
                data={
                    "age_seconds": round(age, 1),
                    "reason": pending.get("reason"),
                    "activity": status.get("activity"),
                },
            )
            return None
        return {
            "background_farm_stopping": True,
            "already_requested": True,
            "reason": pending.get("reason"),
            "age_seconds": round(age, 1),
            "activity": status.get("activity"),
            "completion": completion,
        }

    def _manage_background_farm(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        completion: dict[str, Any],
        *,
        force_stop_reason: str | None = None,
    ) -> dict[str, Any] | None:
        """Give a running farm exclusive control until its bounded phase ends."""
        full_scan = goal["id"] not in self._farm_full_scan_goals
        status = self.broker.call_tool(
            "autopilot",
            {
                "agent": self.config.game.agent,
                "action": "status",
                "full_journal": full_scan,
            },
            timeout=20,
        )
        if full_scan:
            self._farm_full_scan_goals.add(goal["id"])
        if not isinstance(status, dict):
            return None
        # Diagnose an exact route failure before treating an inert telemetry
        # loop as harmless. The controller itself may have requested that stop
        # one turn after the keeper first reported the failed route.
        route_failure = self._handle_stopped_farm_route_failure(
            goal, observation, status, completion
        )
        if route_failure is not None:
            return route_failure
        pending_stop = self._pending_background_farm_stop(
            goal, status, completion
        )
        if pending_stop is not None:
            return pending_stop
        # Upstream now implements ordinary stop as an inert telemetry loop.
        # Once route diagnosis has had its chance, it is safe for foreground or
        # campaign work to proceed and must not be stopped again forever.
        if self._keeper_is_inert(status):
            return None
        if status.get("running") is not True:
            return None

        keeper_mode = str(status.get("mode") or "unknown")
        if keeper_mode != "farm":
            # Every keeper mode can move the character.  A startup/survival
            # keeper must therefore own the turn just like a farm keeper;
            # otherwise the planner can issue foreground travel while the
            # keeper is still completing its own route.  Let survival finish
            # healing first, then request a stop and withhold foreground work
            # until a later status call proves the loop has exited.
            health_fraction = self._vital_fraction(observation, "health")
            activity = str(status.get("activity") or "").strip().casefold()
            current_room = self._observation_room(observation)
            safe_ending_pending = bool(
                force_stop_reason
                and self._verified_safe_staging(current_room) is None
            )
            quiescent = activity in {
                "",
                "idle",
                "waiting",
                "watching",
                "standing by",
            }
            # A survival keeper is a recovery bridge, not a safe-ending
            # navigator.  In a proven monster-room wall it deliberately stays
            # put: leaving the wall would create danger, and survive mode has
            # no destination telling it which sanctuary the verified plan
            # selected.  Waiting merely because that safe ending is pending
            # therefore deadlocks ownership forever once health is full.  Let
            # it retain the character while recovery is genuinely unfinished;
            # at full health stop it even outside town so the foreground
            # controller can execute the already-verified travel step.
            if (
                keeper_mode == "survive"
                and health_fraction is not None
                and health_fraction < 1.0
                and (
                    health_fraction < self.config.policy.rest_health_fraction
                    or not quiescent
                )
            ):
                return {
                    "background_survival_monitoring": True,
                    "activity": status.get("activity"),
                    "health_fraction": health_fraction,
                    "safe_ending_pending": safe_ending_pending,
                    "completion": completion,
                }
            stopped = self._request_background_farm_stop(
                goal, "foreground campaign work is taking permanent ownership"
            )
            self.storage.set_runtime("background_farm_owner_v1", {})
            return {
                "background_keeper_stopping": True,
                "mode": keeper_mode,
                "activity": status.get("activity"),
                "result": redact(stopped),
                "completion": completion,
            }

        if force_stop_reason:
            current_room = self._observation_room(observation)
            if self._verified_safe_staging(current_room) is None:
                switched = self._ensure_survival_keeper()
                self.storage.set_runtime("background_farm_owner_v1", {})
                self.storage.emit_event(
                    "background_farm.safe_ending_handoff",
                    "Keeper switched from combat to survival for a safe phase ending",
                    severity="info",
                    interesting=False,
                    goal_id=goal["id"],
                    data={
                        "room": current_room,
                        "reason": force_stop_reason,
                        "result": redact(switched),
                    },
                )
                return {
                    "background_safe_ending_handoff": True,
                    "reason": force_stop_reason,
                    "result": redact(switched),
                    "completion": completion,
                }
            stopped = self._request_background_farm_stop(goal, force_stop_reason)
            self.storage.set_runtime("background_farm_owner_v1", {})
            return {
                "background_farm_stopping": True,
                "activity": status.get("activity"),
                "reason": force_stop_reason,
                "result": redact(stopped),
                "completion": completion,
            }

        mismatch = self._background_farm_mismatch(goal, status)
        if mismatch:
            stopped = self._request_background_farm_stop(
                goal, "the running farm does not match the active durable goal"
            )
            self.storage.set_runtime("background_farm_owner_v1", {})
            self._set_planner_feedback(
                goal,
                "A stale background farm from another goal was stopped. Wait for the keeper to finish its current pass, then launch only the hunt and assigned_room named by this goal.",
            )
            self.storage.emit_event(
                "background_farm.owner_mismatch",
                "Stopped a background farm whose goal or tactic did not match the active goal",
                severity="warning",
                interesting=True,
                goal_id=goal["id"],
                data={**mismatch, "result": redact(stopped)},
            )
            return {
                "background_farm_stale_stopped": True,
                "mismatch": mismatch,
                "completion": completion,
            }

        assignment_deferred = self._handle_deferred_farm_assignment(
            goal, observation, status, completion
        )
        if assignment_deferred is not None:
            return assignment_deferred

        evidence = self._farm_status_evidence(goal, observation, status)
        if evidence.get("at_assigned_room") is True:
            live_threats = self._live_overlevel_hostiles(observation)
            if live_threats:
                evidence["live_overlevel_hostiles"] = live_threats
                live_hazard = (
                    "live room contains a source-resolved hostile above the verified danger band"
                )
                evidence["risk_reasons"] = list(
                    dict.fromkeys([*evidence.get("risk_reasons", []), live_hazard])
                )
                evidence["quarantine_reasons"] = list(
                    dict.fromkeys(
                        [*evidence.get("quarantine_reasons", []), live_hazard]
                    )
                )
                self.storage.emit_event(
                    "background_farm.live_threat_detected",
                    "Live room state contained an over-level hostile omitted from the generator table",
                    severity="warning",
                    interesting=True,
                    goal_id=goal["id"],
                    data={
                        "room": evidence.get("room"),
                        "assigned_room": evidence.get("assigned_room"),
                        "target": evidence.get("target"),
                        "hostiles": live_threats,
                    },
                )
        if evidence.get("quarantine_reasons"):
            return self._handoff_background_farm_to_survival(
                goal,
                observation,
                status=status,
                evidence=evidence,
            )
        if evidence.get("recovery_reasons"):
            if int(evidence.get("retreat_incident_count", 0) or 0) > 0:
                self.storage.emit_event(
                    "background_farm.recovery_monitored",
                    "Farm keeper entered recovery without condemning the tactic",
                    severity="notice",
                    interesting=False,
                    goal_id=goal["id"],
                    data={
                        "room": evidence.get("room"),
                        "assigned_room": evidence.get("assigned_room"),
                        "target": evidence.get("target"),
                        "reasons": evidence.get("recovery_reasons"),
                        "retreat_incident_count": evidence.get(
                            "retreat_incident_count"
                        ),
                        "window_seconds": FARM_RETREAT_INCIDENT_WINDOW_SECONDS,
                        "classification": "ordinary_recovery_telemetry",
                        "quarantine_from_repetition": False,
                    },
                )
            return {
                "background_farm_recovering": True,
                "activity": status.get("activity"),
                "health_fraction": evidence.get("health_fraction"),
                "reasons": evidence.get("recovery_reasons"),
                "retreat_incident_count": evidence.get("retreat_incident_count"),
                "completion": completion,
            }

        health_criteria = self._health_progress_criteria(goal, completion)
        unmet_health = [item for item in health_criteria if item["result"].get("met") is not True]
        active_keeper_phase = self._active_keeper_combat_phase(goal)
        phase_work_remains = bool(
            active_keeper_phase is not None
            and self._phase_completion_checkpoint(active_keeper_phase) is None
            and self._phase_exhaustion_checkpoint(active_keeper_phase) is None
            and self._phase_abandonment_checkpoint(active_keeper_phase) is None
        )
        unhealthy = self._keeper_stall_is_persistent(status)
        if (unmet_health or phase_work_remains) and not unhealthy:
            runtime_key = f"background_farm_notice_at:{goal['id']}"
            last_notice = float(self.storage.get_runtime(runtime_key, 0) or 0)
            if time.time() - last_notice >= 300:
                self.storage.emit_event(
                    "background_farm.monitored",
                    "Background farming keeper owns movement and combat for this bounded phase",
                    severity="info",
                    interesting=False,
                    goal_id=goal["id"],
                    data={
                        "activity": status.get("activity"),
                        "did": redact(status.get("did")),
                        "placement": redact(status.get("placement")),
                        "safe_spot": redact(status.get("safe_spot")),
                        "health": deep_get(observation, "status.vitals.health"),
                        "targets": [item["criterion"].get("value") for item in unmet_health],
                        "phase_id": (
                            active_keeper_phase.get("id")
                            if active_keeper_phase is not None
                            else None
                        ),
                    },
                )
                self.storage.set_runtime(runtime_key, time.time())
            return {
                "background_farm_monitoring": True,
                "activity": status.get("activity"),
                "completion": completion,
            }

        # A healthy keeper is stopped only when its bounded criterion is met.
        # A stalled or errored keeper is also released so the planner can repair
        # the tactic on the following turn. Returning here prevents a foreground
        # mutation from racing the keeper during the same controller turn.
        reason = (
            "background keeper stalled or errored"
            if unhealthy
            else "bounded keeper-combat target reached"
        )
        stopped = self._request_background_farm_stop(goal, reason)
        self.storage.set_runtime("background_farm_owner_v1", {})
        if unhealthy:
            room = self._farm_room(status, observation)
            assigned_room = self._farm_assigned_room(status)
            target = self._farm_target(status)
            # A keeper can stall before it ever reaches the requested hunting
            # ground (for example, on unreachable geometry in its departure
            # room).  Keying that evidence to the destination would wrongly
            # suppress a later launch after the character is moved there.  A
            # transit stall describes the room where it actually happened;
            # only a stall at the assignment describes that assignment.
            tactic_room = (
                room
                if room is not None
                and assigned_room is not None
                and str(room) != str(assigned_room)
                else assigned_room or room
            )
            stagnations = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
            stagnations = dict(stagnations) if isinstance(stagnations, dict) else {}
            stagnation_key = f"{goal['id']}|{tactic_room}|{target.strip().casefold()}"
            prior = stagnations.get(stagnation_key)
            count = int(prior.get("count", 0) or 0) + 1 if isinstance(prior, dict) else 1
            stagnation = {
                "goal_id": goal["id"],
                "room": room,
                "assigned_room": tactic_room,
                "requested_assigned_room": assigned_room,
                "stalled_in_transit": bool(
                    room is not None
                    and assigned_room is not None
                    and str(room) != str(assigned_room)
                ),
                "target": target,
                "count": count,
                "recorded_at": timestamp(),
                "stalled": redact(status.get("stalled")),
                "last_error": status.get("last_error"),
                # Keeper ``did`` counters are lifetime/cumulative. Persist only
                # launch-scoped deltas so an old death cannot permanently mark
                # every later room unsafe.
                "deltas": redact(evidence.get("session_deltas", {})),
                "did": redact(evidence.get("session_deltas", {})),
                "evidence_scope": "launch",
                "guidance": (
                    "Do not restart this room/prey farm unchanged. Query hunting_grounds once, "
                    "choose a different non-quarantined room whose full spawn table is within the "
                    "verified danger band, and launch the same bounded HP phase there."
                ),
            }
            stagnations[stagnation_key] = stagnation
            self.storage.set_runtime("farm_tactic_stagnation_v1", stagnations)
            # Route diagnosis already ran against this launch above. Mark it
            # handled before clearing ownership so cumulative placement text
            # cannot be promoted on the next inert telemetry turn.
            self.storage.set_runtime(
                f"background_farm_route_failure_handled_v1:{goal['id']}", True
            )
            self.storage.emit_event(
                "background_farm.tactic_deferred",
                "Deferred an unchanged farm tactic after a keeper stall",
                severity="notice",
                interesting=True,
                goal_id=goal["id"],
                data=stagnation,
            )
        self._set_planner_feedback(
            goal,
            (
                f"The farming keeper was stopped because {reason}. "
                + (
                    "On the next turn query hunting_grounds once and launch the same bounded phase "
                    "in a different grounded, non-quarantined room; do not restart the stalled "
                    "room/prey tactic unchanged."
                    if unhealthy
                    else "On the next turn, recover or travel home for the remaining deterministic criteria; "
                    "do not restart the completed farm."
                )
            ),
        )
        self.storage.emit_event(
            "background_farm.stopped",
            f"Stopped background farming keeper: {reason}",
            severity="warning" if unhealthy else "info",
            interesting=unhealthy,
            goal_id=goal["id"],
            data={
                "reason": reason,
                "activity": status.get("activity"),
                "last_error": status.get("last_error"),
                "stalled": status.get("stalled"),
                "result": redact(stopped),
            },
        )
        return {
            "background_farm_stopped": True,
            "reason": reason,
            "completion": completion,
        }

    def _handoff_background_farm_to_survival(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        *,
        status: dict[str, Any] | None = None,
        evidence: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Stop automatic retry at the keeper's own retreat boundary."""
        if status is None:
            status = self.broker.call_tool(
                "autopilot",
                {"agent": self.config.game.agent, "action": "status", "full_journal": True},
                timeout=20,
            )
        if not self._keeper_is_driving(status) or status.get("mode") != "farm":
            return None

        evidence = evidence or self._farm_status_evidence(goal, observation, status)
        active_keeper_phase = self._active_keeper_combat_phase(goal)
        matching_active_phase = bool(
            active_keeper_phase is not None
            and self._background_farm_mismatch(goal, status) is None
        )
        abandonment_checkpoint = self._phase_abandonment_checkpoint(
            active_keeper_phase
        )
        if abandonment_checkpoint is not None and matching_active_phase:
            # The phase outcome is already decided, but terminal state must not
            # revoke the only loop capable of withdrawing the character. Retask
            # that same keeper in place; do not stop it, clear ownership, create
            # a lesson, or pause the goal until sanctuary is verified.
            switched = self._ensure_survival_keeper()
            self.storage.emit_event(
                "background_farm.abandonment_recovery_handoff",
                "Abandoned farm retained continuous keeper ownership for recovery",
                severity="warning",
                interesting=True,
                goal_id=goal["id"],
                data={
                    "phase_id": active_keeper_phase.get("id"),
                    "room": evidence.get("room"),
                    "health_fraction": evidence.get("health_fraction"),
                    "reason": abandonment_checkpoint.get("reason"),
                    "safe_ending": redact(
                        abandonment_checkpoint.get("safe_ending")
                    ),
                    "result": redact(switched),
                    "terminal_deferred": True,
                    "ownership_preserved": True,
                },
            )
            return {
                "abandonment_recovery_handoff": True,
                "switched_to_survival": True,
                "campaign_phase_failed": None,
                "strategic_goal_preserved": True,
                "ownership_preserved": True,
                "checkpoint": redact(abandonment_checkpoint),
                "result": redact(switched),
            }
        if not evidence.get("quarantine_reasons") and matching_active_phase:
            # The farm keeper already owns flee, withdrawal, and recovery. A
            # global critical-health advisory can observe the same health dip
            # one turn earlier than the farm supervisor, but that timing does
            # not turn a first recoverable incident into proof that the room
            # or phase failed. Keep the bounded phase and keeper recipe intact;
            # a death or another precise structural quarantine reason will
            # still take the terminal handoff below.
            self.storage.emit_event(
                "background_farm.critical_recovery_monitored",
                "Critical health remained under the active farm keeper's recovery control",
                severity="notice",
                interesting=False,
                goal_id=goal["id"],
                data={
                    "activity": status.get("activity"),
                    "room": evidence.get("room"),
                    "assigned_room": evidence.get("assigned_room"),
                    "target": evidence.get("target"),
                    "health_fraction": evidence.get("health_fraction"),
                    "flee_threshold": evidence.get("flee_threshold"),
                    "recovery_reasons": evidence.get("recovery_reasons", []),
                    "retreat_incident_count": evidence.get(
                        "retreat_incident_count", 0
                    ),
                    "campaign_phase_preserved": True,
                },
            )
            return {
                "farm_recovery_preserved": True,
                "switched_to_survival": False,
                "campaign_phase_failed": None,
                "strategic_goal_preserved": True,
                "activity": status.get("activity"),
                "reasons": evidence.get("recovery_reasons", []),
                "retreat_incident_count": evidence.get(
                    "retreat_incident_count", 0
                ),
            }
        if not evidence.get("quarantine_reasons"):
            # An unowned/legacy farm loop has no durable phase recipe to
            # preserve. In that case retain the conservative global recovery
            # behavior and prevent the orphan keeper from continuing combat.
            critical_reason = "controller critical-health interrupt"
            evidence["risk_reasons"] = list(
                dict.fromkeys([*evidence.get("risk_reasons", []), critical_reason])
            )
            evidence["quarantine_reasons"] = [critical_reason]

        death_event = None
        last_death = status.get("last_death") if isinstance(status.get("last_death"), dict) else None
        if last_death and last_death.get("at") is not None:
            death_at = str(last_death.get("at"))
            if self.storage.get_runtime("background_farm_last_death_at") != death_at:
                target = last_death.get("hunting") or deep_get(status, "policy.hunt") or "unknown"
                before = {
                    "look": {
                        "room": {
                            "num": last_death.get("room_num"),
                            "name": last_death.get("died_in"),
                        }
                    },
                    "status": {
                        "vitals": {
                            "health": {
                                "current": last_death.get("last_health"),
                                "max": last_death.get("level"),
                            }
                        }
                    },
                    "inventory": observation.get("inventory", {}),
                }
                combat = self.learning.record_combat_outcome(
                    tool="autopilot",
                    arguments={"target": target, "hunt": target},
                    before=before,
                    result={"died": True, "target": target, "post_mortem": last_death.get("post_mortem")},
                    after=observation,
                    died=True,
                )
                death_event = self.storage.emit_event(
                    "character.died",
                    "The character died during background farming",
                    severity="critical",
                    interesting=True,
                    goal_id=goal["id"],
                    data={"tool": "autopilot", "broker_death": redact(last_death), "combat_memory": combat},
                )
                self.storage.set_runtime("background_farm_last_death_at", death_at)

        quarantine = self._quarantine_farm_tactic(goal, observation, evidence)
        handled_key = f"background_farm_failure_handled_v1:{goal['id']}"
        already_handled = bool(self.storage.get_runtime(handled_key, False))
        lesson = None
        paused = None
        if not already_handled:
            live_room_hazard = bool(evidence.get("live_overlevel_hostiles"))
            assigned_tactic_failure = evidence.get("at_assigned_room") is True
            lesson_result = self.learning.defer_goal(
                goal,
                observation,
                tool="autopilot",
                arguments={
                    "action": "start",
                    "mode": "farm",
                    "hunt": evidence.get("target"),
                    "assigned_room": evidence.get("assigned_room"),
                    "use_safe_spots": evidence.get("use_safe_spots"),
                },
                reason=(
                    (
                        "Hazardous transit to the assigned farm room exceeded verified survivability before arrival: "
                        if evidence.get("at_assigned_room") is False
                        else "Background farming exceeded verified survivability in the assigned room: "
                    )
                    + "; ".join(str(item) for item in evidence.get("risk_reasons", []))
                ),
                event_kind="background_farm.survival_handoff",
                # A failure after arrival invalidates that room/target/safe-spot
                # tactic. A pre-arrival retreat invalidates the exact launch
                # route/origin/assignment tactic. Neither observation proves the
                # max-HP outcome impossible or justifies a capability-only gate.
                classification=(
                    "ineffective_tactic"
                    if assigned_tactic_failure
                    else "route_unavailable"
                ),
                scope="tactic",
                block=False,
                # A live over-level threat has a precise safety predicate. Do
                # not let a cooldown or a reconnect-assigned item id release
                # the tactic while the exact same danger is still present.
                retry_when=(
                    {
                        "mode": "any",
                        "conditions": [
                            {
                                "kind": "numeric_at_least",
                                "field": "max_health",
                                "value": max(
                                    1,
                                    max(
                                        int(item["level"])
                                        for item in evidence.get(
                                            "live_overlevel_hostiles", []
                                        )
                                        if isinstance(item, dict)
                                        and isinstance(item.get("level"), (int, float))
                                    )
                                    - FARM_DANGER_MARGIN,
                                ),
                            },
                            {
                                "kind": "corpus_changed",
                                "from": self.knowledge.corpus_version,
                            },
                        ],
                    }
                    if live_room_hazard
                    and any(
                        isinstance(item, dict)
                        and isinstance(item.get("level"), (int, float))
                        for item in evidence.get("live_overlevel_hostiles", [])
                    )
                    else None
                ),
            )
            lesson = lesson_result.get("lesson")

        switched = self.broker.call_tool(
            "autopilot",
            {
                "agent": self.config.game.agent,
                "action": "start",
                "mode": "survive",
                "hunt": "",
                "assigned_room": None,
                "bank_above": 0,
                "rest_below": self.config.policy.rest_health_fraction,
                "flee_below": self.config.policy.rest_health_fraction,
                # Reconnecting while a just-entered sanctuary has not yet been
                # durably saved can restore the prior dangerous room.
                "break_out_via_logoff": False,
            },
            timeout=20,
            mutation=True,
        )
        self.storage.set_runtime("background_farm_owner_v1", {})
        current_goal = self.storage.goal(goal["id"])
        phase_failure_reason = (
            "Farm survivability failed in the current internal phase: "
            + "; ".join(str(item) for item in evidence.get("risk_reasons", []))
        )
        failed_phase = (
            self._fail_active_campaign_phase(goal, phase_failure_reason)
            if not already_handled
            else None
        )
        if (
            not already_handled
            and failed_phase is None
            and current_goal
            and current_goal.get("status") == "active"
        ):
            paused = self.storage.manage_goal(
                {
                    "request_id": uuid7(),
                    "goal_id": goal["id"],
                    "expected_version": current_goal.get("version"),
                    "action": "pause",
                    "reason": (
                        "Controller paused progression after farm survivability failed: "
                        + "; ".join(str(item) for item in evidence.get("risk_reasons", []))
                    ),
                }
            ).get("goal")
        self.storage.set_runtime(handled_key, True)
        self.storage.emit_event(
            "background_farm.survival_handoff",
            "Farm retreat boundary handed the keeper back to survival-only recovery",
            severity="warning",
            interesting=True,
            goal_id=goal["id"],
            data={
                "activity": status.get("activity"),
                "last_death": redact(last_death),
                "death_event_id": death_event.get("id") if death_event else None,
                "evidence": redact(evidence),
                "quarantine": quarantine,
                "lesson_id": lesson.get("id") if isinstance(lesson, dict) else None,
                "goal_paused": paused is not None,
                "campaign_phase_failed": failed_phase.get("id") if failed_phase else None,
                "strategic_goal_preserved": failed_phase is not None,
                "result": redact(switched),
            },
        )
        return {
            "switched_to_survival": True,
            "death_observed": death_event is not None,
            "goal_paused": paused is not None,
            "campaign_phase_failed": failed_phase,
            "strategic_goal_preserved": failed_phase is not None,
            "quarantine": quarantine,
        }

    def _ensure_survival_keeper(self) -> dict[str, Any]:
        """Start foreground emergency recovery unless it already owns the turn."""
        status = self.broker.call_tool(
            "autopilot",
            {"agent": self.config.game.agent, "action": "status"},
            timeout=20,
        )
        if (
            self._keeper_is_driving(status)
            and status.get("mode") == "survive"
        ):
            return {
                "survival_keeper_running": True,
                "already_running": True,
                "activity": status.get("activity"),
            }

        result = self.broker.call_tool(
            "autopilot",
            {
                "agent": self.config.game.agent,
                "action": "start",
                "mode": "survive",
                # The upstream keeper retains farm policy fields across mode
                # changes. Clear them so emergency recovery cannot route back
                # toward a hunting room or make a special banking trip.
                "hunt": "",
                "assigned_room": None,
                "bank_above": 0,
                "rest_below": self.config.policy.rest_health_fraction,
                "flee_below": max(
                    0.75, self.config.policy.rest_health_fraction
                ),
                "break_out_via_logoff": False,
            },
            timeout=20,
            mutation=True,
        )
        return {
            "survival_keeper_started": True,
            "already_running": False,
            "result": redact(result),
        }

    @staticmethod
    def _observed_ability_values(
        observation: dict[str, Any],
    ) -> dict[str, dict[str, Any]] | None:
        abilities = observation.get("abilities")
        if not isinstance(abilities, dict):
            return None
        freshness = abilities.get("freshness")
        if isinstance(freshness, dict) and freshness.get("known") is False:
            return None
        values: dict[str, dict[str, Any]] = {}
        for plural, singular in (("skills", "skill"), ("spells", "spell")):
            rows = abilities.get(plural)
            if not isinstance(rows, list):
                continue
            for row in rows:
                if not isinstance(row, dict) or not row.get("name"):
                    continue
                try:
                    ability = int(row.get("ability"))
                except (TypeError, ValueError):
                    continue
                if ability <= 0:
                    continue
                name = " ".join(str(row["name"]).split())
                key = f"{singular}:{name.casefold()}"
                values[key] = {
                    "kind": singular,
                    "name": name,
                    "ability": ability,
                }
        return values

    def _record_character_progress(self, observation: dict[str, Any]) -> None:
        """Emit only durable character milestones suitable for an executive journal."""
        runtime_key = "character_progress_milestones_v1"
        previous = self.storage.get_runtime(runtime_key)
        health_max = deep_get(
            observation,
            "status.vitals.health.max",
            deep_get(observation, "look.vitals.health.max"),
        )
        try:
            max_health = int(health_max) if health_max is not None else None
        except (TypeError, ValueError):
            max_health = None
        ability_values = self._observed_ability_values(observation)

        if not isinstance(previous, dict):
            baseline = ability_values or {}
            self.storage.set_runtime(
                runtime_key,
                {
                    "max_health": max_health,
                    "abilities": baseline,
                    "reported_abilities": {
                        key: int(value["ability"]) for key, value in baseline.items()
                    },
                    "observed_at": timestamp(),
                },
            )
            return

        active = self.storage.active_goal()
        goal_id = active.get("id") if isinstance(active, dict) else None
        old_max = previous.get("max_health")
        if (
            isinstance(max_health, int)
            and isinstance(old_max, (int, float))
            and max_health > int(old_max)
        ):
            self.storage.emit_event(
                "progress.hp_gained",
                f"Maximum HP increased from {int(old_max)} to {max_health}",
                severity="notice",
                interesting=True,
                goal_id=goal_id,
                data={
                    "before": int(old_max),
                    "after": max_health,
                    "gained": max_health - int(old_max),
                    "room": redact(deep_get(observation, "look.room")),
                },
            )

        prior_abilities = previous.get("abilities")
        prior_abilities = prior_abilities if isinstance(prior_abilities, dict) else {}
        reported = previous.get("reported_abilities")
        reported = dict(reported) if isinstance(reported, dict) else {}
        if ability_values is not None:
            for key, current in ability_values.items():
                before = prior_abilities.get(key)
                if not isinstance(before, dict):
                    self.storage.emit_event(
                        f"progress.{current['kind']}_learned",
                        f"The character learned {current['kind']} {current['name']}",
                        severity="notice",
                        interesting=True,
                        goal_id=goal_id,
                        data={
                            "kind": current["kind"],
                            "name": current["name"],
                            "ability": current["ability"],
                        },
                    )
                    reported[key] = int(current["ability"])
                    continue
                old_value = before.get("ability")
                try:
                    old_value = int(old_value)
                except (TypeError, ValueError):
                    old_value = int(current["ability"])
                new_value = int(current["ability"])
                try:
                    last_reported = int(reported.get(key, old_value))
                except (TypeError, ValueError):
                    last_reported = old_value
                milestone = (new_value // 5) * 5
                if new_value > old_value and milestone >= 5 and milestone > last_reported:
                    self.storage.emit_event(
                        f"progress.{current['kind']}_milestone",
                        f"{current['name']} reached {milestone}",
                        severity="notice",
                        interesting=True,
                        goal_id=goal_id,
                        data={
                            "kind": current["kind"],
                            "name": current["name"],
                            "before": old_value,
                            "after": new_value,
                            "milestone": milestone,
                        },
                    )
                    reported[key] = milestone

        self.storage.set_runtime(
            runtime_key,
            {
                "max_health": max_health if max_health is not None else old_max,
                "abilities": ability_values if ability_values is not None else prior_abilities,
                "reported_abilities": reported,
                "observed_at": timestamp(),
            },
        )

    def _repair_persisted_phase_tactic_preferences(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Remove legacy model-authored exclusions from an active phase.

        New manager decisions are normalized before persistence, but a live
        deployment may inherit an active phase written by an older controller.
        Room and target exclusions are evidence, not planning preferences, and
        therefore belong to controller-owned route lessons, farm tactic
        quarantines, and scorecards. Keep the model's proposal only as an audit
        note and force a fresh execution plan against the repaired contract.
        """

        if not isinstance(phase, dict):
            return phase
        raw_context = phase.get("context")
        if not isinstance(raw_context, dict) or not any(
            field in raw_context for field in ("avoid_rooms", "avoid_targets")
        ):
            return phase

        context = dict(raw_context)
        proposed: dict[str, Any] = {}
        for field in ("avoid_rooms", "avoid_targets"):
            value = context.pop(field, None)
            if value not in (None, []):
                proposed[field] = redact(value)
        if proposed:
            existing = context.get("ignored_unverified_tactic_preferences")
            audit = dict(existing) if isinstance(existing, dict) else {}
            audit.update(proposed)
            context["ignored_unverified_tactic_preferences"] = audit

        repaired = self.storage.update_campaign_phase_guardrails(
            str(phase["id"]),
            abandon_predicates=list(phase.get("abandon_predicates", [])),
            context=context,
            reason=(
                "discarded legacy model-authored room and target exclusions; "
                "negative tactic evidence is controller-owned"
            ),
        )
        self._invalidate_execution_plan(
            goal,
            (
                "active phase contained legacy model-authored room or target "
                "exclusions without controller evidence"
            ),
        )
        return repaired

    def _campaign_turn_state(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        grounding: dict[str, Any],
    ) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any] | None]:
        """Reconcile the durable internal phase and select one when needed."""
        run, phase = self.campaign.ensure(goal)
        phase = self._repair_persisted_phase_tactic_preferences(goal, phase)
        outcome = self._evaluate_campaign_phase(goal, run, phase, observation)
        if outcome.completed or outcome.failed:
            handoff = (
                self._handoff_completed_research_phase(
                    goal, run, outcome.phase, observation
                )
                if outcome.completed
                else None
            )
            self._invalidate_execution_plan(
                goal,
                (
                    "the internal campaign phase reached its deterministic criteria"
                    if outcome.completed
                    else str(outcome.detail.get("reason") or "a phase abandonment predicate was verified")
                ),
            )
            run = self.storage.campaign_run(goal["id"]) or run
            phase = handoff or self.storage.active_campaign_phase(run["id"])
        elif outcome.detail.get("completion_deferred") is True:
            # Once the bounded phase outcome is durably verified, tactical
            # invalidation and phase replacement are no longer relevant. Keep
            # the phase and its plan intact until the safe-ending epilogue.
            return run, outcome.phase or phase, None
        research_avoid_rooms = self._recent_research_avoid_rooms(run)
        phase_blocker = self._campaign_phase_grounding_blocker(
            phase,
            observation,
            avoid_rooms=research_avoid_rooms,
            goal_id=goal["id"],
        )
        if phase is not None and phase_blocker is not None:
            reason = (
                "farm phase conflicts with retained controller evidence: "
                + str(phase_blocker.get("guidance") or phase_blocker.get("kind"))
            )
            self.storage.transition_campaign_phase(
                phase["id"],
                "failed",
                reason=reason,
            )
            self.storage.emit_event(
                "campaign.phase.grounding_rejected",
                "Retired an internal farm phase that conflicts with retained evidence",
                severity="warning",
                interesting=False,
                goal_id=goal["id"],
                data={
                    "phase_id": phase["id"],
                    "blocker": phase_blocker,
                    "strategic_goal_preserved": True,
                },
            )
            self._invalidate_execution_plan(goal, reason)
            run = self.storage.campaign_run(goal["id"]) or run
            phase = None
        if phase is not None:
            return run, phase, None

        grounded_context = (
            self.knowledge.context_for(goal, redact(observation))
            if hasattr(self.knowledge, "context_for")
            else {}
        )
        learned = self._campaign_manager_learning_context(
            self.learning.context_for(goal, redact(observation))
        )
        financial = self._campaign_manager_financial_context(
            self._financial_context(observation)
        )
        manager_observation = self._campaign_manager_observation(
            redact(observation)
        )
        retry_gate = self._research_retry_gate(goal, observation)
        run = self.storage.campaign_run(goal["id"]) or run
        manager_campaign_context = self._campaign_context(
            run, None, audience="manager"
        )
        manager_campaign_context["research_retry"] = retry_gate
        progression: dict[str, Any] | None = None
        durable_farm_intent = self._goal_farm_intent(goal)
        has_complete_durable_farm_recipe = (
            durable_farm_intent.get("assigned_room") is not None
            and bool(durable_farm_intent.get("hunt"))
        )
        if not has_complete_durable_farm_recipe and any(
            str(criterion.get("metric") or "").casefold()
            in {
                "max_health",
                "status.vitals.health.max",
                "look.vitals.health.max",
                "status.vitals.health.maximum",
                "look.vitals.health.maximum",
            }
            for criterion in goal.get("success_criteria", [])
            if isinstance(criterion, dict)
        ):
            try:
                progression = self.progression_context(
                    {"character_state": observation, "detail": "compact", "limit": 8}
                )
            except (BrokerError, ValueError) as exc:
                progression = {"warning": str(exc)[:500]}

        if hasattr(self.model, "manage_campaign"):
            decision = self.model.manage_campaign(
                goal=goal,
                observation=manager_observation,
                campaign_context=manager_campaign_context,
                grounded_knowledge=grounded_context,
                learned_failures=learned,
                financial_context=financial,
                progression_context=progression,
                persona=self.storage.persona(),
            )
            validation_error = self._campaign_manager_decision_error(
                run,
                goal,
                decision,
                observation,
                retry_gate,
                research_avoid_rooms,
            )
            if validation_error is not None:
                rejected_decision = redact(decision)
                manager_campaign_context = {
                    **manager_campaign_context,
                    "manager_feedback": {
                        "status": "rejected",
                        "validation_error": validation_error,
                        "rejected_decision": rejected_decision,
                        "instruction": (
                            "Return one corrected decision. For phase_action_succeeded, copy only "
                            "exact tool names from phase_capabilities for the selected phase kind; "
                            "context property names are facts, not tools. When research_retry.allowed "
                            "is false, do not repeat research_progression: choose an observable phase "
                            "outcome that changes one listed retry predicate. Reading unchanged "
                            "equipment or abilities is evidence collection, not progress."
                        ),
                    },
                }
                self.storage.emit_event(
                    "campaign.manager.revision_requested",
                    "Returned an invalid campaign phase to the manager for one grounded correction",
                    severity="notice",
                    interesting=False,
                    goal_id=goal["id"],
                    data={
                        "validation_error": validation_error[:1000],
                        "rejected_decision": rejected_decision,
                    },
                )
                decision = self.model.manage_campaign(
                    goal=goal,
                    observation=manager_observation,
                    campaign_context=manager_campaign_context,
                    grounded_knowledge=grounded_context,
                    learned_failures=learned,
                    financial_context=financial,
                    progression_context=progression,
                    persona=self.storage.persona(),
                )
            self.dependencies["model"] = "healthy"
        else:
            decision = {
                "decision": "start_phase",
                "phase": self.campaign.fallback_phase(goal, observation),
                "rationale": "Compatibility mode for a planner without a campaign-manager method.",
                "evidence": [],
            }

        external_blocker_candidate: dict[str, Any] | None = None
        manager_decision = str(decision.get("decision") or "")
        if manager_decision == "complete_campaign_candidate":
            decision = {
                "decision": "start_phase",
                "phase": self.campaign.fallback_phase(goal, observation),
                "rationale": "Deterministic strategic criteria rejected premature completion.",
                "evidence": decision.get("evidence", []),
            }
        elif manager_decision == "report_external_blocker_candidate":
            external_blocker_candidate = {
                "status": "candidate",
                "rationale": str(decision.get("rationale") or "")[:1000],
                "evidence": redact(decision.get("evidence", [])),
                "recorded_at": timestamp(),
            }
            self.storage.update_campaign_memory(
                run["id"], external_blocker=external_blocker_candidate
            )
            self.storage.emit_event(
                "campaign.blocker.candidate",
                "Campaign manager reported a possible external blocker; strategic goal remains active",
                severity="warning",
                interesting=False,
                goal_id=goal["id"],
                data={
                    "run_id": run["id"],
                    "rationale": str(decision.get("rationale") or "")[:1000],
                    "strategic_goal_preserved": True,
                },
            )
            decision = {
                "decision": "start_phase",
                "phase": self.campaign.fallback_phase(goal, observation),
                "rationale": "Continue ordinary-game alternatives until an external blocker is verified.",
                "evidence": decision.get("evidence", []),
            }

        try:
            validation_error = self._campaign_manager_decision_error(
                run,
                goal,
                decision,
                observation,
                retry_gate,
                research_avoid_rooms,
            )
            if validation_error is not None:
                raise ValueError(validation_error)
            phase = self.campaign.apply_manager_decision(
                run, goal, decision, observation=observation
            )
        except (TypeError, ValueError) as exc:
            self.storage.emit_event(
                "campaign.manager.rejected",
                f"Rejected invalid internal campaign phase: {str(exc)[:240]}",
                severity="warning",
                interesting=False,
                goal_id=goal["id"],
                data={"decision": redact(decision), "strategic_goal_preserved": True},
            )
            fallback_phase = (
                self._research_exhaustion_support_phase(
                    goal,
                    retry_gate,
                    self._research_retry_state(goal, observation),
                )
                if retry_gate.get("allowed") is False
                else self.campaign.fallback_phase(goal, observation)
            )
            fallback = {
                "decision": "start_phase",
                "phase": fallback_phase,
                "rationale": f"Compatibility fallback after invalid phase: {str(exc)[:300]}",
            }
            phase = self.campaign.apply_manager_decision(
                run, goal, fallback, observation=observation
            )
        if phase is None:
            raise ModelError("campaign manager did not leave an executable internal phase")
        if external_blocker_candidate is not None:
            # Creating a new phase normally clears stale blockers. This one is fresh and
            # must stay visible while the fallback phase tests ordinary-game alternatives.
            self.storage.update_campaign_memory(
                run["id"], external_blocker=external_blocker_candidate
            )
        return run, phase, {"decision": decision, "grounding": grounding}

    def _campaign_manager_decision_error(
        self,
        run: dict[str, Any],
        goal: dict[str, Any],
        decision: Any,
        observation: dict[str, Any],
        retry_gate: dict[str, Any],
        research_avoid_rooms: set[str],
    ) -> str | None:
        """Return deterministic feedback for invalid manager output without mutation."""

        try:
            if not isinstance(decision, dict):
                raise TypeError("campaign manager response must be a JSON object")
            self.campaign.validate_manager_decision(
                run, goal, decision, observation=observation
            )
            proposed_phase = decision.get("phase")
            if (
                retry_gate.get("allowed") is False
                and isinstance(proposed_phase, dict)
                and proposed_phase.get("kind") == "research_progression"
            ):
                raise ValueError(
                    "unchanged progression research is ineligible until its material retry "
                    "predicate changes: "
                    + str(retry_gate.get("reason") or "candidate set unchanged")
                )
            proposed_blocker = self._campaign_phase_grounding_blocker(
                proposed_phase if isinstance(proposed_phase, dict) else None,
                observation,
                avoid_rooms=research_avoid_rooms,
                goal_id=goal["id"],
            )
            if proposed_blocker is not None:
                raise ValueError(
                    "proposed farm phase conflicts with retained controller evidence: "
                    + str(
                        proposed_blocker.get("guidance")
                        or proposed_blocker.get("kind")
                    )
                )
        except (TypeError, ValueError) as exc:
            return str(exc)
        return None

    def _recent_research_avoid_rooms(self, run: dict[str, Any]) -> set[str]:
        """Return controller-owned room-wide exclusions.

        No current negative evidence has room-wide semantics: route lessons are
        exact origin/destination tactics and farm quarantines are exact
        room/prey/strategy combinations. Older phases persisted model-authored
        ``avoid_rooms`` lists, but replaying those opinions as evidence made one
        unrelated safe-return failure poison productive hunting rooms.
        """

        return set()

    def _recent_successful_farm_tactics(
        self, run: dict[str, Any]
    ) -> dict[tuple[str, str], int]:
        """Return successful room/prey pairs ranked newest first."""

        run_id = run.get("id") if isinstance(run, dict) else None
        if not run_id:
            return {}
        ranked: dict[tuple[str, str], int] = {}
        for prior in reversed(self.storage.campaign_phases(str(run_id))):
            if prior.get("kind") != "farm" or prior.get("status") != "succeeded":
                continue
            intent = self._campaign_phase_farm_intent(prior)
            room = intent.get("assigned_room")
            target = normalize(str(intent.get("hunt") or ""))
            if room is None or not target:
                continue
            key = (str(room), target)
            if key not in ranked:
                ranked[key] = len(ranked)
        return ranked

    def _clear_research_recipe_exhaustion(self, goal_id: str) -> None:
        """Discard stale exhaustion once any executable recipe is available."""

        if not goal_id:
            return
        values = self.storage.get_runtime(RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, {})
        if not isinstance(values, dict) or goal_id not in values:
            return
        remaining = dict(values)
        remaining.pop(goal_id, None)
        self.storage.set_runtime(RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, remaining)

    def _research_retry_state(
        self, goal: dict[str, Any], observation: dict[str, Any]
    ) -> dict[str, Any]:
        """Capture enabling capabilities and currently retained negative gates."""

        goal_id = str(goal.get("id") or "")
        raw_equipment = deep_get(
            observation,
            "equipment",
            deep_get(observation, "status.equipment", {}),
        )
        raw_equipment = raw_equipment if isinstance(raw_equipment, dict) else {}
        equipped = raw_equipment.get("equipped", [])
        equipped = equipped if isinstance(equipped, list) else []
        raw_wielding = raw_equipment.get("wielding", [])
        if isinstance(raw_wielding, str):
            raw_wielding = [raw_wielding]
        raw_wielding = raw_wielding if isinstance(raw_wielding, list) else []
        equipment = {
            "known": raw_equipment.get("known"),
            "equipped": sorted(
                [
                    {
                        "name": normalize(str(item.get("name") or "")),
                    }
                    for item in equipped
                    if isinstance(item, dict) and item.get("name")
                ],
                key=canonical_json,
            ),
            "wielding": sorted(
                normalize(str(item))
                for item in raw_wielding
                if str(item).strip()
            ),
        }
        raw_abilities = deep_get(
            observation,
            "abilities",
            {
                "skills": deep_get(
                    observation,
                    "skills",
                    deep_get(observation, "status.skills", []),
                ),
                "spells": deep_get(
                    observation,
                    "spells",
                    deep_get(observation, "status.spells", []),
                ),
            },
        )
        raw_abilities = raw_abilities if isinstance(raw_abilities, dict) else {}

        def ability_values(kind: str) -> list[dict[str, Any]]:
            values = raw_abilities.get(kind, [])
            values = values if isinstance(values, list) else []
            return sorted(
                [
                    {
                        "name": normalize(str(item.get("name") or "")),
                        "ability": item.get("ability"),
                    }
                    for item in values
                    if isinstance(item, dict) and item.get("name")
                ],
                key=canonical_json,
            )

        abilities = {
            "skills": ability_values("skills"),
            "spells": ability_values("spells"),
        }
        inventory = deep_get(observation, "inventory.items", [])
        inventory = inventory if isinstance(inventory, list) else []
        capability_item_words = (
            *WEAPON_WORDS,
            *ARMOR_WORDS,
            *HEALING_SUPPLY_WORDS,
            "potion",
            "cheese",
            "food",
        )
        items = sorted(
            [
                {
                    "name": normalize(str(item.get("name") or "")),
                    "amount": item.get(
                        "amount", item.get("quantity", item.get("count", 1))
                    ),
                    "equipped": item.get("equipped"),
                    "condition": item.get("condition"),
                    "quality": item.get("quality"),
                }
                for item in inventory
                if isinstance(item, dict)
                and item.get("name")
                and any(
                    word in normalize(str(item.get("name") or ""))
                    for word in capability_item_words
                )
            ],
            key=lambda item: (str(item.get("name")), str(item.get("amount"))),
        )
        quarantines = self.storage.get_runtime("farm_tactic_quarantine_v1", {})
        quarantines = quarantines if isinstance(quarantines, dict) else {}
        quarantine_gates = sorted(
            [
                {
                    "key": str(key),
                    "room": item.get("room", item.get("assigned_room")),
                    "target": normalize(str(item.get("target") or "")),
                    "use_safe_spots": item.get("use_safe_spots"),
                }
                for key, item in quarantines.items()
                if isinstance(item, dict)
            ],
            key=canonical_json,
        )
        stagnations = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
        stagnations = stagnations if isinstance(stagnations, dict) else {}
        stagnation_gates = sorted(
            [
                {
                    "key": str(key),
                    "room": item.get("room", item.get("assigned_room")),
                    "target": normalize(str(item.get("target") or "")),
                }
                for key, item in stagnations.items()
                if isinstance(item, dict)
                and str(key).startswith(f"{goal_id}|")
                and self._farm_stagnation_blocks(item)
            ],
            key=canonical_json,
        )
        route_gates = sorted(
            [
                {
                    "id": str(item.get("id") or ""),
                    "summary": str(item.get("summary") or "")[:300],
                }
                for item in self.storage.goal_lessons(
                    statuses=["deferred", "unlocked"], limit=200
                )
                if str(item.get("goal_id") or "") == goal_id
                and item.get("classification") == "route_unavailable"
            ],
            key=canonical_json,
        )
        return {
            "schema_version": RESEARCH_RETRY_STATE_SCHEMA_VERSION,
            "max_health": deep_get(
                observation,
                "status.vitals.health.max",
                deep_get(observation, "look.vitals.health.max"),
            ),
            # Broker cache ages and response notes are deliberately absent.
            "equipment": equipment,
            "abilities": abilities,
            "inventory": items,
            "knowledge_corpus_version": self.knowledge.corpus_version,
            "negative_gates": {
                "quarantines": quarantine_gates,
                "stagnations": stagnation_gates,
                "routes": route_gates,
            },
        }

    def _research_retry_state_fingerprint(
        self, goal: dict[str, Any], observation: dict[str, Any]
    ) -> str:
        """Hash the stable retry state for status and persistence."""

        return json_hash(self._research_retry_state(goal, observation))

    @staticmethod
    def _research_retry_enabling_changes(
        previous: dict[str, Any], current: dict[str, Any]
    ) -> list[str]:
        """Return only state changes that can make an excluded recipe executable."""

        changes: list[str] = []
        try:
            prior_health = int(previous.get("max_health"))
        except (TypeError, ValueError):
            prior_health = -1
        try:
            current_health = int(current.get("max_health"))
        except (TypeError, ValueError):
            current_health = -1
        if current_health > prior_health:
            changes.append("max_health_increased")

        prior_equipment = previous.get("equipment")
        prior_equipment = prior_equipment if isinstance(prior_equipment, dict) else {}
        current_equipment = current.get("equipment")
        current_equipment = current_equipment if isinstance(current_equipment, dict) else {}
        prior_wielding = {
            normalize(str(item))
            for item in prior_equipment.get("wielding", [])
            if str(item).strip()
        } if isinstance(prior_equipment.get("wielding"), list) else set()
        current_wielding = {
            normalize(str(item))
            for item in current_equipment.get("wielding", [])
            if str(item).strip()
        } if isinstance(current_equipment.get("wielding"), list) else set()
        if current_wielding and current_wielding != prior_wielding:
            changes.append("equipment_wielding_added")

        for kind in ("skills", "spells"):
            prior_rows = deep_get(previous, f"abilities.{kind}", [])
            current_rows = deep_get(current, f"abilities.{kind}", [])
            prior_by_name = {
                str(item.get("name") or ""): item.get("ability")
                for item in (prior_rows if isinstance(prior_rows, list) else [])
                if isinstance(item, dict) and item.get("name")
            }
            for item in current_rows if isinstance(current_rows, list) else []:
                if not isinstance(item, dict) or not item.get("name"):
                    continue
                name = str(item["name"])
                try:
                    before = float(prior_by_name.get(name, -1))
                    after = float(item.get("ability", -1))
                except (TypeError, ValueError):
                    continue
                if after > before:
                    changes.append(f"{kind}_increased")
                    break

        prior_items = previous.get("inventory")
        prior_items = prior_items if isinstance(prior_items, list) else []
        current_items = current.get("inventory")
        current_items = current_items if isinstance(current_items, list) else []
        prior_by_name = {
            str(item.get("name") or ""): item
            for item in prior_items if isinstance(item, dict) and item.get("name")
        }
        def category_names(
            state_equipment: dict[str, Any],
            state_items: list[dict[str, Any]],
            words: tuple[str, ...],
            *,
            include_wielding: bool = False,
        ) -> set[str]:
            names = {
                str(item.get("name") or "")
                for item in state_items
                if isinstance(item, dict)
                and item.get("name")
                and any(word in str(item.get("name") or "") for word in words)
            }
            equipped_rows = state_equipment.get("equipped", [])
            names.update(
                str(item.get("name") or "")
                for item in (equipped_rows if isinstance(equipped_rows, list) else [])
                if isinstance(item, dict)
                and item.get("name")
                and any(word in str(item.get("name") or "") for word in words)
            )
            if include_wielding:
                names.update(
                    normalize(str(item))
                    for item in state_equipment.get("wielding", [])
                    if str(item).strip()
                )
            return names

        for category, words, include_wielding in (
            ("weapon", WEAPON_WORDS, True),
            ("armor", ARMOR_WORDS, False),
        ):
            prior_names = category_names(
                prior_equipment, prior_items, words, include_wielding=include_wielding
            )
            current_names = category_names(
                current_equipment, current_items, words, include_wielding=include_wielding
            )
            # The first usable item in a missing category is a capability
            # change. An unverified duplicate is not evidence of improvement.
            if not prior_names and current_names:
                changes.append(f"first_{category}_available")

        for item in current_items:
            if not isinstance(item, dict) or not item.get("name"):
                continue
            name = str(item["name"])
            prior = prior_by_name.get(name)
            is_supply = any(
                word in name
                for word in (*HEALING_SUPPLY_WORDS, "potion", "cheese", "food")
            )
            if prior is None:
                if is_supply:
                    changes.append("capability_supplies_added")
                    break
                continue
            try:
                prior_amount = float(prior.get("amount", 1) or 0)
                current_amount = float(item.get("amount", 1) or 0)
            except (TypeError, ValueError):
                prior_amount = current_amount = 0
            equipment_item = any(
                word in name for word in (*WEAPON_WORDS, *ARMOR_WORDS)
            )
            if (is_supply and current_amount > prior_amount) or (
                equipment_item
                and any(
                    prior.get(key) != item.get(key)
                    for key in ("condition", "quality", "equipped")
                )
            ):
                changes.append(
                    "capability_supplies_improved"
                    if is_supply
                    else "equipment_item_improved"
                )
                break

        if previous.get("knowledge_corpus_version") != current.get(
            "knowledge_corpus_version"
        ):
            changes.append("knowledge_corpus_changed")

        prior_negative = previous.get("negative_gates")
        prior_negative = prior_negative if isinstance(prior_negative, dict) else {}
        current_negative = current.get("negative_gates")
        current_negative = current_negative if isinstance(current_negative, dict) else {}
        prior_gates = {
            canonical_json(item)
            for group in prior_negative.values()
            if isinstance(group, list)
            for item in group
        }
        current_gates = {
            canonical_json(item)
            for group in current_negative.values()
            if isinstance(group, list)
            for item in group
        }
        if prior_gates - current_gates:
            changes.append("blocking_evidence_removed")
        return list(dict.fromkeys(changes))

    def _research_retry_gate(
        self, goal: dict[str, Any], observation: dict[str, Any]
    ) -> dict[str, Any]:
        """Prevent unchanged candidate exhaustion from spawning another lookup phase."""

        goal_id = str(goal.get("id") or "")
        values = self.storage.get_runtime(RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, {})
        values = dict(values) if isinstance(values, dict) else {}
        record = values.get(goal_id)
        if not isinstance(record, dict):
            return {"allowed": True, "reason": "no retained exhausted candidate set"}
        try:
            repeat_count = int(record.get("repeat_count", 0) or 0)
        except (TypeError, ValueError):
            repeat_count = 0
        if repeat_count < 2:
            return {
                "allowed": True,
                "reason": "candidate exhaustion has not repeated independently",
                "repeat_count": repeat_count,
                "candidate_fingerprint": record.get("fingerprint"),
            }

        current_state = self._research_retry_state(goal, observation)
        current = json_hash(current_state)
        recorded_state = record.get("retry_state")
        state_schema = record.get("retry_state_schema")
        if (
            state_schema != RESEARCH_RETRY_STATE_SCHEMA_VERSION
            or not isinstance(recorded_state, dict)
        ):
            # Legacy fingerprints included the research loop's own lessons and
            # failed actions, so they cannot be compared safely with v3. Capture
            # the current state as a baseline and authorize one bounded lookup.
            # This lets a support phase completed while the old controller was
            # running hand back to research without making every later failure
            # look like a new material change. Merely reading this gate does not
            # consume the authorization: a typed hunting-grounds result either
            # clears exhaustion or records the new closed baseline.
            record = {
                **record,
                "retry_state_schema": RESEARCH_RETRY_STATE_SCHEMA_VERSION,
                "retry_state": current_state,
                "retry_state_fingerprint": current,
                "retry_migration_pending_at": timestamp(),
                "retry_migration_consumed_at": None,
            }
            values[goal_id] = record
            self.storage.set_runtime(RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, values)
            run = self.storage.campaign_run(goal_id)
            blocker = run.get("external_blocker") if isinstance(run, dict) else None
            if (
                isinstance(run, dict)
                and isinstance(blocker, dict)
                and blocker.get("kind") == "no_usable_farm_recipe"
            ):
                self.storage.clear_campaign_external_blocker(str(run["id"]))
            self.storage.emit_event(
                "campaign.research.retry_reopened",
                "Authorized one bounded progression lookup while migrating legacy exhaustion state",
                severity="notice",
                interesting=False,
                goal_id=goal_id,
                data={
                    "current_retry_state_fingerprint": current,
                    "migration_retry": True,
                },
            )
            return {
                "allowed": True,
                "reason": "one bounded retry is authorized while migrating legacy exhaustion state",
                "state_changed": False,
                "migration_retry": True,
            }
        if record.get("retry_migration_pending_at"):
            return {
                "allowed": True,
                "reason": (
                    "one bounded legacy migration retry remains pending until a "
                    "typed hunting-grounds result is validated"
                ),
                "state_changed": False,
                "migration_retry": True,
            }
        enabling_changes = self._research_retry_enabling_changes(
            recorded_state,
            current_state,
        )
        if enabling_changes:
            # Authorize exactly one lookup against the materially changed state,
            # while retaining the prior candidate-set history. If that lookup
            # returns the same candidates, it strengthens (rather than erases)
            # the exhaustion evidence and closes the gate again immediately.
            newly_pending = record.get("retry_pending_state_fingerprint") != current
            if newly_pending:
                record = {
                    **record,
                    "retry_pending_state": current_state,
                    "retry_pending_state_fingerprint": current,
                    "retry_reopened_from": record.get("retry_state_fingerprint"),
                    "retry_reopened_at": timestamp(),
                    "retry_reopened_by": enabling_changes,
                }
                values[goal_id] = record
                self.storage.set_runtime(
                    RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, values
                )
            run = self.storage.campaign_run(goal_id)
            blocker = run.get("external_blocker") if isinstance(run, dict) else None
            if (
                isinstance(run, dict)
                and isinstance(blocker, dict)
                and blocker.get("kind") == "no_usable_farm_recipe"
            ):
                self.storage.clear_campaign_external_blocker(str(run["id"]))
            if newly_pending:
                self.storage.emit_event(
                    "campaign.research.retry_reopened",
                    "Reopened progression research after material capability or world evidence changed",
                    severity="notice",
                    interesting=False,
                    goal_id=goal_id,
                    data={
                        "prior_retry_state_fingerprint": record.get(
                            "retry_reopened_from"
                        ),
                        "current_retry_state_fingerprint": current,
                        "enabling_changes": enabling_changes,
                    },
                )
            return {
                "allowed": True,
                "reason": "material capability or enabling world evidence changed",
                "state_changed": True,
                "enabling_changes": enabling_changes,
            }
        if record.get("retry_state_fingerprint") != current:
            # New failure/quarantine evidence can only narrow the candidate set.
            # Retain it as the new baseline without treating the loop's own
            # negative evidence as authorization for more research.
            record = {
                **record,
                "retry_state_schema": RESEARCH_RETRY_STATE_SCHEMA_VERSION,
                "retry_state": current_state,
                "retry_state_fingerprint": current,
            }
            values[goal_id] = record
            self.storage.set_runtime(RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, values)
            run = self.storage.campaign_run(goal_id)
            blocker = run.get("external_blocker") if isinstance(run, dict) else None
            if (
                isinstance(run, dict)
                and isinstance(blocker, dict)
                and blocker.get("kind") == "no_usable_farm_recipe"
            ):
                self.storage.update_campaign_memory(
                    run["id"], external_blocker={**blocker, **record}
                )
        return {
            "allowed": False,
            "reason": (
                "the same fully rejected candidate set repeated without any equipment, ability, "
                "inventory, route, quarantine, max-health, or knowledge-corpus change"
            ),
            "repeat_count": repeat_count,
            "candidate_fingerprint": record.get("fingerprint"),
            "retry_state_fingerprint": current,
            "retry_requires": [
                "equipment_change",
                "ability_change",
                "inventory_or_supplies_change",
                "route_or_quarantine_blocker_removed",
                "max_health_change",
                "knowledge_corpus_change",
            ],
        }

    @staticmethod
    def _research_exhaustion_support_phase(
        goal: dict[str, Any],
        retry_gate: dict[str, Any],
        retry_state: dict[str, Any],
    ) -> dict[str, Any]:
        """Safe non-research fallback after an invalid repeated lookup choice."""

        return {
            "kind": "prepare_combat",
            "objective": (
                "Make a material capability or world-evidence improvement that can reopen exhausted "
                "progression research. Reading unchanged equipment or abilities does not complete "
                "this phase."
            ),
            "success_criteria": [
                {
                    "id": "material-research-retry-unlocked",
                    "kind": RESEARCH_RETRY_UNLOCKED,
                }
            ],
            "abandon_predicates": [],
            "budget": {"max_actions": 24, "max_minutes": 45},
            "context": {
                "research_exhaustion_support": True,
                "candidate_fingerprint": retry_gate.get("candidate_fingerprint"),
                "retry_state_baseline": retry_state,
                "retry_state_fingerprint": json_hash(retry_state),
                "retry_requires": retry_gate.get("retry_requires", []),
            },
            "rationale": (
                "An unchanged progression lookup is deterministically closed. Produce a measurable "
                "equipment, ability, inventory, route, quarantine, max-health, or knowledge-corpus "
                "change before research can run again."
            ),
        }

    def _research_exhaustion_support_completion(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any],
        observation: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Verify a support phase only from a material research-retry delta."""

        context = phase.get("context")
        if (
            not isinstance(context, dict)
            or context.get("research_exhaustion_support") is not True
        ):
            return None
        baseline = context.get("retry_state_baseline")
        if not isinstance(baseline, dict):
            retained = self.storage.get_runtime(
                RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, {}
            )
            record = (
                retained.get(str(goal.get("id") or ""))
                if isinstance(retained, dict)
                else None
            )
            baseline = (
                record.get("retry_state") if isinstance(record, dict) else None
            )
        current = self._research_retry_state(goal, observation)
        enabling_changes = (
            self._research_retry_enabling_changes(baseline, current)
            if isinstance(baseline, dict)
            else []
        )
        met = bool(enabling_changes)
        return {
            "percent_estimate": 100 if met else 0,
            "summary": (
                "1 of 1 criteria verified"
                if met
                else "0 of 1 criteria verified"
            ),
            "evidence_event_ids": [],
            "criteria": [
                {
                    "id": "material-research-retry-unlocked",
                    "kind": RESEARCH_RETRY_UNLOCKED,
                    "met": met,
                    "detail": (
                        "material retry state changed: "
                        + ", ".join(enabling_changes)
                        if met
                        else (
                            "unchanged equipment/ability observations cannot reopen "
                            "research; awaiting one of: "
                            + ", ".join(
                                str(item)
                                for item in context.get("retry_requires", [])
                            )
                        )
                    ),
                }
            ],
            "all_met": met,
            "enabling_changes": enabling_changes,
            "baseline_retry_state_fingerprint": (
                json_hash(baseline) if isinstance(baseline, dict) else None
            ),
            "current_retry_state_fingerprint": json_hash(current),
        }

    def _reconcile_blocked_farm_exhaustion(
        self, observation: dict[str, Any]
    ) -> list[dict[str, Any]]:
        """Re-evaluate the evidence behind blocked no-recipe goals.

        Tactic lessons and their runtime quarantine records can change while a
        strategic goal is blocked.  The blocked goal must be requeued if any
        recorded candidate becomes executable, and must remain blocked when a
        different durable gate (such as the source spawn table) still proves
        every candidate unsafe.
        """

        raw = self.storage.get_runtime(
            RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, {}
        )
        exhaustion = dict(raw) if isinstance(raw, dict) else {}
        changed = False
        results: list[dict[str, Any]] = []
        for goal in self.storage.goals(["blocked"]):
            if goal.get("blocked_reason") != "no_usable_farm_recipe":
                continue
            goal_id = str(goal.get("id") or "")
            record = exhaustion.get(goal_id)
            if not isinstance(record, dict):
                requeued = self.storage.requeue_repaired_blocker(
                    goal_id,
                    blocked_reason="no_usable_farm_recipe",
                    reason=(
                        "the persisted candidate-exhaustion evidence no longer "
                        "exists, so the universal no-recipe claim is invalid"
                    ),
                )
                results.append(
                    {"goal_id": goal_id, "status": "requeued", "goal": requeued}
                )
                continue

            rejected = record.get("rejected")
            rejected = rejected if isinstance(rejected, list) else []
            try:
                candidate_count = int(record.get("candidate_count", 0) or 0)
            except (TypeError, ValueError):
                candidate_count = 0
            # An empty source result is still a current lack of candidates. A
            # malformed non-empty record is kept fail-closed for fresh research
            # rather than guessed into an executable tactic.
            candidates = [item for item in rejected if isinstance(item, dict)]
            if candidate_count <= 0 or not candidates:
                results.append({"goal_id": goal_id, "status": "still_blocked"})
                continue

            refreshed: list[dict[str, Any]] = []
            usable: dict[str, Any] | None = None
            for candidate in candidates:
                old_blocker = candidate.get("blocker")
                old_blocker = old_blocker if isinstance(old_blocker, dict) else {}
                use_safe_spots = old_blocker.get("use_safe_spots", True)
                if not isinstance(use_safe_spots, bool):
                    use_safe_spots = True
                proposed = {
                    "kind": "farm",
                    "context": {
                        "room": candidate.get("room"),
                        "target": candidate.get("target"),
                        "use_safe_spots": use_safe_spots,
                    },
                }
                blocker = self._campaign_phase_grounding_blocker(
                    proposed, observation, goal_id=goal_id
                )
                if blocker is None:
                    usable = candidate
                    break
                refreshed.append(
                    {
                        "room": candidate.get("room"),
                        "target": candidate.get("target"),
                        "blocker": redact(blocker),
                    }
                )

            if usable is not None:
                exhaustion.pop(goal_id, None)
                changed = True
                requeued = self.storage.requeue_repaired_blocker(
                    goal_id,
                    blocked_reason="no_usable_farm_recipe",
                    reason=(
                        "a previously rejected farm candidate now passes all "
                        "current source, route, and survivability gates"
                    ),
                )
                self.storage.emit_event(
                    "campaign.blocker.invalidated",
                    "Requeued progression because a farm candidate became executable",
                    severity="notice",
                    interesting=True,
                    goal_id=goal_id,
                    data={"candidate": redact(usable)},
                )
                results.append(
                    {
                        "goal_id": goal_id,
                        "status": "requeued",
                        "candidate": usable,
                        "goal": requeued,
                    }
                )
                continue

            if canonical_json(refreshed) != canonical_json(record.get("rejected", [])):
                updated = {
                    **record,
                    "fingerprint": json_hash(
                        {
                            "corpus_version": self.knowledge.corpus_version,
                            "rejected": [
                                {
                                    "room": item.get("room"),
                                    "target": item.get("target"),
                                    "kind": deep_get(item, "blocker.kind"),
                                }
                                for item in refreshed
                            ],
                        }
                    ),
                    "rejected": refreshed,
                    "reconciled_at": timestamp(),
                }
                exhaustion[goal_id] = updated
                changed = True
            results.append({"goal_id": goal_id, "status": "still_blocked"})

        if changed:
            self.storage.set_runtime(
                RESEARCH_RECIPE_EXHAUSTION_RUNTIME_KEY, exhaustion
            )
        return results

    def _source_room_overlevel_assessment(
        self,
        room_id: Any,
        observation: dict[str, Any],
        *,
        danger_margin: int = FARM_DANGER_MARGIN,
    ) -> dict[str, Any] | None:
        """Classify source-listed overlevel spawns without hiding unknown data."""

        maximum = deep_get(
            observation,
            "status.vitals.health.max",
            deep_get(observation, "look.vitals.health.max"),
        )
        try:
            character_level = int(maximum)
        except (TypeError, ValueError):
            return None
        getter = getattr(self.knowledge, "get", None)
        if not callable(getter) or room_id is None:
            return None
        entity_id = str(room_id)
        if not entity_id.startswith("location:"):
            entity_id = f"location:{entity_id}"
        try:
            result = getter(entity_id)
        except (OSError, sqlite3.Error, TypeError, ValueError):
            return None
        entity = result.get("entity") if isinstance(result, dict) else None
        spawn_table = entity.get("spawn_table") if isinstance(entity, dict) else None
        spawns = spawn_table.get("spawns") if isinstance(spawn_table, dict) else None
        if not isinstance(spawns, list):
            return None
        danger_limit = character_level + max(0, int(danger_margin))
        threats: list[dict[str, Any]] = []
        forgiven: list[dict[str, Any]] = []
        for spawn in spawns:
            if not isinstance(spawn, dict) or not self._spawn_is_hostile(spawn):
                continue
            try:
                creature_level = int(spawn.get("level"))
            except (TypeError, ValueError):
                continue
            is_threat, attack_rating = _is_overlevel_farm_threat(
                creature_level,
                danger_limit,
                difficulty=spawn.get("difficulty"),
            )
            if creature_level <= danger_limit:
                continue
            detail = {
                "entity_id": spawn.get("creature_id"),
                "name": spawn.get("creature"),
                "level": creature_level,
                "difficulty": spawn.get("difficulty"),
                "attack_rating": attack_rating,
                "character_level": character_level,
                "danger_limit": danger_limit,
                "chance": spawn.get("chance"),
                "cap": spawn.get("cap"),
                "how": spawn.get("how"),
                "source_ref": spawn.get("citation"),
            }
            (threats if is_threat else forgiven).append(detail)
        return {
            "danger_limit": danger_limit,
            "threats": sorted(threats, key=lambda item: -int(item["level"])),
            "forgiven": sorted(forgiven, key=lambda item: -int(item["level"])),
        }

    def _source_room_overlevel_hostiles(
        self,
        room_id: Any,
        observation: dict[str, Any],
        *,
        danger_margin: int = FARM_DANGER_MARGIN,
    ) -> list[dict[str, Any]]:
        """Return source-listed hostile spawns above the farm safety limit."""

        assessment = self._source_room_overlevel_assessment(
            room_id,
            observation,
            danger_margin=danger_margin,
        )
        return list(assessment["threats"]) if assessment is not None else []

    def _campaign_phase_grounding_blocker(
        self,
        phase: dict[str, Any] | None,
        observation: dict[str, Any] | None = None,
        *,
        avoid_rooms: set[str] | None = None,
        goal_id: str | None = None,
    ) -> dict[str, Any] | None:
        """Reject a phase with an unobservable outcome or hard tactic conflict.

        Tactical planning cannot replace a durable campaign phase.  Accepting a
        phase for a quarantined room/prey/strategy therefore traps the planner
        in endless plan revisions even when it correctly recognizes the bad
        destination. Apply the same quarantine matching used by autopilot
        before the phase is allowed to own execution. ``avoid_rooms`` remains
        accepted for persisted-call compatibility but is only a planning
        preference; it is never itself a grounding blocker.
        """

        if not isinstance(phase, dict):
            return None
        criteria = [
            criterion
            for criterion in phase.get("success_criteria", [])
            if isinstance(criterion, dict)
        ]
        if phase.get("kind") == "prepare_combat" and criteria and all(
            criterion.get("kind") == "phase_action_succeeded"
            for criterion in criteria
        ):
            mutating_tools = sorted(
                {
                    tool
                    for criterion in criteria
                    for tool in (
                        criterion.get("tools", [])
                        if isinstance(criterion.get("tools"), list)
                        else []
                    )
                    if tool in {"act", "cast", "sell", "sell_all", "shop"}
                }
            )
            if mutating_tools:
                return {
                    "kind": "invalid_prepare_combat_phase_outcome",
                    "tools": mutating_tools,
                    "guidance": (
                        "combat preparation cannot be verified by mutating adapter "
                        "success alone; require observable equipment, inventory, or "
                        "capacity state for "
                        + ", ".join(mutating_tools)
                    ),
                }
        phase_kind = str(phase.get("kind") or "")
        context = phase.get("context")
        context = context if isinstance(context, dict) else {}
        train_combat = self._train_ability_uses_combat_keeper(phase)
        if phase_kind != "farm" and not train_combat:
            return None
        intent = self._campaign_phase_farm_intent(phase)
        assigned_room = intent.get("assigned_room")
        target = intent.get("hunt")
        use_safe_spots = intent.get("use_safe_spots")
        missing = []
        if assigned_room is None:
            missing.append("context.room")
        if not target:
            missing.append("context.target")
        if not isinstance(use_safe_spots, bool):
            missing.append("context.use_safe_spots")
        if missing:
            label = "combat-training" if train_combat else "farm"
            return {
                "kind": (
                    "invalid_combat_training_phase_context"
                    if train_combat
                    else "invalid_farm_phase_context"
                ),
                "assigned_room": assigned_room,
                "hunt": target,
                "use_safe_spots": use_safe_spots,
                "guidance": (
                    f"{label} phase is not executable; provide structured "
                    + ", ".join(missing)
                    + " instead of relying on rationale prose"
                ),
            }
        if criteria and all(
            criterion.get("kind") == "phase_action_succeeded"
            for criterion in criteria
        ):
            return {
                "kind": (
                    "invalid_combat_training_phase_outcome"
                    if train_combat
                    else "invalid_farm_phase_outcome"
                ),
                "assigned_room": assigned_room,
                "hunt": target,
                "guidance": (
                    f"{('combat-training' if train_combat else 'farm')} phase cannot complete "
                    "when the keeper merely launches; require an observable outcome such as "
                    "an ability or max-HP milestone"
                ),
            }
        if isinstance(observation, dict):
            source_hostiles = self._source_room_overlevel_hostiles(
                assigned_room, observation
            )
            if source_hostiles:
                return {
                    "kind": "source_room_overlevel_hostile",
                    "assigned_room": assigned_room,
                    "hunt": target,
                    "use_safe_spots": use_safe_spots,
                    "hostiles": source_hostiles,
                    "danger_limit": source_hostiles[0].get("danger_limit"),
                    "guidance": (
                        "choose a source-grounded room whose full monster spawn "
                        "table stays within the character's survivability limit"
                    ),
                }
        if goal_id:
            stagnations = self.storage.get_runtime("farm_tactic_stagnation_v1", {})
            stagnations = stagnations if isinstance(stagnations, dict) else {}
            stagnation_key = (
                f"{goal_id}|{assigned_room}|{str(target).strip().casefold()}"
            )
            stagnation = stagnations.get(stagnation_key)
            if isinstance(stagnation, dict) and self._farm_stagnation_blocks(
                stagnation
            ):
                return {
                    "kind": "stagnated_farm_phase",
                    "assigned_room": assigned_room,
                    "hunt": target,
                    "guidance": stagnation.get("guidance")
                    or "choose a different grounded room/prey tactic",
                    "evidence": redact(stagnation),
                }
        arguments = {
            "assigned_room": assigned_room,
            "hunt": target,
            "use_safe_spots": use_safe_spots,
        }
        quarantines = self.storage.get_runtime("farm_tactic_quarantine_v1", {})
        quarantines = quarantines if isinstance(quarantines, dict) else {}
        quarantine = quarantines.get(str(assigned_room))
        if isinstance(quarantine, dict) and self._farm_quarantine_matches(
            quarantine, arguments
        ):
            return {
                "kind": "quarantined_farm_phase",
                "assigned_room": assigned_room,
                "hunt": target,
                "use_safe_spots": use_safe_spots,
                "guidance": quarantine.get("guidance")
                or "choose a different grounded farm room and tactic",
                "evidence": redact(quarantine),
            }

        if not isinstance(observation, dict):
            return None
        current_room = self._observation_room(observation)
        for lesson in self.storage.goal_lessons(
            statuses=["deferred", "unlocked"],
            limit=200,
        ):
            if lesson.get("classification") != "route_unavailable":
                continue
            failed_state = lesson.get("failed_state")
            failed_state = failed_state if isinstance(failed_state, dict) else {}
            failed_tactic = failed_state.get("failed_tactic")
            failed_tactic = failed_tactic if isinstance(failed_tactic, dict) else {}
            failed_arguments = failed_tactic.get("arguments")
            failed_arguments = failed_arguments if isinstance(failed_arguments, dict) else {}
            failed_destination = next(
                (
                    failed_arguments.get(key)
                    for key in ("to", "destination", "room", "assigned_room")
                    if failed_arguments.get(key) is not None
                ),
                None,
            )
            failed_room = failed_tactic.get("room", failed_state.get("room"))
            failed_origin = (
                failed_room.get("id", failed_room.get("num"))
                if isinstance(failed_room, dict)
                else failed_room
            )
            failed_corpus = failed_state.get("corpus_version")
            if (
                failed_destination is None
                or str(failed_destination) != str(assigned_room)
                or str(failed_origin) != str(current_room)
                or (
                    failed_corpus
                    and str(failed_corpus) != str(self.knowledge.corpus_version)
                )
            ):
                continue
            return {
                "kind": "retained_route_failure",
                "assigned_room": assigned_room,
                "origin_room": current_room,
                "lesson_id": lesson.get("id"),
                "guidance": (
                    str(lesson.get("summary") or "route is unavailable from the current origin")
                    + "; choose a different grounded destination or staging origin"
                ),
                "evidence": {
                    "tool": failed_tactic.get("tool"),
                    "arguments": redact(failed_arguments),
                    "corpus_version": failed_corpus,
                },
            }
        return None

    def _structured_farm_route_action(
        self,
        phase: dict[str, Any] | None,
        observation: dict[str, Any],
        execution_plan: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Execute a farm phase's explicit route one observed hop at a time."""

        if (
            not isinstance(phase, dict)
            or phase.get("kind") != "farm"
            or not isinstance(execution_plan, dict)
        ):
            return None
        context = phase.get("context")
        context = context if isinstance(context, dict) else {}
        route = context.get("route")
        route = route if isinstance(route, dict) else {}
        origin = route.get("from")
        hops = route.get("via")
        destination = context.get("room")
        if origin is None or not isinstance(hops, list) or not hops:
            return None
        hop_rooms = [
            hop.get("to")
            for hop in hops
            if isinstance(hop, dict) and hop.get("to") is not None
        ]
        if len(hop_rooms) != len(hops) or str(hop_rooms[-1]) != str(destination):
            return None
        route_rooms = [origin, *hop_rooms]
        current_room = self._observation_room(observation)
        current_index = next(
            (
                index
                for index, room in enumerate(route_rooms[:-1])
                if str(room) == str(current_room)
            ),
            None,
        )
        if current_index is None:
            return None
        next_room = route_rooms[current_index + 1]
        visible_exits = deep_get(observation, "look.exits", [])
        visible_exits = visible_exits if isinstance(visible_exits, list) else []
        if not any(
            isinstance(exit_, dict)
            and str(exit_.get("to")) == str(next_room)
            and exit_.get("reachable") is not False
            for exit_ in visible_exits
        ):
            return None

        steps = execution_plan.get("steps")
        steps = steps if isinstance(steps, list) else []
        safe_step_id = str(deep_get(execution_plan, "safe_ending.step_id", ""))
        plan_step_id = next(
            (
                str(step.get("id"))
                for step in steps
                if isinstance(step, dict)
                and step.get("tool") == "travel"
                and step.get("id")
                and str(step.get("id")) != safe_step_id
                and (
                    re.search(
                        rf"(?<!\d){re.escape(str(next_room))}(?!\d)",
                        canonical_json(step),
                    )
                    is not None
                    or re.search(
                        rf"(?<!\d){re.escape(str(destination))}(?!\d)",
                        canonical_json(step),
                    )
                    is not None
                )
            ),
            None,
        )
        if plan_step_id is None:
            return None
        return {
            "tool": "travel",
            "arguments": {"to": next_room},
            "rationale": (
                "Follow the farm phase's structured route one live, visible hop at a time."
            ),
            "expected_observation": {"room_id": next_room},
            "plan_step_id": plan_step_id,
        }

    def _structured_research_progression_action(
        self,
        phase: dict[str, Any] | None,
        observation: dict[str, Any],
        execution_plan: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Advance an explicitly grounded first-exit research contract.

        A planning model can keep selecting ``look`` because every fresh look is
        technically successful, even while the phase and verified plan both say
        to cross one specific visible exit first. Three independent records must
        agree before this fast path mutates: phase context, the live exit, and a
        matching non-terminal execution-plan step.
        """

        if (
            not isinstance(phase, dict)
            or phase.get("kind") != "research_progression"
            or not isinstance(execution_plan, dict)
        ):
            return None
        context = phase.get("context")
        context = context if isinstance(context, dict) else {}
        current_room = self._observation_room(observation)
        steps = execution_plan.get("steps")
        steps = steps if isinstance(steps, list) else []
        safe_step_id = str(deep_get(execution_plan, "safe_ending.step_id", ""))

        def plan_step(tool: str, *, room: int | None = None) -> str | None:
            for step in steps:
                if not isinstance(step, dict) or step.get("tool") != tool:
                    continue
                step_id = str(step.get("id") or "")
                if not step_id or step_id == safe_step_id:
                    continue
                if room is not None and re.search(
                    rf"(?<!\d){room}(?!\d)", canonical_json(step)
                ) is None:
                    continue
                return step_id
            return None

        successful_tools: set[str] = set()
        if phase.get("id"):
            successful_tools = {
                str(attempt.get("semantic_action") or "")
                for attempt in self.storage.phase_attempts(
                    str(phase["id"]), limit=200
                )
                if attempt.get("status") == "succeeded"
            }
        requires_hunting_grounds = any(
            isinstance(criterion, dict)
            and criterion.get("kind") == "phase_action_succeeded"
            and "hunting_grounds" in criterion.get("tools", [])
            for criterion in phase.get("success_criteria", [])
        )
        max_health = deep_get(
            observation,
            "status.vitals.health.max",
            deep_get(observation, "look.vitals.health.max"),
        )
        if context.get("deterministic_fallback") is True:
            if (
                requires_hunting_grounds
                and "hunting_grounds" not in successful_tools
                and isinstance(max_health, (int, float))
                and not isinstance(max_health, bool)
            ):
                # A model sometimes keeps rewriting this fallback plan between
                # `prey` and farm preparation. The phase contract itself names
                # the required read-only adapter, so execute it once even when
                # the plan used its broader `prey` alias.
                step_id = plan_step("hunting_grounds") or plan_step("prey")
                action = {
                    "tool": "hunting_grounds",
                    "arguments": {"for_level": int(max_health), "limit": 6},
                    "rationale": (
                        "Collect the exact bounded progression evidence required by "
                        "the deterministic fallback phase."
                    ),
                    "expected_observation": {
                        "progression_candidates": "returned"
                    },
                }
                if step_id is not None:
                    action["plan_step_id"] = step_id
                return action

        destination = context.get("first_exit_room")
        if (
            not isinstance(destination, int)
            and requires_hunting_grounds
            and "hunting_grounds" not in successful_tools
            and isinstance(max_health, (int, float))
            and not isinstance(max_health, bool)
        ):
            # Manager-created research phases do not always need a staging
            # exit. Their trusted criterion still names the only adapter whose
            # result can become a farm recipe. Honor a planner's broader prey
            # alias as authorization for that exact read-only lookup rather
            # than allowing the alias to satisfy an incompatible outcome.
            step_id = plan_step("hunting_grounds") or plan_step("prey")
            if step_id is not None:
                return {
                    "tool": "hunting_grounds",
                    "arguments": {"for_level": int(max_health), "limit": 6},
                    "rationale": (
                        "Collect the exact typed progression candidates required "
                        "by the active farm-recipe research phase."
                    ),
                    "expected_observation": {
                        "progression_candidates": "returned"
                    },
                    "plan_step_id": step_id,
                }
        if not isinstance(destination, int) or isinstance(destination, bool):
            return None

        if str(current_room) != str(destination):
            start_room = context.get("start_room")
            if start_room is not None and str(current_room) != str(start_room):
                return None
            visible_exits = deep_get(observation, "look.exits", [])
            visible_exits = visible_exits if isinstance(visible_exits, list) else []
            has_live_exit = any(
                isinstance(exit_, dict)
                and str(exit_.get("to")) == str(destination)
                and exit_.get("reachable") is not False
                for exit_ in visible_exits
            )
            step_id = plan_step("travel", room=destination)
            if not has_live_exit or step_id is None:
                return None
            return {
                "tool": "travel",
                "arguments": {"to": destination},
                "rationale": (
                    "Cross the phase's explicit first exit; live room evidence and the "
                    "verified execution plan agree on this destination."
                ),
                "expected_observation": {"room_id": destination},
                "plan_step_id": step_id,
            }

        needs_hunting_grounds = any(
            isinstance(criterion, dict)
            and criterion.get("kind") == "phase_action_succeeded"
            and "hunting_grounds" in criterion.get("tools", [])
            for criterion in phase.get("success_criteria", [])
        )
        step_id = plan_step("hunting_grounds")
        max_health = deep_get(
            observation,
            "status.vitals.health.max",
            deep_get(observation, "look.vitals.health.max"),
        )
        if (
            needs_hunting_grounds
            and step_id is not None
            and isinstance(max_health, (int, float))
            and not isinstance(max_health, bool)
        ):
            return {
                "tool": "hunting_grounds",
                "arguments": {"for_level": int(max_health), "limit": 6},
                "rationale": (
                    "The declared first exit is reached; collect the exact progression "
                    "evidence required by this phase once."
                ),
                "expected_observation": {"progression_candidates": "returned"},
                "plan_step_id": step_id,
            }
        return None

    def _structured_raza_exit_action(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any] | None,
        observation: dict[str, Any],
        execution_plan: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Execute the one-way tutorial graduation once HP progression is done.

        Raza has no world-graph route to the mainland.  The museum portal is a
        dedicated ordinary-client adapter and is the only supported exit, so a
        return phase must not spend turns searching unrelated city routes.
        """

        if (
            not isinstance(phase, dict)
            or phase.get("kind") not in {"return_home", "recover", "general"}
            or not self._goal_requires_raza_exit(goal)
            or not self._in_raza_zone(observation)
        ):
            return None
        max_health = deep_get(
            observation,
            "status.vitals.health.max",
            deep_get(observation, "look.vitals.health.max"),
        )
        if (
            not isinstance(max_health, (int, float))
            or isinstance(max_health, bool)
            or max_health < 25
        ):
            return None
        destination = self._verified_safe_staging(RAZA_EXIT_SAFE_ROOM_ID)
        if destination is None:
            return None

        step_id: str | None = None
        if isinstance(execution_plan, dict):
            safe_step_id = str(deep_get(execution_plan, "safe_ending.step_id", ""))
            for step in execution_plan.get("steps", []):
                if not isinstance(step, dict) or step.get("tool") != "leave_raza":
                    continue
                candidate = str(step.get("id") or "")
                if candidate and candidate != safe_step_id:
                    step_id = candidate
                    break
        action: dict[str, Any] = {
            "tool": "leave_raza",
            "arguments": {"then_travel_to": RAZA_EXIT_SAFE_ROOM_ID},
            "rationale": (
                "Maximum HP has reached the Raza cap; use the one-way museum "
                "portal and finish in a source-verified safe mainland room."
            ),
            "expected_observation": {
                "event_kind": "raza.left",
                "room_id": RAZA_EXIT_SAFE_ROOM_ID,
            },
        }
        if step_id is not None:
            action["plan_step_id"] = step_id
        return action

    @staticmethod
    def _campaign_manager_observation(observation: dict[str, Any]) -> dict[str, Any]:
        """Project verified state needed for phase choice, omitting raw room geometry."""

        look = observation.get("look")
        look = look if isinstance(look, dict) else {}
        status = observation.get("status")
        status = status if isinstance(status, dict) else {}
        inventory = observation.get("inventory")
        inventory = inventory if isinstance(inventory, dict) else {}

        objects = look.get("objects")
        compact_objects = [
            {
                key: item.get(key)
                for key in (
                    "id",
                    "name",
                    "type",
                    "class",
                    "is_player",
                    "attackable",
                    "relation",
                    "hostile",
                    "distance",
                    "x",
                    "y",
                    "can",
                )
                if item.get(key) is not None
            }
            for item in (objects[:24] if isinstance(objects, list) else [])
            if isinstance(item, dict)
        ]
        exits = look.get("exits")
        compact_exits = [
            {
                key: item.get(key)
                for key in (
                    "kind",
                    "to",
                    "toRid",
                    "name",
                    "reachable",
                    "steps_away",
                    "id",
                )
                if item.get(key) is not None
            }
            for item in (exits[:24] if isinstance(exits, list) else [])
            if isinstance(item, dict)
        ]
        raw_items = inventory.get("items")
        compact_items = [
            {
                key: item.get(key)
                for key in (
                    "id",
                    "name",
                    "amount",
                    "quantity",
                    "count",
                    "equipped",
                    "condition",
                    "quality",
                    "value",
                    "can",
                )
                if item.get(key) is not None
            }
            for item in (raw_items[:40] if isinstance(raw_items, list) else [])
            if isinstance(item, dict)
        ]
        compact_status = {
            key: status.get(key)
            for key in (
                "vitals",
                "stats",
                "attributes",
                "level",
                "karma",
                "effects",
                "resting",
                "combat",
                "load",
                "equipment",
                "abilities",
                "skills",
                "spells",
            )
            if status.get(key) is not None
        }
        value: dict[str, Any] = {
            "id": observation.get("id"),
            "observed_at": observation.get("observed_at"),
            "look": {
                key: look.get(key)
                for key in ("room", "self", "vitals", "combat", "affordances")
                if look.get(key) is not None
            },
            "status": compact_status,
            "inventory": {
                **{
                    key: inventory.get(key)
                    for key in ("carry", "capacity", "room_for", "full")
                    if inventory.get(key) is not None
                },
                "items": compact_items,
            },
        }
        if compact_objects:
            value["look"]["objects"] = compact_objects
        if compact_exits:
            value["look"]["exits"] = compact_exits
        for key in ("equipment", "abilities", "skills", "spells"):
            if observation.get(key) is not None:
                value[key] = observation.get(key)
        return value

    @staticmethod
    def _campaign_manager_financial_context(value: dict[str, Any]) -> dict[str, Any]:
        """Give the manager economic posture; defer full merchant catalogues to commerce."""

        if not isinstance(value, dict):
            return {}
        compact = {
            key: value.get(key)
            for key in (
                "carried_shillings",
                "source_estimated_inventory_value",
                "source_estimated_liquidatable_inventory_value",
                "confirmed_live_quote_liquidatable_value",
                "known_inventory_item_value",
                "known_liquidatable_inventory_value",
                "known_total_carried_value",
                "valuation_complete",
                "valuation_note",
                "liquidation_status",
                "banking_policy",
            )
            if value.get(key) is not None
        }
        for key in (
            "valued_items",
            "unknown_value_items",
            "unquoted_liquidatable_items",
            "valid_live_sell_quotes",
            "protected_sale_items",
            "rejected_buyer_candidates",
            "merchant_sale_refusals",
            "sale_exhausted_items",
        ):
            items = value.get(key)
            if isinstance(items, list):
                compact[key] = items[:16]
        buyers = value.get("buyer_candidates")
        if isinstance(buyers, list):
            compact["buyer_candidate_summary"] = [
                {
                    "item": item.get("item"),
                    "item_kind": item.get("item_kind"),
                    "candidate_count": len(item.get("candidates", []))
                    if isinstance(item.get("candidates"), list)
                    else 0,
                    "usable_room_ids": sorted(
                        {
                            room
                            for candidate in item.get("candidates", [])
                            if isinstance(candidate, dict)
                            for room in (
                                candidate.get("room_ids", [])
                                if isinstance(candidate.get("room_ids"), list)
                                else []
                            )
                        },
                        key=str,
                    )[:12],
                }
                for item in buyers[:16]
                if isinstance(item, dict)
            ]
            compact["merchant_detail_deferred"] = (
                "Select a commerce phase to retrieve exact buyers and live quotes."
            )
        return compact

    @staticmethod
    def _campaign_manager_learning_context(value: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(value, dict):
            return {}

        def lessons(name: str, limit: int) -> list[dict[str, Any]]:
            rows = value.get(name)
            rows = rows if isinstance(rows, list) else []
            return [
                {
                    key: item.get(key)
                    for key in (
                        "id",
                        "scope",
                        "classification",
                        "status",
                        "summary",
                        "retry_evaluation",
                        "unlock_condition",
                        "tactic_key",
                    )
                    if item.get(key) is not None
                }
                for item in rows[:limit]
                if isinstance(item, dict)
            ]

        readiness = value.get("combat_readiness")
        readiness = readiness if isinstance(readiness, dict) else {}
        room_evidence: list[dict[str, Any]] = []
        for quarantine in readiness.get("farm_tactic_quarantines", []):
            if not isinstance(quarantine, dict):
                continue
            room = quarantine.get("assigned_room", quarantine.get("room"))
            if room is None:
                continue
            room_evidence.append(
                {
                    "classification": "quarantined_exact_farm_tactic",
                    "evidence_strength": "hard",
                    "scope": "exact_room_target_strategy",
                    "room": room,
                    "target": quarantine.get("target"),
                    "use_safe_spots": quarantine.get(
                        "effective_use_safe_spots",
                        quarantine.get("use_safe_spots"),
                    ),
                    "room_wide_block": False,
                    "reasons": quarantine.get("reasons", [])[:4]
                    if isinstance(quarantine.get("reasons"), list)
                    else [],
                }
            )
        for score in readiness.get("farm_room_scorecard", []):
            if not isinstance(score, dict) or score.get("room") is None:
                continue
            target_kills = int(score.get("target_kills", 0) or 0)
            deaths = int(score.get("deaths", 0) or 0)
            withdrawals = int(score.get("withdrawals", 0) or 0)
            if score.get("quarantined") is True:
                classification = "quarantined_exact_farm_tactic"
                strength = "hard"
            elif target_kills > 0 and deaths == 0:
                classification = "productive_if_level_eligible"
                strength = "positive"
            elif deaths > 0 or withdrawals > 0:
                classification = "mixed_or_unsafe_observation"
                strength = "negative"
            else:
                classification = "insufficient_yield_evidence"
                strength = "informational"
            room_evidence.append(
                {
                    "classification": classification,
                    "evidence_strength": strength,
                    "scope": "exact_room_target_strategy",
                    "room": score.get("room"),
                    "target": score.get("target"),
                    "strategy": score.get("strategy"),
                    "target_kills": target_kills,
                    "deaths": deaths,
                    "withdrawals": withdrawals,
                    "room_wide_block": False,
                }
            )
        raw_tactics = value.get("deferred_tactics")
        raw_tactics = raw_tactics if isinstance(raw_tactics, list) else []
        for lesson in raw_tactics:
            if (
                not isinstance(lesson, dict)
                or lesson.get("classification") != "route_unavailable"
            ):
                continue
            failed = lesson.get("failed_tactic")
            failed = failed if isinstance(failed, dict) else {}
            arguments = failed.get("arguments")
            arguments = arguments if isinstance(arguments, dict) else {}
            destination = next(
                (
                    arguments.get(key)
                    for key in ("to", "destination", "room", "room_id")
                    if arguments.get(key) is not None
                ),
                None,
            )
            if destination is None:
                continue
            room_evidence.append(
                {
                    "classification": "unavailable_exact_route",
                    "evidence_strength": "hard",
                    "scope": "exact_origin_destination_tool",
                    "tool": failed.get("tool"),
                    "origin_room": failed.get("room"),
                    "destination_room": destination,
                    "room_wide_block": False,
                    "summary": str(lesson.get("summary") or "")[:300],
                }
            )

        return {
            "goal_family": value.get("goal_family"),
            "instructions": value.get("instructions"),
            "lessons": lessons("lessons", 8),
            "deferred_tactics": lessons("deferred_tactics", 12),
            "combat_readiness": readiness,
            "combat_history": (
                value.get("combat_history", [])[:8]
                if isinstance(value.get("combat_history"), list)
                else value.get("combat_history")
            ),
            "room_evidence": room_evidence[:24],
        }

    def _campaign_context(
        self,
        run: dict[str, Any],
        phase: dict[str, Any] | None,
        *,
        audience: str = "tactical",
    ) -> dict[str, Any]:
        if audience == "manager":
            value = self.campaign.manager_context(run, phase)
        elif audience == "tactical":
            value = self.campaign.tactical_context(run, phase)
        else:
            raise ValueError("campaign context audience must be manager or tactical")
        blocked_actions = self.storage.get_runtime("blocked_actions", [])
        if isinstance(blocked_actions, list):
            verified_no_progress = [
                {
                    key: item.get(key)
                    for key in (
                        "tool",
                        "arguments",
                        "room",
                        "reason",
                        "offered_item_names",
                        "merchant_identity",
                        "suppressed_count",
                        "updated_at",
                    )
                    if item.get(key) is not None
                }
                for item in blocked_actions
                if isinstance(item, dict)
                and item.get("goal_id") == run.get("goal_id")
            ][-12:]
            if verified_no_progress:
                value["verified_no_progress_tactics"] = redact(
                    verified_no_progress
                )
                value["instructions"] = (
                    str(value.get("instructions") or "")
                    + " Treat verified_no_progress_tactics as durable negative evidence: "
                    "do not restore an exact failed tool/argument/room tactic after travel, "
                    "a successful unrelated action, or a plan rewrite. Change the buyer, "
                    "offered item set, tool, or causal prerequisite."
                ).strip()
        value["operator_contract"] = {
            "primary": "Complete the active operator-supplied strategic goal through ordinary gameplay.",
            "pvp": (
                "Use player combat only when the active goal or immediate direct-defense context calls for it."
            ),
            "finish": "Use the active goal's deterministic terminal criteria; do not add a default destination.",
        }
        return value

    def _reconcile_existing_campaign_phase(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Finish a verified phase before legacy keeper ownership can mask it."""
        run = self.storage.campaign_run(goal["id"])
        if run is None:
            return None
        phase = self.storage.active_campaign_phase(run["id"])
        if phase is None:
            return None
        phase_context = (
            dict(phase.get("context"))
            if isinstance(phase.get("context"), dict)
            else {}
        )
        obsolete_healing_gate = (
            phase.get("kind") == "acquire_item"
            and phase_context.get("reason")
            == "replenish_healing_supplies_after_death"
        )
        if (
            obsolete_healing_gate
            and deep_get(observation, "autopilot.running") is not True
        ):
            reason = (
                "retired obsolete controller-imposed post-death flask phase; "
                "healing supplies are now planner discretion"
            )
            retired = self.storage.transition_campaign_phase(
                phase["id"], "superseded", reason=reason, resume_parent=True
            )
            resumed = self.storage.active_campaign_phase(run["id"])
            self._invalidate_execution_plan(goal, reason)
            self._clear_safety_suppression(str(goal.get("id") or ""))
            self._clear_planner_feedback()
            self.storage.emit_event(
                "campaign.post_death_healing_policy_migrated",
                "Removed obsolete controller-imposed healing-supply work",
                severity="notice",
                interesting=False,
                goal_id=goal.get("id"),
                data={
                    "retired_phase_id": retired.get("id"),
                    "resumed_parent_phase_id": (
                        resumed.get("id") if isinstance(resumed, dict) else None
                    ),
                    "strategic_goal_preserved": True,
                },
            )
            return {
                "campaign_phase_policy_migrated": True,
                "phase": retired,
                "next_phase": resumed,
                "goal_blocked": False,
                "goal": self.storage.goal(goal["id"]),
                "keeper_released": True,
                "strategic_goal_preserved": True,
            }
        combat_recipe_phase = phase.get("kind") == "farm" or (
            phase.get("kind") == "train_ability"
            and phase_context.get("training_method") == "combat"
        )
        policy_normalized = False
        if (
            combat_recipe_phase
            and phase_context.get("eat_before_fighting") is not True
            and phase_context.get("fight_above_vigor") != FARM_FIGHT_VIGOR
            and deep_get(observation, "autopilot.running") is not True
        ):
            phase_context["fight_above_vigor"] = FARM_FIGHT_VIGOR
            phase = self.storage.update_campaign_phase_guardrails(
                phase["id"],
                abandon_predicates=phase.get("abandon_predicates", []),
                context=phase_context,
                reason=(
                    "normalized persisted combat vigor policy to the natural "
                    f"rested floor of {FARM_FIGHT_VIGOR}"
                ),
            )
            policy_normalized = True
        retired_phases: list[dict[str, Any]] = []
        old_required_vigor: int | None = None
        retired_rest_reachable_recovery = False
        while phase is not None and len(retired_phases) < 2:
            context = (
                phase.get("context")
                if isinstance(phase.get("context"), dict)
                else {}
            )
            phase_reason = context.get("reason")
            obsolete_bootstrap = (
                phase.get("kind") == "farm"
                and phase_reason == "bootstrap_combat_funding"
            )
            obsolete_recovery = False
            required_vigor: int | None = None
            if (
                phase.get("kind") == "prepare_combat"
                and phase_reason == "recover_combat_vigor"
            ):
                try:
                    required_vigor = int(context.get("required_vigor") or 0)
                except (TypeError, ValueError):
                    required_vigor = 0
                # Above-rest gates are normalized away, while an at/below-rest
                # gate is recoverable by the keeper itself.  Neither belongs in
                # a persisted food-provisioning phase.
                obsolete_recovery = required_vigor > 0
                if obsolete_recovery:
                    old_required_vigor = required_vigor
                    retired_rest_reachable_recovery = (
                        retired_rest_reachable_recovery
                        or required_vigor <= RESTED_VIGOR_FLOOR
                    )
            if not obsolete_bootstrap and not obsolete_recovery:
                break
            if obsolete_bootstrap and deep_get(observation, "autopilot.running") is True:
                # Never abandon a keeper-owned phase while it may be outside
                # safe staging. A later safe restart/reconciliation can retire
                # the obsolete stack without orphaning hazardous movement.
                break
            reason = (
                "retired obsolete combat-provision funding bootstrap"
                if obsolete_bootstrap
                else (
                    f"retired unnecessary {old_required_vigor}-vigor provisioning gate; "
                    f"ordinary rest reaches {RESTED_VIGOR_FLOOR} and the keeper owns recovery"
                )
            )
            retired_phases.append(
                self.storage.transition_campaign_phase(
                    phase["id"],
                    "superseded",
                    reason=reason,
                    resume_parent=True,
                )
            )
            phase = self.storage.active_campaign_phase(run["id"])
        if retired_phases:
            reason = (
                (
                    "retired rest-reachable vigor provisioning; ordinary recovery "
                    "belongs to the keeper"
                )
                if retired_rest_reachable_recovery
                else (
                    "retired obsolete above-rest vigor recovery stack; ordinary farms "
                    f"now start at the rested floor of {FARM_FIGHT_VIGOR}"
                )
            )
            if isinstance(phase, dict) and phase.get("kind") in {
                "farm",
                "train_ability",
            }:
                resumed_context = (
                    dict(phase.get("context"))
                    if isinstance(phase.get("context"), dict)
                    else {}
                )
                if (
                    resumed_context.get("eat_before_fighting") is not True
                    and resumed_context.get("fight_above_vigor")
                    != FARM_FIGHT_VIGOR
                ):
                    resumed_context["fight_above_vigor"] = FARM_FIGHT_VIGOR
                    phase = self.storage.update_campaign_phase_guardrails(
                        phase["id"],
                        abandon_predicates=phase.get("abandon_predicates", []),
                        context=resumed_context,
                        reason=reason,
                    )
            self._invalidate_execution_plan(goal, reason)
            self._clear_safety_suppression(str(goal.get("id") or ""))
            self._clear_planner_feedback()
            self.storage.emit_event(
                "campaign.combat_vigor_policy_migrated",
                (
                    "Removed unnecessary rest-reachable vigor support work"
                    if retired_rest_reachable_recovery
                    else "Removed obsolete above-rest vigor support work"
                ),
                severity="notice",
                interesting=False,
                goal_id=goal.get("id"),
                data={
                    "retired_phase_ids": [item.get("id") for item in retired_phases],
                    "old_required_vigor": old_required_vigor,
                    "new_required_vigor": FARM_FIGHT_VIGOR,
                    "resumed_parent_phase_id": (
                        phase.get("id") if isinstance(phase, dict) else None
                    ),
                    "strategic_goal_preserved": True,
                },
            )
            return {
                "campaign_phase_completed": True,
                "campaign_phase_policy_migrated": True,
                "phase": retired_phases[-1],
                "next_phase": phase,
                "goal_blocked": False,
                "goal": self.storage.goal(goal["id"]),
                "keeper_released": True,
                "strategic_goal_preserved": True,
            }
        if policy_normalized:
            reason = (
                "normalized persisted combat vigor policy to the natural rested "
                f"floor of {FARM_FIGHT_VIGOR}"
            )
            self._invalidate_execution_plan(goal, reason)
            self._clear_safety_suppression(str(goal.get("id") or ""))
            self._clear_planner_feedback()
            self.storage.emit_event(
                "campaign.combat_vigor_policy_migrated",
                "Normalized an active combat phase to the rested vigor floor",
                severity="notice",
                interesting=False,
                goal_id=goal.get("id"),
                data={
                    "phase_id": phase.get("id"),
                    "new_required_vigor": FARM_FIGHT_VIGOR,
                    "strategic_goal_preserved": True,
                },
            )
            return {
                "campaign_phase_policy_migrated": True,
                "phase": phase,
                "next_phase": phase,
                "goal_blocked": False,
                "goal": self.storage.goal(goal["id"]),
                "keeper_released": True,
                "strategic_goal_preserved": True,
            }
        exhaustion_checkpoint = self._phase_exhaustion_checkpoint(phase)
        outcome = self._evaluate_campaign_phase(goal, run, phase, observation)
        if outcome.detail.get("abandonment_deferred") is True:
            # The verified failure is durable, but this phase still owns a
            # character outside safety.  Leave it active so the ordinary
            # keeper handoff and safe-return path keep continuous ownership.
            return None
        if (
            exhaustion_checkpoint is not None
            and (
                outcome.completed
                or outcome.failed
                or outcome.detail.get("completion_deferred") is True
            )
        ):
            # A deterministically verified success or abandonment supersedes a
            # previously latched budget boundary. Completion still performs
            # its own safe-ending hygiene before becoming terminal.
            self._clear_phase_exhaustion_checkpoint(str(phase["id"]))
            exhaustion_checkpoint = None
        exhausted = (
            exhaustion_checkpoint.get("budget")
            if isinstance(exhaustion_checkpoint, dict)
            else (
                None
                if (
                    outcome.completed
                    or outcome.failed
                    or outcome.detail.get("completion_deferred") is True
                )
                else self.campaign.budget_exhausted(phase)
            )
        )
        if not outcome.completed and not outcome.failed and exhausted is not None:
            if exhaustion_checkpoint is None:
                exhaustion_checkpoint = self._latch_phase_exhaustion(
                    goal, run, phase, exhausted, observation
                )
            safety = self._phase_exhaustion_safety(goal, phase, observation)
            if safety.get("met") is not True:
                # Keep the phase active so the ordinary keeper handoff and
                # safe-return path retain ownership. No further goal work is
                # authorized while this durable checkpoint exists.
                return None
        if not outcome.completed and not outcome.failed and exhausted is None:
            return None
        if outcome.completed:
            result_phase = outcome.phase
            reason = "the internal campaign phase reached its deterministic criteria"
            next_phase = self._handoff_completed_research_phase(
                goal, run, result_phase, observation
            )
        elif outcome.failed:
            result_phase = outcome.phase
            reason = str(
                outcome.detail.get("reason")
                or "a phase abandonment predicate was verified"
            )
            next_phase = None
        else:
            reason = (
                "internal campaign phase reached a verified safe boundary after "
                "exhausting its bounded review budget: "
                + canonical_json(exhausted)
            )
            result_phase = self.storage.transition_campaign_phase(
                phase["id"], "failed", reason=reason, resume_parent=False
            )
            self._clear_phase_exhaustion_checkpoint(str(phase["id"]))
            next_phase = None
        external_blocker = None
        if outcome.detail.get("external_blocker_verified") is True:
            external_blocker = {
                "kind": "no_usable_farm_recipe",
                "reason": (
                    "Two independent bounded research phases returned the same "
                    "candidate set, and every candidate conflicts with retained "
                    "route or survivability evidence."
                ),
                "research_exhaustion": redact(
                    outcome.detail.get("research_exhaustion")
                ),
            }
            self.storage.emit_event(
                "campaign.blocker.verified",
                "Retained the strategic goal after repeated research found no safe executable farm",
                severity="warning",
                interesting=True,
                goal_id=goal["id"],
                data={
                    "phase_id": phase.get("id"),
                    "research_exhaustion": redact(
                        outcome.detail.get("research_exhaustion")
                    ),
                    "retry_condition": (
                        "new route, world, or survivability evidence changes the "
                        "validated candidate set"
                    ),
                    "strategic_goal_preserved": True,
                },
            )
        self._invalidate_execution_plan(goal, reason)
        keeper_result: Any = None
        keeper_owned_phase = phase.get("kind") in {"farm", "train_ability"}
        keeper_released = not keeper_owned_phase
        if keeper_owned_phase:
            try:
                keeper = self.broker.call_tool(
                    "autopilot",
                    {"agent": self.config.game.agent, "action": "status"},
                    timeout=10,
                    mutation=False,
                )
                keeper_result = keeper
                if self._keeper_is_driving(keeper):
                    keeper_result = self._request_background_farm_stop(
                        goal, reason
                    )
                    self.storage.set_runtime("background_farm_owner_v1", {})
                keeper_released = isinstance(keeper_result, dict) and not (
                    self._keeper_is_driving(keeper_result)
                )
            except (BrokerError, ValueError):
                # The phase result is already deterministic and durable. The
                # next turn will reconcile any keeper still owning movement.
                keeper_result = {"status": "stop_pending_reconciliation"}
                keeper_released = False
        return {
            "campaign_phase_completed": outcome.completed,
            "campaign_phase_abandoned": outcome.failed,
            "campaign_phase_budget_exhausted": exhausted is not None,
            "phase": result_phase,
            "next_phase": next_phase,
            "research_handoff": next_phase is not None,
            "goal_blocked": False,
            "goal": self.storage.goal(goal["id"]),
            "external_blocker": external_blocker,
            "completion": outcome.detail,
            "budget": exhausted,
            "keeper": redact(keeper_result),
            "keeper_released": keeper_released,
            "strategic_goal_preserved": True,
        }

    def _fail_active_campaign_phase(
        self, goal: dict[str, Any], reason: str
    ) -> dict[str, Any] | None:
        run = self.storage.campaign_run(goal["id"])
        phase = self.storage.active_campaign_phase(run["id"]) if run else None
        if phase is None:
            return None
        failed = self.storage.transition_campaign_phase(
            phase["id"], "failed", reason=reason, resume_parent=False
        )
        self._clear_phase_exhaustion_checkpoint(str(phase["id"]))
        self._invalidate_execution_plan(goal, reason)
        return failed

    def turn(self) -> dict[str, Any]:
        if self.offline_diagnostics:
            return {"offline_diagnostics": True}
        if not self._turn_lock.acquire(blocking=False):
            return {"skipped": "turn already running"}
        try:
            observation = self._reconcile_recent_inventory_creation(
                self._reconcile_recent_room_transition(self.broker.observe())
            )
            self.last_observation = observation
            self._remember_safe_staging(observation)
            self.storage.record_snapshot(redact(observation))
            self._record_character_progress(observation)
            self.dependencies["broker"] = "healthy"
            self.learning.refresh_unlocks(observation)
            repaired_goal_blocks = self._repair_controller_goal_blocks()
            farm_blockers = self._reconcile_blocked_farm_exhaustion(observation)
            reconciled = self._reconcile_inactive_goal_completions(observation)
            goal = self.storage.active_goal()
            if goal is None:
                onboarding = self._onboarding_turn(observation)
                return {
                    "idle": True,
                    "reconciled_goal_ids": [item["id"] for item in reconciled],
                    "repaired_goal_block_ids": [
                        item["id"] for item in repaired_goal_blocks
                    ],
                    "farm_blocker_reconciliation": farm_blockers,
                    "onboarding": onboarding,
                }
            legacy_feedback = self._planner_feedback(goal)
            legacy_feedback_message = str(
                (legacy_feedback or {}).get("message") or ""
            ).casefold()
            if (
                "farm plan must travel to the verified regional sanctuary"
                in legacy_feedback_message
            ):
                # Schema v2 encoded the removed Tos/Raza staging policy. Do
                # not keep presenting its rejected-plan message after the
                # source-derived staging migration.
                self._clear_planner_feedback()
            grounding = self.knowledge.validate_goal(goal)
            if not grounding["valid"]:
                error_codes = {
                    str(error.get("code") or "")
                    for error in grounding.get("errors", [])
                    if isinstance(error, dict)
                }
                if error_codes == {"INVALID_FARM_OPERATOR_NOTES"}:
                    reason = (
                        "active goal contains malformed farm operator notes; "
                        "replace it with the validated key=value recipe"
                    )
                    paused = self.storage.manage_goal(
                        {
                            "request_id": f"controller-invalid-contract-{uuid7()}",
                            "goal_id": goal["id"],
                            "expected_version": goal.get("version"),
                            "action": "pause",
                            "reason": reason,
                        }
                    )["goal"]
                    self.storage.emit_event(
                        "knowledge.goal_paused",
                        f"Paused malformed farm goal for contract repair: {goal['title']}",
                        severity="warning",
                        interesting=True,
                        goal_id=goal["id"],
                        data={
                            "errors": grounding["errors"],
                            "corpus": grounding["corpus"],
                            "replacement_allowed": True,
                            "strategic_goal_preserved": True,
                        },
                    )
                    return {
                        "paused": True,
                        "goal": paused,
                        "grounding": grounding,
                        "replacement_allowed": True,
                        "strategic_goal_preserved": True,
                    }
                reason = (
                    "active goal failed grounded feasibility validation: "
                    + "; ".join(
                        str(error.get("message") or error.get("code"))
                        for error in grounding.get("errors", [])[:5]
                        if isinstance(error, dict)
                    )
                )
                deferred = self.learning.defer_goal(
                    goal,
                    observation,
                    reason=reason,
                    event_kind="knowledge.goal_paused",
                    classification="invalid_reference",
                    scope="goal",
                    block=False,
                )
                paused = self.storage.manage_goal(
                    {
                        "request_id": f"controller-ungrounded-contract-{uuid7()}",
                        "goal_id": goal["id"],
                        "expected_version": goal.get("version"),
                        "action": "pause",
                        "reason": reason,
                    }
                )["goal"]
                self.storage.emit_event(
                    "knowledge.goal_paused",
                    f"Paused ungrounded goal for contract repair: {goal['title']}",
                    severity="warning",
                    interesting=True,
                    goal_id=goal["id"],
                    data={
                        "errors": grounding["errors"],
                        "corpus": grounding["corpus"],
                        "strategic_goal_preserved": True,
                    },
                )
                return {
                    **deferred,
                    "paused": True,
                    "goal": paused,
                    "grounding": grounding,
                    "strategic_goal_preserved": True,
                }
            self._reconcile_purchase_transaction(goal)
            completion = self.criteria.evaluate(goal, observation)
            done = self._complete_goal_if_safe(goal, observation, completion)
            if done is not None:
                return {"goal": done, "completed": True}
            completion_checkpoint = self._goal_completion_checkpoint(goal)
            if completion_checkpoint is not None:
                # Criteria such as location_reached may become false again as
                # the character leaves the achieved target. Keep the verified
                # outcome latched while the final safe travel executes.
                completion = completion_checkpoint["completion"]
            goal = self.storage.set_goal_completion(goal["id"], completion)
            phase_completion_checkpoint = None
            phase_exhaustion_checkpoint = None
            phase_abandonment_checkpoint = None
            phase_safe_return_checkpoint = None
            if completion_checkpoint is None:
                phase_completion = self._reconcile_existing_campaign_phase(
                    goal, observation
                )
                if phase_completion is not None:
                    priority_preemption = self._preempt_at_safe_campaign_boundary(
                        goal,
                        observation,
                        phase_completion.get("phase"),
                        keeper_released=phase_completion.get("keeper_released"),
                    )
                    if priority_preemption is not None:
                        phase_completion.update(priority_preemption)
                    return phase_completion
                existing_run = self.storage.campaign_run(goal["id"])
                existing_phase = (
                    self.storage.active_campaign_phase(existing_run["id"])
                    if existing_run is not None
                    else None
                )
                if existing_run is not None and existing_phase is None:
                    prior_phases = self.storage.campaign_phases(existing_run["id"])
                    boundary_phase = prior_phases[-1] if prior_phases else None
                    priority_preemption = self._preempt_at_safe_campaign_boundary(
                        goal,
                        observation,
                        boundary_phase,
                    )
                    if priority_preemption is not None:
                        return {
                            "campaign_phase_boundary": True,
                            "phase": boundary_phase,
                            **priority_preemption,
                        }
                phase_completion_checkpoint = self._phase_completion_checkpoint(
                    existing_phase
                )
                phase_exhaustion_checkpoint = self._phase_exhaustion_checkpoint(
                    existing_phase
                )
                phase_abandonment_checkpoint = (
                    self._phase_abandonment_checkpoint(existing_phase)
                )
                phase_safe_return_checkpoint = (
                    phase_completion_checkpoint
                    if phase_completion_checkpoint is not None
                    else (
                        phase_exhaustion_checkpoint
                        if phase_exhaustion_checkpoint is not None
                        else phase_abandonment_checkpoint
                    )
                )
            expired_opportunity = self._expire_direct_pvp_opportunity(
                goal, observation, completion
            )
            if expired_opportunity is not None:
                return expired_opportunity
            if not any(
                item.get("result", {}).get("met") is not True
                for item in self._health_progress_criteria(goal, completion)
            ):
                feedback = self._planner_feedback(goal)
                feedback_message = str((feedback or {}).get("message") or "").casefold()
                if (
                    "execution plan failed deterministic verification" in feedback_message
                    and any(
                        marker in feedback_message
                        for marker in (
                            "farm launch",
                            "autopilot launch",
                            "assigned room",
                            "safe staging room",
                        )
                    )
                ):
                    self._clear_planner_feedback()
            # A successfully learned skill/spell normally disappears from the
            # teacher's quote. Verify the durable transaction result first;
            # re-running stock preflight after acquisition would misclassify
            # that expected disappearance as world_unavailable and block any
            # remaining explicit completion criteria.
            purchase_result_met = self._purchase_result_met(goal, completion)
            purchase_preflight = (
                None
                if purchase_result_met or phase_safe_return_checkpoint is not None
                else self._purchase_preflight(goal, observation)
            )
            if isinstance(purchase_preflight, dict):
                failed_statuses = {
                    "merchant_not_visible",
                    "item_not_quoted",
                    "price_exceeds_limit",
                }
                failure_is_durable = (
                    purchase_preflight.get("status") == "price_exceeds_limit"
                    or int(purchase_preflight.get("failed_checks", 0) or 0) >= 3
                )
                if purchase_preflight.get("status") in failed_statuses and failure_is_durable:
                    reason = (
                        "purchase plan failed live verification: "
                        + str(purchase_preflight.get("reason") or purchase_preflight.get("status"))
                    )
                    deferred = self.learning.defer_goal(
                        goal,
                        observation,
                        tool="purchase_preflight",
                        reason=reason,
                        event_kind="planner.preflight.failed",
                        classification="world_unavailable",
                        scope="tactic",
                        block=False,
                    )
                    self.storage.emit_event(
                        "planner.preflight.failed",
                        f"Purchase preflight deferred one tactic for: {goal['title']}",
                        severity="warning",
                        interesting=True,
                        goal_id=goal["id"],
                        data={
                            "preflight": redact(purchase_preflight),
                            "strategic_goal_preserved": True,
                        },
                    )
                    return {
                        "goal_blocked": False,
                        "tactic_deferred": True,
                        "purchase_preflight": purchase_preflight,
                        **deferred,
                    }
            advisories = self._goal_advisories(goal, observation)
            if any(item["kind"] == "survival_interrupt" for item in advisories):
                handoff = self._handoff_background_farm_to_survival(goal, observation)
                # A foreground fight/travel goal has no farm keeper for the
                # handoff helper to convert. Start recovery directly instead
                # of repeatedly suppressing planning while nothing heals or
                # withdraws the character.
                if handoff is None:
                    handoff = self._ensure_survival_keeper()
                incident = self.storage.get_runtime("survival_incident_v1", {})
                same_incident = isinstance(incident, dict) and incident.get("goal_id") == goal["id"]
                event = None
                if not same_incident:
                    farm_recovery_preserved = bool(
                        isinstance(handoff, dict)
                        and handoff.get("farm_recovery_preserved")
                    )
                    event = self.storage.emit_event(
                        "survival.interrupt",
                        (
                            "Critical health: active farm keeper retained recovery control"
                            if farm_recovery_preserved
                            else "Critical health: tactical planning yielded to survival autopilot"
                        ),
                        severity="warning",
                        interesting=True,
                        goal_id=goal["id"],
                        data={"advisories": advisories, "keeper": redact(handoff)},
                    )
                    self.storage.set_runtime(
                        "survival_incident_v1",
                        {"goal_id": goal["id"], "started_at": time.time(), "event_id": event["id"]},
                    )
                interrupts = self.storage.goal_events(
                    goal["id"], kinds=["survival.interrupt"], limit=100
                )
                budget = max(1, self.config.learning.survival_interrupt_budget)
                if event and len(interrupts) >= budget and len(interrupts) % budget == 0:
                    self.storage.emit_event(
                        "survival.pattern_observed",
                        "Repeated survival handoffs retained as planning evidence",
                        severity="warning",
                        interesting=True,
                        goal_id=goal["id"],
                        data={
                            "interrupt_count": len(interrupts),
                            "goal_blocked": False,
                            "guidance": (
                                "choose a different exact tactic or supporting phase; "
                                "do not stop the strategic goal"
                            ),
                        },
                    )
                return {"survival_interrupt": True, "advisories": advisories, "background_farm": handoff}
            incident = self.storage.get_runtime("survival_incident_v1", {})
            if isinstance(incident, dict) and incident.get("goal_id") == goal["id"]:
                self.storage.set_runtime("survival_incident_v1", None)
            farm_control = self._manage_background_farm(
                goal,
                observation,
                completion,
                force_stop_reason=(
                    (
                        "the active campaign phase budget is exhausted; preserve "
                        "survival control before the safe-ending travel"
                        if phase_exhaustion_checkpoint is not None
                        else (
                            "the active campaign phase abandonment is verified; preserve "
                            "survival control before the safe-ending travel"
                            if phase_abandonment_checkpoint is not None
                            else "the active campaign phase outcome is verified; release "
                            "movement control for the plan's safe-ending travel"
                        )
                    )
                    if phase_safe_return_checkpoint is not None
                    else None
                ),
            )
            if farm_control is not None:
                return farm_control
            structured_purchase = (
                None
                if phase_safe_return_checkpoint is not None
                else self._structured_purchase_preparation_action(
                    goal, observation, completion, purchase_preflight
                )
            )
            if structured_purchase is not None:
                execution_plan = self._execution_plan(goal)
                if execution_plan is not None:
                    step_ids = {
                        str(step.get("id") or "")
                        for step in execution_plan.get("steps", [])
                        if isinstance(step, dict)
                    }
                    step_id = str(structured_purchase.get("plan_step_id") or "")
                    if step_id not in step_ids:
                        stored_plan = self._store_execution_plan(
                            goal,
                            self._structured_purchase_controller_plan(
                                goal,
                                completion,
                                selected_plan=execution_plan,
                            ),
                            grounding=grounding,
                            revision=True,
                        )
                        return {"planned": True, "execution_plan": stored_plan}
                    return self._execute(goal, observation, structured_purchase)
            structured_preparation = (
                None
                if phase_safe_return_checkpoint is not None
                else self._structured_farm_preparation_action(
                    goal, observation, completion
                )
            )
            if structured_preparation is not None:
                execution_plan = self._execution_plan(goal)
                if execution_plan is not None:
                    step_ids = {
                        str(step.get("id") or "")
                        for step in execution_plan.get("steps", [])
                        if isinstance(step, dict)
                    }
                    step_id = str(structured_preparation.get("plan_step_id") or "")
                    if step_id not in step_ids:
                        stored_plan = self._store_execution_plan(
                            goal,
                            self._structured_farm_controller_plan(
                                goal,
                                selected_plan=execution_plan,
                            ),
                            grounding=grounding,
                            revision=True,
                        )
                        return {"planned": True, "execution_plan": stored_plan}
                    return self._execute(goal, observation, structured_preparation)
            structured_launch = (
                None
                if phase_safe_return_checkpoint is not None
                else self._structured_farm_launch_plan(
                    goal, observation, completion
                )
            )
            if structured_launch is not None:
                execution_plan = self._execution_plan(goal)
                if execution_plan is not None:
                    step_ids = {
                        str(step.get("id") or "")
                        for step in execution_plan.get("steps", [])
                        if isinstance(step, dict)
                    }
                    if "launch-goal-keeper" not in step_ids:
                        stored_plan = self._store_execution_plan(
                            goal,
                            self._structured_farm_controller_plan(
                                goal,
                                selected_plan=execution_plan,
                            ),
                            grounding=grounding,
                            revision=True,
                        )
                        return {"planned": True, "execution_plan": stored_plan}
                    structured_launch = {
                        **structured_launch,
                        "plan_step_id": "launch-goal-keeper",
                    }
                    return self._execute(goal, observation, structured_launch)
            if completion_checkpoint is not None:
                campaign_run, campaign_phase = self.campaign.ensure(goal)
                _campaign_selection = None
            else:
                campaign_run, campaign_phase, _campaign_selection = self._campaign_turn_state(
                    goal, observation, grounding
                )
            phase_completion_checkpoint = self._phase_completion_checkpoint(
                campaign_phase
            )
            phase_exhaustion_checkpoint = self._phase_exhaustion_checkpoint(
                campaign_phase
            )
            phase_abandonment_checkpoint = self._phase_abandonment_checkpoint(
                campaign_phase
            )
            phase_safe_return_checkpoint = (
                phase_completion_checkpoint
                if phase_completion_checkpoint is not None
                else (
                    phase_exhaustion_checkpoint
                    if phase_exhaustion_checkpoint is not None
                    else phase_abandonment_checkpoint
                )
            )
            page = self.storage.events(after_cursor=max(0, self.storage.get_runtime("planner_event_cursor", 0) - 12), limit=20)
            pending_proposals = self.storage.proposals()[:10]
            planner_feedback = self._planner_feedback(goal)
            grounded_context = self.knowledge.context_for(goal, redact(observation))
            grounded_context["safe_ending_candidates"] = self._safe_ending_context(
                observation
            )
            completion_checkpoint = self._goal_completion_checkpoint(goal)
            if completion_checkpoint is not None:
                grounded_context["goal_outcome_checkpoint"] = {
                    "verified": True,
                    "verified_at": completion_checkpoint.get("verified_at"),
                    "instruction": (
                        "The public goal outcome is latched. Stop/release any keeper and "
                        "execute only the verified plan's final safe-ending travel."
                    ),
                }
            if phase_completion_checkpoint is not None:
                grounded_context["phase_outcome_checkpoint"] = {
                    "verified": True,
                    "verified_at": phase_completion_checkpoint.get("verified_at"),
                    "phase_id": campaign_phase.get("id"),
                    "phase_kind": campaign_phase.get("kind"),
                    "instruction": (
                        "The active phase outcome is latched. Stop/release any keeper and "
                        "execute only the verified plan's final safe-ending travel."
                    ),
                }
            if phase_exhaustion_checkpoint is not None:
                grounded_context["phase_budget_exhaustion_checkpoint"] = {
                    "exhausted": True,
                    "exhausted_at": phase_exhaustion_checkpoint.get("exhausted_at"),
                    "phase_id": campaign_phase.get("id"),
                    "phase_kind": campaign_phase.get("kind"),
                    "budget": redact(phase_exhaustion_checkpoint.get("budget")),
                    "safe_ending": redact(
                        phase_exhaustion_checkpoint.get("safe_ending")
                    ),
                    "instruction": (
                        "The active phase budget is exhausted. Do not continue goal "
                        "work. Preserve survival control and execute only the exact "
                        "source-verified safe-ending travel before the controller "
                        "closes this phase."
                    ),
                }
            if phase_abandonment_checkpoint is not None:
                grounded_context["phase_abandonment_checkpoint"] = {
                    "abandoned": True,
                    "abandoned_at": phase_abandonment_checkpoint.get(
                        "abandoned_at"
                    ),
                    "phase_id": campaign_phase.get("id"),
                    "phase_kind": campaign_phase.get("kind"),
                    "reason": phase_abandonment_checkpoint.get("reason"),
                    "safe_ending": redact(
                        phase_abandonment_checkpoint.get("safe_ending")
                    ),
                    "instruction": (
                        "The active phase abandonment is verified. Do not continue "
                        "goal work. Preserve survival control and execute only the "
                        "exact source-verified safe-ending travel before the "
                        "controller closes this phase."
                    ),
                }
            grounded_context["live_overlevel_hostiles"] = self._live_overlevel_hostiles(
                observation
            )
            direct_capabilities = self._direct_phase_capabilities(
                campaign_phase,
                observation,
            )
            if direct_capabilities is not None:
                grounded_context["direct_phase_capabilities"] = direct_capabilities
            farm_intent = self._effective_farm_intent(goal)
            if farm_intent.get("assigned_room") is not None and farm_intent.get("hunt"):
                grounded_context["farm_safe_staging"] = self._farm_launch_origin(
                    goal, observation, farm_intent
                )
            if purchase_preflight is not None:
                grounded_context["purchase_preflight"] = redact(purchase_preflight)
            execution_plan = self._execution_plan(goal)
            if (
                phase_exhaustion_checkpoint is not None
                and isinstance(campaign_phase, dict)
            ):
                try:
                    execution_plan = self._ensure_phase_exhaustion_plan(
                        goal,
                        campaign_phase,
                        observation,
                        grounding=grounding,
                    )
                except ModelError as exc:
                    self._set_planner_feedback(
                        goal,
                        "The phase budget is exhausted and safety return is the only "
                        f"permitted work. Build one travel-only plan to a source-verified "
                        f"safe-ending room: {exc}",
                    )
                    planner_feedback = self._planner_feedback(goal)
            if (
                phase_abandonment_checkpoint is not None
                and isinstance(campaign_phase, dict)
            ):
                try:
                    execution_plan = self._ensure_phase_abandonment_plan(
                        goal,
                        campaign_phase,
                        observation,
                        grounding=grounding,
                    )
                except ModelError as exc:
                    self._set_planner_feedback(
                        goal,
                        "The phase abandonment is verified and safety return is the "
                        "only permitted work. Build one travel-only plan to a source-"
                        f"verified safe-ending room: {exc}",
                    )
                    planner_feedback = self._planner_feedback(goal)
            revision_authorization = self._plan_revision_authorization(
                goal, execution_plan, planner_feedback
            )
            structured_exhaustion_return = self._structured_phase_exhaustion_return_action(
                goal,
                campaign_phase,
                observation,
                execution_plan,
            )
            if structured_exhaustion_return is not None:
                return self._execute(goal, observation, structured_exhaustion_return)
            structured_abandonment_return = (
                self._structured_phase_abandonment_return_action(
                    campaign_phase,
                    observation,
                    execution_plan,
                )
            )
            if structured_abandonment_return is not None:
                return self._execute(
                    goal, observation, structured_abandonment_return
                )
            structured_raza_exit = (
                None
                if phase_safe_return_checkpoint is not None
                else self._structured_raza_exit_action(
                    goal,
                    campaign_phase,
                    observation,
                    execution_plan,
                )
            )
            if structured_raza_exit is not None:
                return self._execute(goal, observation, structured_raza_exit)
            structured_farm_route = (
                None
                if phase_safe_return_checkpoint is not None
                else self._structured_farm_route_action(
                    campaign_phase,
                    observation,
                    execution_plan,
                )
            )
            if structured_farm_route is not None:
                return self._execute(goal, observation, structured_farm_route)
            structured_research = (
                None
                if phase_safe_return_checkpoint is not None
                else self._structured_research_progression_action(
                    campaign_phase,
                    observation,
                    execution_plan,
                )
            )
            if structured_research is not None:
                return self._execute(goal, observation, structured_research)
            decision = self.model.plan(
                goal=goal,
                observation=redact(observation),
                tools=self._planner_tools(campaign_phase),
                persona=self.storage.persona(),
                recent_events=page["events"],
                pending_proposals=[
                    {
                        "id": proposal["id"],
                        "title": proposal["goal_draft"].get("title"),
                        "objective": proposal["goal_draft"].get("objective"),
                    }
                    for proposal in pending_proposals
                ],
                planner_feedback=planner_feedback,
                policy_summary=self.policy.summary(observation),
                financial_context=self._financial_context(observation),
                grounded_knowledge=grounded_context,
                learned_failures=self.learning.context_for(goal, redact(observation)),
                execution_plan=redact(execution_plan) if execution_plan else None,
                revision_authorization=revision_authorization,
                campaign_context=self._campaign_context(
                    campaign_run, campaign_phase, audience="tactical"
                ),
            )
            self.dependencies["model"] = "healthy"
            self.storage.set_runtime("planner_event_cursor", page["next_cursor"])
            if decision["decision"] == "plan":
                if execution_plan is not None:
                    raw_plan = decision.get("execution_plan")
                    supplied_authorization = (
                        str(raw_plan.get("revision_authorization_id") or "")
                        if isinstance(raw_plan, dict)
                        else ""
                    )
                    expected_authorization = str(
                        (revision_authorization or {}).get("id") or ""
                    )
                    if (
                        not expected_authorization
                        or supplied_authorization != expected_authorization
                    ):
                        return self._reject_plan_revision(
                            goal,
                            execution_plan=execution_plan,
                            decision=decision,
                            expected_authorization=revision_authorization,
                        )
                try:
                    stored_plan = self._store_execution_plan(
                        goal,
                        decision.get("execution_plan"),
                        grounding=grounding,
                        revision=execution_plan is not None,
                    )
                except ModelError as exc:
                    rejected_invariant = str(exc)[:1000]
                    if (
                        execution_plan is None
                        and isinstance(campaign_phase, dict)
                        and campaign_phase.get("kind") == "farm"
                        and "structured farm goal plan requires one explicit autopilot launch step"
                        in rejected_invariant
                        and isinstance(decision.get("execution_plan"), dict)
                    ):
                        try:
                            repaired_plan = self._store_execution_plan(
                                goal,
                                self._structured_farm_controller_plan(
                                    goal,
                                    selected_plan=decision["execution_plan"],
                                ),
                                grounding=grounding,
                                revision=False,
                            )
                        except ModelError as repair_exc:
                            # If another independent invariant is also broken,
                            # preserve the normal exact-feedback path below.
                            rejected_invariant = (
                                f"{rejected_invariant}; deterministic farm-plan repair also failed: "
                                f"{str(repair_exc)[:500]}"
                            )[:1000]
                        else:
                            self._clear_planner_feedback()
                            self.storage.emit_event(
                                "planner.plan.repaired",
                                "Inserted the controller-owned farm launch sequence into an incomplete plan",
                                severity="info",
                                interesting=False,
                                goal_id=goal["id"],
                                data={
                                    "phase_id": campaign_phase.get("id"),
                                    "repaired_invariant": rejected_invariant,
                                    "source": "structured_farm_controller_plan",
                                },
                            )
                            return {
                                "planned": True,
                                "plan_repaired": True,
                                "execution_plan": repaired_plan,
                            }
                    prior_failure_context = (
                        (planner_feedback or {}).get("failure_context")
                        if isinstance(planner_feedback, dict)
                        else None
                    )
                    same_invalid_invariant = (
                        execution_plan is None
                        and isinstance(prior_failure_context, dict)
                        and prior_failure_context.get("kind") == "invalid_execution_plan"
                        and prior_failure_context.get("invariant") == rejected_invariant
                    )
                    plan_rejections = int(
                        (planner_feedback or {}).get(
                            "consecutive_plan_rejections", 0
                        )
                        or 0
                    ) + 1
                    retained_steps = [
                        str(step.get("id") or "")
                        for step in execution_plan.get("steps", [])
                        if isinstance(step, dict) and step.get("tool")
                    ] if isinstance(execution_plan, dict) else []
                    if execution_plan is not None:
                        feedback_message = (
                            f"The optional plan revision failed deterministic verification: {exc}. "
                            "The existing execution plan remains verified; do not revise it again. "
                            "Return decision=act bound to one existing actionable step id: "
                            + ", ".join(retained_steps)
                            + "."
                        )
                    else:
                        feedback_message = (
                            f"The proposed execution plan failed deterministic verification: {exc}. "
                            "This rejection prevents a plan whose declared tool cannot produce its "
                            "outcome or whose required prerequisite is absent. Treat the stated "
                            "invariant as a hard corrective constraint, not as an obstacle to retry "
                            "under different wording. Return one materially corrected plan before "
                            "selecting a tool."
                        )
                    self._set_planner_feedback(
                        goal,
                        feedback_message,
                        consecutive_plan_rejections=plan_rejections,
                        failure_context=(
                            {
                                "kind": "rejected_optional_plan_revision",
                                "invariant": rejected_invariant,
                                "purpose": "Preserve the existing verified execution plan.",
                                "required_response": (
                                    "Act on an existing actionable step; do not submit another "
                                    "optional revision."
                                ),
                            }
                            if execution_plan is not None
                            else {
                                "kind": "invalid_execution_plan",
                                "invariant": rejected_invariant,
                                "purpose": (
                                    "Prevent execution of a plan whose tool semantics, ordering, "
                                    "or prerequisites cannot produce the declared outcome."
                                ),
                                "required_response": (
                                    "Change the tool, ordering, target, or prerequisite that "
                                    "violated the invariant; do not merely paraphrase the rejected plan."
                                ),
                            }
                        ),
                    )
                    self.storage.emit_event(
                        "planner.plan.rejected",
                        f"Rejected unverifiable execution plan: {str(exc)[:240]}",
                        severity="warning",
                        interesting=plan_rejections >= 3,
                        goal_id=goal["id"],
                        data={
                            "reason": rejected_invariant,
                            "plan": redact(decision.get("execution_plan")),
                            "consecutive_plan_rejections": plan_rejections,
                            "retained_verified_plan": execution_plan is not None,
                        },
                    )
                    if same_invalid_invariant and plan_rejections >= 2:
                        retired = self._fail_active_campaign_phase(
                            goal,
                            "campaign phase retired after the planner repeated the same "
                            f"deterministically invalid execution plan: {rejected_invariant}",
                        )
                        if retired is not None:
                            self._clear_planner_feedback()
                            self.storage.emit_event(
                                "campaign.phase.invalid_plan_retired",
                                "Retired an infeasible phase after two equivalent invalid plans",
                                severity="warning",
                                interesting=True,
                                goal_id=goal["id"],
                                data={
                                    "phase_id": retired.get("id"),
                                    "invariant": rejected_invariant,
                                    "strategic_goal_preserved": True,
                                },
                            )
                            return {
                                "plan_rejected": True,
                                "phase_retired": True,
                                "reason": rejected_invariant,
                                "strategic_goal_preserved": True,
                            }
                    return {"plan_rejected": True, "reason": str(exc)}
                self._clear_planner_feedback()
                return {"planned": True, "execution_plan": stored_plan}
            safe_return_checkpoint = (
                completion_checkpoint
                if completion_checkpoint is not None
                else phase_safe_return_checkpoint
            )
            if (
                safe_return_checkpoint is not None
                and decision["decision"] != "act"
            ):
                self._set_planner_feedback(
                    goal,
                    "The active goal or campaign phase is at a terminal safety "
                    "boundary. Select only the stored plan's final safe-ending "
                    "travel step.",
                )
                return {
                    "safe_ending_required": True,
                    "action_suppressed": True,
                }
            if decision["decision"] == "act" and execution_plan is None:
                self._set_planner_feedback(
                    goal,
                    "No verified execution plan exists for this goal. Return decision=plan "
                    f"with 1-{EXECUTION_PLAN_MAX_STEPS} grounded, verifiable steps before "
                    "selecting a tool.",
                )
                return {"plan_required": True, "action_suppressed": True}
            if decision["decision"] == "act":
                step_id = str(decision.get("plan_step_id") or "").strip()
                valid_step_ids = {
                    str(step.get("id") or "")
                    for step in execution_plan.get("steps", [])
                    if isinstance(step, dict)
                } if isinstance(execution_plan, dict) else set()
                if step_id not in valid_step_ids:
                    return self._reject_planner_action(
                        goal,
                        "The selected action was not bound to a valid execution_plan step. Return plan_step_id exactly matching one stored step, or revise the plan first.",
                        decision=decision,
                        execution_plan=execution_plan,
                        result={
                            "plan_step_required": True,
                            "valid_step_ids": sorted(valid_step_ids),
                        },
                    )
                selected_step = next(
                    step
                    for step in execution_plan.get("steps", [])
                    if isinstance(step, dict) and str(step.get("id") or "") == step_id
                )
                last_plan_action = execution_plan.get("last_action")
                if (
                    safe_return_checkpoint is None
                    and isinstance(last_plan_action, dict)
                    and last_plan_action.get("status") == "partial_progress"
                ):
                    required_step_id = str(last_plan_action.get("step_id") or "")
                    if step_id != required_step_id:
                        return self._reject_planner_action(
                            goal,
                            "The preceding travel call made verified partial progress but did "
                            "not reach its destination. Continue that same stored travel step "
                            f"{required_step_id!r}; do not advance to a later plan step.",
                            decision=decision,
                            execution_plan=execution_plan,
                            result={
                                "partial_travel_incomplete": True,
                                "required_plan_step_id": required_step_id,
                            },
                        )
                    prior_arguments = last_plan_action.get("arguments")
                    current_arguments = (
                        decision.get("arguments")
                        if isinstance(decision.get("arguments"), dict)
                        else {}
                    )
                    prior_destination = next(
                        (
                            prior_arguments.get(key)
                            for key in ("to", "destination", "room", "room_id")
                            if isinstance(prior_arguments, dict)
                            and prior_arguments.get(key) is not None
                        ),
                        None,
                    )
                    current_destination = next(
                        (
                            current_arguments.get(key)
                            for key in ("to", "destination", "room", "room_id")
                            if current_arguments.get(key) is not None
                        ),
                        None,
                    )
                    if str(current_destination) != str(prior_destination):
                        return self._reject_planner_action(
                            goal,
                            "The incomplete travel step must retain its original destination "
                            f"{prior_destination!r}; received {current_destination!r}.",
                            decision=decision,
                            execution_plan=execution_plan,
                            result={
                                "partial_travel_incomplete": True,
                                "required_destination": prior_destination,
                            },
                        )
                safe_step_id = str(
                    deep_get(execution_plan, "safe_ending.step_id", "")
                )
                if safe_return_checkpoint is not None and step_id != safe_step_id:
                    return self._reject_planner_action(
                        goal,
                        "The active goal or campaign phase is at a terminal safety boundary. "
                        f"Select only the final safe-ending step {safe_step_id!r}; "
                        "do not repeat completed or exhausted work.",
                        decision=decision,
                        execution_plan=execution_plan,
                        result={
                            "safe_ending_required": True,
                            "required_plan_step_id": safe_step_id,
                        },
                    )
                safe_step_is_goal_destination = any(
                    isinstance(criterion, dict)
                    and criterion.get("kind") == "location_reached"
                    and criterion.get("room_id") is not None
                    and str(criterion.get("room_id"))
                    == str(deep_get(execution_plan, "safe_ending.room_id"))
                    for criterion in goal.get("success_criteria", [])
                )
                safe_step_is_phase_destination = any(
                    isinstance(criterion, dict)
                    and criterion.get("kind") == "location_reached"
                    and criterion.get("room_id") is not None
                    and str(criterion.get("room_id"))
                    == str(deep_get(execution_plan, "safe_ending.room_id"))
                    for criterion in (
                        campaign_phase.get("success_criteria", [])
                        if isinstance(campaign_phase, dict)
                        else []
                    )
                )
                if (
                    safe_return_checkpoint is None
                    and step_id == safe_step_id
                    and not safe_step_is_goal_destination
                    and not safe_step_is_phase_destination
                ):
                    return self._reject_planner_action(
                        goal,
                        "The final safe-ending step is reserved for after the active phase "
                        "or public goal outcome is verified. Advance an earlier plan step first.",
                        decision=decision,
                        execution_plan=execution_plan,
                        result={"safe_ending_premature": True},
                    )
                if step_id == safe_step_id:
                    expected_room = deep_get(
                        execution_plan, "safe_ending.room_id"
                    )
                    arguments = (
                        decision.get("arguments")
                        if isinstance(decision.get("arguments"), dict)
                        else {}
                    )
                    requested_room = next(
                        (
                            arguments.get(key)
                            for key in ("to", "destination", "room", "room_id")
                            if arguments.get(key) is not None
                        ),
                        None,
                    )
                    if str(requested_room) != str(expected_room):
                        return self._reject_planner_action(
                            goal,
                            "The final safe-ending travel must target the exact verified "
                            f"room id {expected_room}; received {requested_room!r}.",
                            decision=decision,
                            execution_plan=execution_plan,
                            result={
                                "safe_ending_target_mismatch": True,
                                "expected_room_id": expected_room,
                                "selected_room_id": requested_room,
                            },
                        )
                selected_tool = selected_step.get("tool")
                if not selected_tool or selected_tool != decision.get("tool"):
                    return self._reject_planner_action(
                        goal,
                        "The selected action tool did not match the declared execution_plan step tool. Revise the plan or bind the action to the correct actionable step.",
                        decision=decision,
                        execution_plan=execution_plan,
                        result={
                            "plan_tool_mismatch": True,
                            "plan_step_id": step_id,
                            "expected_tool": selected_tool,
                            "selected_tool": decision.get("tool"),
                        },
                    )
                if selected_tool == "shop":
                    selected_arguments = (
                        decision.get("arguments")
                        if isinstance(decision.get("arguments"), dict)
                        else {}
                    )
                    quantified_shop_error = self._quantified_shop_action_error(
                        selected_step,
                        selected_arguments,
                    )
                    if quantified_shop_error is not None:
                        return self._reject_planner_action(
                            goal,
                            quantified_shop_error,
                            decision=decision,
                            execution_plan=execution_plan,
                            result={
                                "quantified_shop_basket_mismatch": True,
                                "plan_step_id": step_id,
                            },
                        )
            if decision["decision"] == "wait":
                learned_wait = self.learning.check_action("planner_wait", {}, observation)
                if learned_wait:
                    self._set_planner_feedback(
                        goal,
                        "Waiting is durably known not to advance this goal in the current state. Choose a concrete tool or a materially different supporting proposal now.",
                    )
                    self.storage.emit_event(
                        "action.lesson_suppressed",
                        "Suppressed a planner wait known not to advance the goal",
                        severity="warning",
                        interesting=True,
                        goal_id=goal["id"],
                        data={"tool": "planner_wait", "lesson": learned_wait["lesson"]},
                    )
                    failed_phase = self._fail_active_campaign_phase(
                        goal,
                        "planner wait is durably known not to advance this internal phase",
                    )
                    if failed_phase is not None:
                        return {
                            "retry_suppressed": True,
                            "campaign_phase_failed": failed_phase,
                            "strategic_goal_preserved": True,
                            "learning": learned_wait,
                        }
                    return {"retry_suppressed": True, "learning": learned_wait}
                rationale = str(decision.get("rationale", ""))[:500]
                waits = int((planner_feedback or {}).get("consecutive_waits", 0)) + 1
                self._set_planner_feedback(
                    goal,
                    (
                        f"The previous {waits} planning turn(s) waited without advancing the active goal. "
                        f"Last rationale: {rationale or 'none'}. Pending proposals are inert and must not block "
                        "the active goal. Choose one concrete available tool on the next turn unless a transient "
                        "in-game condition makes every legal action unsafe or impossible."
                    ),
                    consecutive_waits=waits,
                )
                if waits == 3:
                    self.storage.emit_event(
                        "planner.stalled",
                        "Planner waited for three consecutive turns without advancing the active goal",
                        severity="warning",
                        interesting=True,
                        goal_id=goal["id"],
                        data={"last_rationale": rationale},
                    )
                if waits >= self.config.learning.wait_budget:
                    failed_phase = self._fail_active_campaign_phase(
                        goal,
                        f"planner waited {waits} consecutive turns without verified progress",
                    )
                    if failed_phase is not None:
                        return {
                            "campaign_phase_failed": failed_phase,
                            "strategic_goal_preserved": True,
                            "consecutive_waits": waits,
                        }
                    deferred = self.learning.defer_goal(
                        goal,
                        observation,
                        tool="planner_wait",
                        reason=f"Planner waited {waits} consecutive turns without verified progress: {rationale or 'no rationale'}",
                        event_kind="planner.stalled",
                        classification="ineffective_tactic",
                        scope="tactic",
                    )
                    return {
                        "goal_blocked": bool(deferred.get("goal_blocked")),
                        "tactic_deferred": not bool(deferred.get("goal_blocked")),
                        "consecutive_waits": waits,
                        **deferred,
                    }
                return {"wait": True, "rationale": rationale, "consecutive_waits": waits}
            if decision["decision"] == "propose_goal":
                proposal = decision.get("proposal")
                if not isinstance(proposal, dict):
                    if pending_proposals:
                        self._set_planner_feedback(
                            goal,
                            "The prior propose_goal decision had no proposal object and changed nothing. A pending "
                            "proposal is inert and unrelated to execution. Advance the active goal with a concrete tool.",
                        )
                        return {
                            "wait": True,
                            "rationale": "Planner referred to a proposal while one is already pending.",
                            "suppressed": "proposal_already_pending",
                        }
                    raise ModelError("planner proposed a goal without a proposal object")
                try:
                    proposal_grounding = self.knowledge.require_valid_goal(proposal)
                    self.learning.require_goal_eligible(proposal_grounding["canonical_goal"], observation)
                    created = self.storage.create_proposal(
                        proposal_grounding["canonical_goal"],
                        str(decision.get("rationale", "Bot-proposed follow-up")),
                    )
                except GoalDeferredError as exc:
                    self._set_planner_feedback(
                        goal,
                        f"The proposed follow-up is deferred: {exc}. Do not paraphrase it; choose a supporting goal from the lesson or continue the active goal.",
                    )
                    return {"proposal_suppressed": True, "reason": str(exc), "learning": exc.result}
                except (TypeError, ValueError, KnowledgeValidationError) as exc:
                    self._set_planner_feedback(
                        goal,
                        f"The prior proposal was invalid and changed nothing: {exc}. Advance the active goal with a concrete tool.",
                    )
                    raise ModelError(f"planner proposed an invalid goal: {exc}") from exc
                self._set_planner_feedback(
                    goal,
                    "The optional future proposal was stored and is now inert pending supervisor review. Do not revisit "
                    "or wait on it; resume the active goal with a concrete tool.",
                )
                return {"proposal": created}
            return self._execute_planner_action(
                goal,
                observation,
                decision,
                execution_plan=execution_plan,
            )
        finally:
            self._turn_lock.release()

    @staticmethod
    def _execution_plan_fingerprint(execution_plan: dict[str, Any]) -> str:
        """Hash only the stable plan contract, not mutable action bookkeeping."""

        return json_hash(
            {
                key: execution_plan.get(key)
                for key in (
                    "schema_version",
                    "goal_id",
                    "goal_version",
                    "phase_id",
                    "summary",
                    "steps",
                    "safe_ending",
                    "assumptions",
                )
            }
        )

    def _plan_revision_authorization(
        self,
        goal: dict[str, Any],
        execution_plan: dict[str, Any] | None,
        planner_feedback: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Issue a one-plan token only after controller-owned fresh evidence."""

        if not isinstance(execution_plan, dict):
            return None
        source: dict[str, Any] | None = None
        last_action = execution_plan.get("last_action")
        if (
            isinstance(last_action, dict)
            and last_action.get("status") == "partial_progress"
        ):
            return None
        if isinstance(last_action, dict) and last_action.get("observed_at"):
            source = {
                "kind": "completed_plan_action",
                "step_id": last_action.get("step_id"),
                "tool": last_action.get("tool"),
                "arguments": last_action.get("arguments"),
                "observed_at": last_action.get("observed_at"),
                "result_summary": last_action.get("result_summary"),
            }
        elif isinstance(planner_feedback, dict):
            failure_context = planner_feedback.get("failure_context")
            failure_kind = (
                str(failure_context.get("kind") or "")
                if isinstance(failure_context, dict)
                else ""
            )
            if failure_kind and failure_kind not in {
                "invalid_planner_action",
                "unauthorized_plan_revision",
            }:
                source = {
                    "kind": "verified_failure_feedback",
                    "updated_at": planner_feedback.get("updated_at"),
                    "failure_context": failure_context,
                    "blocked_action": planner_feedback.get("blocked_action"),
                    "safety_suppression": planner_feedback.get(
                        "safety_suppression"
                    ),
                }
            elif isinstance(planner_feedback.get("blocked_action"), dict):
                source = {
                    "kind": "verified_blocked_action",
                    "updated_at": planner_feedback.get("updated_at"),
                    "blocked_action": planner_feedback.get("blocked_action"),
                    "safety_suppression": planner_feedback.get(
                        "safety_suppression"
                    ),
                }
        if source is None:
            return None
        fingerprint = self._execution_plan_fingerprint(execution_plan)
        authorization_id = json_hash(
            {
                "goal_id": goal.get("id"),
                "plan_fingerprint": fingerprint,
                "source": source,
            }
        )
        return {
            "id": authorization_id,
            "plan_fingerprint": fingerprint,
            "reason": (
                "Fresh controller-owned action or failure evidence permits one "
                "revision of this exact plan. Echo id as "
                "execution_plan.revision_authorization_id."
            ),
            "source": redact(source),
        }

    def _reject_plan_revision(
        self,
        goal: dict[str, Any],
        *,
        execution_plan: dict[str, Any],
        decision: dict[str, Any],
        expected_authorization: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Bound unsolicited plan churn while preserving actionable work."""

        fingerprint = self._execution_plan_fingerprint(execution_plan)
        prior = self._planner_feedback(goal)
        prior_context = (
            prior.get("failure_context") if isinstance(prior, dict) else None
        )
        same_plan = (
            isinstance(prior_context, dict)
            and prior_context.get("kind") == "unauthorized_plan_revision"
            and prior_context.get("plan_fingerprint") == fingerprint
        )
        consecutive = (
            int(prior.get("consecutive_plan_rejections", 0) or 0) + 1
            if same_plan and isinstance(prior, dict)
            else 1
        )
        invalidated = False
        if consecutive >= INVALID_PLAN_REVISION_LIMIT:
            invalidated = self._invalidate_execution_plan(
                goal,
                "planner attempted two consecutive revisions without fresh "
                "controller authorization",
            )
        step_ids = [
            str(step.get("id") or "")
            for step in execution_plan.get("steps", [])
            if isinstance(step, dict) and step.get("tool")
        ]
        if invalidated:
            message = (
                "The stored execution plan was invalidated after two unauthorized "
                "revision attempts. Return decision=plan with a corrected executable plan."
            )
        else:
            expected = (
                "No revision is currently authorized because no fresh controller-owned "
                "action or failure evidence invalidated the plan."
                if expected_authorization is None
                else "The revision did not echo the controller-issued authorization id."
            )
            message = (
                f"The optional plan revision failed deterministic verification: {expected} "
                "The existing execution plan remains verified; do not revise it again. "
                "Return decision=act bound to one existing actionable step id: "
                + ", ".join(step_ids)
                + "."
            )
        self._set_planner_feedback(
            goal,
            message,
            consecutive_plan_rejections=consecutive,
            failure_context={
                "kind": "unauthorized_plan_revision",
                "plan_fingerprint": fingerprint,
                "expected_authorization_id": (
                    expected_authorization.get("id")
                    if isinstance(expected_authorization, dict)
                    else None
                ),
                "supplied_authorization_id": deep_get(
                    decision, "execution_plan.revision_authorization_id"
                ),
            },
        )
        self.storage.emit_event(
            "planner.plan.revision_rejected",
            "Rejected execution-plan revision without fresh controller authorization",
            severity="warning",
            interesting=invalidated,
            goal_id=goal["id"],
            data={
                "plan_fingerprint": fingerprint,
                "consecutive_plan_rejections": consecutive,
                "plan_invalidated": invalidated,
                "expected_authorization": redact(expected_authorization),
                "proposal": redact(decision.get("execution_plan")),
            },
        )
        return {
            "plan_rejected": True,
            "action_suppressed": True,
            "reason": message,
            "consecutive_plan_rejections": consecutive,
            "plan_invalidated": invalidated,
        }

    def _reject_planner_action(
        self,
        goal: dict[str, Any],
        reason: str,
        *,
        decision: dict[str, Any],
        execution_plan: dict[str, Any] | None,
        result: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Return a malformed model action to the planner without degrading it."""

        fingerprint = (
            self._execution_plan_fingerprint(execution_plan)
            if isinstance(execution_plan, dict)
            else "no-execution-plan"
        )
        prior = self._planner_feedback(goal)
        prior_context = (
            prior.get("failure_context") if isinstance(prior, dict) else None
        )
        same_plan_rejection = (
            isinstance(prior_context, dict)
            and prior_context.get("kind") == "invalid_planner_action"
            and prior_context.get("plan_fingerprint") == fingerprint
        )
        consecutive = (
            int(prior.get("consecutive_invalid_actions", 0) or 0) + 1
            if same_plan_rejection and isinstance(prior, dict)
            else 1
        )
        invalidated = False
        if (
            isinstance(execution_plan, dict)
            and consecutive >= INVALID_PLANNER_ACTION_LIMIT
        ):
            invalidated = self._invalidate_execution_plan(
                goal,
                f"planner returned {consecutive} consecutive invalid actions against the same plan: {reason}",
            )
        guidance = (
            f"The selected action was rejected before execution: {reason} "
            + (
                "The stored execution plan was invalidated after two consecutive invalid "
                "decisions. Return decision=plan with a corrected executable plan."
                if invalidated
                else "The stored execution plan remains available. Return one schema-valid "
                "action bound to it; another invalid decision will force replanning."
            )
        )
        self._set_planner_feedback(
            goal,
            guidance,
            consecutive_invalid_actions=consecutive,
            failure_context={
                "kind": "invalid_planner_action",
                "plan_fingerprint": fingerprint,
                "plan_step_id": decision.get("plan_step_id"),
                "reason": reason[:500],
                "purpose": (
                    "Prevent a structurally invalid or unsafe tool call before it can "
                    "mutate game state. The reason names the invariant to satisfy."
                ),
                "required_response": (
                    "Correct the rejected arguments or prerequisite; do not repeat the "
                    "same action under different wording."
                ),
            },
        )
        self.storage.emit_event(
            "planner.action.rejected",
            f"Rejected invalid planner action: {reason[:240]}",
            severity="warning",
            interesting=invalidated,
            goal_id=goal["id"],
            data={
                "reason": reason[:1000],
                "decision": redact(decision),
                "plan_fingerprint": fingerprint,
                "consecutive_invalid_actions": consecutive,
                "plan_invalidated": invalidated,
            },
        )
        return {
            **(result or {}),
            "planner_action_rejected": True,
            "action_suppressed": True,
            "reason": reason,
            "consecutive_invalid_actions": consecutive,
            "plan_invalidated": invalidated,
        }

    def _execute_planner_action(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        decision: dict[str, Any],
        *,
        execution_plan: dict[str, Any] | None,
    ) -> dict[str, Any]:
        try:
            return self._execute(goal, observation, decision)
        except ModelError as exc:
            return self._reject_planner_action(
                goal,
                str(exc),
                decision=decision,
                execution_plan=execution_plan,
            )

    def _broker_action_timeout(self, tool: str) -> float:
        """Keep LLM responsiveness independent from legitimate game action time."""
        minimums = {
            # Cross-world travel advances through multiple rooms and can take
            # several minutes while remaining healthy and productive.
            "travel": 600.0,
            "rest_up": 300.0,
            "escape_underworld": 240.0,
            "leave_raza": 240.0,
            "go_through": 120.0,
            "walk_to": 120.0,
        }
        return max(
            float(self.config.model.planner_timeout_seconds),
            minimums.get(tool, 0.0),
        )

    def _sell_quote_signature(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any] | None,
        arguments: dict[str, Any],
        observation: dict[str, Any],
    ) -> str:
        semantic_arguments = {
            key: value
            for key, value in arguments.items()
            if key not in {"agent", "confirm"}
        }
        return canonical_json(
            {
                "goal_id": goal.get("id"),
                "phase_id": (phase or {}).get("id"),
                "room": self._observation_room(observation),
                "arguments": semantic_arguments,
            }
        )

    @staticmethod
    def _selected_sale_inventory(
        arguments: dict[str, Any], observation: dict[str, Any]
    ) -> list[dict[str, Any]]:
        """Resolve a sell request to exact current inventory evidence."""

        raw_selected = arguments.get("items")
        selected = raw_selected if isinstance(raw_selected, list) else [raw_selected]
        selected_ids: set[str] = set()
        selected_names: set[str] = set()
        requested_amounts: dict[str, int] = {}
        for value in selected:
            if isinstance(value, dict):
                item_id = value.get("id", value.get("object_id"))
                name = value.get("name")
                if item_id is not None and str(item_id).strip():
                    item_id_key = str(item_id).strip().casefold()
                    selected_ids.add(item_id_key)
                    amount = value.get("amount")
                    if (
                        isinstance(amount, (int, float))
                        and not isinstance(amount, bool)
                        and amount > 0
                    ):
                        requested_amounts[item_id_key] = int(amount)
                if name is not None and str(name).strip():
                    selected_names.add(str(name).strip().casefold())
            elif value is not None and str(value).strip():
                clean = str(value).strip().casefold()
                selected_ids.add(clean)
                selected_names.add(clean)

        inventory = deep_get(observation, "inventory.items", [])
        resolved: list[dict[str, Any]] = []
        for item in inventory if isinstance(inventory, list) else []:
            if not isinstance(item, dict):
                continue
            item_id = item.get("id", item.get("object_id"))
            item_id_key = (
                str(item_id).strip().casefold() if item_id is not None else ""
            )
            name = " ".join(str(item.get("name") or "").split())
            if not (
                (item_id_key and item_id_key in selected_ids)
                or name.casefold() in selected_names
            ):
                continue
            raw_quantity = item.get(
                "amount", item.get("quantity", item.get("count", 1))
            )
            quantity = (
                int(raw_quantity)
                if isinstance(raw_quantity, (int, float))
                and not isinstance(raw_quantity, bool)
                and raw_quantity > 0
                else 1
            )
            offered_quantity = requested_amounts.get(item_id_key, quantity)
            resolved.append(
                {
                    "id": item_id,
                    "name": name,
                    "quantity": offered_quantity,
                    "inventory_quantity": quantity,
                }
            )
        return resolved

    def _guard_prepare_combat_sale(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any] | None,
        tool: str,
        arguments: dict[str, Any],
        observation: dict[str, Any],
    ) -> None:
        phase_kind = str((phase or {}).get("kind") or "")
        if phase_kind not in {"prepare_combat", "liquidate_inventory"}:
            return
        keep_candidates = self._phase_keep_candidates(phase)
        if tool == "sell_all":
            if arguments.get("ignore_loadout") is True:
                raise ModelError(
                    f"{phase_kind} rejected sell_all with ignore_loadout=true. Purpose: "
                    "preserve goal-relevant equipment and the character loadout while raising "
                    "funds; omit ignore_loadout or set it false"
                )
            if arguments.get("max_weapons") is not None:
                raise ModelError(
                    f"{phase_kind} rejected sell_all with a weapon cap. Purpose: preserve all "
                    "candidate weapons until combat setup has selected a working one; omit "
                    "max_weapons"
                )
            arguments["ignore_loadout"] = False
            if keep_candidates:
                requested_keep = arguments.get("keep")
                requested = (
                    [str(value) for value in requested_keep]
                    if isinstance(requested_keep, list)
                    else []
                )
                arguments["keep"] = sorted(
                    {value for value in [*requested, *keep_candidates] if value},
                    key=str.casefold,
                )
            return
        if tool != "sell":
            return
        intrinsic_block = self._intrinsic_sale_block(
            goal, arguments, observation
        )
        if intrinsic_block is not None:
            blocked_ids = sorted(self._sale_item_ids(arguments))
            raise ModelError(
                f"{phase_kind} rejected targeted sale of item id(s) "
                f"{', '.join(blocked_ids)} because the server already verified that "
                "the exact instance cannot be given to any NPC. Purpose: treat the "
                "item restriction as intrinsic rather than cycling through merchants; "
                "choose a different exact inventory item or a non-sale funding route"
            )
        raw_selected = arguments.get("items")
        selected = raw_selected if isinstance(raw_selected, list) else [raw_selected]
        selected_keys = {
            str(value).strip().casefold()
            for value in selected
            if value is not None and str(value).strip()
        }
        inventory = deep_get(observation, "inventory.items", [])
        inventory = inventory if isinstance(inventory, list) else []
        equipped = deep_get(observation, "equipment.equipped", [])
        equipped = equipped if isinstance(equipped, list) else []
        equipped_ids = {
            str(item.get(key)).strip().casefold()
            for item in equipped
            if isinstance(item, dict)
            for key in ("id", "object_id")
            if item.get(key) is not None
        }
        equipped_ids.update(
            str(item.get(key)).strip().casefold()
            for item in inventory
            if isinstance(item, dict)
            and (item.get("in_use") is True or item.get("equipped") is True)
            for key in ("id", "object_id")
            if item.get(key) is not None
        )
        selected_inventory = []
        for item in inventory:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name") or "").strip().casefold()
            identifiers = {
                str(item.get(key)).strip().casefold()
                for key in ("id", "object_id")
                if item.get(key) is not None
            }
            if selected_keys & identifiers or name in selected_keys:
                selected_inventory.append((item, name, identifiers))
        selected_equipped = [
            (item, name, identifiers)
            for item, name, identifiers in selected_inventory
            if identifiers & equipped_ids
            or item.get("in_use") is True
            or item.get("equipped") is True
        ]
        if selected_equipped:
            protected_names = {name for _, name, _ in selected_equipped if name}
            protected_ids = sorted(
                {
                    identifier
                    for _, _, identifiers in selected_equipped
                    for identifier in identifiers
                }
            )
            alternatives = sorted(
                {
                    str(item.get(key)).strip()
                    for item in inventory
                    if isinstance(item, dict)
                    and str(item.get("name") or "").strip().casefold()
                    in protected_names
                    and item.get("in_use") is not True
                    and item.get("equipped") is not True
                    for key in ("id", "object_id")
                    if item.get(key) is not None
                    and str(item.get(key)).strip().casefold() not in equipped_ids
                }
            )
            alternative_guidance = (
                " Use exact unequipped duplicate item id(s) "
                + ", ".join(alternatives)
                + " instead."
                if alternatives
                else " No verified unequipped duplicate is available; choose different ordinary loot."
            )
            raise ModelError(
                f"{phase_kind} rejected targeted sale of equipped item id(s) "
                f"{', '.join(protected_ids) or ', '.join(sorted(protected_names))}. "
                "Purpose: preserve the active combat loadout and avoid attempting to "
                "transfer gear that the character is currently using."
                + alternative_guidance
            )
        if keep_candidates:
            protected: set[str] = set()
            for item in inventory:
                if not isinstance(item, dict):
                    continue
                name = str(item.get("name") or "").strip().casefold()
                identifiers = {
                    str(item.get(key)).strip().casefold()
                    for key in ("id", "object_id")
                    if item.get(key) is not None
                }
                if not (selected_keys & identifiers or name in selected_keys):
                    continue
                if any(candidate in name for candidate in keep_candidates):
                    protected.add(name or next(iter(identifiers), "retained item"))
            protected.update(
                selected
                for selected in selected_keys
                if any(candidate in selected for candidate in keep_candidates)
            )
            if protected:
                raise ModelError(
                    f"{phase_kind} rejected targeted sale of retained keep_candidate(s): "
                    f"{', '.join(sorted(protected))}. Purpose: preserve the phase's explicitly "
                    "retained equipment and valuables; choose only ordinary excess loot"
                )
        if arguments.get("confirm") is False:
            return
        signature = self._sell_quote_signature(
            goal,
            phase,
            arguments,
            observation,
        )
        quotes = self.storage.get_runtime("prepare_combat_sell_quotes_v1", [])
        verified = any(
            isinstance(item, dict)
            and item.get("signature") == signature
            and isinstance(item.get("offered_price"), (int, float))
            and item.get("offered_price") > 0
            for item in (quotes if isinstance(quotes, list) else [])
        )
        if not verified:
            raise ModelError(
                f"{phase_kind} rejected an unquoted targeted sale. Purpose: confirm that this "
                "exact merchant accepts these exact inventory items before transferring them; "
                "call sell once with the same to/items and confirm=false, then confirm the sale "
                "only if the returned offered_price is acceptable"
            )

    @staticmethod
    def _guard_map_semantics(
        phase: dict[str, Any] | None,
        tool: str,
        arguments: dict[str, Any],
    ) -> None:
        if tool != "map" or not isinstance(arguments.get("search"), str):
            return
        context = (
            phase.get("context")
            if isinstance(phase, dict) and isinstance(phase.get("context"), dict)
            else {}
        )
        target = str(context.get("target") or "").strip().casefold()
        search = str(arguments.get("search") or "").strip().casefold()
        if not target or not search:
            return
        if target not in search and search not in target:
            return
        raise ModelError(
            f"map rejected creature search {search!r} for phase target {target!r}. "
            "Purpose: map.search only matches room names and its substring results "
            "cannot establish creature occupancy; call hunting_grounds with creature="
            f"{target!r}, then map the returned numeric room id for route evidence"
        )

    def _record_prepare_combat_sell_quote(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any] | None,
        arguments: dict[str, Any],
        observation: dict[str, Any],
        result: Any,
    ) -> None:
        if (
            str((phase or {}).get("kind") or "")
            not in {"prepare_combat", "liquidate_inventory"}
            or arguments.get("confirm") is not False
            or not isinstance(result, dict)
            or not isinstance(result.get("offered_price"), (int, float))
            or result.get("offered_price") <= 0
        ):
            return
        signature = self._sell_quote_signature(
            goal,
            phase,
            arguments,
            observation,
        )
        quotes = self.storage.get_runtime("prepare_combat_sell_quotes_v1", [])
        values = [
            item
            for item in (quotes if isinstance(quotes, list) else [])
            if isinstance(item, dict) and item.get("signature") != signature
        ]
        values.append(
            {
                "signature": signature,
                "offered_price": result.get("offered_price"),
                "quoted_at": timestamp(),
                "goal_id": goal.get("id"),
                "phase_id": (phase or {}).get("id"),
                "merchant_id": arguments.get("to", arguments.get("merchant")),
                "room_id": self._observation_room(observation),
                "items": self._selected_sale_inventory(arguments, observation),
            }
        )
        self.storage.set_runtime("prepare_combat_sell_quotes_v1", values[-30:])

    def _phase_action_failure_context(
        self,
        goal: dict[str, Any],
        phase: dict[str, Any] | None,
        observation: dict[str, Any],
        plan: dict[str, Any],
        tool: str,
        arguments: dict[str, Any],
        *,
        safety_recovery: bool = False,
    ) -> dict[str, Any]:
        """Describe exactly which action failed and whether it was phase work."""

        execution_plan = self._execution_plan(goal)
        safe_ending = (
            execution_plan.get("safe_ending")
            if isinstance(execution_plan, dict)
            and isinstance(execution_plan.get("safe_ending"), dict)
            else {}
        )
        plan_step_id = str(plan.get("plan_step_id") or "").strip() or None
        safe_step_id = str(safe_ending.get("step_id") or "").strip()
        terminal_checkpoint = bool(
            isinstance(phase, dict)
            and (
                self._phase_completion_checkpoint(phase) is not None
                or self._phase_exhaustion_checkpoint(phase) is not None
            )
        )
        safe_return = bool(
            safety_recovery
            or (tool == "travel" and terminal_checkpoint)
            or (
                tool == "travel"
                and plan_step_id is not None
                and safe_step_id
                and plan_step_id == safe_step_id
            )
        )
        destination = next(
            (
                arguments.get(key)
                for key in ("to", "destination", "room", "room_id")
                if arguments.get(key) is not None
            ),
            None,
        )
        origin_room = {
            "id": self._observation_room(observation),
            "name": self._observation_room_name(observation) or None,
        }
        return {
            "stage": "safe_return" if safe_return else "phase_work",
            "tool": tool,
            "arguments": redact(arguments),
            "plan_step_id": plan_step_id,
            "phase_kind": phase.get("kind") if isinstance(phase, dict) else None,
            "origin_room": {
                key: value for key, value in origin_room.items() if value is not None
            },
            "destination_room": destination,
            "phase_work_implicated": not safe_return,
        }

    def _execute(self, goal: dict[str, Any], observation: dict[str, Any], plan: dict[str, Any]) -> dict[str, Any]:
        tool = str(plan.get("tool") or "")
        safety_recovery = plan.get("safety_recovery") is True
        arguments = plan.get("arguments")
        if not isinstance(arguments, dict):
            raise ModelError("planner arguments must be an object")
        if tool in CONTROLLER_ONLY_TOOLS:
            raise ModelError(f"planner cannot call controller-owned tool {tool}")
        arguments = dict(arguments)
        # Agent ids are controller-owned routing metadata. The planner never
        # chooses them, even if an older model context emits one.
        arguments.pop("agent", None)
        campaign_run = self.storage.campaign_run(goal["id"])
        campaign_phase = (
            self.storage.active_campaign_phase(campaign_run["id"])
            if campaign_run
            else None
        )
        if safety_recovery:
            checkpoint = self._phase_exhaustion_checkpoint(campaign_phase)
            destination = (
                checkpoint.get("safe_ending")
                if isinstance(checkpoint, dict)
                and isinstance(checkpoint.get("safe_ending"), dict)
                else None
            )
            requested_room = next(
                (
                    arguments.get(key)
                    for key in ("to", "destination", "room", "room_id")
                    if arguments.get(key) is not None
                ),
                None,
            )
            if (
                checkpoint is None
                or not isinstance(destination, dict)
                or tool != "travel"
                or str(requested_room) != str(destination.get("room_id"))
                or self._verified_safe_staging(requested_room) is None
            ):
                raise ModelError(
                    "safety_recovery is reserved for an exhausted phase's exact "
                    "source-verified sanctuary travel"
                )
        self._guard_map_semantics(campaign_phase, tool, arguments)
        if (
            tool == "fight"
            and isinstance(campaign_phase, dict)
            and campaign_phase.get("kind") == "train_ability"
        ):
            intent = self._campaign_phase_farm_intent(campaign_phase)
            recipe = (
                f"{intent.get('hunt')} in room {intent.get('assigned_room')}"
                if intent.get("hunt") and intent.get("assigned_room") is not None
                else "a grounded prey and assigned room"
            )
            raise ModelError(
                "foreground fight is unsafe for combat training because it performs only "
                "one swing and model latency leaves the character exposed; launch the "
                f"bounded farm keeper for {recipe} instead"
            )
        self._guard_prepare_combat_sale(
            goal,
            campaign_phase,
            tool,
            arguments,
            observation,
        )
        direct_pvp = self._direct_pvp_contract(goal)
        if direct_pvp is not None:
            if tool == PVP_SEEK_TOOL_NAME:
                raise ModelError(
                    "active goal requires pvp_engage only against the fresh local target; "
                    "pvp_seek cannot broaden it into a patrol"
                )
            if tool == PVP_TOOL_NAME and str(arguments.get("target") or "").strip().casefold() != str(
                direct_pvp["target"]
            ).strip().casefold():
                raise ModelError(
                    f"active goal permits pvp_engage only against exact target {direct_pvp['target']}"
                )
        bank_changes: dict[str, Any] = {}
        if tool == "bank" and str(arguments.get("action") or "").casefold() == "deposit":
            carried = self._carried_currency(observation)
            if carried <= 0:
                return self._complete_already_satisfied_bank_deposit(
                    goal, observation, plan, arguments
                )
            requested = arguments.get("amount")
            normalized_amount = (
                min(int(requested), carried)
                if isinstance(requested, (int, float))
                and not isinstance(requested, bool)
                and requested > 0
                else carried
            )
            if requested != normalized_amount:
                bank_changes["amount"] = {
                    "requested": requested,
                    "applied": normalized_amount,
                    "verified_carried_currency": carried,
                }
                arguments["amount"] = normalized_amount
        if tool == PVP_SEEK_TOOL_NAME:
            # Daily phases should involve different opponents.  Durable phase
            # evidence, rather than the model's memory, owns this exclusion.
            completed_targets = [
                str(item.get("target") or "").strip()
                for item in self._pvp_today_summary().get("recent", [])
                if str(item.get("target") or "").strip()
            ]
            requested_exclusions = arguments.get("exclude_targets", [])
            requested_exclusions = requested_exclusions if isinstance(requested_exclusions, list) else []
            exclusions = list(
                dict.fromkeys(
                    str(item).strip()
                    for item in [*requested_exclusions, *completed_targets]
                    if str(item).strip()
                )
            )
            if exclusions:
                arguments["exclude_targets"] = exclusions
                target = str(arguments.get("target") or "").strip()
                if target and target.casefold() in {item.casefold() for item in exclusions}:
                    # Continue the bounded goal by seeking somebody else rather
                    # than feeding a known-completed opponent back to the model.
                    arguments.pop("target", None)
        farm_intent: dict[str, Any] = {}
        if (
            tool == "autopilot"
            and arguments.get("action") == "start"
            and arguments.get("mode") == "farm"
        ):
            farm_intent = self._effective_farm_intent(goal)
            # Farm identity and deliberate strategy belong to the durable goal,
            # not to one fallible planner response.  Safety normalization below
            # still raises weak numeric thresholds.
            for field, value in farm_intent.items():
                if value is not None:
                    arguments[field] = value
        try:
            arguments, safety_changes = self._normalize_combat_arguments(
                tool,
                arguments,
                observation,
                allow_open_field=farm_intent.get("use_safe_spots") is False,
            )
        except (TypeError, ValueError) as exc:
            raise ModelError(f"planner supplied invalid {tool} safety arguments: {exc}") from exc
        safety_changes = {**bank_changes, **safety_changes}
        capabilities = self._available_tools()
        tool_spec = capabilities.get(tool)
        if tool_spec is None:
            raise ModelError(f"planner selected unknown broker tool {tool}")
        if tool_spec.accepts("agent"):
            arguments["agent"] = self.config.game.agent
        if (
            tool == "cast"
            and str(arguments.get("spell") or "").strip().casefold()
            in {"create food", "create weapon"}
            and tool_spec.accepts("observe_created")
        ):
            # Creation spells can succeed silently. Ask the broker to establish a
            # before/after inventory delta so plan-step completion never rests
            # on the first potentially stale inventory read after the cast.
            arguments["observe_created"] = True
        try:
            tool_spec.validate(arguments)
            if tool == PVP_TOOL_NAME:
                self.pvp.validate(arguments)
            elif tool == PVP_SEEK_TOOL_NAME:
                self.pvp.validate_seek(arguments)
        except ValueError as exc:
            raise ModelError(f"planner supplied invalid {tool} arguments: {exc}") from exc
        # Reaching this point proves that the decision is structurally valid.
        # Any earlier invalid-action streak is no longer consecutive, even if
        # policy or live game state subsequently suppresses the action.
        feedback = self._planner_feedback(goal)
        if deep_get(feedback or {}, "failure_context.kind") == "invalid_planner_action":
            self._clear_planner_feedback()
        if self._is_combat_start(tool, arguments):
            # Model inference can take long enough for an adjacent creature to
            # change the character's health after the turn's initial snapshot.
            # Never authorize a hazardous start from that stale observation.
            observation = self.broker.observe()
            self.last_observation = observation
            self._remember_safe_staging(observation)
            self.storage.record_snapshot(redact(observation))
            if direct_pvp is not None and tool == PVP_TOOL_NAME:
                expired = self._expire_direct_pvp_opportunity(
                    goal,
                    observation,
                    self.criteria.evaluate(goal, observation),
                )
                if expired is not None:
                    return {
                        "action": tool,
                        "action_suppressed": True,
                        **expired,
                    }
        # The exhausted budget must remain a hard ceiling. Sanctuary travel is
        # still recorded by the ordinary action-attempt audit, but it is safety
        # hygiene rather than another attempt to advance the exhausted phase.
        phase_attempt_id, repeated_signature = self.campaign.prepare_attempt(
            None if safety_recovery else campaign_phase,
            tool=tool,
            arguments=arguments,
            observation=observation,
            expected_effect=plan.get("expected_observation"),
        )
        phase_failure_context = self._phase_action_failure_context(
            goal,
            campaign_phase,
            observation,
            plan,
            tool,
            arguments,
            safety_recovery=safety_recovery,
        )
        if repeated_signature:
            breaker = self.campaign.trip_breaker(
                goal,
                campaign_phase,
                signature=repeated_signature,
                semantic_action=tool,
                failure_count=self.campaign.ACTION_FAILURE_LIMIT,
                reason="equivalent action already failed twice in the same verified state",
                failure_context=phase_failure_context,
            )
            self._invalidate_execution_plan(
                goal, "campaign circuit breaker rejected an equivalent failed action"
            )
            self._clear_safety_suppression(goal["id"])
            return {
                "action": tool,
                "action_suppressed": True,
                "campaign_breaker": breaker,
                "strategic_goal_preserved": True,
            }

        def finish_phase_attempt(
            status: str,
            *,
            action_attempt_id: str | None = None,
            result: Any = None,
            verification: Any = None,
            reason: str = "",
        ) -> dict[str, Any]:
            return self.campaign.finish_attempt(
                goal,
                campaign_run,
                campaign_phase,
                phase_attempt_id,
                status=status,
                action_attempt_id=action_attempt_id,
                result=result,
                verification=verification,
                reason=reason,
                failure_context=phase_failure_context,
            )

        preflight = self._safety_preflight(tool, arguments, observation, goal)
        preflight.extend(
            self._purchase_action_blockers(goal, observation, tool, arguments)
        )
        if preflight:
            phase_result = finish_phase_attempt(
                "suppressed",
                result={"blockers": preflight},
                verification={"allowed": False},
                reason="; ".join(
                    str(item.get("guidance") or item.get("kind")) for item in preflight
                ),
            )
            suppression = self._record_safety_suppression(
                goal, observation, tool, arguments, preflight
            )
            self._set_planner_feedback(
                goal,
                "The action was held for a deterministic safety preflight. Resolve these conditions before retrying: "
                + "; ".join(str(item.get("guidance") or item.get("kind")) for item in preflight),
                blocked_action={"tool": tool, "arguments": redact(arguments), "room": self._observation_room(observation)},
                safety_suppression=suppression,
            )
            count = int(suppression["same_blocker_count"])
            event_data = {
                "tool": tool,
                "arguments": redact(arguments),
                "blockers": preflight,
                **suppression,
            }
            # Preserve the first occurrence and escalation thresholds without
            # writing hundreds of identical deterministic warnings to SQLite.
            if count in {1, 3, self.config.learning.wait_budget}:
                self.storage.emit_event(
                    "action.safety_suppressed",
                    f"Held {tool} until its safety preflight is satisfied",
                    severity="warning",
                    interesting=False,
                    goal_id=goal["id"],
                    data=event_data,
                )
            if count == 3:
                self.storage.emit_event(
                    "planner.stalled",
                    f"Planner repeated the same blocked {tool} action three times",
                    severity="warning",
                    interesting=True,
                    goal_id=goal["id"],
                    data=event_data,
                )
            if phase_result.get("breaker_tripped"):
                self._invalidate_execution_plan(
                    goal, "campaign breaker ended a repeatedly safety-blocked phase"
                )
                self._clear_safety_suppression(goal["id"])
                return {
                    "action": tool,
                    "safety_suppressed": True,
                    "blockers": preflight,
                    "campaign_breaker": phase_result,
                    "strategic_goal_preserved": True,
                }
            if count >= self.config.learning.wait_budget:
                stall_reason = (
                    "Repeated deterministic safety suppression exhausted the controller wait budget: "
                    + "; ".join(
                        str(item.get("guidance") or item.get("kind"))
                        for item in preflight
                    )
                )
                deferred = self.learning.defer_goal(
                    goal,
                    observation,
                    tool=tool,
                    arguments=arguments,
                    reason=stall_reason,
                    event_kind="action.safety_suppressed",
                    classification="ineffective_tactic",
                    scope="tactic",
                    block=False,
                )
                failed_phase = self._fail_active_campaign_phase(goal, stall_reason)
                if failed_phase is None:
                    self._invalidate_execution_plan(
                        goal, "retired a repeatedly safety-blocked tactic"
                    )
                self._clear_safety_suppression(goal["id"])
                return {
                    **deferred,
                    "action": tool,
                    "safety_suppressed": True,
                    "tactic_deferred": True,
                    "phase_retired": failed_phase is not None,
                    "phase": failed_phase,
                    "goal": self.storage.goal(goal["id"]),
                    "blockers": preflight,
                    "suppression": suppression,
                    "strategic_goal_preserved": True,
                }
            return {
                "action": tool,
                "safety_suppressed": True,
                "blockers": preflight,
                "suppression": suppression,
            }
        self._clear_safety_suppression(goal["id"])
        if safety_changes:
            self.storage.emit_event(
                "action.safety_normalized",
                f"Applied controller combat safety defaults to {tool}",
                severity="info",
                interesting=False,
                goal_id=goal["id"],
                data={"tool": tool, "changes": safety_changes},
            )
        learned_block = self.learning.check_action(tool, arguments, observation)
        if learned_block:
            lesson = learned_block["lesson"]
            failure_reason = str(lesson.get("summary") or "")
            recorded_block = self._blocked_action(goal, observation, tool, arguments)
            if recorded_block and is_inventory_capacity_refusal(recorded_block.get("reason")):
                failure_reason = str(recorded_block.get("reason") or failure_reason)
            capacity_refusal = tool in {"shop", "cast"} and is_inventory_capacity_refusal(
                failure_reason
            )
            invalidates_plan = self._failure_invalidates_plan(tool, failure_reason)
            runtime_key = f"lesson_suppression:{goal['id']}:{lesson['id']}"
            suppressed_count = int(self.storage.get_runtime(runtime_key, 0) or 0) + 1
            self.storage.set_runtime(runtime_key, suppressed_count)
            if invalidates_plan:
                self._invalidate_execution_plan(goal, failure_reason)
            phase_result = finish_phase_attempt(
                "suppressed",
                result={"lesson": lesson},
                verification={"durably_deferred": True},
                reason=failure_reason or "tactic is durably deferred",
            )
            self._set_planner_feedback(
                goal,
                (
                    self._no_progress_guidance(
                        tool,
                        failure_reason,
                        repeated=True,
                        observation=observation,
                    )
                    if invalidates_plan
                    else f"This exact tactic is durably deferred: {lesson.get('summary')}. Choose different arguments or a different tool; do not repeat it until its retry condition is met."
                ),
                blocked_action={"tool": tool, "arguments": redact(arguments), "room": self._observation_room(observation)},
                failure_context=self._failure_context(tool, failure_reason, observation),
            )
            self.storage.emit_event(
                "action.lesson_suppressed",
                f"Suppressed a tactic known not to work in the current state: {tool}",
                severity="warning",
                interesting=suppressed_count >= self.config.learning.repeated_tactic_budget,
                goal_id=goal["id"],
                data={"tool": tool, "arguments": redact(arguments), "lesson": lesson, "suppressed_count": suppressed_count},
            )
            if phase_result.get("breaker_tripped"):
                self._invalidate_execution_plan(
                    goal, "campaign breaker ended a phase repeating a deferred tactic"
                )
                return {
                    "action": tool,
                    "retry_suppressed": True,
                    "campaign_breaker": phase_result,
                    "strategic_goal_preserved": True,
                }
            return {"action": tool, "retry_suppressed": True, "learning": learned_block, "suppressed_count": suppressed_count}
        blocked = self._blocked_action(goal, observation, tool, arguments)
        if blocked:
            blocked_reason = str(blocked.get("reason") or "")
            capacity_refusal = tool in {"shop", "cast"} and is_inventory_capacity_refusal(
                blocked_reason
            )
            blocked["suppressed_count"] = int(blocked.get("suppressed_count", 0)) + 1
            self._save_blocked_action(blocked)
            phase_result = finish_phase_attempt(
                "suppressed",
                result=blocked,
                verification={"known_no_progress": True},
                reason=blocked_reason,
            )
            if self._failure_invalidates_plan(tool, blocked_reason):
                self._invalidate_execution_plan(goal, blocked_reason)
            self._set_planner_feedback(
                goal,
                self._no_progress_guidance(
                    tool,
                    blocked_reason,
                    repeated=True,
                    observation=observation,
                ),
                blocked_action={"tool": tool, "arguments": redact(arguments), "room": blocked.get("room")},
                failure_context=self._failure_context(tool, blocked_reason, observation),
            )
            if blocked["suppressed_count"] in {1, 3}:
                self.storage.emit_event(
                    "action.retry_suppressed",
                    f"Suppressed repeated no-progress action: {tool}",
                    severity="warning",
                    interesting=blocked["suppressed_count"] == 3,
                    goal_id=goal["id"],
                    data={
                        "tool": tool,
                        "arguments": redact(arguments),
                        "reason": blocked.get("reason"),
                        "suppressed_count": blocked["suppressed_count"],
                    },
                )
            if phase_result.get("breaker_tripped"):
                self._invalidate_execution_plan(
                    goal, "campaign breaker ended a phase repeating a known no-progress action"
                )
                return {
                    "action": tool,
                    "retry_suppressed": True,
                    "reason": blocked_reason,
                    "campaign_breaker": phase_result,
                    "strategic_goal_preserved": True,
                }
            if blocked["suppressed_count"] >= self.config.learning.repeated_tactic_budget:
                invalid_reference = tool in {"map", KNOWLEDGE_TOOL_NAME} and "no match" in str(blocked.get("reason", "")).casefold()
                insufficient_funds = tool == "shop" and any(
                    marker in blocked_reason.casefold()
                    for marker in ("enough money", "insufficient fund", "cannot afford")
                )
                reason = (
                    "repeated authoritative lookup returned no matching game entity"
                    if invalid_reference
                    else (
                        f"the exact {tool} tactic repeatedly made no progress in the same state: {blocked_reason}"
                        if insufficient_funds
                        else f"the exact {tool} tactic repeatedly made no progress in the same state"
                    )
                )
                deferred = self.learning.defer_goal(
                    goal,
                    observation,
                    tool=tool,
                    arguments=arguments,
                    reason=reason,
                    event_kind="action.retry_suppressed",
                    classification="invalid_reference" if invalid_reference else None,
                    # Goal activation already validates references from the
                    # operator-authored goal against the knowledge corpus.  A
                    # later zero-match map/search string was invented by the
                    # tactical planner, so quarantine that exact lookup rather
                    # than falsely declaring the valid goal impossible.
                    scope="tactic",
                    retry_when=(
                        {
                            "mode": "any",
                            "conditions": [
                                {
                                    "kind": "numeric_increase",
                                    "field": "carried_currency",
                                    "from": int(blocked.get("carried_currency", 0) or 0),
                                }
                            ],
                        }
                        if insufficient_funds
                        else (
                            {
                                "mode": "any",
                                "conditions": [
                                    {
                                        "kind": "component_changed",
                                        "field": "inventory_load_hash",
                                        "from": blocked.get("inventory_load_hash"),
                                    }
                                ],
                            }
                            if capacity_refusal
                            else None
                        )
                    ),
                )
                goal_blocked = bool(deferred.get("goal_blocked"))
                return {
                    "action": tool,
                    "goal_blocked": goal_blocked,
                    "tactic_deferred": not goal_blocked,
                    **deferred,
                    "reason": blocked.get("reason"),
                    "suppressed_count": blocked["suppressed_count"],
                }
            return {
                "action": tool,
                "retry_suppressed": True,
                "reason": blocked.get("reason"),
                "suppressed_count": blocked["suppressed_count"],
            }
        known = set(capabilities)
        policy = self.policy.evaluate(tool, arguments, observation, goal, known_tools=known)
        correlation_id = uuid7()
        self.storage.emit_event(
            "policy.authorized" if policy.decision != "deny" else "policy.denied",
            policy.summary,
            interesting=policy.notify,
            severity="warning" if policy.decision == "deny" else "info",
            goal_id=goal["id"],
            data=policy.as_dict(),
            correlation_id=correlation_id,
            policy_decision_id=policy.id,
        )
        if policy.decision == "deny":
            phase_result = finish_phase_attempt(
                "suppressed",
                result=policy.as_dict(),
                verification={"policy_allowed": False},
                reason=policy.summary,
            )
            return {"denied": True, "policy": policy.as_dict()}
        rationale = str(plan.get("rationale", ""))[:1000]
        attempt_id = self.storage.create_action_attempt(goal["id"], observation.get("id"), tool, arguments, rationale, policy.id, correlation_id)
        assessment_id: str | None = None
        if policy.decision == "allow_with_caution":
            assessment = self.policy.consequence_assessment(policy, goal, rationale)
            assessment["action_attempt_id"] = attempt_id
            assessment_id = self.storage.record_consequence(assessment)["id"]
            if tool == "reroll" and arguments.get("action") == "reroll":
                arguments["confirm"] = True
        self.storage.update_action_attempt(attempt_id, "sent")
        try:
            if tool == KNOWLEDGE_TOOL_NAME:
                self.knowledge.validate_tool_arguments(arguments)
                result = self.knowledge.search(
                    str(arguments["query"]),
                    kinds=arguments.get("kinds"),
                    limit=int(arguments.get("limit", 5)),
                )
            else:
                self._begin_foreground_action(tool, goal_id=goal["id"])
                try:
                    if tool == PVP_TOOL_NAME:
                        result = self.pvp.engage(arguments, timeout=self.config.model.planner_timeout_seconds)
                        self._emit_pvp_result(goal, result, correlation_id=correlation_id, policy_decision_id=policy.id)
                    elif tool == PVP_SEEK_TOOL_NAME:
                        result = self.pvp.seek(
                            arguments,
                            timeout=max(360, self.config.model.planner_timeout_seconds),
                        )
                        self._emit_pvp_result(goal, result, correlation_id=correlation_id, policy_decision_id=policy.id)
                    else:
                        if tool in MOVEMENT_TOOLS and "rest" in capabilities:
                            stood = self.broker.call_tool(
                                "rest",
                                {"agent": self.config.game.agent, "stand": True},
                                timeout=10,
                                mutation=True,
                            )
                            self.storage.emit_event(
                                "action.movement_prepared",
                                "Stood the character up before movement",
                                severity="info",
                                interesting=False,
                                goal_id=goal["id"],
                                data={"tool": tool, "result": redact(stood)},
                                correlation_id=correlation_id,
                                policy_decision_id=policy.id,
                            )
                        if tool in MOVEMENT_TOOLS and "look" in capabilities:
                            # The ordinary client can temporarily lose its self
                            # object across posture/room-content transitions. A
                            # look in a prior planner turn is not sufficient;
                            # refresh position immediately before movement.
                            self.broker.call_tool(
                                "look",
                                {"agent": self.config.game.agent},
                                timeout=20,
                                mutation=False,
                            )
                        result = self.broker.call_tool(
                            tool,
                            arguments,
                            timeout=self._broker_action_timeout(tool),
                            mutation=True,
                        )
                        transient_movement_failure = self._transient_movement_failure_reason(
                            tool, result
                        )
                        if transient_movement_failure and "look" in capabilities:
                            # A lost self position or an explicitly silent go
                            # response does not disprove the route. Refresh the
                            # authoritative room first, then retry at most once.
                            # If the delayed first response already moved us,
                            # synthesize success instead of sending go in the
                            # newly entered room.
                            first_result = result
                            refreshed = self.broker.call_tool(
                                "look",
                                {"agent": self.config.game.agent},
                                timeout=20,
                                mutation=False,
                            )
                            if self._look_room_matches_destination(
                                refreshed, arguments.get("to")
                            ):
                                result = {
                                    "arrived": True,
                                    "room": redact(
                                        refreshed.get("room")
                                        if isinstance(refreshed, dict)
                                        else None
                                    ),
                                    "recovered_after_silent_reply": True,
                                }
                            else:
                                result = self.broker.call_tool(
                                    tool,
                                    arguments,
                                    timeout=self._broker_action_timeout(tool),
                                    mutation=True,
                                )
                            position_unknown = "own position unknown" in transient_movement_failure.casefold()
                            self.storage.emit_event(
                                (
                                    "action.movement_relocalized"
                                    if position_unknown
                                    else "action.movement_retried"
                                ),
                                (
                                    "Relocalized the character and retried movement once"
                                    if position_unknown
                                    else "Refreshed live room state after a silent transition and retried once"
                                ),
                                severity="info",
                                interesting=False,
                                goal_id=goal["id"],
                                data={
                                    "tool": tool,
                                    "initial_failure": transient_movement_failure,
                                    "initial_result": redact(first_result),
                                    "look": redact(refreshed),
                                    "result": redact(result),
                                },
                                correlation_id=correlation_id,
                                policy_decision_id=policy.id,
                            )
                finally:
                    self._end_foreground_action()
            post_action = (
                self.broker.observe()
                if tool
                in {
                    "cast",
                    "fight",
                    *PVP_TOOL_NAMES,
                    "bank",
                    "shop",
                    "sell",
                    "sell_all",
                    "trade",
                    "act",
                    "equip_best",
                    "wear_best",
                }
                else None
            )
            if post_action is not None:
                self.last_observation = post_action
                self.storage.record_snapshot(redact(post_action))
            self._record_plan_action(
                goal,
                step_id=str(plan.get("plan_step_id") or "controller-owned-step"),
                tool=tool,
                arguments=arguments,
                result=result,
            )
            if post_action is not None and (
                tool == "fight"
                or tool == PVP_TOOL_NAME
                or (tool == PVP_SEEK_TOOL_NAME and isinstance(result, dict) and result.get("engaged") is True)
            ):
                died = bool(
                    isinstance(result, dict) and result.get("died") is True
                    or (not self._underworld(observation) and self._underworld(post_action))
                )
                if died:
                    self.storage.update_action_attempt(attempt_id, "failed", result=redact(result), error_code="CHARACTER_DIED")
                    finish_phase_attempt(
                        "failed",
                        action_attempt_id=attempt_id,
                        result=result,
                        verification={"died": True},
                        reason="character died during the internal phase",
                    )
                    death = self._record_death(
                        goal,
                        tool=tool,
                        arguments=arguments,
                        before=observation,
                        after=post_action,
                        result=result,
                        correlation_id=correlation_id,
                        policy_decision_id=policy.id,
                    )
                    if assessment_id:
                        self.storage.complete_consequence(assessment_id, outcome={"died": True, "result": redact(result)}, succeeded=False)
                    return {"action": tool, "failed": True, "died": True, **death}
                combat = self.learning.record_combat_outcome(
                    tool=tool,
                    arguments=arguments,
                    before=observation,
                    result=result,
                    after=post_action,
                )
                self.storage.emit_event(
                    "combat.encounter.completed",
                    f"Combat encounter completed: {tool}",
                    severity="warning" if combat.get("outcome") == "disengaged" else "info",
                    interesting=combat.get("outcome") == "disengaged",
                    goal_id=goal["id"],
                    data=combat,
                    correlation_id=correlation_id,
                    policy_decision_id=policy.id,
                )
            no_progress = self._no_progress_reason(
                result,
                observation,
                tool=tool,
                arguments=arguments,
                after_observation=post_action,
            )
            if no_progress is None:
                no_progress = self._repeated_evidence_reason(tool, arguments, result, observation)
            if no_progress:
                failure_observation = post_action or observation
                transient_movement_failure = self._transient_movement_failure_reason(
                    tool, result
                )
                if transient_movement_failure:
                    # The bounded retry also received no authoritative reply.
                    # Report it as a transport/client failure, but do not write
                    # a blocked-action fingerprint or a route lesson: neither
                    # would be supported by the broker's evidence.
                    self.storage.update_action_attempt(
                        attempt_id,
                        "failed",
                        result=redact(result),
                        error_code="TRANSIENT_MOVEMENT_FAILURE",
                    )
                    phase_result = finish_phase_attempt(
                        "failed",
                        action_attempt_id=attempt_id,
                        result=result,
                        verification={
                            "transient_movement_failure": True,
                            "reason": transient_movement_failure,
                        },
                        reason=transient_movement_failure,
                    )
                    self.storage.emit_event(
                        "action.transient_failure",
                        f"Movement received no authoritative reply after one retry: {tool}",
                        severity="warning",
                        interesting=False,
                        goal_id=goal["id"],
                        data={
                            "tool": tool,
                            "arguments": redact(arguments),
                            "room": redact(deep_get(observation, "look.room")),
                            "reason": transient_movement_failure,
                            "result": redact(result),
                            "attempt_id": attempt_id,
                            "route_disproved": False,
                        },
                        correlation_id=correlation_id,
                        policy_decision_id=policy.id,
                    )
                    self._set_planner_feedback(
                        goal,
                        (
                            "The verified movement request received no room-change or refusal after "
                            "one bounded retry. This is transient protocol evidence, not a blocked "
                            "route; refresh live state and retry the verified hop on a later turn."
                        ),
                        failure_context=self._failure_context(
                            tool, transient_movement_failure, failure_observation
                        ),
                    )
                    if phase_result.get("breaker_tripped"):
                        self._invalidate_execution_plan(
                            goal,
                            "campaign breaker ended a phase after repeated transient movement failures",
                        )
                    return {
                        "action": tool,
                        "no_progress": True,
                        "transient_failure": True,
                        "route_disproved": False,
                        "reason": transient_movement_failure,
                        "result": redact(result),
                        **(
                            {
                                "campaign_breaker": phase_result,
                                "strategic_goal_preserved": True,
                            }
                            if phase_result.get("breaker_tripped")
                            else {}
                        ),
                    }
                transient_cast_failure = self._transient_cast_failure_reason(
                    tool, result
                )
                if transient_cast_failure:
                    ambiguous_creation = "no authoritative created-item delta" in (
                        transient_cast_failure.casefold()
                    )
                    # A zero-cost swallowed packet, half-cost random failure, or
                    # full-cost creation with no authoritative item/refusal does
                    # not disprove the spell, its reagents, or the verified plan.
                    # None may enter blocked-action memory: that would turn a
                    # timing/random/observation outcome into permanent suppression.
                    # Repeated full-cost ambiguity is still bounded inside the
                    # current phase so a broken observer cannot burn mana forever.
                    self._record_plan_action(
                        goal,
                        step_id=str(
                            plan.get("plan_step_id") or "controller-owned-step"
                        ),
                        tool=tool,
                        arguments=arguments,
                        result=result,
                        status="transient_failure",
                    )
                    self.storage.update_action_attempt(
                        attempt_id,
                        "failed",
                        result=redact(result),
                        error_code=(
                            "AMBIGUOUS_CREATION_RESULT"
                            if ambiguous_creation
                            else "TRANSIENT_CAST_FAILURE"
                        ),
                    )
                    phase_result = finish_phase_attempt(
                        "failed" if ambiguous_creation else "partial",
                        action_attempt_id=attempt_id,
                        result=result,
                        verification={
                            "transient_cast_failure": True,
                            "ambiguous_creation_result": ambiguous_creation,
                            "plan_step_complete": False,
                            "reason": transient_cast_failure,
                        },
                        reason=transient_cast_failure,
                    )
                    plan_step_preserved = not phase_result.get("breaker_tripped")
                    if not plan_step_preserved:
                        self._invalidate_execution_plan(
                            goal,
                            "campaign breaker ended a phase after repeated ambiguous creation results",
                        )
                    event = self.storage.emit_event(
                        "action.transient_failure",
                        (
                            (
                                "Creation cast result was ambiguous; preserved the current plan step"
                                if plan_step_preserved
                                else "Repeated ambiguous creation results ended the current phase"
                            )
                            if ambiguous_creation
                            else "Cast failed transiently; preserved the current plan step"
                        ),
                        severity="warning",
                        interesting=False,
                        goal_id=goal["id"],
                        data={
                            "tool": tool,
                            "arguments": redact(arguments),
                            "room": redact(deep_get(observation, "look.room")),
                            "reason": transient_cast_failure,
                            "result": redact(result),
                            "attempt_id": attempt_id,
                            "plan_step_preserved": plan_step_preserved,
                            "ambiguous_creation_result": ambiguous_creation,
                            "campaign_breaker": phase_result
                            if phase_result.get("breaker_tripped")
                            else None,
                        },
                        correlation_id=correlation_id,
                        policy_decision_id=policy.id,
                    )
                    self._set_planner_feedback(
                        goal,
                        self._no_progress_guidance(
                            tool,
                            transient_cast_failure,
                            observation=failure_observation,
                        ),
                        failure_context={
                            **self._failure_context(
                                tool,
                                transient_cast_failure,
                                failure_observation,
                            ),
                            "transient": True,
                            "plan_step_preserved": plan_step_preserved,
                        },
                    )
                    if assessment_id:
                        self.storage.complete_consequence(
                            assessment_id,
                            outcome={
                                "no_progress": True,
                                "transient_cast_failure": True,
                                "ambiguous_creation_result": ambiguous_creation,
                                "reason": transient_cast_failure,
                                "result": redact(result),
                                "action_event_id": event["id"],
                            },
                            succeeded=False,
                        )
                    return {
                        "action": tool,
                        "no_progress": True,
                        "transient_failure": True,
                        "ambiguous_creation_result": ambiguous_creation,
                        "plan_step_preserved": plan_step_preserved,
                        "reason": transient_cast_failure,
                        "result": redact(result),
                        **(
                            {
                                "campaign_breaker": phase_result,
                                "strategic_goal_preserved": True,
                            }
                            if phase_result.get("breaker_tripped")
                            else {}
                        ),
                    }
                self.storage.update_action_attempt(attempt_id, "failed", result=redact(result), error_code="NO_PROGRESS")
                phase_result = finish_phase_attempt(
                    "failed",
                    action_attempt_id=attempt_id,
                    result=result,
                    verification={"no_progress": True, "reason": no_progress},
                    reason=no_progress,
                )
                event = self.storage.emit_event(
                    "action.no_progress",
                    f"Action made no progress: {tool}",
                    severity="warning",
                    interesting=False,
                    goal_id=goal["id"],
                    data={"tool": tool, "arguments": redact(arguments), "room": redact(deep_get(observation, "look.room")), "reason": no_progress, "result": redact(result), "attempt_id": attempt_id},
                    correlation_id=correlation_id,
                    policy_decision_id=policy.id,
                )
                pvp_route_outcome = (
                    tool == PVP_SEEK_TOOL_NAME
                    and isinstance(result, dict)
                    and result.get("outcome") in {"route_unavailable", "travel_error"}
                )
                pvp_route_failure = (
                    result.get("route_failure")
                    if pvp_route_outcome
                    and isinstance(result.get("route_failure"), dict)
                    else {}
                )
                if pvp_route_outcome:
                    self.storage.set_runtime(
                        PVP_ROUTE_FAILURE_RUNTIME_KEY,
                        {
                            "goal_id": goal["id"],
                            "outcome": result.get("outcome"),
                            "actual_room_id": pvp_route_failure.get("actual_room_id"),
                            "actual_room_name": pvp_route_failure.get("actual_room_name"),
                            "requested_room_id": pvp_route_failure.get("requested_room_id"),
                            "failed_hop": redact(pvp_route_failure.get("failed_hop")),
                            "reason": pvp_route_failure.get("reason") or no_progress,
                            "corpus_version": self.knowledge.corpus_version,
                            "recorded_at": timestamp(),
                        },
                    )
                if self._failure_invalidates_plan(tool, no_progress):
                    self._invalidate_execution_plan(goal, no_progress)
                self._set_planner_feedback(
                    goal,
                    self._no_progress_guidance(
                        tool,
                        no_progress,
                        observation=failure_observation,
                    ),
                    blocked_action={
                        "tool": tool,
                        "arguments": redact(arguments),
                        "room": self._observation_room(observation),
                    },
                    failure_context=self._failure_context(
                        tool,
                        no_progress,
                        failure_observation,
                    ),
                )
                self._record_blocked_action(
                    goal,
                    failure_observation,
                    tool,
                    arguments,
                    no_progress,
                )
                if phase_result.get("breaker_tripped"):
                    self._invalidate_execution_plan(
                        goal, "campaign breaker ended a phase after repeated semantic failure"
                    )
                    if assessment_id:
                        self.storage.complete_consequence(
                            assessment_id,
                            outcome={
                                "no_progress": True,
                                "reason": no_progress,
                                "campaign_breaker": phase_result,
                            },
                            succeeded=False,
                        )
                    return {
                        "action": tool,
                        "no_progress": True,
                        "reason": no_progress,
                        "campaign_breaker": phase_result,
                        "strategic_goal_preserved": True,
                    }
                if pvp_route_outcome:
                    lesson_arguments = {
                        "actual_room_id": pvp_route_failure.get("actual_room_id"),
                        "requested_room_id": pvp_route_failure.get("requested_room_id"),
                        "failed_hop": pvp_route_failure.get("failed_hop"),
                    }
                    deferred = self.learning.defer_goal(
                        goal,
                        observation,
                        tool=tool,
                        arguments=lesson_arguments,
                        reason=no_progress,
                        event_kind="pvp.search.failed",
                        evidence_event_ids=[event["id"]],
                        classification=(
                            "route_unavailable"
                            if result.get("outcome") == "route_unavailable"
                            else "dependency_failure"
                        ),
                        scope="tactic",
                        block=False,
                    )
                else:
                    deferred = self.learning.maybe_defer(
                        goal,
                        observation,
                        tool=tool,
                        arguments=arguments,
                        reason=no_progress,
                        event=event,
                    )
                if assessment_id:
                    self.storage.complete_consequence(
                        assessment_id,
                        outcome={"no_progress": True, "reason": no_progress, "result": redact(result)},
                        succeeded=False,
                    )
                if deferred:
                    return {
                        "action": tool,
                        "goal_blocked": bool(deferred.get("goal_blocked")),
                        "tactic_deferred": not bool(deferred.get("goal_blocked")),
                        "reason": no_progress,
                        **deferred,
                    }
                return {"action": tool, "no_progress": True, "reason": no_progress, "result": redact(result)}
            partial_progress = self._partial_progress_reason(
                result,
                observation,
                tool=tool,
                arguments=arguments,
            )
            if partial_progress:
                # A multi-hop travel can move through several verified rooms and
                # then stop on a later transient hop. The RPC produced useful
                # movement, but `arrived:false` means the plan step's declared
                # destination is still unmet. Preserve the plan and force the
                # same step to resume from the new live room on the next turn.
                self._record_plan_action(
                    goal,
                    step_id=str(plan.get("plan_step_id") or "controller-owned-step"),
                    tool=tool,
                    arguments=arguments,
                    result=result,
                    status="partial_progress",
                )
                self.storage.update_action_attempt(
                    attempt_id,
                    "partial",
                    result=redact(result),
                    error_code="OUTCOME_INCOMPLETE",
                )
                finish_phase_attempt(
                    "partial",
                    action_attempt_id=attempt_id,
                    result=result,
                    verification={
                        "partial_progress": True,
                        "outcome_complete": False,
                        "reason": partial_progress,
                    },
                )
                event = self.storage.emit_event(
                    "action.partial_progress",
                    f"Action made partial progress but did not complete: {tool}",
                    interesting=False,
                    goal_id=goal["id"],
                    data={
                        "tool": tool,
                        "arguments": redact(arguments),
                        "reason": partial_progress,
                        "result": redact(result),
                        "attempt_id": attempt_id,
                    },
                    correlation_id=correlation_id,
                    policy_decision_id=policy.id,
                )
                self.last_observation = self.broker.observe()
                self.storage.record_snapshot(redact(self.last_observation))
                self._set_planner_feedback(
                    goal,
                    partial_progress
                    + " The route itself is not disproved. Keep the existing execution "
                    "plan and repeat this same plan step with the same destination from "
                    "the newly observed room; do not advance or revise the plan.",
                    failure_context={
                        "kind": "partial_progress",
                        "tool": tool,
                        "arguments": redact(arguments),
                        "room": self._observation_room(self.last_observation),
                        "outcome_complete": False,
                    },
                )
                if assessment_id:
                    self.storage.complete_consequence(
                        assessment_id,
                        outcome={
                            "action_event_id": event["id"],
                            "partial_progress": True,
                            "result": redact(result),
                        },
                        succeeded=True,
                    )
                return {
                    "action": tool,
                    "partial_progress": True,
                    "outcome_complete": False,
                    "reason": partial_progress,
                    "result": redact(result),
                }
            if (
                tool == "bank"
                and arguments.get("action") == "deposit"
                and post_action is not None
            ):
                self._record_bank_receipt(goal, observation, post_action)
            if tool == "sell":
                self._record_prepare_combat_sell_quote(
                    goal,
                    campaign_phase,
                    arguments,
                    observation,
                    result,
                )
            # Feedback describes the immediately previous failed/suppressed
            # tactic. Once any concrete action succeeds it is stale and can
            # mislead both the next planner turn and supervisor status into
            # treating a recovered route as still blocked.
            self._clear_planner_feedback()
            self._record_plan_action(
                goal,
                step_id=str(plan.get("plan_step_id") or "controller-owned-step"),
                tool=tool,
                arguments=arguments,
                result=result,
                status="succeeded",
            )
            self.storage.update_action_attempt(attempt_id, "succeeded", result=redact(result))
            finish_phase_attempt(
                "succeeded",
                action_attempt_id=attempt_id,
                result=result,
                verification={"no_progress": False},
            )
            event = self.storage.emit_event(
                "action.succeeded",
                f"Action succeeded: {tool}",
                interesting=False,
                goal_id=goal["id"],
                data={
                    "tool": tool,
                    "arguments": redact(arguments),
                    "result": redact(result),
                    "attempt_id": attempt_id,
                },
                correlation_id=correlation_id,
                policy_decision_id=policy.id,
            )
            if tool == "shop" and isinstance(result, dict):
                self._emit_shop_property_transaction(
                    goal,
                    result,
                    correlation_id=correlation_id,
                    policy_decision_id=policy.id,
                )
            if assessment_id:
                self.storage.complete_consequence(assessment_id, outcome={"action_event_id": event["id"], "result": redact(result)}, succeeded=True)
            fresh_observation = post_action or self.broker.observe()
            observed_room = self._observation_room(fresh_observation)
            self.last_observation = self._reconcile_successful_room_transition(
                tool,
                result,
                fresh_observation,
            )
            self._remember_successful_room_transition(
                tool,
                result,
                goal_id=goal["id"],
            )
            self._remember_successful_inventory_creation(
                tool,
                result,
                observation,
                goal_id=goal["id"],
            )
            if tool == "cast" and isinstance(result, dict) and result.get("created"):
                # Consume the broker's authoritative creation delta in this
                # action turn. The next cache refresh remains useful evidence,
                # but a briefly stale inventory read must not hide a completed
                # Create Food/Create Weapon mutation from phase verification.
                reconciled_creation = self._reconcile_recent_inventory_creation(
                    self.last_observation, emit_event=False
                )
                if reconciled_creation != self.last_observation:
                    self.last_observation = reconciled_creation
                    self.storage.record_snapshot(redact(reconciled_creation))
            reconciled_room = self._observation_room(self.last_observation)
            if str(reconciled_room) != str(observed_room):
                self.storage.emit_event(
                    "action.movement_observation_reconciled",
                    "Reconciled a stale post-movement room from the successful action receipt",
                    severity="info",
                    interesting=False,
                    goal_id=goal["id"],
                    data={
                        "tool": tool,
                        "stale_observed_room": observed_room,
                        "receipt_room": reconciled_room,
                    },
                    correlation_id=correlation_id,
                    policy_decision_id=policy.id,
                )
            if (
                tool == "leave_raza"
                and isinstance(result, dict)
                and result.get("left") is True
                and not self._in_raza_zone(self.last_observation)
                and not self._raza_exit_event_recorded(goal)
            ):
                self.storage.emit_event(
                    "raza.left",
                    "Left the one-way Raza tutorial zone through the museum portal",
                    severity="notice",
                    interesting=True,
                    goal_id=goal["id"],
                    data={
                        "room": redact(deep_get(self.last_observation, "look.room")),
                        "safe_room_verified": self._verified_safe_staging(
                            self._observation_room(self.last_observation)
                        )
                        is not None,
                        "result": redact(result),
                    },
                    correlation_id=correlation_id,
                    policy_decision_id=policy.id,
                )
            if (
                tool == "autopilot"
                and arguments.get("action") == "start"
                and arguments.get("mode") == "farm"
            ):
                # Failure handling is per launch, not per durable goal. A prior
                # route retreat may have been corrected and the goal resumed;
                # without resetting this marker, a later independent room hazard
                # would be quarantined but could not pause the goal, leaving the
                # planner to repeat a permanently blocked launch.
                self.storage.set_runtime(
                    f"background_farm_failure_handled_v1:{goal['id']}", False
                )
                self.storage.set_runtime(
                    f"background_farm_route_failure_handled_v1:{goal['id']}", False
                )
                self.storage.set_runtime(
                    self._background_farm_stop_key(str(goal["id"])), {}
                )
                self.storage.set_runtime(
                    "background_farm_owner_v1",
                    {
                        "goal_id": goal["id"],
                        "phase_id": (
                            campaign_phase.get("id")
                            if isinstance(campaign_phase, dict)
                            else None
                        ),
                        "phase_kind": (
                            campaign_phase.get("kind")
                            if isinstance(campaign_phase, dict)
                            else None
                        ),
                        "assigned_room": arguments.get("assigned_room"),
                        "hunt": str(arguments.get("hunt") or "").strip().casefold(),
                        "use_safe_spots": arguments.get("use_safe_spots"),
                        "origin_room": self._observation_room(observation),
                        "started_at": timestamp(),
                    },
                )
                self.storage.set_runtime(
                    f"background_farm_snapshot_v2:{goal['id']}",
                    {
                        "observed_at": timestamp(),
                        "room": arguments.get("assigned_room"),
                        "target": arguments.get("hunt"),
                        "use_safe_spots": arguments.get("use_safe_spots"),
                        "counters": {
                            name: self._farm_counter(result, name)
                            for name in (
                                "kills",
                                "deaths",
                                "withdrawals",
                                "mulligans",
                                "logoffs",
                                "deaths_in_safe_spot",
                                "deaths_in_proven_safe_spot",
                            )
                        },
                        "launch_counters": {
                            name: self._farm_counter(result, name)
                            for name in (
                                "kills",
                                "deaths",
                                "withdrawals",
                                "mulligans",
                                "logoffs",
                                "deaths_in_safe_spot",
                                "deaths_in_proven_safe_spot",
                            )
                        },
                        "launch_placement": self._farm_placement_signature(
                            result.get("placement") if isinstance(result, dict) else None
                        ),
                        "launch_started_at": timestamp(),
                        "origin_room": self._observation_room(observation),
                        "healing_supply_count": self.learning.profile(observation).get(
                            "healing_supply_count", 0
                        ),
                        "safe_spot": None,
                        "activity": "starting",
                        "health_fraction": self._vital_fraction(observation, "health"),
                        "flee_threshold": arguments.get("flee_below"),
                        "pass_floor": (
                            int(result.get("passes"))
                            if isinstance(result, dict)
                            and isinstance(result.get("passes"), (int, float))
                            else None
                        ),
                        # The keeper uses Date.now() for journal ids. Establish
                        # the launch boundary even when its compact tail has no
                        # kill record, so cumulative history cannot be replayed.
                        "last_kill_at": int(time.time() * 1000),
                    },
                )
            completion = self.criteria.evaluate(goal, self.last_observation)
            done = self._complete_goal_if_safe(
                goal, self.last_observation, completion
            )
            if done is None:
                checkpoint = self._goal_completion_checkpoint(goal)
                self.storage.set_goal_completion(
                    goal["id"],
                    checkpoint["completion"] if checkpoint is not None else completion,
                )
            return {"action": tool, "result": redact(result), "completion": completion}
        except ToolCallError as exc:
            self.storage.update_action_attempt(attempt_id, "failed", error_code=exc.code)
            phase_result = finish_phase_attempt(
                "failed",
                action_attempt_id=attempt_id,
                result={"error": str(exc)[:500], "code": exc.code},
                verification={"tool_call_succeeded": False},
                reason=str(exc),
            )
            reconciled = self._reconcile_after_action_error(error=str(exc))
            event = self.storage.emit_event(
                "action.failed",
                f"Action failed: {tool}",
                severity="warning",
                interesting=tool == "fight" or tool in PVP_TOOL_NAMES,
                goal_id=goal["id"],
                data={
                    "tool": tool,
                    "arguments": redact(arguments),
                    "room": redact(deep_get(observation, "look.room")),
                    "error": str(exc)[:500],
                    "attempt_id": attempt_id,
                    "reconciled_state": None if reconciled is None else {
                        "room": redact(deep_get(reconciled, "look.room")),
                        "vitals": redact(deep_get(reconciled, "status.vitals", deep_get(reconciled, "look.vitals", {}))),
                    },
                },
                correlation_id=correlation_id,
                policy_decision_id=policy.id,
            )
            died = bool(
                (tool == "fight" or tool in PVP_TOOL_NAMES)
                and reconciled is not None
                and not self._underworld(observation)
                and self._underworld(reconciled)
            )
            if died and reconciled is not None:
                death = self._record_death(
                    goal,
                    tool=tool,
                    arguments=arguments,
                    before=observation,
                    after=reconciled,
                    error=str(exc),
                    correlation_id=correlation_id,
                    policy_decision_id=policy.id,
                )
                if assessment_id:
                    self.storage.complete_consequence(assessment_id, outcome={"error": str(exc)[:500], "died": True}, succeeded=False)
                return {
                    "action": tool,
                    "goal_blocked": False,
                    "failed": True,
                    "died": True,
                    "error": str(exc),
                    "strategic_goal_preserved": True,
                    **death,
                }
            if phase_result.get("breaker_tripped"):
                self._invalidate_execution_plan(
                    goal, "campaign breaker ended a phase after repeated broker rejection"
                )
                if assessment_id:
                    self.storage.complete_consequence(
                        assessment_id,
                        outcome={"error": str(exc)[:500], "campaign_breaker": phase_result},
                        succeeded=False,
                    )
                return {
                    "action": tool,
                    "failed": True,
                    "error": str(exc),
                    "campaign_breaker": phase_result,
                    "strategic_goal_preserved": True,
                }
            if tool == "fight" or tool in PVP_TOOL_NAMES:
                self.learning.record_combat_outcome(
                    tool=tool,
                    arguments=arguments,
                    before=observation,
                    after=reconciled,
                    error=str(exc),
                    died=False,
                )
            deferred = self.learning.maybe_defer(goal, observation, tool=tool, arguments=arguments, reason=str(exc), event=event)
            if assessment_id:
                self.storage.complete_consequence(assessment_id, outcome={"error": str(exc)[:500]}, succeeded=False)
            if deferred:
                return {
                    "action": tool,
                    "goal_blocked": bool(deferred.get("goal_blocked")),
                    "tactic_deferred": not bool(deferred.get("goal_blocked")),
                    "error": str(exc),
                    **deferred,
                }
            return {"action": tool, "failed": True, "error": str(exc)}
        except BrokerError:
            self.storage.update_action_attempt(attempt_id, "unknown", error_code="AMBIGUOUS_ACTION_RESULT")
            finish_phase_attempt(
                "unknown",
                action_attempt_id=attempt_id,
                verification={"result_ambiguous": True},
                reason="broker failure left mutation outcome ambiguous",
            )
            self.storage.emit_event("action.unknown", f"Action result unknown after broker failure: {tool}", severity="critical", interesting=True, goal_id=goal["id"], data={"tool": tool, "attempt_id": attempt_id}, correlation_id=correlation_id, policy_decision_id=policy.id)
            current_goal = self.storage.goal(goal["id"])
            if current_goal and current_goal.get("status") == "active":
                self.storage.manage_goal(
                    {
                        "request_id": f"controller-ambiguous-mutation-{uuid7()}",
                        "goal_id": goal["id"],
                        "expected_version": current_goal.get("version"),
                        "action": "pause",
                        "reason": (
                            "mutation result could not be reconciled safely; refresh "
                            "evidence before resuming"
                        ),
                    }
                )
            raise

    def _emit_pvp_result(
        self,
        goal: dict[str, Any],
        result: Any,
        *,
        correlation_id: str,
        policy_decision_id: str,
    ) -> None:
        if not isinstance(result, dict):
            return
        search = result.get("search") if isinstance(result.get("search"), dict) else None
        if search is not None:
            visits = search.get("rooms_visited") if isinstance(search.get("rooms_visited"), list) else []
            distinct_rooms = sorted(
                {
                    int(item["room_id"])
                    for item in visits
                    if isinstance(item, dict)
                    and item.get("arrived") is True
                    and isinstance(item.get("room_id"), int)
                    and not isinstance(item.get("room_id"), bool)
                }
            )
            search_failed = result.get("outcome") in {
                "route_unavailable",
                "travel_error",
            }
            route_failure = (
                result.get("route_failure")
                if isinstance(result.get("route_failure"), dict)
                else None
            )
            self.storage.emit_event(
                "pvp.search.failed" if search_failed else "pvp.search.completed",
                (
                    (
                        "PvP patrol failed before completing its route"
                        if search_failed
                        else f"PvP patrol searched {len(distinct_rooms)} room(s)"
                    )
                    + (f" and acquired {deep_get(result, 'target.name')}" if deep_get(result, "target.name") else "")
                ),
                severity="warning" if search_failed or result.get("outcome") in {"search_timeout", "search_aborted_low_health"} else "info",
                interesting=result.get("outcome") == "search_aborted_low_health",
                goal_id=goal["id"],
                data={
                    "outcome": result.get("outcome"),
                    "reason": result.get("reason"),
                    "target_requested": result.get("target_requested"),
                    "requested_route": search.get("requested_route"),
                    "route": search.get("route"),
                    "completed_patrol": search.get("completed_patrol") is True,
                    "skipped_rooms": redact(search.get("skipped_rooms", [])),
                    "guild_eligibility_verified": search.get("guild_eligibility_verified"),
                    "distinct_rooms": distinct_rooms,
                    "rooms_visited": redact(visits),
                    "route_failure": redact(route_failure),
                    "route_failures": redact(search.get("route_failures", [])),
                    "online_candidates": redact(search.get("online_candidates", [])),
                    "target_acquired": redact(result.get("target")),
                },
                correlation_id=correlation_id,
                policy_decision_id=policy_decision_id,
            )

        engagement = result.get("engagement") if isinstance(result.get("engagement"), dict) else result
        outcome = str(engagement.get("outcome", result.get("outcome", "unknown")))
        target = engagement.get("target") if isinstance(engagement.get("target"), dict) else {}
        target_name = target.get("name") or engagement.get("target_requested") or result.get("target_requested") or "unknown player"
        accepted_swings = int(engagement.get("accepted_swings", 0) or 0)
        engaged = engagement.get("engaged") is True
        if not engaged and accepted_swings <= 0:
            self.storage.emit_event(
                "pvp.engagement.skipped",
                f"PvP engagement with {target_name} did not start: {outcome.replace('_', ' ')}",
                severity="info",
                interesting=False,
                goal_id=goal["id"],
                data={
                    "target": target or {"name": target_name},
                    "outcome": outcome,
                    "accepted_swings": 0,
                    "reason": engagement.get("reason"),
                    "refused_room": engagement.get("refused_room"),
                    "room_policy": engagement.get("room_policy"),
                },
                correlation_id=correlation_id,
                policy_decision_id=policy_decision_id,
            )
            return

        loot = engagement.get("loot") if isinstance(engagement.get("loot"), dict) else None
        loot_attempted = bool(loot and loot.get("attempted") is True)
        items_taken = loot.get("items_taken", []) if loot_attempted and isinstance(loot.get("items_taken"), list) else []
        items_taken_count = int(loot.get("items_taken_count", 0) or 0) if loot_attempted else 0
        qualifying_phase = bool(
            outcome == "target_left_or_defeated"
            and accepted_swings > 0
            and loot_attempted
        )
        severity = "critical" if engagement.get("cleanup_errors") or result.get("cleanup_errors") else (
            "warning" if outcome in {"disengaged_low_health", "attack_refused"} else "notice"
        )
        self.storage.emit_event(
            "pvp.engagement.completed",
            f"PvP engagement with {target_name}: {outcome.replace('_', ' ')}",
            severity=severity,
            interesting=True,
            goal_id=goal["id"],
            data={
                "target": target or {"name": target_name},
                "outcome": outcome,
                "rounds": len(engagement.get("rounds", [])) if isinstance(engagement.get("rounds"), list) else 0,
                "accepted_swings": accepted_swings,
                "loot_attempted": loot_attempted,
                "items_taken_count": items_taken_count,
                "qualifying_phase": qualifying_phase,
                "disengage_at": engagement.get("disengage_at"),
                "cleanup": engagement.get("cleanup"),
                "cleanup_errors": engagement.get("cleanup_errors"),
                "reason": engagement.get("reason"),
                "refused_room": engagement.get("refused_room"),
            },
            correlation_id=correlation_id,
            policy_decision_id=policy_decision_id,
        )
        if loot_attempted:
            self.storage.emit_event(
                "pvp.loot.completed",
                f"PvP loot sweep after engaging {target_name}: {items_taken_count} item(s) taken",
                severity="notice" if items_taken_count else "info",
                interesting=items_taken_count > 0,
                goal_id=goal["id"],
                data={
                    "target": target or {"name": target_name},
                    "items_taken": redact(items_taken),
                    "items_taken_count": items_taken_count,
                    "nothing_available": items_taken_count == 0,
                },
                correlation_id=correlation_id,
                policy_decision_id=policy_decision_id,
            )
        if items_taken_count > 0:
            self.storage.emit_event(
                "property.transaction",
                f"PvP loot transaction after engaging {target_name}: {items_taken_count} item(s) taken",
                severity="notice",
                interesting=True,
                goal_id=goal["id"],
                data={
                    "transaction": "pvp_loot",
                    "target": target or {"name": target_name},
                    "items_taken": redact(items_taken),
                    "items_taken_count": items_taken_count,
                    "protected_or_valuable": True,
                    "approval_required": False,
                },
                correlation_id=correlation_id,
                policy_decision_id=policy_decision_id,
            )
        if qualifying_phase:
            self.storage.emit_event(
                "pvp.phase.completed",
                f"Observed qualifying PvP phase against {target_name}",
                severity="notice",
                interesting=True,
                goal_id=goal["id"],
                data={
                    "target": target or {"name": target_name},
                    "outcome": outcome,
                    "accepted_swings": accepted_swings,
                    "loot_attempted": True,
                    "items_taken": redact(items_taken),
                    "items_taken_count": items_taken_count,
                    "protocol_limit": "target departure cannot be distinguished from defeat",
                },
                correlation_id=correlation_id,
                policy_decision_id=policy_decision_id,
            )

    def _repeated_evidence_reason(
        self,
        tool: str,
        arguments: dict[str, Any],
        result: Any,
        observation: dict[str, Any],
    ) -> str | None:
        """Treat an identical static lookup replay as non-progress.

        Catalog and corpus lookups are useful evidence once.  Without this
        guard, the planner can repeat the same successful read forever while
        never acting on the result, and the normal failure budget never sees
        the loop because the RPC itself succeeded.
        """
        evidence_tools = {
            "map",
            "merchants",
            "prey",
            "hunting_grounds",
            KNOWLEDGE_TOOL_NAME,
        }
        is_bank_balance = tool == "bank" and str(
            arguments.get("action") or ""
        ).casefold() == "balance"
        is_shop_catalogue = tool == "shop" and not arguments.get("buy_ids")
        if tool not in evidence_tools and not is_bank_balance and not is_shop_catalogue:
            return None
        active_phase_id = None
        active_goal = self.storage.active_goal()
        if active_goal is not None:
            run = self.storage.campaign_run(active_goal["id"])
            phase = (
                self.storage.active_campaign_phase(run["id"])
                if isinstance(run, dict)
                else None
            )
            if isinstance(phase, dict):
                active_phase_id = phase.get("id")
        signature = canonical_json(
            {
                "tool": tool,
                "arguments": arguments,
                "room": self._observation_room(observation),
                # Evidence is allowed to satisfy one bounded phase once. A
                # replay inside that phase is still non-progress, but a fresh
                # repair phase must not inherit an earlier phase's lookup
                # cache and become impossible to complete.
                "phase_id": active_phase_id,
            }
        )
        result_fingerprint = canonical_json(redact(result))
        entries = self.storage.get_runtime("evidence_lookup_cache_v1", [])
        if not isinstance(entries, list):
            entries = []
        prior = next(
            (
                entry
                for entry in entries
                if isinstance(entry, dict) and entry.get("signature") == signature
            ),
            None,
        )
        if prior is not None and prior.get("result") == result_fingerprint:
            return "repeated identical evidence lookup returned no new evidence"
        entries = [
            entry
            for entry in entries
            if isinstance(entry, dict) and entry.get("signature") != signature
        ]
        entries.append(
            {
                "signature": signature,
                "result": result_fingerprint,
                "updated_at": timestamp(),
            }
        )
        self.storage.set_runtime("evidence_lookup_cache_v1", entries[-50:])
        return None

    @staticmethod
    def _inventory_capacity_context(observation: dict[str, Any] | None) -> dict[str, Any]:
        carry = deep_get(observation or {}, "inventory.carry", {})
        if not isinstance(carry, dict):
            return {"known": False, "note": "broker carry estimate was unavailable"}
        load = carry.get("load") if isinstance(carry.get("load"), dict) else {}
        room_for = carry.get("room_for") if isinstance(carry.get("room_for"), dict) else None
        return {
            "known": carry.get("known") is True,
            "items": carry.get("items"),
            "weight": load.get("weight"),
            "weight_max": carry.get("weight_max"),
            "bulk": load.get("bulk"),
            "bulk_max": carry.get("bulk_max"),
            "exact": load.get("exact"),
            "unweighed": load.get("unweighed", []),
            "room_for": room_for,
            "note": carry.get("note"),
        }

    @classmethod
    def _failure_context(
        cls,
        tool: str,
        reason: str,
        observation: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        text = str(reason or "").casefold()
        if tool == "cast" and "no authoritative created-item delta" in text:
            return {
                "kind": "creation_result_ambiguous",
                "source": "broker_observation",
                "reason": str(reason)[:500],
                "purpose": (
                    "Preserve the incomplete plan step without writing a blocked-action "
                    "fingerprint or durable lesson."
                ),
                "inventory_capacity": cls._inventory_capacity_context(observation),
                "required_response": (
                    "Refresh live inventory and equipment, recover the spell cost, and "
                    "retry later or choose a different grounded acquisition route."
                ),
            }
        if tool == "cast" and is_inventory_capacity_refusal(reason):
            return {
                "kind": "creation_inventory_capacity_refused",
                "source": "server_message",
                "reason": str(reason)[:500],
                "purpose": (
                    "Defer only this creation attempt at the current carried load; "
                    "the refusal is inventory state, not combat-power evidence."
                ),
                "item_transfer_verified": False,
                "inventory_capacity": cls._inventory_capacity_context(observation),
                "required_response": (
                    "Free verified weight or bulk, refresh inventory, then retry the "
                    "same creation spell. Do not raise HP or change hunting rooms for "
                    "an inventory-capacity refusal."
                ),
            }
        if tool == "shop" and is_inventory_capacity_refusal(reason):
            return {
                "kind": "inventory_capacity_refused",
                "source": "merchant_message",
                "reason": str(reason)[:500],
                "purpose": (
                    "Invalidate the unchanged purchase because the merchant verified "
                    "that no item transferred at the current carried load."
                ),
                "item_transfer_verified": False,
                "inventory_capacity": cls._inventory_capacity_context(observation),
            }
        if tool == "shop" and any(
            marker in text
            for marker in ("enough money", "insufficient fund", "cannot afford")
        ):
            return {
                "kind": "purchase_funds_insufficient",
                "source": "merchant_message",
                "reason": str(reason)[:500],
                "purpose": (
                    "Invalidate the current purchase tactic until an earlier action "
                    "verifiably increases carried shillings."
                ),
                "carried_shillings": cls._carried_currency(observation or {}),
                "required_response": (
                    "Fund the purchase with sell, guarded sell_all, or bank withdrawal, "
                    "or use a verified direct capability instead."
                ),
            }
        if tool == "shop" and "identical evidence lookup" in text:
            return {
                "kind": "merchant_catalogue_already_known",
                "reason": str(reason)[:500],
                "purpose": (
                    "A repeated read-only shop result cannot satisfy a mutation outcome "
                    "or make an unaffordable purchase affordable."
                ),
                "required_response": (
                    "Act on the known catalogue with valid funds, perform a real funding "
                    "action, or choose a different plan."
                ),
            }
        if tool == "sell_all" and "merchant bought zero" in text:
            return {
                "kind": "bulk_sale_transferred_nothing",
                "reason": str(reason)[:500],
                "purpose": (
                    "Invalidate this merchant/liquidation tactic because it neither raised "
                    "funds nor reduced carried inventory."
                ),
                "required_response": (
                    "Use merchant evidence to choose a compatible buyer or use a targeted "
                    "sell quote for a materially different ordinary item."
                ),
            }
        if tool in {"sell", "sell_all"} and cls._is_intrinsic_item_sale_refusal(
            text
        ):
            return {
                "kind": "item_not_npc_transferable",
                "reason": str(reason)[:500],
                "source": "server_can_be_given_to_npc_check",
                "purpose": (
                    "Block this exact item instance across every merchant because the "
                    "server rejected it before evaluating buyer preference."
                ),
                "required_response": (
                    "Choose a different exact inventory item id or use a non-sale "
                    "funding route; do not search for another buyer for this item."
                ),
            }
        if tool == "sell" or (
            tool == "sell_all" and cls._is_merchant_sale_refusal(text)
        ):
            return {
                "kind": "merchant_rejected_sale",
                "reason": str(reason)[:500],
                "purpose": (
                    "Reject only this item/merchant tactic; the refusal does not block "
                    "other inventory items, merchants, or direct equipment capabilities."
                ),
                "required_response": (
                    "Change the offered item or buyer using live merchant evidence."
                ),
            }
        if tool == "merchants" and "no candidate merchants" in text:
            return {
                "kind": "merchant_lookup_no_candidates",
                "reason": str(reason)[:500],
                "purpose": (
                    "Keep an empty read-only merchant search from satisfying a plan "
                    "step or authorizing travel to an undefined seller."
                ),
                "required_response": (
                    "Use an exact source-grounded item query, actual known catalogue "
                    "stock, or a different acquisition prerequisite; do not continue "
                    "to travel or shop without a returned merchant."
                ),
            }
        return {
            "kind": "action_made_no_progress",
            "reason": str(reason)[:500],
            "purpose": (
                "Mark the exact failed tactic as non-progress so it is not replayed in "
                "unchanged state. This is not a goal-wide block."
            ),
            "required_response": (
                "Use the observed cause to change the tool, prerequisite, target, route, "
                "or other causal argument before retrying."
            ),
        }

    @staticmethod
    def _failure_invalidates_plan(tool: str, reason: Any) -> bool:
        text = str(reason or "").casefold()
        return (
            tool == "shop"
            and (
                is_inventory_capacity_refusal(text)
                or any(
                    marker in text
                    for marker in (
                        "enough money",
                        "insufficient fund",
                        "cannot afford",
                        "identical evidence lookup",
                    )
                )
            )
        ) or (
            tool == "merchants" and "no candidate merchants" in text
        ) or tool == "sell" or (
            tool == "sell_all"
            and (
                "merchant bought zero" in text
                or BotController._is_merchant_sale_refusal(text)
            )
        ) or (
            tool == "travel" and "travel route cycled" in text
        ) or (
            tool == "cast"
            and (
                "produced no verified carried item" in text
                or is_inventory_capacity_refusal(text)
            )
        )

    @staticmethod
    def _is_merchant_sale_refusal(reason: Any) -> bool:
        """Recognize factual broker/NPC refusals that disprove a sale tactic."""

        text = str(reason or "").casefold()
        return any(
            marker in text
            for marker in (
                "not interested",
                "did not buy",
                "no counteroffer",
                "no need for that",
                "no need of that",
            )
        )

    @staticmethod
    def _is_intrinsic_item_sale_refusal(reason: Any) -> bool:
        """Recognize Monster.ReqOffer's CanBeGivenToNPC=false response."""

        text = str(reason or "").casefold()
        return (
            "cannot see how you could bear to part with" in text
            or "couldn't be the one to take it off your hands" in text
            or "could not be the one to take it off your hands" in text
        )

    @classmethod
    def _no_progress_guidance(
        cls,
        tool: str,
        reason: str,
        *,
        repeated: bool = False,
        observation: dict[str, Any] | None = None,
    ) -> str:
        prefix = f"The {'repeated ' if repeated else 'previous '}{tool} call made no progress: {reason}. "
        text = reason.casefold()
        if tool == PVP_SEEK_TOOL_NAME:
            if any(
                marker in text
                for marker in (
                    "route",
                    "travel",
                    "exit",
                    "boundary",
                    "no floor",
                    "could not reach",
                    "failed hop",
                )
            ):
                return (
                    prefix
                    + "The patrol did not complete, so this is route failure evidence—not target absence and "
                    "not insufficient combat power. Preserve the reported requested room, actual room, failed "
                    "hop, and broker reason. Do not vary room pairs that share this hop; relocate through a "
                    "verified working exit or wait for the route implementation/corpus to change."
                )
            if any(
                marker in text
                for marker in ("guild", "combat forbidden", "player combat forbidden", "safe_death", "safe death")
            ):
                return (
                    prefix
                    + "The room cannot support this PvP phase in the character's verified state. Exclude rooms marked "
                    "ROOM_GUILD_PK_ONLY unless guild eligibility is positively observed, and exclude ROOM_NO_PK, "
                    "ROOM_NO_COMBAT, and safe-death rooms for loot hunts. Use the controller's eligible route."
                )
            return (
                prefix
                + "The completed patrol did not acquire an eligible local player. Do not camp or repeat the same "
                "route unchanged. Choose at least two different grounded, PvP-eligible public room ids; global who "
                "only proves that a name is online and never proves the player is in the character's room."
            )
        if tool == PVP_TOOL_NAME and "visible" in text:
            return (
                prefix
                + "The named player was not freshly visible locally. If the durable goal is a fresh-local "
                "pvp_engage-only opportunity, end that stale opportunity and resume progression; never broaden "
                "it into who, pvp_seek, camping, or a replacement target. pvp_seek is permitted only for a "
                "specific hunt the operator explicitly requested."
            )
        if tool == "shop" and any(marker in text for marker in ("enough money", "insufficient fund", "cannot afford")):
            return (
                prefix
                + "The merchant refused for insufficient carried funds. Do not retry this purchase at any quantity "
                "until carried shillings increase. Inspect inventory, quote a different ordinary loot item with sell "
                "confirm:false and confirm an accepted offer, or travel to a verified bank and withdraw its confirmed "
                "balance; only then return and buy the remaining needed quantity."
            )
        if tool == "shop" and "identical evidence lookup" in text:
            return (
                prefix
                + "The merchant catalogue is already known. This read-only success is evidence, not progress: "
                "do not inspect the same stock again. Act on it with sufficient carried funds, use only a "
                "funding route explicitly still viable in current financial_context, use a verified direct "
                "capability, or replace the plan."
            )
        if tool == "shop" and is_inventory_capacity_refusal(reason):
            capacity = cls._inventory_capacity_context(observation)
            facts = [
                "The merchant reported carried-inventory capacity as the reason the requested item was not transferred."
            ]
            if capacity.get("known"):
                facts.append(
                    "Broker carry evidence at failure: "
                    f"items={capacity.get('items')}, "
                    f"weight={capacity.get('weight')}/{capacity.get('weight_max')}, "
                    f"bulk={capacity.get('bulk')}/{capacity.get('bulk_max')}, "
                    f"exact={capacity.get('exact')}."
                )
                if capacity.get("exact") is not True:
                    facts.append(
                        "The broker marks that load as a lower bound because one or more carried items were unweighed."
                    )
            else:
                facts.append("A broker carry estimate was not available in the failure observation.")
            facts.append("The unchanged purchase step's expected item-transfer observation was disproved.")
            return prefix + " ".join(facts)
        if tool == "sell_all" and "merchant bought zero" in text:
            return (
                prefix
                + "No property transferred and the call did not reduce the carried inventory load."
            )
        if tool in {"sell", "sell_all"} and cls._is_intrinsic_item_sale_refusal(
            text
        ):
            return (
                prefix
                + "The server rejected this exact item before checking whether the merchant "
                "wanted it (CanBeGivenToNPC=false). Do not try this item id with another "
                "merchant and do not repeat buyer discovery for it. Choose a different exact "
                "inventory item id or a non-sale funding route."
            )
        if tool == "sell" or (
            tool == "sell_all" and cls._is_merchant_sale_refusal(text)
        ):
            return (
                prefix
                + "Do not retry the same item with this merchant. Quote a materially different ordinary item or use "
                "merchant evidence to choose a different buyer."
            )
        if tool == "bank" and "no banker" in text:
            return (
                prefix
                + "Do not repeat the same bank mutation. Verify that a banker NPC is visible; if already in a named "
                "bank, use broker route/merchant evidence to choose a working bank endpoint or report the bank-tool "
                "compatibility failure. A bank-room name alone does not prove that currency moved."
            )
        if tool == "bank" and "identical evidence lookup" in text:
            return (
                prefix
                + "The bank balance is already established. Do not ask for it again in the unchanged state; "
                "if carried shillings are zero, launch the goal-owned bounded keeper from this sanctuary."
            )
        if tool == "cast" and any(
            marker in text
            for marker in (
                "nothing was spent",
                "cast did not happen",
                "zero mana",
            )
        ):
            return (
                prefix
                + "The spell packet produced no cast and the plan step remains incomplete. "
                "Keep the existing plan step, refresh posture and mana, wait for the shared "
                "attack/cast timer if necessary, and retry only after that live state changes."
            )
        if tool == "cast" and any(
            marker in text for marker in ("failed its roll", "half cost")
        ):
            return (
                prefix
                + "The spell resolved as a normal random failure, so the current plan step "
                "remains valid and incomplete. Recover enough mana and retry that same step; "
                "this outcome does not disprove the spell, reagents, or plan."
            )
        if tool == "cast" and is_inventory_capacity_refusal(reason):
            capacity = cls._inventory_capacity_context(observation)
            facts = [
                "The server explicitly refused to hand over the created item at the current carried load."
            ]
            if capacity.get("known"):
                facts.append(
                    "Broker carry evidence at failure: "
                    f"items={capacity.get('items')}, "
                    f"weight={capacity.get('weight')}/{capacity.get('weight_max')}, "
                    f"bulk={capacity.get('bulk')}/{capacity.get('bulk_max')}, "
                    f"exact={capacity.get('exact')}."
                )
            facts.append(
                "Free verified weight or bulk and refresh inventory before retrying; "
                "do not treat this as a need for more HP or combat training."
            )
            return prefix + " ".join(facts)
        if tool == "cast" and any(
            marker in text
            for marker in (
                "produced no verified carried item",
                "no authoritative created-item delta",
            )
        ):
            return (
                prefix
                + "Mana expenditure proves the spell ran, but there is no authoritative item "
                "delta or refusal. Treat the result as an observation/dependency ambiguity, "
                "refresh inventory and equipment, and preserve the plan step. Do not save a "
                "durable lesson or infer insufficient combat power from this result."
            )
        if tool == "prey":
            return (
                prefix
                + "The prey ranking is already grounded. Select its eligible creature once, then call "
                "hunting_grounds for that exact creature or launch the already-validated bounded keeper; do not "
                "ask prey to return the same ranking again."
            )
        if tool == "hunting_grounds":
            return (
                prefix
                + "The hunting-room evidence is already grounded. Use the exact non-quarantined numeric room id "
                "to launch the bounded keeper from sanctuary, or choose a materially different room; do not repeat "
                "the same location lookup."
            )
        if tool in MOVEMENT_TOOLS and any(
            marker in text
            for marker in (
                "kept ending up somewhere other than the planned square",
                "every heading refused",
                "no_move",
            )
        ):
            return (
                prefix
                + "The server was refusing movement state, not disproving the destination. Issue rest with "
                "stand:true, then retry with materially distinct route arguments (for example an explicit "
                "max_hops) or use go_through for one verified neighbouring exit."
            )
        if tool == "travel" and "travel route cycled" in text:
            return (
                prefix
                + "The broker repeated an edge and exhausted its hop budget, so the selected safe-ending route "
                "is not executable from the current room. Choose a different source-verified safe ending or "
                "use fresh map evidence for a materially different route; do not submit the same destination again."
            )
        return (
            prefix
            + "Do not repeat the same call unchanged. Use returned route, exit, inventory, or location evidence to "
            "choose a materially different tool or target; prefer authoritative numeric ids."
        )

    @staticmethod
    def _partial_progress_reason(
        result: Any,
        observation: dict[str, Any],
        *,
        tool: str | None = None,
        arguments: dict[str, Any] | None = None,
    ) -> str | None:
        """Recognize useful movement that did not fulfill the requested trip."""

        if tool != "travel" or not isinstance(result, dict):
            return None
        if result.get("arrived") is not False:
            return None
        before_room = deep_get(
            observation,
            "look.room.num",
            deep_get(observation, "status.room.num"),
        )
        after_room = deep_get(result, "now.room.num")
        if (
            before_room is None
            or after_room is None
            or str(before_room) == str(after_room)
        ):
            return None
        requested = next(
            (
                (arguments or {}).get(key)
                for key in ("to", "destination", "room", "room_id")
                if (arguments or {}).get(key) is not None
            ),
            deep_get(result, "destination.num"),
        )
        after_name = deep_get(result, "now.room.name")
        destination_text = (
            f" destination {requested}" if requested is not None else " the requested destination"
        )
        return (
            f"Travel advanced from room {before_room} to room {after_room}"
            + (f" ({after_name})" if after_name else "")
            + f" but did not reach{destination_text}."
        )[:500]

    @staticmethod
    def _no_progress_reason(
        result: Any,
        observation: dict[str, Any],
        *,
        tool: str | None = None,
        arguments: dict[str, Any] | None = None,
        after_observation: dict[str, Any] | None = None,
    ) -> str | None:
        if not isinstance(result, dict):
            return None
        if tool == "cast":
            if result.get("cast") is False:
                return str(
                    result.get("reason")
                    or result.get("what_the_mana_says")
                    or "broker reported that the requested spell was not cast"
                )[:500]
            mana_spent = result.get("mana_spent")
            mana_reading = str(result.get("what_the_mana_says") or "").strip()
            if (
                isinstance(mana_spent, (int, float))
                and not isinstance(mana_spent, bool)
                and mana_spent == 0
            ):
                return (
                    mana_reading
                    or "zero mana was spent; the requested cast did not happen"
                )[:500]
            if any(
                marker in mana_reading.casefold()
                for marker in ("failed its roll", "half cost")
            ):
                return mana_reading[:500]
            created = result.get("created")
            observes_created = (arguments or {}).get("observe_created") is True
            spell = " ".join(
                str((arguments or {}).get("spell") or result.get("spell") or "").split()
            )
            if (
                observes_created
                and isinstance(mana_spent, (int, float))
                and not isinstance(mana_spent, bool)
                and mana_spent > 0
                and isinstance(created, list)
                and not created
            ):
                messages = result.get("messages")
                if isinstance(messages, list) and messages:
                    return str(messages[0])[:500]
                return (
                    f"{spell or 'creation spell'} spent {mana_spent:g} mana but "
                    "produced no verified carried item"
                )[:500]
        if tool in PVP_TOOL_NAMES:
            outcome = str(result.get("outcome") or "")
            if outcome in {
                "target_not_visible",
                "target_escaped_before_attack",
                "target_offline",
                "target_not_found",
                "search_timeout",
                "route_unavailable",
                "travel_error",
                "no_eligible_search_rooms",
                "guild_required",
                "player_combat_forbidden",
                "combat_forbidden",
                "safe_death_ineligible",
                "attack_refused",
            }:
                return str(result.get("reason") or outcome.replace("_", " "))[:500]
        if tool == "bank" and after_observation is not None:
            # A completed bank RPC is not evidence that money moved.  Banker
            # dialogue can describe a refusal without using the small set of
            # generic refusal words below (for example, "you only have 133"),
            # and the broker may still return a normal result object.  Current
            # inventory is authoritative: a withdrawal must increase carried
            # currency and a deposit must decrease it.
            action = str(result.get("action") or "").casefold()
            before_currency = BotController._carried_currency(observation)
            after_currency = BotController._carried_currency(after_observation)
            wrong_direction = (
                action == "withdraw" and after_currency <= before_currency
            ) or (
                action == "deposit" and after_currency >= before_currency
            )
            if wrong_direction:
                banker_messages = result.get("banker_said")
                if isinstance(banker_messages, list) and banker_messages:
                    return str(banker_messages[0])[:500]
                note = result.get("note")
                if isinstance(note, str) and note.strip():
                    return note[:500]
                return (
                    f"carried shillings did not move in the requested direction after {action}: "
                    f"before {before_currency}, after {after_currency}"
                )[:500]
        if tool == "merchants":
            candidate_fields = [
                result.get(key)
                for key in ("matches", "buys_anything", "rules_mentioning")
                if isinstance(result.get(key), list)
            ]
            if candidate_fields and not any(candidate_fields):
                return (
                    "merchant lookup returned no candidate merchants for the "
                    "requested item/query"
                )
        if tool in {"map", KNOWLEDGE_TOOL_NAME} and result.get("matches") == []:
            return "authoritative lookup returned no matches"
        if tool == "map" and (arguments or {}).get("to") is not None:
            destination = deep_get(result, "destination.num")
            before_room = deep_get(
                observation,
                "look.room.num",
                deep_get(observation, "status.room.num"),
            )
            route = result.get("route")
            if (
                destination is not None
                and str(destination) != str(before_room)
                and (not isinstance(route, list) or not route)
            ):
                return (
                    f"map resolved destination room {destination} but found no route "
                    f"from current room {before_room} in the graph"
                )[:500]
        if tool == "shop" and isinstance(result.get("bought"), list):
            received = result.get("got")
            if not isinstance(received, list) or not received:
                messages = result.get("messages")
                if isinstance(messages, list) and messages:
                    return str(messages[0])[:500]
                return "purchase request yielded no items"
        if (
            tool == "act"
            and str((arguments or {}).get("verb") or "").casefold() in {"drop", "get"}
            and after_observation is not None
        ):
            before_inventory = deep_get(observation, "inventory.items", [])
            after_inventory = deep_get(after_observation, "inventory.items", [])
            if canonical_json(before_inventory) == canonical_json(after_inventory):
                messages = result.get("messages")
                if isinstance(messages, list) and messages:
                    return str(messages[0])[:500]
                verb = str((arguments or {}).get("verb") or "action")
                return f"carried inventory did not change after {verb}"[:500]
        if tool == "equip_best":
            # A completed broker call is not an equipped weapon.  The harness
            # deliberately returns a truthful result when every carried weapon
            # is broken or refused: wielding=null, verified=false, plus a useful
            # note.  Treating that RPC completion as action success refreshed
            # semantic liveness forever while the deterministic farm preflight
            # retried the same impossible equip step.
            wielding = result.get("wielding")
            has_weapon = (
                isinstance(wielding, str) and bool(wielding.strip())
            ) or (
                isinstance(wielding, (list, tuple, set)) and bool(wielding)
            )
            if not has_weapon:
                note = str(result.get("note") or "").strip()
                if note:
                    return note[:500]
                known_broken = result.get("known_broken")
                suffix = (
                    f"; {known_broken} carried weapon(s) are known broken"
                    if isinstance(known_broken, int) and known_broken > 0
                    else ""
                )
                return ("equip_best produced no wielded weapon" + suffix)[:500]
        if tool in {"sell", "sell_all"} and result.get("sold") is False:
            # A non-confirming sell call that returns a concrete counteroffer is
            # a useful quote, not a failed mutation.  No quote and no sale is
            # genuine non-progress even when the RPC itself completed normally.
            if result.get("offered_price") is None:
                messages = result.get("messages")
                if isinstance(messages, list) and messages:
                    return str(messages[0])[:500]
                return str(result.get("note") or "merchant did not buy the offered item")[:500]
        if tool == "sell_all" and isinstance(result.get("sold"), list):
            sold = result.get("sold")
            refused = result.get("refused")
            if not sold and isinstance(refused, list) and refused:
                refusal_facts = [
                    f"{str(item.get('name') or 'item')}: {str(item.get('why') or 'refused')}"
                    for item in refused[:4]
                    if isinstance(item, dict)
                ]
                detail = "; ".join(refusal_facts) or "merchant returned refusal evidence"
                return (
                    f"merchant bought zero of {len(refused)} offered inventory entries; {detail}"
                )[:500]
        if tool == "leave_raza" and result.get("left") is not True:
            return str(
                result.get("reason")
                or result.get("note")
                or "the Raza museum portal did not move the character outside the tutorial zone"
            )[:500]
        if tool == "travel" and result.get("arrived") is False:
            route_log = result.get("log")
            seen_edges: set[str] = set()
            repeated_edge: dict[str, Any] | None = None
            for entry in route_log if isinstance(route_log, list) else []:
                if not isinstance(entry, dict):
                    continue
                edge = canonical_json(
                    {"from": entry.get("from"), "to": entry.get("to")}
                )
                if edge in seen_edges:
                    repeated_edge = entry
                    break
                seen_edges.add(edge)
            if repeated_edge is not None:
                return (
                    "travel route cycled before reaching the destination; repeated "
                    f"{repeated_edge.get('from')!r} -> {repeated_edge.get('to')!r}; "
                    + str(result.get("reason") or "broker exhausted its hop budget")
                )[:500]
        failed_flag = any(result.get(name) is False for name in ("arrived", "left", "ok", "success"))
        if failed_flag:
            before_room = deep_get(observation, "look.room.num", deep_get(observation, "look.room.name"))
            after_room = deep_get(result, "now.room.num", deep_get(result, "now.room.name"))
            if before_room is not None and after_room is not None and str(before_room) != str(after_room):
                return None
            return str(result.get("reason") or "broker result reported that the requested outcome did not occur")[:500]
        banker_messages = result.get("banker_said")
        if isinstance(banker_messages, list):
            refusal = next(
                (
                    str(message)
                    for message in banker_messages
                    if any(marker in str(message).casefold() for marker in ("can't", "cannot", "couldn't", "no such"))
                ),
                None,
            )
            if refusal:
                return refusal[:500]
        note = result.get("note")
        if isinstance(note, str) and any(
            marker in note.casefold()
            for marker in (
                "banker said nothing",
                "no banker in this room",
                "no merchant in this room",
                "there is no merchant",
            )
        ):
            if after_observation is not None:
                before_inventory = deep_get(observation, "inventory.items", [])
                after_inventory = deep_get(after_observation, "inventory.items", [])
                if canonical_json(before_inventory) != canonical_json(after_inventory):
                    return None
                # A completed post-action observation with no inventory change
                # resolves the broker's ambiguous prose: the requested transfer
                # did not happen. Room-name verification authorizes attempting a
                # bank call; it is not evidence of economic success.
                return note[:500]
            # The broker can report its generic "banker said nothing" note even
            # when the server accepted a deposit or withdrawal.  At a verified
            # bank, treating that ambiguous note as a durable failure poisoned
            # retry memory and suppressed later valid transactions.  Location
            # preflight already prevents bank mutations elsewhere. Without a
            # post-action observation the note remains non-authoritative; the
            # next observation must still verify the economic result.
            room_name = str(
                deep_get(observation, "look.room.name", deep_get(observation, "look.room", ""))
                or ""
            ).casefold()
            if tool == "bank" and "bank" in room_name:
                return None
            return note[:500]
        messages = result.get("messages")
        if isinstance(messages, list):
            refusal_markers = (
                "unable to",
                "can't",
                "cannot",
                "couldn't",
                "don't have",
                "do not have",
                "not carrying",
                "that amount",
                "inventory is full",
                "pack is full",
                "too much to carry",
                "can't carry",
                "cannot carry",
                "not enough room",
                "nothing happens",
                "refused",
                "no such",
            )
            refusal = next(
                (
                    str(message)
                    for message in messages
                    if any(marker in str(message).casefold() for marker in refusal_markers)
                ),
                None,
            )
            if refusal:
                return refusal[:500]
        return None

    def _social_loop(self) -> None:
        try:
            while not self.stop_event.is_set():
                try:
                    self._social_tick()
                    self.dependencies["social"] = "healthy"
                except (BrokerError, ModelError) as exc:
                    self.dependencies["social"] = "degraded"
                    self._degrade("social", exc)
                except Exception as exc:
                    LOG.exception("social turn failed")
                    self.dependencies["social"] = "degraded"
                    self._degrade("social", exc)
                self.stop_event.wait(self.config.controller.social_poll_seconds)
        finally:
            # Storage owns one SQLite connection per thread.
            self.storage.close()

    def _social_tick(self) -> None:
        if self.offline_diagnostics or not self.config.controller.conversation_enabled:
            return
        if self._shutdown_requested.is_set() or self._game_action_active.is_set():
            return
        self._reconcile_conversation_listener()
        if self._shutdown_requested.is_set() or self._game_action_active.is_set():
            return
        look = self.broker.call_tool(
            "look",
            {"agent": self.config.game.agent, "cached": True},
            timeout=10,
        )
        if not isinstance(look, dict):
            look = {}
        self._greeting_turn(look)
        self._conversation_turn(look=look)

    def _reconcile_conversation_listener(self) -> None:
        now = time.time()
        if now - self._last_conversation_reconcile_at < 30:
            return
        status = self.broker.call_tool(
            "converse",
            {"agent": self.config.game.agent, "action": "status"},
            timeout=10,
        )
        policy = status.get("policy", {}) if isinstance(status, dict) else {}
        inbox = status.get("inbox", {}) if isinstance(status, dict) else {}
        desired = (
            status.get("attached") is True
            and status.get("running") is True
            and policy.get("ack") is False
            and policy.get("smallTalk") is False
            and policy.get("faceSpeaker") is False
            and policy.get("escalate") is True
            and inbox.get("reply_budget") == 20
        ) if isinstance(status, dict) else False
        if not desired:
            self._start_conversation_listener()
        self._last_conversation_reconcile_at = now

    @staticmethod
    def _speaker_key(name: Any, object_id: Any = None) -> str:
        cleaned = " ".join(str(name or "").split()).casefold()
        return f"name:{cleaned}" if cleaned else f"object:{object_id}"

    def _history_for(self, key: str) -> list[dict[str, Any]]:
        entries = self._conversation_history.get(key, [])
        if not isinstance(entries, list):
            return []
        return entries[-(self.config.controller.conversation_history_turns * 2) :]

    def _recent_conversation_message_count(
        self, key: str, *, now: float | None = None
    ) -> int:
        """Count retained incoming and delivered outgoing lines in the rolling window."""

        cutoff = (time.time() if now is None else now) - float(
            self.config.controller.conversation_window_seconds
        )
        count = 0
        for value in self._conversation_activity.get(key, []):
            occurred_at = str(value or "").strip()
            try:
                parsed = datetime.fromisoformat(
                    occurred_at.replace("Z", "+00:00")
                )
                if parsed.tzinfo is None:
                    parsed = parsed.replace(tzinfo=timezone.utc)
            except (TypeError, ValueError, OverflowError):
                continue
            if parsed.timestamp() >= cutoff:
                count += 1
        return count

    def _conversation_window_allows(
        self, key: str, *, additional_messages: int, now: float | None = None
    ) -> bool:
        return (
            self._recent_conversation_message_count(key, now=now)
            + max(0, int(additional_messages))
            <= self.config.controller.conversation_window_messages
        )

    def _remember_conversation(
        self,
        key: str,
        role: str,
        content: str,
        *,
        speaker_kind: str,
        speaker: Any = None,
    ) -> None:
        clean = " ".join(str(content).split())[:600]
        if not clean:
            return
        entries = self._conversation_history.setdefault(key, [])
        entry = {
            "role": role,
            "content": clean,
            "speaker_kind": speaker_kind,
            "at": timestamp(),
        }
        if speaker:
            entry["speaker"] = " ".join(str(speaker).split())[:100]
        entries.append(entry)
        del entries[: -self.config.controller.conversation_history_turns * 2]
        if len(self._conversation_history) > 100:
            oldest = min(
                self._conversation_history,
                key=lambda candidate: str((self._conversation_history[candidate] or [{}])[-1].get("at", "")),
            )
            self._conversation_history.pop(oldest, None)
        activity = self._conversation_activity.setdefault(key, [])
        activity.append(str(entry["at"]))
        del activity[:-200]
        if len(self._conversation_activity) > 100:
            oldest_activity = min(
                self._conversation_activity,
                key=lambda candidate: str(
                    (self._conversation_activity[candidate] or [""])[-1]
                ),
            )
            self._conversation_activity.pop(oldest_activity, None)
        self.storage.set_runtime("conversation_history_v1", self._conversation_history)
        self.storage.set_runtime("conversation_activity_v1", self._conversation_activity)

    @staticmethod
    def _visible_objects(look: dict[str, Any]) -> list[dict[str, Any]]:
        objects = look.get("objects", [])
        return [item for item in objects if isinstance(item, dict)] if isinstance(objects, list) else []

    def _speaker_kind(self, message: dict[str, Any], look: dict[str, Any]) -> str:
        source = message.get("from") if isinstance(message.get("from"), dict) else {}
        object_id = source.get("object_id")
        for item in self._visible_objects(look):
            if object_id is not None and str(item.get("id")) == str(object_id):
                return "player" if item.get("is_player") is True else "npc"
        return "player" if source.get("is_peer") is True else "unknown_in_game_speaker"

    def _public_context_for_look(self, look: dict[str, Any]) -> dict[str, Any]:
        value = self.public_game_context()
        value["room"] = deep_get(look, "room.name", look.get("room", value.get("room")))
        value["visible_players"] = [
            item.get("name")
            for item in self._visible_objects(look)
            if item.get("is_player") is True and item.get("name")
        ][:30]
        return value

    def _socially_unsafe(self, look: dict[str, Any]) -> bool:
        room = str(deep_get(look, "room.name", look.get("room", "")) or "")
        if "underworld" in room.casefold():
            return True
        health = deep_get(look, "vitals.health", {})
        if not isinstance(health, dict):
            return False
        maximum = health.get("max")
        current = health.get("current", health.get("value"))
        try:
            return bool(maximum) and float(current) / float(maximum) < self.config.policy.critical_health_fraction
        except (TypeError, ValueError, ZeroDivisionError):
            return False

    def _save_social_presence(self) -> None:
        self.storage.set_runtime(
            "social_presence_v1",
            {"greeted_at": self._greeted_at, "greeting_times": self._greeting_times[-60:]},
        )

    def _greeting_turn(self, look: dict[str, Any]) -> None:
        if not self.config.controller.proactive_greetings_enabled:
            return
        persona = self.storage.persona()
        if persona.get("version", 0) == 0:
            return

        now = time.time()
        self_name = str(
            deep_get(look, "self.name", self._character_name(self.last_observation or {}) or "")
        ).casefold()
        visible: dict[str, dict[str, Any]] = {}
        for item in self._visible_objects(look):
            if item.get("is_player") is not True or not item.get("name"):
                continue
            if str(item.get("name")).casefold() == self_name:
                continue
            key = self._speaker_key(item.get("name"), item.get("id"))
            visible[key] = {
                "name": str(item.get("name")),
                "object_id": item.get("id"),
                "distance": item.get("distance"),
                "speaker_kind": "player",
            }

        entered = set(visible) - self._visible_players
        self._visible_players = set(visible)
        for key in entered:
            if now - self._greeted_at.get(key, 0) >= self.config.controller.greeting_cooldown_seconds:
                self._pending_greetings[key] = visible[key]
        for key in list(self._pending_greetings):
            if key not in visible:
                self._pending_greetings.pop(key, None)

        self._greeting_times = [stamp for stamp in self._greeting_times if now - stamp < 60]
        if (
            not self._pending_greetings
            or len(self._greeting_times) >= self.config.controller.greetings_per_minute
            or self._socially_unsafe(look)
        ):
            return

        # At most one initiated line per social tick. The minute budget is generous,
        # but this spacing keeps a crowded-room arrival from becoming a burst of spam.
        key = next(iter(self._pending_greetings))
        encounter = self._pending_greetings[key]
        if not self._conversation_window_allows(
            key, additional_messages=1, now=now
        ):
            self._pending_greetings.pop(key, None)
            self._greeted_at[key] = now
            self._save_social_presence()
            self.storage.emit_event(
                "conversation.rate_limited",
                f"Skipped a greeting to {encounter['name']} at the rolling conversation limit",
                severity="info",
                interesting=False,
                data={
                    "speaker_kind": "player",
                    "window_messages": self.config.controller.conversation_window_messages,
                    "window_seconds": self.config.controller.conversation_window_seconds,
                },
            )
            return
        result = self.model.greet(
            persona=persona,
            encounter=encounter,
            context=self._public_context_for_look(look),
            history=self._history_for(key),
        )
        if result["ignore"] or not result["reply"]:
            self._pending_greetings.pop(key, None)
            self._greeted_at[key] = now
            self._save_social_presence()
            return
        if self._shutdown_requested.is_set() or self._game_action_active.is_set():
            # Keep the pending greeting for the next quiet social tick.
            return
        if contains_secret(result["reply"], self.config.secrets):
            self._pending_greetings.pop(key, None)
            self._greeted_at[key] = now
            self._save_social_presence()
            self.storage.emit_event(
                "security.egress_blocked",
                "Blocked an initiated greeting matching private credential material",
                severity="critical",
                interesting=True,
                data={"speaker_kind": "player"},
            )
            return

        delivered = self.broker.call_tool(
            "say",
            {"agent": self.config.game.agent, "type": "say", "text": result["reply"]},
            timeout=15,
            # Speech is ambient, not part of the one-game-action transaction.
            # The broker's per-session pacer safely sequences its packet.
            mutation=False,
        )
        self._pending_greetings.pop(key, None)
        self._greeted_at[key] = now
        self._greeting_times.append(now)
        self._save_social_presence()
        self._remember_conversation(
            key,
            "assistant",
            result["reply"],
            speaker_kind="player",
            speaker=encounter["name"],
        )
        self.storage.emit_event(
            "conversation.greeted",
            f"Greeted visible player {encounter['name']}",
            data={
                "player": encounter["name"],
                "persona_version": persona["version"],
                "delivery": redact(delivered),
            },
        )

    def _conversation_turn(self, *, look: dict[str, Any] | None = None) -> None:
        persona = self.storage.persona()
        if self.offline_diagnostics or not self.config.controller.conversation_enabled or persona.get("version", 0) == 0:
            return
        if self._shutdown_requested.is_set() or self._game_action_active.is_set():
            return
        look = look if isinstance(look, dict) else {}
        inbox = self.broker.call_tool(
            "inbox",
            {"agent": self.config.game.agent, "action": "read", "state": "escalated", "limit": 4},
            timeout=10,
        )
        for raw_message in inbox.get("messages", []) if isinstance(inbox, dict) else []:
            if not isinstance(raw_message, dict):
                continue
            message_id = raw_message.get("id")
            if not message_id:
                continue
            source = raw_message.get("from") if isinstance(raw_message.get("from"), dict) else {}
            speaker_kind = self._speaker_kind(raw_message, look)
            speaker_key = self._speaker_key(source.get("name"), source.get("object_id"))
            message = {**raw_message, "speaker_kind": speaker_kind}
            pending = self._pending_conversation_replies.get(str(message_id))
            if pending is not None and time.time() < float(pending.get("retry_after", 0) or 0):
                continue

            if pending is None:
                incoming = str(message.get("utterance", ""))
                history = self._history_for(speaker_key)
                allowed = self._conversation_window_allows(
                    speaker_key,
                    # Reserve room for this incoming line and MANIAC's reply.
                    additional_messages=2,
                )
                self._remember_conversation(
                    speaker_key,
                    "speaker",
                    incoming,
                    speaker_kind=speaker_kind,
                    speaker=source.get("name"),
                )
                if not allowed:
                    self.broker.call_tool(
                        "inbox",
                        {
                            "agent": self.config.game.agent,
                            "action": "resolve",
                            "id": message_id,
                            "state": "refused",
                            "note": (
                                "rolling conversation limit reached "
                                f"({self.config.controller.conversation_window_messages} "
                                "messages per "
                                f"{int(self.config.controller.conversation_window_seconds)}s)"
                            ),
                        },
                        timeout=10,
                        mutation=False,
                    )
                    self.storage.emit_event(
                        "conversation.rate_limited",
                        "Declined dialogue at the per-speaker rolling conversation limit",
                        severity="info",
                        interesting=False,
                        data={
                            "inbox_item_id": message_id,
                            "speaker_kind": speaker_kind,
                            "window_messages": self.config.controller.conversation_window_messages,
                            "window_seconds": self.config.controller.conversation_window_seconds,
                        },
                    )
                    continue
                result = self.model.respond(
                    persona=persona,
                    message=redact(message),
                    context=self._public_context_for_look(look),
                    history=history,
                )
                if contains_secret(result["reply"], self.config.secrets):
                    result = {"reply": "", "ignore": True, "reason": "credential egress filter"}
                    self.storage.emit_event(
                        "security.egress_blocked",
                        "Blocked a conversational reply matching private credential material",
                        severity="critical",
                        interesting=True,
                        data={"inbox_item_id": message_id, "speaker_kind": speaker_kind},
                    )
                if result["ignore"] or not result["reply"]:
                    self.broker.call_tool(
                        "inbox",
                        {
                            "agent": self.config.game.agent,
                            "action": "resolve",
                            "id": message_id,
                            "state": "refused",
                            "note": result["reason"][:200],
                        },
                        timeout=10,
                        mutation=False,
                    )
                    self.storage.emit_event(
                        "conversation.responded",
                        "Considered dialogue from an in-game speaker",
                        data={
                            "inbox_item_id": message_id,
                            "persona_version": persona["version"],
                            "speaker_kind": speaker_kind,
                            "ignored": True,
                        },
                    )
                    continue
                pending = {
                    "reply": result["reply"],
                    "speaker_key": speaker_key,
                    "speaker": source.get("name"),
                    "speaker_kind": speaker_kind,
                    "persona_version": persona["version"],
                    "attempts": 0,
                    "retry_after": 0.0,
                }

            if self._shutdown_requested.is_set() or self._game_action_active.is_set():
                self._pending_conversation_replies[str(message_id)] = pending
                continue
            if not self._conversation_window_allows(
                str(pending["speaker_key"]), additional_messages=1
            ):
                self.broker.call_tool(
                    "inbox",
                    {
                        "agent": self.config.game.agent,
                        "action": "resolve",
                        "id": message_id,
                        "state": "refused",
                        "note": "rolling conversation limit reached before delivery",
                    },
                    timeout=10,
                    mutation=False,
                )
                self._pending_conversation_replies.pop(str(message_id), None)
                self.storage.emit_event(
                    "conversation.rate_limited",
                    "Withheld a queued reply at the per-speaker rolling conversation limit",
                    severity="info",
                    interesting=False,
                    data={
                        "inbox_item_id": message_id,
                        "speaker_kind": pending["speaker_kind"],
                        "window_messages": self.config.controller.conversation_window_messages,
                        "window_seconds": self.config.controller.conversation_window_seconds,
                    },
                )
                continue
            delivery = self.broker.call_tool(
                "inbox",
                {
                    "agent": self.config.game.agent,
                    "action": "reply",
                    "id": message_id,
                    "text": pending["reply"],
                },
                timeout=15,
                mutation=False,
            )
            if isinstance(delivery, dict) and delivery.get("retry"):
                attempts = int(pending.get("attempts", 0) or 0) + 1
                pending["attempts"] = attempts
                pending["retry_after"] = time.time() + min(60.0, 2.0 ** attempts * 2.0)
                if attempts >= 3:
                    self.broker.call_tool(
                        "inbox",
                        {
                            "agent": self.config.game.agent,
                            "action": "resolve",
                            "id": message_id,
                            "state": "refused",
                            "note": "dialogue delivery exhausted after bounded retries",
                        },
                        timeout=10,
                        mutation=False,
                    )
                    self._pending_conversation_replies.pop(str(message_id), None)
                    self.storage.emit_event(
                        "conversation.delivery_abandoned",
                        "Stopped retrying an undeliverable dialogue reply",
                        severity="notice",
                        interesting=False,
                        data={"inbox_item_id": message_id, "attempts": attempts, "speaker_kind": pending["speaker_kind"]},
                    )
                    continue
                self._pending_conversation_replies[str(message_id)] = pending
                continue
            self._pending_conversation_replies.pop(str(message_id), None)
            replied = not isinstance(delivery, dict) or delivery.get("replied") is not False
            if replied:
                self._remember_conversation(
                    str(pending["speaker_key"]),
                    "assistant",
                    str(pending["reply"]),
                    speaker_kind=str(pending["speaker_kind"]),
                    speaker=pending.get("speaker"),
                )
            else:
                self.broker.call_tool(
                    "inbox",
                    {
                        "agent": self.config.game.agent,
                        "action": "resolve",
                        "id": message_id,
                        "state": "refused",
                        "note": str(delivery.get("why", "reply could not be delivered"))[:200],
                    },
                    timeout=10,
                    mutation=False,
                )
            self.storage.emit_event(
                "conversation.responded",
                "Responded to dialogue from an in-game speaker" if replied else "Could not deliver dialogue reply",
                data={
                    "inbox_item_id": message_id,
                    "persona_version": pending["persona_version"],
                    "speaker_kind": pending["speaker_kind"],
                    "ignored": False,
                    "delivered": replied,
                },
            )

    def _degrade(self, dependency: str, exc: Exception) -> None:
        self.state = "degraded"
        warning = f"{dependency}: {str(exc)[:300]}"
        self.warnings = [warning]
        if self._active_degradations.get(dependency) == warning:
            return
        self._active_degradations[dependency] = warning
        goal = self.storage.active_goal()
        self.storage.emit_event(
            f"dependency.{dependency}.unhealthy",
            warning,
            severity="warning",
            interesting=True,
            goal_id=goal and goal["id"],
        )

    def _planner_feedback(self, goal: dict[str, Any]) -> dict[str, Any] | None:
        value = self.storage.get_runtime("planner_feedback")
        if not isinstance(value, dict) or value.get("goal_id") != goal.get("id"):
            return None
        blocked_action = value.get("blocked_action")
        if isinstance(blocked_action, dict) and self.last_observation:
            tool = str(blocked_action.get("tool") or "")
            arguments = blocked_action.get("arguments")
            if tool and isinstance(arguments, dict):
                blocked = self._blocked_action(goal, self.last_observation, tool, arguments)
                if blocked and blocked.get("reason"):
                    # Upgrade persisted feedback created by older controller
                    # versions.  Otherwise a restart can preserve the generic
                    # "try different arguments" wording that encourages models
                    # to cycle unaffordable quantities instead of satisfying the
                    # missing-funds prerequisite.
                    blocked_reason = str(blocked["reason"])
                    guidance = self._no_progress_guidance(
                        tool,
                        blocked_reason,
                        repeated=True,
                        observation=self.last_observation,
                    )
                    failure_context = self._failure_context(
                        tool,
                        blocked_reason,
                        self.last_observation,
                    )
                    if value.get("message") != guidance or value.get("failure_context") != failure_context:
                        value = {
                            **value,
                            "message": guidance,
                            "failure_context": redact(failure_context) if failure_context else None,
                            "updated_at": timestamp(),
                        }
                        self.storage.set_runtime("planner_feedback", value)
        return value

    def _set_planner_feedback(
        self,
        goal: dict[str, Any],
        message: str,
        *,
        consecutive_waits: int = 0,
        consecutive_plan_rejections: int = 0,
        consecutive_invalid_actions: int = 0,
        blocked_action: dict[str, Any] | None = None,
        safety_suppression: dict[str, Any] | None = None,
        failure_context: dict[str, Any] | None = None,
    ) -> None:
        self.storage.set_runtime(
            "planner_feedback",
            {
                "goal_id": goal["id"],
                "message": message[:1000],
                "consecutive_waits": consecutive_waits,
                "consecutive_plan_rejections": consecutive_plan_rejections,
                "consecutive_invalid_actions": consecutive_invalid_actions,
                "blocked_action": blocked_action,
                "safety_suppression": safety_suppression,
                "failure_context": redact(failure_context) if failure_context else None,
                "updated_at": timestamp(),
            },
        )

    def _clear_planner_feedback(self) -> None:
        self.storage.set_runtime("planner_feedback", None)

    def _record_safety_suppression(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        tool: str,
        arguments: dict[str, Any],
        blockers: list[dict[str, Any]],
    ) -> dict[str, Any]:
        room = self._observation_room(observation)
        blocker_kinds = sorted(
            str(item.get("kind") or "unknown")
            for item in blockers
            if isinstance(item, dict)
        )
        signature = canonical_json(
            {
                "goal_id": goal.get("id"),
                "tool": tool,
                "arguments": redact(arguments),
                "room": room,
                "blocker_kinds": blocker_kinds,
            }
        )
        now_unix = time.time()
        now_text = timestamp()
        prior = self.storage.get_runtime("safety_suppression_v1", {})
        same = (
            isinstance(prior, dict)
            and prior.get("goal_id") == goal.get("id")
            and prior.get("signature") == signature
        )
        first_unix = (
            float(prior.get("first_blocked_unix", now_unix))
            if same
            else now_unix
        )
        value = {
            "goal_id": goal["id"],
            "signature": signature,
            "tool": tool,
            "room": room,
            "blocker_kinds": blocker_kinds,
            "same_blocker_count": int(prior.get("same_blocker_count", 0) or 0) + 1
            if same
            else 1,
            "first_blocked_at": prior.get("first_blocked_at", now_text)
            if same
            else now_text,
            "first_blocked_unix": first_unix,
            "last_blocked_at": now_text,
            "blocked_for_seconds": round(max(0.0, now_unix - first_unix), 1),
        }
        self.storage.set_runtime("safety_suppression_v1", value)
        return {
            key: value[key]
            for key in (
                "same_blocker_count",
                "first_blocked_at",
                "last_blocked_at",
                "blocked_for_seconds",
                "blocker_kinds",
            )
        }

    def _clear_safety_suppression(self, goal_id: str) -> None:
        value = self.storage.get_runtime("safety_suppression_v1")
        if isinstance(value, dict) and value.get("goal_id") == goal_id:
            self.storage.set_runtime("safety_suppression_v1", None)

    @staticmethod
    def _observation_room(observation: dict[str, Any]) -> Any:
        return deep_get(observation, "look.room.num", deep_get(observation, "look.room.name"))

    @staticmethod
    def _carried_currency(observation: dict[str, Any]) -> int:
        items = deep_get(observation, "inventory.items", [])
        total = 0
        for item in items if isinstance(items, list) else []:
            if not isinstance(item, dict) or "shilling" not in str(item.get("name") or "").casefold():
                continue
            amount = item.get("amount", item.get("quantity", item.get("count", 1)))
            total += int(amount) if isinstance(amount, (int, float)) and amount > 0 else 1
        return total

    def _financial_context(self, observation: dict[str, Any]) -> dict[str, Any]:
        """Summarize carried wealth for planning without turning it into a gate.

        Inventory valuation is deliberately best effort.  The knowledge corpus
        contains source-derived base values for many items, while the live
        server's sale price can differ and some items have no known value.
        """

        raw_items = deep_get(observation, "inventory.items", [])
        items = [item for item in raw_items if isinstance(item, dict)] if isinstance(raw_items, list) else []
        active_goal = self.storage.active_goal()
        npc_transfer_restricted_ids = self._intrinsically_unsellable_item_ids(
            active_goal, observation
        )
        npc_transfer_restricted_names = self._intrinsically_unsellable_item_names(
            active_goal, observation
        )
        protected_sale_ids, protected_sale_names = (
            self._protected_sale_inventory(observation)
        )
        merchant_refusals = self._merchant_sale_refusals(
            active_goal, observation
        )
        sale_exhausted_items = self._sale_exhausted_items(merchant_refusals)
        sale_exhausted_ids = {
            str(item.get("item_id") or "").casefold()
            for item in sale_exhausted_items
            if item.get("item_id")
        }
        bank_accounts = self._latest_bank_balance_context()
        raw_sell_quotes = self.storage.get_runtime(
            "prepare_combat_sell_quotes_v1", []
        )
        sell_quotes = (
            [item for item in raw_sell_quotes if isinstance(item, dict)]
            if isinstance(raw_sell_quotes, list)
            else []
        )
        signature = canonical_json(
            {
                "items": items,
                "npc_transfer_restricted_ids": sorted(
                    npc_transfer_restricted_ids
                ),
                "npc_transfer_restricted_names": sorted(
                    npc_transfer_restricted_names
                ),
                "protected_sale_ids": sorted(protected_sale_ids),
                "protected_sale_names": sorted(protected_sale_names),
                "merchant_refusals": merchant_refusals,
                "sale_exhausted_items": sale_exhausted_items,
                "bank_accounts": bank_accounts,
                "sell_quotes": sell_quotes,
            }
        )
        if (
            signature == self._financial_context_signature
            and self._financial_context_value is not None
        ):
            return self._financial_context_value

        carried_shillings = self._carried_currency(observation)
        known_inventory_value = 0.0
        known_liquidatable_inventory_value = 0.0
        valued_items: list[dict[str, Any]] = []
        unknown_value_items: list[dict[str, Any]] = []
        npc_transfer_restricted_items: list[dict[str, Any]] = []
        protected_sale_items: list[dict[str, Any]] = []
        sale_eligible_items: list[dict[str, Any]] = []
        sale_eligible_details: list[dict[str, Any]] = []
        sale_eligible_by_id: dict[str, dict[str, Any]] = {}
        for item in items:
            name = " ".join(str(item.get("name") or "").split())
            if not name or "shilling" in name.casefold():
                continue
            item_id = item.get("id", item.get("object_id"))
            item_id_key = (
                str(item_id).strip().casefold()
                if item_id is not None
                else None
            )
            protected_loadout = (
                item_id_key in protected_sale_ids
                if item_id_key is not None
                else name.casefold() in protected_sale_names
            )
            transfer_restricted = (
                item_id_key in npc_transfer_restricted_ids
                if item_id_key is not None
                else name.casefold() in npc_transfer_restricted_names
            )
            sale_exhausted = bool(
                item_id_key and item_id_key in sale_exhausted_ids
            )
            if protected_loadout:
                protected_sale_items.append(
                    {
                        "id": item_id,
                        "name": name,
                        "reason": "equipped or in-use active loadout",
                    }
                )
            if (
                not protected_loadout
                and not transfer_restricted
                and not sale_exhausted
            ):
                sale_eligible_items.append(item)
            raw_quantity = item.get("amount", item.get("quantity", item.get("count", 1)))
            quantity = (
                int(raw_quantity)
                if isinstance(raw_quantity, (int, float))
                and not isinstance(raw_quantity, bool)
                and raw_quantity > 0
                else 1
            )
            if (
                not protected_loadout
                and not transfer_restricted
                and not sale_exhausted
            ):
                sale_eligible_details.append(
                    {"id": item_id, "name": name, "quantity": quantity}
                )
            if (
                item_id_key
                and not protected_loadout
                and not transfer_restricted
                and not sale_exhausted
            ):
                sale_eligible_by_id[item_id_key] = {
                    "id": item_id,
                    "name": name,
                    "quantity": quantity,
                }
            valuation = self.knowledge.item_valuation(name)
            unit_value = valuation.get("unit_value")
            basis = valuation.get("basis")
            source_ref = valuation.get("source_ref")
            if not isinstance(unit_value, (int, float)) or isinstance(unit_value, bool):
                live_value = item.get("value")
                if isinstance(live_value, (int, float)) and not isinstance(live_value, bool):
                    unit_value = live_value
                    basis = "live inventory value reported by the broker"
                    source_ref = None
            if isinstance(unit_value, (int, float)) and not isinstance(unit_value, bool):
                subtotal = float(unit_value) * quantity
                known_inventory_value += subtotal
                if (
                    not transfer_restricted
                    and not protected_loadout
                    and not sale_exhausted
                ):
                    known_liquidatable_inventory_value += subtotal
                valued_items.append(
                    {
                        "id": item_id,
                        "name": valuation.get("canonical_name") or name,
                        "quantity": quantity,
                        "unit_value": unit_value,
                        "subtotal": int(subtotal) if subtotal.is_integer() else subtotal,
                        "basis": basis,
                        "source_ref": source_ref,
                        "npc_transferable": not transfer_restricted,
                        "sale_protected": protected_loadout,
                        "sale_evidence_exhausted": sale_exhausted,
                        "liquidatable": not transfer_restricted
                        and not protected_loadout
                        and not sale_exhausted,
                    }
                )
                if transfer_restricted:
                    npc_transfer_restricted_items.append(
                        {
                            "id": item_id,
                            "name": valuation.get("canonical_name") or name,
                            "reason": (
                                "live server refusal proved CanBeGivenToNPC=false "
                                "for this exact instance"
                            ),
                        }
                    )
            else:
                unknown_value_items.append(
                    {
                        "name": name,
                        "quantity": quantity,
                        "reason": valuation.get("status", "value_unknown"),
                        "sale_evidence_exhausted": sale_exhausted,
                    }
                )

        inventory_total: int | float = (
            int(known_inventory_value)
            if known_inventory_value.is_integer()
            else known_inventory_value
        )
        liquidatable_total: int | float = (
            int(known_liquidatable_inventory_value)
            if known_liquidatable_inventory_value.is_integer()
            else known_liquidatable_inventory_value
        )
        known_total: int | float = carried_shillings + known_inventory_value
        if isinstance(known_total, float) and known_total.is_integer():
            known_total = int(known_total)
        raw_buyers = (
            self.knowledge.buyer_candidates(
                sale_eligible_items,
                per_item_limit=10,
            )
            if hasattr(self.knowledge, "buyer_candidates")
            else []
        )
        buyer_candidates, rejected_buyer_candidates = (
            self._filter_refused_buyer_candidates(
                raw_buyers,
                merchant_refusals,
            )
        )
        valid_live_sell_quotes: list[dict[str, Any]] = []
        quoted_item_ids: set[str] = set()
        for quote in sell_quotes:
            offered_price = quote.get("offered_price")
            quote_items = quote.get("items")
            if (
                not isinstance(offered_price, (int, float))
                or isinstance(offered_price, bool)
                or offered_price <= 0
                or not isinstance(quote_items, list)
                or not quote_items
            ):
                continue
            item_ids: set[str] = set()
            normalized_items: list[dict[str, Any]] = []
            valid = True
            for quoted_item in quote_items:
                if not isinstance(quoted_item, dict):
                    valid = False
                    break
                quoted_id = quoted_item.get("id", quoted_item.get("object_id"))
                quoted_id_key = (
                    str(quoted_id).strip().casefold()
                    if quoted_id is not None
                    else ""
                )
                current = sale_eligible_by_id.get(quoted_id_key)
                inventory_quantity_at_quote = quoted_item.get(
                    "inventory_quantity", quoted_item.get("quantity")
                )
                offered_quantity = quoted_item.get("quantity")
                if (
                    not quoted_id_key
                    or current is None
                    or str(current.get("name") or "").casefold()
                    != str(quoted_item.get("name") or "").casefold()
                    or current.get("quantity") != inventory_quantity_at_quote
                    or not isinstance(offered_quantity, int)
                    or isinstance(offered_quantity, bool)
                    or offered_quantity <= 0
                    or offered_quantity > current.get("quantity", 0)
                ):
                    valid = False
                    break
                item_ids.add(quoted_id_key)
                normalized_items.append(
                    {
                        **current,
                        "quantity": offered_quantity,
                        "inventory_quantity": current.get("quantity"),
                    }
                )
            if not valid or not item_ids:
                continue
            valid_live_sell_quotes.append(
                {
                    "offered_price": offered_price,
                    "quoted_at": quote.get("quoted_at"),
                    "merchant_id": quote.get("merchant_id"),
                    "room_id": quote.get("room_id"),
                    "items": normalized_items,
                    "_item_ids": item_ids,
                }
            )

        # Quotes can overlap. Count a conservative disjoint subset so one
        # carried object is never represented twice in the confirmed total.
        confirmed_live_quote_value = 0.0
        counted_item_ids: set[str] = set()
        for quote in sorted(
            valid_live_sell_quotes,
            key=lambda item: float(item.get("offered_price", 0)),
            reverse=True,
        ):
            quote_ids = quote.pop("_item_ids")
            counted = not bool(quote_ids & counted_item_ids)
            quote["counted_in_confirmed_total"] = counted
            if counted:
                counted_item_ids.update(quote_ids)
                confirmed_live_quote_value += float(quote["offered_price"])
            for quoted_item in quote.get("items", []):
                if (
                    quoted_item.get("quantity")
                    == quoted_item.get("inventory_quantity")
                    and quoted_item.get("id") is not None
                ):
                    quoted_item_ids.add(
                        str(quoted_item["id"]).strip().casefold()
                    )

        confirmed_quote_total: int | float = (
            int(confirmed_live_quote_value)
            if confirmed_live_quote_value.is_integer()
            else confirmed_live_quote_value
        )
        unquoted_liquidatable_items = [
            item
            for item in sale_eligible_details
            if item.get("id") is None
            or str(item["id"]).strip().casefold() not in quoted_item_ids
        ]
        has_grounded_buyer = any(
            isinstance(item, dict)
            and isinstance(item.get("candidates"), list)
            and bool(item["candidates"])
            for item in buyer_candidates
        )
        if confirmed_quote_total:
            liquidation_state = "live_quotes_available"
            liquidation_interpretation = (
                "At least one exact current inventory selection has a positive live "
                "merchant quote. Re-quote immediately before a mutating sale."
            )
        elif sale_eligible_items and has_grounded_buyer:
            liquidation_state = "quote_required"
            liquidation_interpretation = (
                "Sale-eligible inventory and grounded buyer candidates exist, but no "
                "positive live quote is recorded for the unchanged exact items. Zero "
                "confirmed quote value means unquoted, not worthless."
            )
        elif sale_eligible_items:
            liquidation_state = "buyer_discovery_required"
            liquidation_interpretation = (
                "Sale-eligible inventory exists, but no currently usable grounded buyer "
                "placement is known. Seek new buyer evidence or use another funding route."
            )
        else:
            liquidation_state = "no_sale_eligible_inventory"
            liquidation_interpretation = (
                "No current inventory instance is eligible for sale after loadout and "
                "live negative-evidence protections."
            )
        value = {
            "carried_shillings": carried_shillings,
            "source_estimated_inventory_value": inventory_total,
            "source_estimated_liquidatable_inventory_value": liquidatable_total,
            "confirmed_live_quote_liquidatable_value": confirmed_quote_total,
            "known_inventory_item_value": inventory_total,
            "known_liquidatable_inventory_value": liquidatable_total,
            "known_total_carried_value": known_total,
            "valuation_complete": not unknown_value_items,
            "valued_items": valued_items[:30],
            "unknown_value_items": unknown_value_items[:30],
            "unquoted_liquidatable_items": unquoted_liquidatable_items[:30],
            "valid_live_sell_quotes": valid_live_sell_quotes[:30],
            "liquidation_status": {
                "state": liquidation_state,
                "interpretation": liquidation_interpretation,
            },
            "npc_transfer_restricted_items": npc_transfer_restricted_items[:30],
            "protected_sale_items": protected_sale_items[:30],
            "npc_transfer_rules": [
                {
                    "source": "Create Weapon",
                    "rule": (
                        "Every created weapon receives IA_MADE and cannot be given "
                        "to an NPC, so it is equipment only and never sale funding."
                    ),
                    "source_ref": "CreateWeapon.Cast / Item.CanBeGivenToNPC",
                }
            ],
            "bank_accounts": bank_accounts,
            "buyer_candidates": buyer_candidates,
            "rejected_buyer_candidates": rejected_buyer_candidates,
            "merchant_sale_refusals": merchant_refusals,
            "sale_exhausted_items": sale_exhausted_items,
            "valuation_note": (
                "source_estimated_* and the legacy known_* value fields are best-effort "
                "base/live inventory estimates, not spendable cash or guaranteed resale. "
                "source_estimated_liquidatable_inventory_value excludes equipped/in-use loadout "
                "items and exact instances the live server proved cannot be given to an "
                "NPC and exact carried items whose source sale hypothesis was disproved "
                f"by {SALE_BUYER_REFUSAL_LIMIT} independent live buyers. Source buyer "
                "candidates exclude exact item/merchant/room placements already refused "
                "live. confirmed_live_quote_liquidatable_value contains only positive live "
                "quotes whose exact item ids, names, and quantities still match inventory; "
                "zero means no current quote evidence, not zero market value. Unknown items "
                "mean the source estimate may be higher."
            ),
            "banking_policy": {
                "mode": "planner_discretion",
                "never_blocks_travel_or_combat": True,
                "canonical_tos_bank_room_id": TOS_BANK_ROOM_ID,
                "funding_guidance": (
                    "A last-known positive account balance is a grounded funding option. "
                    "When a sale would consume inventory required by the active phase, "
                    "prefer traveling to the bank, live-checking/withdrawing funds, and "
                    "preserving that required inventory."
                ),
            },
        }
        self._financial_context_signature = signature
        self._financial_context_value = value
        return value

    def _latest_bank_balance_context(self) -> list[dict[str, Any]]:
        """Recover the newest durable balance evidence for each known account."""

        cached = self.storage.get_runtime(BANK_BALANCE_CONTEXT_RUNTIME_KEY, [])
        accounts: dict[str, dict[str, Any]] = {
            str(account.get("account") or ""): dict(account)
            for account in cached
            if isinstance(account, dict) and account.get("account")
        } if isinstance(cached, list) else {}
        for event in reversed(
            self.storage.latest_events(limit=200, kinds=["action.succeeded"])
        ):
            data = event.get("data")
            if not isinstance(data, dict) or data.get("tool") != "bank":
                continue
            result = data.get("result")
            if not isinstance(result, dict):
                continue
            balance = result.get("balance")
            if not isinstance(balance, (int, float)) or isinstance(balance, bool):
                continue
            account = " ".join(
                str(result.get("account") or "shared mainland account").split()
            )
            existing = accounts.get(account)
            if (
                isinstance(existing, dict)
                and str(existing.get("recorded_at") or "")
                >= str(event.get("occurred_at") or "")
            ):
                continue
            accounts[account] = {
                "account": account,
                "last_known_balance": int(balance),
                "recorded_at": event.get("occurred_at"),
                "source": (
                    "live banker reply"
                    if result.get("balance_observed") is True
                    else "broker-maintained balance updated by the completed bank action"
                ),
                "last_action": result.get("action"),
                "requires_live_check_before_exact_transfer": True,
            }
        value = sorted(
            accounts.values(),
            key=lambda account: str(account.get("recorded_at") or ""),
            reverse=True,
        )
        if value != cached:
            self.storage.set_runtime(BANK_BALANCE_CONTEXT_RUNTIME_KEY, value)
        return value

    @staticmethod
    def _sale_item_ids(arguments: dict[str, Any]) -> set[str]:
        raw_items = arguments.get("items")
        values = raw_items if isinstance(raw_items, list) else [raw_items]
        result: set[str] = set()
        for value in values:
            item_id = value.get("id") if isinstance(value, dict) else value
            if item_id is not None and str(item_id).strip():
                result.add(str(item_id).strip().casefold())
        return result

    @staticmethod
    def _merchant_speaker_name(reason: Any) -> str | None:
        """Recover the live NPC name from an authoritative refusal message."""

        text = " ".join(str(reason or "").split())
        match = re.match(
            r'^\s*([^\"]+?)\s+(?:tells\s+you|says)(?:\s*,)?\s*[,:]?\s*[\"]',
            text,
            re.IGNORECASE,
        )
        if match is None:
            return None
        name = match.group(1).strip(" ,:'\"")
        return name or None

    @staticmethod
    def _protected_sale_inventory(
        observation: dict[str, Any],
    ) -> tuple[set[str], set[str]]:
        """Return exact carried items protected by the active loadout.

        Source value and NPC transferability do not make equipped gear
        liquidatable. Prefer exact ids so an unequipped duplicate with the same
        name remains eligible. A name-only equipment record protects the name
        only when there is one matching carried instance.
        """

        raw_items = deep_get(observation, "inventory.items", [])
        items = raw_items if isinstance(raw_items, list) else []
        equipped = deep_get(observation, "equipment.equipped", [])
        equipped = equipped if isinstance(equipped, list) else []
        protected_ids: set[str] = set()
        unresolved_names: set[str] = set()
        counts: dict[str, int] = {}
        for item in items:
            if not isinstance(item, dict):
                continue
            name = " ".join(str(item.get("name") or "").split()).casefold()
            if name:
                counts[name] = counts.get(name, 0) + 1
            if item.get("in_use") is True or item.get("equipped") is True:
                item_id = item.get("id", item.get("object_id"))
                if item_id is not None:
                    protected_ids.add(str(item_id).strip().casefold())
                elif name:
                    unresolved_names.add(name)
        for item in equipped:
            if not isinstance(item, dict):
                continue
            item_id = item.get("id", item.get("object_id"))
            name = " ".join(str(item.get("name") or "").split()).casefold()
            if item_id is not None:
                protected_ids.add(str(item_id).strip().casefold())
            elif name:
                unresolved_names.add(name)
        protected_names = {
            name for name in unresolved_names if counts.get(name, 0) == 1
        }
        return protected_ids, protected_names

    def _merchant_sale_refusals(
        self,
        goal: dict[str, Any] | None,
        observation: dict[str, Any],
    ) -> list[dict[str, Any]]:
        """Normalize live buyer refusals across NPC ids and source classes."""

        if not isinstance(goal, dict):
            return []
        raw_items = deep_get(observation, "inventory.items", [])
        items = [item for item in raw_items if isinstance(item, dict)] if isinstance(raw_items, list) else []
        source_buyers = (
            self.knowledge.buyer_candidates(items, per_item_limit=10)
            if hasattr(self.knowledge, "buyer_candidates")
            else []
        )
        buyer_rows = {
            " ".join(str(row.get("item") or "").split()).casefold(): row
            for row in source_buyers
            if isinstance(row, dict) and row.get("item")
        }
        result: list[dict[str, Any]] = []
        entries = self.storage.get_runtime("blocked_actions", [])
        for entry in entries if isinstance(entries, list) else []:
            if (
                not isinstance(entry, dict)
                or entry.get("goal_id") != goal.get("id")
                or entry.get("tool") not in {"sell", "sell_all"}
                or deep_get(
                    self._failure_context(
                        str(entry.get("tool") or ""),
                        str(entry.get("reason") or ""),
                        observation,
                    ),
                    "kind",
                )
                != "merchant_rejected_sale"
            ):
                continue
            arguments = entry.get("arguments")
            arguments = arguments if isinstance(arguments, dict) else {}
            item_names = {
                " ".join(str(value).split()).casefold()
                for value in entry.get("offered_item_names", [])
                if str(value).strip()
            } if isinstance(entry.get("offered_item_names"), list) else set()
            item_names.update(
                self._sale_selected_item_names(arguments, observation)
            )
            room = entry.get("room")
            identity = entry.get("merchant_identity")
            identity = identity if isinstance(identity, dict) else {}
            live_name = str(
                identity.get("live_name")
                or self._merchant_speaker_name(entry.get("reason"))
                or ""
            ).strip()
            live_name_key = " ".join(live_name.split()).casefold()
            target = identity.get("object_id", arguments.get("to"))
            target_key = (
                str(target).strip().casefold() if target is not None else ""
            )
            source_classes: set[str] = set()
            resolved_identity = (
                self.knowledge.merchant_identity(
                    object_id=target,
                    name=live_name,
                )
                if hasattr(self.knowledge, "merchant_identity")
                else None
            )
            if isinstance(resolved_identity, dict) and resolved_identity.get(
                "merchant_class"
            ):
                source_classes.add(str(resolved_identity["merchant_class"]))
            for item_name in item_names:
                row = buyer_rows.get(item_name)
                candidates = row.get("candidates") if isinstance(row, dict) else []
                for candidate in candidates if isinstance(candidates, list) else []:
                    if not isinstance(candidate, dict):
                        continue
                    instances = candidate.get("instances")
                    instances = instances if isinstance(instances, list) else []
                    identity_match = any(
                        isinstance(instance, dict)
                        and (
                            (
                                target_key
                                and str(
                                    instance.get("seller_id_at_build")
                                ).strip().casefold()
                                == target_key
                            )
                            or (
                                live_name_key
                                and " ".join(
                                    str(instance.get("name") or "").split()
                                ).casefold()
                                == live_name_key
                            )
                        )
                        for instance in instances
                    )
                    if not identity_match:
                        continue
                    merchant_class = str(candidate.get("merchant") or "").strip()
                    if merchant_class:
                        source_classes.add(merchant_class)
            if isinstance(identity.get("source_classes"), list):
                source_classes.update(
                    str(value).strip()
                    for value in identity["source_classes"]
                    if str(value).strip()
                )
            aliases = {
                value.casefold()
                for value in [live_name, *source_classes]
                if value
            }
            if target is not None:
                aliases.add(str(target).strip().casefold())
            result.append(
                {
                    "tool": entry.get("tool"),
                    "room": room,
                    "item_ids": sorted(self._sale_item_ids(arguments)),
                    "item_names": sorted(item_names),
                    "merchant": {
                        "object_id": target,
                        "live_name": live_name or None,
                        "source_classes": sorted(source_classes),
                        "aliases": sorted(aliases),
                    },
                    "reason": str(entry.get("reason") or "")[:500],
                    "updated_at": entry.get("updated_at"),
                }
            )
        return result[-20:]

    @staticmethod
    def _sale_exhausted_items(
        refusals: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        """Retire one exact carried item after independent buyer disprovals.

        This is deliberately neither room-wide nor goal-wide. A single refusal
        removes only that buyer placement. Reaching the bound means enough live
        buyers have independently disproved the source catalogue's sale
        hypothesis for this exact object id; a new item id remains eligible.
        """

        grouped: dict[str, dict[str, Any]] = {}
        for refusal in refusals:
            if not isinstance(refusal, dict):
                continue
            merchant = refusal.get("merchant")
            merchant = merchant if isinstance(merchant, dict) else {}
            identity = str(
                merchant.get("object_id")
                or merchant.get("live_name")
                or ""
            ).strip().casefold()
            if not identity:
                continue
            for raw_item_id in refusal.get("item_ids", []):
                item_id = str(raw_item_id).strip().casefold()
                if not item_id:
                    continue
                row = grouped.setdefault(
                    item_id,
                    {
                        "item_id": item_id,
                        "item_names": set(),
                        "merchant_identities": set(),
                        "refusals": [],
                    },
                )
                row["item_names"].update(
                    " ".join(str(value).split()).casefold()
                    for value in refusal.get("item_names", [])
                    if str(value).strip()
                )
                row["merchant_identities"].add(identity)
                row["refusals"].append(refusal)
        result: list[dict[str, Any]] = []
        for row in grouped.values():
            identities = row["merchant_identities"]
            if len(identities) < SALE_BUYER_REFUSAL_LIMIT:
                continue
            result.append(
                {
                    "item_id": row["item_id"],
                    "item_names": sorted(row["item_names"]),
                    "distinct_refusing_buyers": len(identities),
                    "threshold": SALE_BUYER_REFUSAL_LIMIT,
                    "scope": "exact_carried_item_instance",
                    "reason": (
                        "multiple independent live buyers rejected this exact "
                        "item; use a non-sale funding route or materially change "
                        "inventory before retrying it"
                    ),
                }
            )
        return sorted(result, key=lambda item: item["item_id"])

    @staticmethod
    def _filter_refused_buyer_candidates(
        buyers: list[dict[str, Any]],
        refusals: list[dict[str, Any]],
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        """Remove only exact item/merchant/room placements disproved live."""

        usable: list[dict[str, Any]] = []
        rejected: list[dict[str, Any]] = []
        for raw in buyers:
            if not isinstance(raw, dict):
                continue
            item_name = " ".join(str(raw.get("item") or "").split()).casefold()
            item_refusals = [
                refusal
                for refusal in refusals
                if item_name in set(refusal.get("item_names", []))
            ]
            candidates: list[dict[str, Any]] = []
            for raw_candidate in raw.get("candidates", []):
                if not isinstance(raw_candidate, dict):
                    continue
                candidate = dict(raw_candidate)
                room_ids = (
                    list(candidate.get("room_ids", []))
                    if isinstance(candidate.get("room_ids"), list)
                    else []
                )
                merchant_class = str(
                    candidate.get("merchant") or ""
                ).casefold()
                matching_refusals = [
                    refusal
                    for refusal in item_refusals
                    if merchant_class
                    and merchant_class
                    in {
                        str(value).casefold()
                        for value in deep_get(
                            refusal, "merchant.aliases", []
                        )
                    }
                ]
                refused_rooms = {
                    str(refusal.get("room"))
                    for refusal in matching_refusals
                    if refusal.get("room") is not None
                }
                kept_rooms = [
                    room for room in room_ids if str(room) not in refused_rooms
                ]
                removed_rooms = [
                    room for room in room_ids if str(room) in refused_rooms
                ]
                if removed_rooms:
                    matching = next(
                        (
                            refusal
                            for refusal in matching_refusals
                            if str(refusal.get("room"))
                            in {str(room) for room in removed_rooms}
                        ),
                        {},
                    )
                    rejected.append(
                        {
                            "item": raw.get("item"),
                            "merchant": candidate.get("merchant"),
                            "room_ids": removed_rooms,
                            "live_name": deep_get(matching, "merchant.live_name"),
                            "reason": matching.get("reason"),
                            "scope": "exact_item_buyer_placement",
                        }
                    )
                if kept_rooms:
                    candidate["room_ids"] = kept_rooms
                    candidates.append(candidate)
            usable.append({**raw, "candidates": candidates[:5]})
        return usable, rejected[-30:]

    def _intrinsically_unsellable_item_ids(
        self,
        goal: dict[str, Any] | None,
        observation: dict[str, Any] | None = None,
    ) -> set[str]:
        if not isinstance(goal, dict):
            return set()
        entries = self.storage.get_runtime("blocked_actions", [])
        result = {
            item_id
            for entry in (entries if isinstance(entries, list) else [])
            if isinstance(entry, dict)
            and entry.get("goal_id") == goal.get("id")
            and entry.get("tool") in {"sell", "sell_all"}
            and self._is_intrinsic_item_sale_refusal(entry.get("reason"))
            for item_id in self._sale_item_ids(
                entry.get("arguments")
                if isinstance(entry.get("arguments"), dict)
                else {}
            )
        }
        if isinstance(observation, dict):
            restricted_names = self._intrinsically_unsellable_item_names(
                goal, observation
            )
            raw_items = deep_get(observation, "inventory.items", [])
            result.update(
                str(item.get("id", item.get("object_id"))).strip().casefold()
                for item in (raw_items if isinstance(raw_items, list) else [])
                if isinstance(item, dict)
                and " ".join(str(item.get("name") or "").split()).casefold()
                in restricted_names
                and item.get("id", item.get("object_id")) is not None
            )
        return result

    @staticmethod
    def _intrinsic_refusal_item_name(reason: Any) -> str | None:
        text = " ".join(str(reason or "").split()).casefold()
        match = re.search(
            r"\bpart with\s+(?:(?:a|an|the|some)\s+)?(.+?)(?:!|\.|\?|\"|$)",
            text,
        )
        if match is None:
            return None
        name = match.group(1).strip(" !?.\"'")
        return name or None

    def _intrinsically_unsellable_item_names(
        self,
        goal: dict[str, Any] | None,
        observation: dict[str, Any],
    ) -> set[str]:
        """Carry exact refusal evidence across opaque server item-id churn.

        The inference applies only while the semantic inventory hash remains
        unchanged. Distinct refused ids must cover every currently carried
        instance, so one bad duplicate never poisons its siblings.
        """

        if not isinstance(goal, dict):
            return set()
        current_hash = self.learning.profile(observation).get(
            "inventory_load_hash"
        )
        if not current_hash:
            return set()
        raw_items = deep_get(observation, "inventory.items", [])
        counts: dict[str, int] = {}
        for item in raw_items if isinstance(raw_items, list) else []:
            if not isinstance(item, dict):
                continue
            name = " ".join(str(item.get("name") or "").split()).casefold()
            if name:
                counts[name] = counts.get(name, 0) + 1
        refused_ids: dict[str, set[str]] = {}
        entries = self.storage.get_runtime("blocked_actions", [])
        for entry in entries if isinstance(entries, list) else []:
            if (
                not isinstance(entry, dict)
                or entry.get("goal_id") != goal.get("id")
                or entry.get("tool") not in {"sell", "sell_all"}
                or entry.get("inventory_load_hash") != current_hash
                or not self._is_intrinsic_item_sale_refusal(entry.get("reason"))
            ):
                continue
            name = self._intrinsic_refusal_item_name(entry.get("reason"))
            if not name or name not in counts:
                continue
            refused_ids.setdefault(name, set()).update(
                self._sale_item_ids(
                    entry.get("arguments")
                    if isinstance(entry.get("arguments"), dict)
                    else {}
                )
            )
        return {
            name
            for name, item_ids in refused_ids.items()
            if counts.get(name, 0) > 0 and len(item_ids) >= counts[name]
        }

    @staticmethod
    def _sale_selected_item_names(
        arguments: dict[str, Any], observation: dict[str, Any]
    ) -> set[str]:
        raw_values = arguments.get("items")
        values = raw_values if isinstance(raw_values, list) else [raw_values]
        selected = {
            str(value.get("id") if isinstance(value, dict) else value)
            .strip()
            .casefold()
            for value in values
            if (value.get("id") if isinstance(value, dict) else value) is not None
        }
        raw_items = deep_get(observation, "inventory.items", [])
        names: set[str] = set()
        for item in raw_items if isinstance(raw_items, list) else []:
            if not isinstance(item, dict):
                continue
            name = " ".join(str(item.get("name") or "").split()).casefold()
            identifiers = {
                str(item.get(key)).strip().casefold()
                for key in ("id", "object_id")
                if item.get(key) is not None
            }
            if name in selected or identifiers & selected:
                names.add(name)
        return names

    def _intrinsic_sale_block(
        self,
        goal: dict[str, Any],
        arguments: dict[str, Any],
        observation: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        requested_ids = self._sale_item_ids(arguments)
        restricted_names = (
            self._intrinsically_unsellable_item_names(goal, observation)
            if isinstance(observation, dict)
            else set()
        )
        requested_names = (
            self._sale_selected_item_names(arguments, observation)
            if isinstance(observation, dict)
            else set()
        )
        if not requested_ids and not requested_names:
            return None
        entries = self.storage.get_runtime("blocked_actions", [])
        for entry in entries if isinstance(entries, list) else []:
            if (
                isinstance(entry, dict)
                and entry.get("goal_id") == goal.get("id")
                and entry.get("tool") in {"sell", "sell_all"}
                and self._is_intrinsic_item_sale_refusal(entry.get("reason"))
                and (
                    requested_ids
                    & self._sale_item_ids(
                        entry.get("arguments")
                        if isinstance(entry.get("arguments"), dict)
                        else {}
                    )
                    or requested_names & restricted_names
                )
            ):
                return entry
        return None

    def _blocked_action(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        tool: str,
        arguments: dict[str, Any],
    ) -> dict[str, Any] | None:
        intrinsic_sale_block = (
            self._intrinsic_sale_block(goal, arguments, observation)
            if tool in {"sell", "sell_all"}
            else None
        )
        if intrinsic_sale_block is not None:
            return intrinsic_sale_block
        signature = canonical_json({"tool": tool, "arguments": arguments})
        room = self._observation_room(observation)
        entries = self.storage.get_runtime("blocked_actions", [])
        if not isinstance(entries, list):
            return None
        for entry in entries:
            if (
                isinstance(entry, dict)
                and entry.get("goal_id") == goal.get("id")
                and entry.get("signature") == signature
                and str(entry.get("room")) == str(room)
            ):
                # Historical broker ambiguity could record a successful bank
                # mutation as "no banker" even inside a verified bank.  Do not
                # let that stale fingerprint suppress a valid future withdrawal
                # or deposit forever; the bank-location preflight is the source
                # of truth for whether the action is in the right place.
                room_name = str(
                    deep_get(observation, "look.room.name", deep_get(observation, "look.room", ""))
                    or ""
                ).casefold()
                if (
                    tool == "bank"
                    and "bank" in room_name
                    and "no banker" in str(entry.get("reason", "")).casefold()
                ):
                    continue
                if (
                    tool == "shop"
                    and any(
                        marker in str(entry.get("reason", "")).casefold()
                        for marker in ("enough money", "insufficient fund", "cannot afford")
                    )
                    and self._carried_currency(observation) > int(entry.get("carried_currency", 0) or 0)
                ):
                    continue
                if tool == "cast":
                    reason = str(entry.get("reason") or "")
                    if (
                        "produced no verified carried item" in reason.casefold()
                        and not is_inventory_capacity_refusal(reason)
                    ):
                        # Older builds persisted an ambiguous broker observation
                        # as a proven cast failure.  With no authoritative
                        # refusal that fingerprint has no valid retry predicate,
                        # so it must never suppress a fresh live attempt.
                        self._discard_blocked_action(entry)
                        continue
                    required_mana = entry.get("required_mana")
                    if required_mana is None:
                        required_mana = self._required_mana_from_refusal(
                            entry.get("reason")
                        )
                    current_mana = self._vital_value(observation, "mana")
                    try:
                        mana_ready = (
                            required_mana is not None
                            and current_mana is not None
                            and current_mana >= float(required_mana)
                        )
                    except (TypeError, ValueError):
                        mana_ready = False
                    if mana_ready:
                        # An insufficient-mana refusal is valid only while the
                        # verified resource state remains below the spell cost.
                        self._discard_blocked_action(entry)
                        continue
                if (
                    tool in {"shop", "cast"}
                    and is_inventory_capacity_refusal(entry.get("reason"))
                    and self.learning.profile(observation).get("inventory_load_hash")
                    != entry.get("inventory_load_hash")
                ):
                    # Capacity refusals are state-specific. A changed load makes
                    # the old result historical evidence rather than a reason
                    # to suppress a newly grounded attempt.
                    continue
                if tool in {"equip_best", "wear_best"}:
                    current_equipment_hash = self._equipment_attempt_hash(tool, observation)
                    recorded_equipment_hash = entry.get("equipment_attempt_hash")
                    if recorded_equipment_hash is not None:
                        equipment_changed = current_equipment_hash != recorded_equipment_hash
                    else:
                        # Migration path for fingerprints written before equipment
                        # attempts had their own state key.  The legacy inventory
                        # hash is broader than ideal, but it safely releases an old
                        # refusal once after any observed inventory change.  New
                        # records below use only relevant equipment candidates.
                        equipment_changed = (
                            self.learning.profile(observation).get("inventory_load_hash")
                            != entry.get("inventory_load_hash")
                        )
                    if equipment_changed:
                        self._discard_blocked_action(entry)
                        continue
                return entry
        return None

    def _equipment_attempt_hash(
        self,
        tool: str,
        observation: dict[str, Any],
    ) -> str | None:
        """Fingerprint only the state that can change an equipment attempt.

        Currency and unrelated loot must not make the controller hammer the
        same known-bad item again.  A replacement candidate, a changed item
        condition/capability, or a changed equipped item should permit a fresh
        broker attempt immediately.
        """

        words = WEAPON_WORDS if tool == "equip_best" else ARMOR_WORDS if tool == "wear_best" else None
        if words is None:
            return None
        raw_items = deep_get(observation, "inventory.items", [])
        candidates: list[dict[str, Any]] = []
        for item in raw_items if isinstance(raw_items, list) else []:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name") or "").strip()
            if not any(word in name.casefold() for word in words):
                continue
            candidates.append(
                {
                    "id": item.get("id"),
                    "name": name.casefold(),
                    "amount": item.get("amount", item.get("quantity", item.get("count", 1))),
                    "can": sorted(
                        str(value).casefold()
                        for value in item.get("can", [])
                    )
                    if isinstance(item.get("can"), list)
                    else item.get("can"),
                    "condition": item.get("condition"),
                    "durability": item.get("durability"),
                    "broken": item.get("broken"),
                }
            )
        profile = self.learning.profile(observation)
        return json_hash(
            {
                "tool": tool,
                "candidates": sorted(candidates, key=canonical_json),
                "equipment_state": profile.get("equipment_state"),
                "equipment": profile.get("equipment"),
                "wielded_weapons": profile.get("wielded_weapons"),
            }
        )

    def _discard_blocked_action(self, discarded: dict[str, Any]) -> None:
        entries = self.storage.get_runtime("blocked_actions", [])
        if not isinstance(entries, list):
            return
        self.storage.set_runtime(
            "blocked_actions",
            [entry for entry in entries if entry != discarded],
        )

    def _save_blocked_action(self, updated: dict[str, Any]) -> None:
        entries = self.storage.get_runtime("blocked_actions", [])
        values = [entry for entry in entries if isinstance(entry, dict)] if isinstance(entries, list) else []
        values = [
            entry
            for entry in values
            if not (
                entry.get("goal_id") == updated.get("goal_id")
                and entry.get("signature") == updated.get("signature")
                and str(entry.get("room")) == str(updated.get("room"))
            )
        ]
        values.append(updated)
        self.storage.set_runtime("blocked_actions", values[-20:])

    def _record_blocked_action(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        tool: str,
        arguments: dict[str, Any],
        reason: str,
    ) -> None:
        failure_kind = str(
            deep_get(
                self._failure_context(tool, reason, observation) or {},
                "kind",
                "",
            )
        )
        offered_item_names = (
            sorted(self._sale_selected_item_names(arguments, observation))
            if tool in {"sell", "sell_all"}
            else []
        )
        merchant_identity = None
        if failure_kind == "merchant_rejected_sale":
            merchant_identity = {
                "object_id": arguments.get("to"),
                "live_name": self._merchant_speaker_name(reason),
            }
        required_mana = (
            self._required_mana_from_refusal(reason) if tool == "cast" else None
        )
        self._save_blocked_action(
            {
                "goal_id": goal["id"],
                "signature": canonical_json({"tool": tool, "arguments": arguments}),
                "tool": tool,
                "arguments": redact(arguments),
                "room": self._observation_room(observation),
                "carried_currency": self._carried_currency(observation),
                "inventory_load_hash": self.learning.profile(observation).get(
                    "inventory_load_hash"
                ),
                "equipment_attempt_hash": self._equipment_attempt_hash(tool, observation),
                **(
                    {
                        "observed_mana": self._vital_value(observation, "mana"),
                        "required_mana": required_mana,
                    }
                    if tool == "cast" and required_mana is not None
                    else {}
                ),
                "reason": reason[:500],
                **(
                    {"offered_item_names": offered_item_names}
                    if offered_item_names
                    else {}
                ),
                **(
                    {"merchant_identity": merchant_identity}
                    if merchant_identity is not None
                    else {}
                ),
                "suppressed_count": 0,
                "updated_at": timestamp(),
            }
        )

    def public_game_context(self) -> dict[str, Any]:
        observation = self.last_observation or {}
        return {
            "character": self._character_name(observation),
            "room": deep_get(observation, "look.room.name", deep_get(observation, "look.room")),
            "activity": (self.storage.active_goal() or {}).get("title"),
            "combat_readiness": self.learning.readiness_summary(observation),
        }

    @staticmethod
    def _age_seconds(value: Any) -> float | None:
        if not value:
            return None
        try:
            if isinstance(value, (int, float)):
                return round(max(0.0, time.time() - float(value)), 1)
            text = str(value).strip()
            if text.endswith("Z"):
                text = text[:-1] + "+00:00"
            parsed = datetime.fromisoformat(text)
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return round(
                max(0.0, time.time() - parsed.astimezone(timezone.utc).timestamp()),
                1,
            )
        except (TypeError, ValueError, OverflowError):
            return None

    def _compact_liveness(
        self,
        goal: dict[str, Any] | None,
        *,
        broker_activity: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        suppression = self.storage.get_runtime("safety_suppression_v1")
        if not isinstance(suppression, dict) or (
            goal is not None and suppression.get("goal_id") != goal.get("id")
        ):
            suppression = None
        goal_id = goal.get("id") if isinstance(goal, dict) else None
        goal_is_active = bool(goal and goal.get("status") == "active")
        successful = (
            self.storage.goal_events(goal_id, kinds=["action.succeeded"], limit=1)
            if goal_id and goal_is_active
            else self.storage.latest_events(limit=1, kinds=["action.succeeded"])
        )
        progress_kinds = [
            "action.partial_progress",
            "progress.hp_gained",
            "progress.skill_learned",
            "progress.spell_learned",
            "progress.skill_milestone",
            "progress.spell_milestone",
            "goal.succeeded",
            "pvp.phase.completed",
        ]
        progress = (
            self.storage.goal_events(goal_id, kinds=progress_kinds, limit=1)
            if goal_id and goal_is_active
            else self.storage.latest_events(limit=1, kinds=progress_kinds)
        )
        if goal_id and goal_is_active and self._direct_pvp_contract(goal) is None:
            goal_text = " ".join(
                (
                    str(goal.get("title") or ""),
                    str(goal.get("objective") or ""),
                    str(deep_get(goal, "constraints.operator_notes", "")),
                )
            ).casefold()
            explicit_hunt = (
                "pvp_seek" in goal_text
                or "pvp hunt" in goal_text
                or "player hunt" in goal_text
                or "pvp patrol" in goal_text
            ) and "do not use pvp_seek" not in goal_text
            if explicit_hunt:
                completed_searches = self.storage.goal_events(
                    goal_id, kinds=["pvp.search.completed"], limit=20
                )
                verified_searches = [
                    event
                    for event in completed_searches
                    if event.get("data", {}).get("completed_patrol") is True
                    and len(event.get("data", {}).get("distinct_rooms", [])) >= 2
                ]
                if verified_searches:
                    progress = [*progress, verified_searches[-1]]
                    progress.sort(key=lambda event: str(event.get("occurred_at") or ""))
                    progress = progress[-1:]
        last_action_at = successful[-1]["occurred_at"] if successful else None
        last_action = None
        if successful:
            event = successful[-1]
            event_data = event.get("data") if isinstance(event.get("data"), dict) else {}
            last_action = {
                "at": event.get("occurred_at"),
                "tool": event_data.get("tool"),
                "summary": event.get("summary"),
            }
        last_progress_at = progress[-1]["occurred_at"] if progress else None
        activity_text = str((broker_activity or {}).get("activity") or "")
        blocker_count = int((suppression or {}).get("same_blocker_count", 0) or 0)
        state = "idle" if goal is None else "active"
        if goal and goal.get("status") in {"paused", "blocked"}:
            state = str(goal["status"])
        if blocker_count >= 3 or any(
            marker in activity_text.casefold() for marker in ("stalled", "error")
        ):
            state = "stalled"
        compact_suppression = None
        if suppression:
            compact_suppression = {
                key: suppression.get(key)
                for key in (
                    "tool",
                    "room",
                    "blocker_kinds",
                    "same_blocker_count",
                    "first_blocked_at",
                    "last_blocked_at",
                    "blocked_for_seconds",
                )
            }
        return {
            "state": state,
            "goal_age_seconds": self._age_seconds(goal.get("created_at")) if goal else None,
            "last_successful_action": last_action,
            "last_successful_action_at": last_action_at,
            "seconds_since_successful_action": self._age_seconds(last_action_at),
            "last_verified_progress_at": last_progress_at,
            "seconds_since_verified_progress": self._age_seconds(last_progress_at),
            "broker_keeper": broker_activity,
            "safety_suppression": compact_suppression,
        }

    @staticmethod
    def _compact_lesson(lesson: dict[str, Any]) -> dict[str, Any]:
        evaluation = (
            lesson.get("retry_evaluation")
            if isinstance(lesson.get("retry_evaluation"), dict)
            else {}
        )
        unmet = [
            str(item.get("detail") or item.get("condition") or "")[:240]
            for item in evaluation.get("conditions", [])
            if isinstance(item, dict) and item.get("met") is not True
        ]
        if evaluation.get("met") is True:
            unmet = []
        return {
            "id": lesson.get("id"),
            "goal_id": lesson.get("goal_id"),
            "status": lesson.get("status"),
            "scope": lesson.get("scope"),
            "classification": lesson.get("classification"),
            "summary": str(lesson.get("summary") or "")[:300],
            "retry_ready": evaluation.get("met"),
            "retry_mode": evaluation.get("mode"),
            "unmet_retry_conditions": unmet[:4],
        }

    def _compact_readiness(self, observation: dict[str, Any]) -> dict[str, Any]:
        readiness = self.learning.readiness_summary(observation)
        quarantines = []
        for item in readiness.get("farm_tactic_quarantines", []):
            if not isinstance(item, dict):
                continue
            quarantines.append(
                {
                    "room": item.get("room", item.get("assigned_room")),
                    "target": item.get("target", item.get("hunt")),
                    "scope": item.get("quarantine_scope"),
                    "reasons": [str(reason)[:180] for reason in item.get("reasons", [])[:3]],
                }
            )
        scorecard = []
        for item in readiness.get("farm_room_scorecard", [])[:3]:
            if not isinstance(item, dict):
                continue
            scorecard.append(
                {
                    key: item.get(key)
                    for key in (
                        "room",
                        "target",
                        "strategy",
                        "target_kills",
                        "deaths",
                        "withdrawals",
                        "quarantined",
                        "last_observed_at",
                    )
                }
            )
        return {
            key: readiness.get(key)
            for key in (
                "max_health",
                "pvp_eligible_by_guide",
                "equipment_state",
                "equipped",
                "wielded_weapons",
                "carried_weapons",
                "carried_armor",
                "healing_supply_count",
                "recent_combat_deaths",
                "recommended_goal_type",
            )
        } | {"farm_tactic_quarantines": quarantines, "farm_room_scorecard": scorecard}

    @staticmethod
    def _compact_character_development(observation: dict[str, Any]) -> dict[str, Any]:
        """Expose live build evidence without leaking the raw broker surface."""
        abilities = observation.get("abilities")
        abilities = abilities if isinstance(abilities, dict) else {}

        def ability_rows(group: str) -> tuple[list[dict[str, Any]], int]:
            raw = abilities.get(group)
            raw = raw if isinstance(raw, list) else []
            singular = group[:-1]
            rows: list[dict[str, Any]] = []
            for item in raw[:24]:
                if not isinstance(item, dict) or not item.get("name"):
                    continue
                name = " ".join(str(item["name"]).split())
                rows.append(
                    {
                        key: item.get(key)
                        for key in ("name", "ability", "school", "level", "mana", "targets")
                        if item.get(key) is not None
                    }
                    | {"goal_metric": f"ability.{singular}.{name}"}
                )
            return rows, max(0, len(raw) - len(rows))

        skills, skills_omitted = ability_rows("skills")
        spells, spells_omitted = ability_rows("spells")
        freshness = abilities.get("freshness")
        freshness = freshness if isinstance(freshness, dict) else {"known": False}
        advancement = abilities.get("advancement")
        advancement = advancement if isinstance(advancement, dict) else {}
        recent = advancement.get("recent")
        recent = recent if isinstance(recent, list) else []
        atrophied = advancement.get("atrophied")
        atrophied = atrophied if isinstance(atrophied, list) else []

        spell_catalog = observation.get("spells")
        spell_catalog = spell_catalog if isinstance(spell_catalog, dict) else {}
        readiness_rows = spell_catalog.get("spells")
        readiness_rows = readiness_rows if isinstance(readiness_rows, list) else []
        spell_readiness = {
            key: spell_catalog.get(key)
            for key in (
                "your_karma",
                "your_mana",
                "known_spells",
                "identified",
                "castable_now",
            )
            if key in spell_catalog
        } | {
            "spells": [
                {
                    key: item.get(key)
                    for key in (
                        "name",
                        "school",
                        "level",
                        "mana",
                        "targets",
                        "reagents",
                        "castable",
                        "blocked_by",
                    )
                    if item.get(key) is not None
                }
                for item in readiness_rows[:24]
                if isinstance(item, dict)
            ],
            "omitted": max(0, len(readiness_rows) - 24),
        }
        return {
            "ability_scale": "0-100",
            "freshness": {
                key: freshness.get(key)
                for key in ("from", "age_ms", "known", "note")
                if key in freshness
            },
            "known_skill_count": len(abilities.get("skills", []))
            if isinstance(abilities.get("skills"), list)
            else 0,
            "known_spell_count": len(abilities.get("spells", []))
            if isinstance(abilities.get("spells"), list)
            else 0,
            "skills": skills,
            "skills_omitted": skills_omitted,
            "spells": spells,
            "spells_omitted": spells_omitted,
            "advancement": {
                "since_first_seen": advancement.get("since_first_seen"),
                "changes_on_record": advancement.get("changes_on_record", 0),
                "recent": recent[-6:],
                "atrophied": atrophied[:12],
                **({"note": advancement.get("note")} if advancement.get("note") else {}),
            },
            "spell_readiness": spell_readiness,
        }

    def _local_visible_players(self, observation: dict[str, Any]) -> list[dict[str, Any]]:
        self_name = str(self._character_name(observation) or "").strip().casefold()
        objects = deep_get(observation, "look.objects", [])
        players: list[dict[str, Any]] = []
        for item in objects if isinstance(objects, list) else []:
            if not isinstance(item, dict) or item.get("is_player") is not True:
                continue
            name = str(item.get("name") or "").strip()
            if not name or name.casefold() == self_name:
                continue
            players.append(
                {
                    "id": item.get("id"),
                    "name": name,
                    "distance": item.get("distance"),
                    "relation": item.get("relation"),
                    "safety_on": item.get("safety_on"),
                    "attacking_character": any(
                        item.get(field) is True
                        for field in ("attacking_self", "targeting_self", "damaging_self")
                    ),
                }
            )
        return players[:20]

    @staticmethod
    def _direct_pvp_contract(goal: dict[str, Any] | None) -> dict[str, Any] | None:
        """Recover the closed target contract for a fresh local PvP opportunity.

        The supervisor deliberately records this boundary in operator notes because an
        opportunistic encounter expires when that exact player leaves.  Keep a
        small parser here so the tactical model cannot broaden ``pvp_engage
        only`` into a patrol or substitute another online player.
        """

        if not isinstance(goal, dict):
            return None
        constraints = goal.get("constraints") if isinstance(goal.get("constraints"), dict) else {}
        notes = str(constraints.get("operator_notes") or "").strip()
        objective = str(goal.get("objective") or "").strip()
        note_text = notes.casefold()
        direct_only = "pvp_engage" in note_text and (
            "pvp_engage only" in note_text
            or "only against" in note_text
            or "do not use pvp_seek" in note_text
            or "do not use who" in note_text
        )
        if not direct_only:
            return None

        target: str | None = None
        patterns = (
            r"\bpvp_engage\s+only\s+against\s+([^;,.]+)",
            r"\bpvp_engage\s+(.+?)\s+only(?:\s*[;,.]|$)",
            r"\bengage\s+(.+?)\s+with\s+pvp_engage\b",
        )
        for source, pattern in ((notes, patterns[0]), (notes, patterns[1]), (objective, patterns[2])):
            match = re.search(pattern, source, re.IGNORECASE)
            if match:
                target = match.group(1).strip().strip("\"'")
                break
        if not target:
            return None
        cancel_if_absent = any(
            marker in note_text
            for marker in (
                "freshly locally visible",
                "fresh local observation",
                "present in the current",
                "if " + target.casefold() + " disappears",
                "if the peer disappears",
                "do not substitute another target",
            )
        )
        return {
            "target": target,
            "direct_only": True,
            "cancel_if_absent": cancel_if_absent,
        }

    @staticmethod
    def _pvp_phase_criterion_met(
        goal: dict[str, Any], completion: dict[str, Any]
    ) -> bool:
        phase_ids = {
            str(item.get("id") or f"criterion_{index + 1}")
            for index, item in enumerate(goal.get("success_criteria", []))
            if isinstance(item, dict)
            and item.get("kind") == "event_occurred"
            and item.get("event_kind") == "pvp.phase.completed"
        }
        return any(
            isinstance(item, dict)
            and str(item.get("id")) in phase_ids
            and item.get("met") is True
            for item in completion.get("criteria", [])
        )

    @staticmethod
    def _visible_player_matches(
        observation: dict[str, Any], target: str
    ) -> bool:
        requested = str(target).strip().casefold()
        if not requested:
            return False
        objects = deep_get(observation, "look.objects", [])
        for item in objects if isinstance(objects, list) else []:
            if not isinstance(item, dict) or item.get("is_player") is not True:
                continue
            if requested in {
                str(item.get("id") or "").strip().casefold(),
                str(item.get("name") or "").strip().casefold(),
            }:
                return True
        return False

    def _validate_direct_pvp_plan(
        self,
        goal: dict[str, Any],
        steps: list[dict[str, Any]],
        completion: dict[str, Any],
    ) -> None:
        contract = self._direct_pvp_contract(goal)
        if contract is None or self._pvp_phase_criterion_met(goal, completion):
            return
        forbidden = [
            str(step.get("tool"))
            for step in steps
            if step.get("tool") in {PVP_SEEK_TOOL_NAME, "who"}
        ]
        if forbidden:
            raise ModelError(
                "this is an expiring fresh-local PvP opportunity: the goal requires "
                f"pvp_engage only against {contract['target']}; pvp_seek, who, patrols, camping, "
                "and replacement targets are forbidden"
            )
        direct_steps = [step for step in steps if step.get("tool") == PVP_TOOL_NAME]
        if not direct_steps:
            raise ModelError(
                f"the unfinished direct PvP phase requires one pvp_engage step against {contract['target']}"
            )
        target_text = normalize(str(contract["target"]))
        if any(target_text not in normalize(canonical_json(step)) for step in direct_steps):
            raise ModelError(
                f"every pvp_engage step must name the goal-owned exact target {contract['target']}"
            )

    def _expire_direct_pvp_opportunity(
        self,
        goal: dict[str, Any],
        observation: dict[str, Any],
        completion: dict[str, Any],
    ) -> dict[str, Any] | None:
        contract = self._direct_pvp_contract(goal)
        if (
            contract is None
            or contract.get("cancel_if_absent") is not True
            or self._pvp_phase_criterion_met(goal, completion)
            or self._visible_player_matches(observation, str(contract["target"]))
        ):
            return None
        result = self.manage_goal(
            {
                "request_id": f"controller-pvp-opportunity-ended-{goal['id']}-{uuid7()}",
                "goal_id": goal["id"],
                "expected_version": goal.get("version"),
                "action": "cancel",
                "cause": "opportunity_ended",
                "reason": (
                    f"Fresh local PvP opportunity ended before a server-accepted swing: "
                    f"{contract['target']} is no longer locally visible"
                ),
            }
        )
        self.storage.emit_event(
            "pvp.opportunity.ended",
            f"Ended stale direct PvP opportunity for {contract['target']}",
            severity="notice",
            interesting=True,
            goal_id=goal["id"],
            data={
                "target": contract["target"],
                "local_visibility": False,
                "accepted_phase_complete": False,
                "resumed_progression_eligible": True,
            },
        )
        return {
            "opportunity_ended": True,
            "target": contract["target"],
            "goal": result["goal"],
            "cancellation_assessment": result.get("cancellation_assessment"),
        }

    def _pvp_today_summary(self) -> dict[str, Any]:
        now_day = self.notifications.journal.local_datetime(timestamp()).date().isoformat()
        phases = self.storage.latest_events(
            limit=200, kinds=["pvp.phase.completed"]
        )
        loot_events = self.storage.latest_events(
            limit=200, kinds=["property.transaction"]
        )
        searches = self.storage.latest_events(
            limit=200, kinds=["pvp.search.completed"]
        )
        qualifying = []
        seen_targets: set[str] = set()
        for event in phases:
            if self.notifications.journal.local_day(event) != now_day:
                continue
            target = event.get("data", {}).get("target", {})
            target_name = target.get("name") if isinstance(target, dict) else target
            target_key = str(target.get("id") if isinstance(target, dict) and target.get("id") is not None else target_name).casefold()
            if target_key and target_key in seen_targets:
                continue
            if target_key:
                seen_targets.add(target_key)
            qualifying.append(
                {
                    "at": event.get("occurred_at"),
                    "target": target_name,
                    "accepted_swings": event.get("data", {}).get("accepted_swings"),
                    "items_taken_count": event.get("data", {}).get("items_taken_count"),
                }
            )
        loot_count = sum(
            1
            for event in loot_events
            if self.notifications.journal.local_day(event) == now_day
            and event.get("data", {}).get("transaction") == "pvp_loot"
        )
        today_searches = [
            event
            for event in searches
            if self.notifications.journal.local_day(event) == now_day
            and event.get("data", {}).get("completed_patrol") is True
        ]
        last_search = None
        if today_searches:
            event = today_searches[-1]
            data = event.get("data", {}) if isinstance(event.get("data"), dict) else {}
            last_search = {
                "at": event.get("occurred_at"),
                "outcome": data.get("outcome"),
                "target_requested": data.get("target_requested"),
                "requested_route": data.get("requested_route", []),
                "eligible_route": data.get("route", []),
                "skipped_rooms": data.get("skipped_rooms", []),
                "guild_eligibility_verified": data.get("guild_eligibility_verified"),
                "distinct_rooms": data.get("distinct_rooms", []),
                "target_acquired": data.get("target_acquired"),
            }
        observation = self.last_observation or {}
        observed_at = observation.get("observed_at")
        observation_age = self._age_seconds(observed_at)
        visible_players = self._local_visible_players(observation)
        opportunity_fresh = bool(
            visible_players
            and isinstance(observation_age, (int, float))
            and observation_age <= 30
        )
        return {
            "local_day": now_day,
            "qualifying_victories": len(qualifying),
            "pvp_loot_transactions": loot_count,
            "search_patrols": len(today_searches),
            "last_search": last_search,
            "policy": "operator_goal_driven",
            "daily_limit": None,
            "initiation_available": True,
            "opportunity": {
                "fresh_local_visibility": opportunity_fresh,
                "observation_age_seconds": observation_age,
                "visible_players": visible_players,
                "note": (
                    "Informational visibility only. Start player combat only for an explicit goal "
                    "or immediate defense; an empty list never creates work."
                ),
            },
            "recent": qualifying[-10:],
        }

    def _campaign_execution_status(
        self, goal: dict[str, Any] | None
    ) -> dict[str, Any] | None:
        if not goal:
            return None
        run = self.storage.campaign_run(str(goal.get("id") or ""))
        if run is None and goal.get("status") == "paused":
            run = self.storage.campaign_run(
                str(goal.get("id") or ""), include_terminal=True
            )
        if run is None:
            return None
        phase = self.storage.active_campaign_phase(run["id"])
        phases = self.storage.campaign_phases(run["id"])
        if phase is None and run.get("status") == "paused" and run.get(
            "active_phase_id"
        ):
            phase = self.storage.campaign_phase(str(run["active_phase_id"]))
        attempt_phase = phase or (phases[-1] if phases else None)
        attempts = (
            self.storage.phase_attempts(attempt_phase["id"], limit=8)
            if attempt_phase
            else []
        )
        exhaustion_checkpoint = self._phase_exhaustion_checkpoint(phase)
        abandonment_checkpoint = self._phase_abandonment_checkpoint(phase)
        return {
            "run_id": run["id"],
            "status": run["status"],
            "strategy_summary": run.get("strategy_summary"),
            "active_phase": phase,
            "phase_outcome_latched": (
                self._phase_completion_checkpoint(phase) is not None
            ),
            "phase_exhaustion_latched": exhaustion_checkpoint is not None,
            "phase_abandonment_latched": abandonment_checkpoint is not None,
            "safe_return_pending": (
                self._phase_completion_checkpoint(phase) is not None
                or exhaustion_checkpoint is not None
                or abandonment_checkpoint is not None
            ),
            "phase_exhaustion": (
                None
                if exhaustion_checkpoint is None
                else {
                    "exhausted_at": exhaustion_checkpoint.get("exhausted_at"),
                    "budget": redact(exhaustion_checkpoint.get("budget")),
                    "safe_ending": redact(exhaustion_checkpoint.get("safe_ending")),
                }
            ),
            "phase_abandonment": (
                None
                if abandonment_checkpoint is None
                else {
                    "abandoned_at": abandonment_checkpoint.get("abandoned_at"),
                    "reason": abandonment_checkpoint.get("reason"),
                    "safe_ending": redact(
                        abandonment_checkpoint.get("safe_ending")
                    ),
                }
            ),
            "recent_phases": phases[-8:],
            "recent_attempts": attempts,
            "progress_checkpoint": run.get("progress_checkpoint"),
            "external_blocker": run.get("external_blocker"),
            "action_breaker_limit": self.campaign.ACTION_FAILURE_LIMIT,
        }

    def _supervision_status(
        self,
        *,
        active: dict[str, Any] | None,
        queued: list[dict[str, Any]],
        health: dict[str, Any] | None,
        observation: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        observation = observation or self.last_observation or {}
        inactive = self.storage.goals(["paused", "blocked"])
        current = active or (
            max(inactive, key=lambda item: str(item.get("updated_at") or ""))
            if inactive
            else None
        )
        keeper: dict[str, Any] | None = None
        if health and self.config.game.agent in health.get("sessions", []):
            try:
                raw_keeper = self.broker.call_tool(
                    "autopilot",
                    {"agent": self.config.game.agent, "action": "status"},
                    timeout=3,
                    mutation=False,
                )
                if isinstance(raw_keeper, dict):
                    keeper = {
                        key: raw_keeper.get(key)
                        for key in (
                            "running",
                            "inert",
                            "mode",
                            "activity",
                            "goal_id",
                            "started_at",
                            "updated_at",
                            "error",
                        )
                        if key in raw_keeper
                    }
            except (BrokerError, TypeError, ValueError):
                keeper = {"status": "unavailable"}
        foreground_action = (
            dict(self._foreground_action)
            if isinstance(self._foreground_action, dict)
            else None
        )
        if keeper is not None and foreground_action is not None:
            keeper["control_owner"] = "controller_foreground_action"
            keeper["suspension_expected"] = not self._keeper_is_driving(keeper)
        deferred = self.storage.goal_lessons(statuses=["deferred"], limit=20)
        unlocked = self.storage.goal_lessons(statuses=["unlocked"], limit=20)
        actionable_unlocked = [
            lesson for lesson in unlocked if lesson.get("scope") == "goal"
        ]
        lesson_values = []
        for lesson in [*deferred, *actionable_unlocked]:
            public = self.learning.public_lesson(
                lesson, evaluation=self.learning.evaluate_retry(lesson, observation)
            )
            lesson_values.append(self._compact_lesson(public))
        completion = current.get("completion", {}) if current else {}
        criteria = [
            {
                key: item.get(key)
                for key in ("id", "kind", "met", "detail")
            }
            for item in completion.get("criteria", [])
            if isinstance(item, dict)
        ]
        planner_feedback = self._planner_feedback(current) if current else None
        execution_plan = self._execution_plan(current) if current else None
        purchase_preflights = self.storage.get_runtime(PURCHASE_PREFLIGHT_RUNTIME_KEY, {})
        purchase_preflight = (
            purchase_preflights.get(current["id"])
            if current and isinstance(purchase_preflights, dict)
            else None
        )
        now_text = timestamp()
        value = {
            "now_utc": now_text,
            "now_local": self.notifications.journal.local_datetime(now_text).isoformat(
                timespec="seconds"
            ),
            "timezone": self.config.deployment.timezone,
            "controller": {
                "state": self.state,
                "since": self.started_at,
                "version": self.VERSION,
                "last_heartbeat_at": self.last_heartbeat_at,
                "heartbeat_age_seconds": self._age_seconds(self.last_heartbeat_at),
                "shutdown": self._shutdown_status_snapshot(),
                "control_owner": (
                    "foreground_action"
                    if foreground_action is not None
                    else (
                        "keeper"
                        if self._keeper_is_driving(keeper)
                        else "controller"
                    )
                ),
                "foreground_action": foreground_action,
            },
            "game": {
                "connection": "joined"
                if health and self.config.game.agent in health.get("sessions", [])
                else "disconnected",
                "character_name": self._character_name(observation),
                "location": deep_get(observation, "look.room.name", deep_get(observation, "look.room")),
                "room_id": deep_get(observation, "look.room.num", deep_get(observation, "look.room_id")),
                "room_properties": self._room_properties(
                    deep_get(
                        observation,
                        "look.room.num",
                        deep_get(observation, "look.room_id"),
                    )
                ),
                "position": deep_get(observation, "status.position"),
                "vitals": deep_get(observation, "status.vitals", deep_get(observation, "look.vitals", {})),
                "risk": self._risk(observation),
                "carried_currency": self._carried_currency(observation),
                "finances": self._financial_context(observation),
                "visible_players": self._local_visible_players(observation),
                "observation_age_seconds": round(
                    max(0.0, time.time() - float(observation.get("observed_at", time.time()))),
                    1,
                ),
            },
            "onboarding": self._onboarding_status(observation),
            "goal": None
            if current is None
            else {
                "id": current.get("id"),
                "title": current.get("title"),
                "objective": current.get("objective"),
                "status": current.get("status"),
                "version": current.get("version"),
                "priority": current.get("priority"),
                "progress_percent": completion.get("percent_estimate", 0),
                "progress_summary": completion.get("summary"),
                "criteria": criteria,
                "outcome_latched": self._goal_completion_checkpoint(current)
                is not None,
                "execution_plan": None
                if execution_plan is None
                else {
                    "status": deep_get(execution_plan, "verification.status"),
                    "summary": execution_plan.get("summary"),
                    "steps": execution_plan.get("steps", []),
                    "safe_ending": execution_plan.get("safe_ending"),
                    "last_action": execution_plan.get("last_action"),
                    "updated_at": execution_plan.get("updated_at"),
                },
                "purchase_preflight": purchase_preflight,
            },
            "queue": [
                {
                    "id": item.get("id"),
                    "title": item.get("title"),
                    "priority": item.get("priority"),
                }
                for item in queued[:3]
            ],
            "attention": {
                "liveness": self._compact_liveness(current, broker_activity=keeper),
                "planner_feedback": planner_feedback,
                "warnings": self.warnings[-5:],
                "pending_proposals": len(self.storage.proposals()),
                "deferred_goal_count": sum(
                    1 for item in deferred if item.get("scope") == "goal"
                ),
                "deferred_tactic_count": sum(
                    1 for item in deferred if item.get("scope") == "tactic"
                ),
                "eligible_retry_count": len(actionable_unlocked),
            },
            "campaign": {
                "execution": self._campaign_execution_status(current),
                "readiness": self._compact_readiness(observation),
                "development": self._compact_character_development(observation),
                "lessons": lesson_values[:8],
                "pvp_today": self._pvp_today_summary(),
            },
            "dependencies": self.dependencies,
        }
        return redact(value)

    def _journal_assessment_context(self) -> dict[str, Any]:
        observation = self.last_observation or {}
        active = self.storage.active_goal()
        inactive = self.storage.goals(["paused", "blocked"])
        current_goal = active or (
            max(inactive, key=lambda goal: str(goal.get("updated_at") or ""))
            if inactive
            else None
        )
        queued = self.storage.goals(["queued"])
        lessons = self.storage.goal_lessons(statuses=["deferred", "unlocked"], limit=20)
        liveness = self._compact_liveness(current_goal)
        current_plan = self._execution_plan(current_goal) if current_goal else None
        purchase_preflights = self.storage.get_runtime(PURCHASE_PREFLIGHT_RUNTIME_KEY, {})
        current_purchase_preflight = (
            purchase_preflights.get(current_goal["id"])
            if current_goal and isinstance(purchase_preflights, dict)
            else None
        )
        return redact(
            {
                "controller": {"state": self.state, "dependencies": self.dependencies},
                "character": self._character_name(observation),
                "location": deep_get(observation, "look.room.name", deep_get(observation, "look.room")),
                "vitals": deep_get(observation, "status.vitals", deep_get(observation, "look.vitals", {})),
                "risk": self._risk(observation),
                "liveness": liveness,
                "combat_readiness": self.learning.readiness_summary(observation),
                "combat_history": self.learning.combat_summary(observation, limit=12),
                "execution_plan": current_plan,
                "purchase_preflight": current_purchase_preflight,
                "abilities": {
                    "skills": deep_get(observation, "abilities.skills", []),
                    "spells": deep_get(observation, "abilities.spells", []),
                    "advancement": deep_get(observation, "abilities.advancement", {}),
                },
                "active_goal": None
                if active is None
                else {
                    "id": active["id"],
                    "title": active["title"],
                    "objective": active["objective"],
                    "status": active["status"],
                    "completion": active["completion"],
                },
                "current_goal": None
                if current_goal is None
                else {
                    "id": current_goal["id"],
                    "title": current_goal["title"],
                    "objective": current_goal["objective"],
                    "status": current_goal["status"],
                    "completion": current_goal["completion"],
                    "active": current_goal.get("status") == "active",
                },
                "queued_goals": [
                    {"id": goal["id"], "title": goal["title"], "priority": goal["priority"]}
                    for goal in queued[:5]
                ],
                "pending_proposals": len(self.storage.proposals()),
                "campaign_lessons": [
                    {
                        "id": lesson["id"],
                        "status": lesson["status"],
                        "scope": lesson["scope"],
                        "classification": lesson["classification"],
                        "summary": lesson["summary"],
                    }
                    for lesson in lessons
                ],
                # The source batch supplies the delta. Older operational events
                # made the assessor repeatedly recap already-journaled milestones.
                # Current state and durable combat/lesson summaries are enough to
                # explain significance without turning the journal into a log.
            }
        )

    @staticmethod
    def _character_name(observation: dict[str, Any]) -> Any:
        return deep_get(
            observation,
            "status.character",
            deep_get(observation, "look.self.name", deep_get(observation, "look.character")),
        )

    def _foreground_status_observation(
        self, observation: dict[str, Any]
    ) -> tuple[dict[str, Any], dict[str, Any] | None]:
        """Project cheap live progress while a synchronous action owns the turn."""
        if not isinstance(self._foreground_action, dict):
            return observation, None
        try:
            live = self.broker.call_tool(
                "status",
                {"agent": self.config.game.agent, "brief": True},
                timeout=3,
                mutation=False,
            )
        except (BrokerError, TypeError, ValueError):
            return observation, None
        if not isinstance(live, dict):
            return observation, None
        raw_room = (
            live.get("where")
            if isinstance(live.get("where"), dict)
            else live.get("room")
        )
        raw_room = raw_room if isinstance(raw_room, dict) else {}
        room_id = raw_room.get("num", raw_room.get("id"))
        room_name = raw_room.get("name")
        vitals = live.get("vitals") if isinstance(live.get("vitals"), dict) else None
        if room_id is None and room_name is None and vitals is None:
            return observation, None

        projected = dict(observation)
        look = dict(projected.get("look") or {})
        if room_id is not None or room_name is not None:
            previous_room = (
                look.get("room") if isinstance(look.get("room"), dict) else {}
            )
            look["room"] = {
                "num": room_id if room_id is not None else previous_room.get("num"),
                "name": (
                    room_name
                    if room_name is not None
                    else previous_room.get("name")
                ),
            }
        projected["look"] = look
        projected_status = dict(projected.get("status") or {})
        if vitals is not None:
            projected_status["vitals"] = vitals
        if isinstance(live.get("position"), dict):
            projected_status["position"] = live["position"]
        if live.get("character"):
            projected_status["character"] = live["character"]
        projected["status"] = projected_status
        projected["observed_at"] = time.time()
        return projected, {
            "observed_at": timestamp(),
            "room_id": room_id,
            "location": room_name,
            "position": redact(live.get("position")),
            "vitals": redact(vitals),
        }

    def character_status(self) -> dict[str, Any]:
        """Return a complete, read-only character snapshot for the local TUI."""

        observation, _ = self._foreground_status_observation(
            self.last_observation or {}
        )
        health = None
        try:
            health = self.broker.health(timeout=1)
        except BrokerError:
            pass

        raw_inventory = deep_get(observation, "inventory.items")
        inventory_items = []
        for item in raw_inventory if isinstance(raw_inventory, list) else []:
            if not isinstance(item, dict) or not item.get("name"):
                continue
            quantity = next(
                (
                    item.get(key)
                    for key in ("amount", "quantity", "count")
                    if item.get(key) is not None
                ),
                1,
            )
            inventory_items.append(
                {
                    "id": item.get("id"),
                    "name": " ".join(str(item.get("name")).split()),
                    "quantity": quantity,
                    "slot": item.get("slot"),
                    "equipped": bool(
                        item.get("equipped")
                        or item.get("in_use")
                        or item.get("worn")
                        or (
                            isinstance(item.get("can"), list)
                            and any(
                                str(value).casefold() == "unuse"
                                for value in item["can"]
                            )
                        )
                    ),
                }
            )

        raw_abilities = observation.get("abilities")
        raw_abilities = raw_abilities if isinstance(raw_abilities, dict) else {}

        def ability_rows(group: str) -> list[dict[str, Any]]:
            rows = raw_abilities.get(group)
            if not isinstance(rows, list):
                return []
            return [
                {
                    key: item.get(key)
                    for key in (
                        "name",
                        "ability",
                        "school",
                        "level",
                        "mana",
                        "targets",
                    )
                    if item.get(key) is not None
                }
                for item in rows
                if isinstance(item, dict) and item.get("name")
            ]

        spell_catalog = observation.get("spells")
        spell_catalog = spell_catalog if isinstance(spell_catalog, dict) else {}
        raw_spell_readiness = spell_catalog.get("spells")
        spell_readiness = [
            {
                key: item.get(key)
                for key in (
                    "name",
                    "school",
                    "level",
                    "mana",
                    "targets",
                    "reagents",
                    "castable",
                    "blocked_by",
                )
                if item.get(key) is not None
            }
            for item in (
                raw_spell_readiness
                if isinstance(raw_spell_readiness, list)
                else []
            )
            if isinstance(item, dict) and item.get("name")
        ]
        readiness = self.learning.readiness_summary(observation)
        observed_at = observation.get("observed_at")
        now_text = timestamp()
        return redact(
            {
                "now_utc": now_text,
                "now_local": self.notifications.journal.local_datetime(
                    now_text
                ).isoformat(timespec="seconds"),
                "timezone": self.config.deployment.timezone,
                "game": {
                    "connection": (
                        "joined"
                        if health
                        and self.config.game.agent in health.get("sessions", [])
                        else "disconnected"
                    ),
                    "character_name": self._character_name(observation),
                    "location": deep_get(
                        observation,
                        "look.room.name",
                        deep_get(observation, "look.room"),
                    ),
                    "room_id": deep_get(
                        observation,
                        "look.room.num",
                        deep_get(observation, "look.room_id"),
                    ),
                    "room_properties": self._room_properties(
                        deep_get(
                            observation,
                            "look.room.num",
                            deep_get(observation, "look.room_id"),
                        )
                    ),
                    "position": deep_get(observation, "status.position"),
                    "vitals": deep_get(
                        observation,
                        "status.vitals",
                        deep_get(observation, "look.vitals", {}),
                    ),
                    "attributes": deep_get(
                        observation,
                        "status.attributes",
                        deep_get(observation, "look.attributes", {}),
                    ),
                    "risk": self._risk(observation),
                    "carried_currency": self._carried_currency(observation),
                    "observation_age_seconds": self._age_seconds(observed_at),
                },
                "abilities": {
                    "ability_scale": "0-100",
                    "freshness": raw_abilities.get("freshness", {}),
                    "skills": ability_rows("skills"),
                    "spells": ability_rows("spells"),
                    "spell_readiness": spell_readiness,
                },
                "inventory": {
                    "known": isinstance(raw_inventory, list),
                    "items": inventory_items,
                    "capacity": self._inventory_capacity_context(observation),
                },
                "equipment": {
                    "state": readiness.get("equipment_state"),
                    "equipped": readiness.get("equipped", []),
                    "wielded_weapons": readiness.get("wielded_weapons", []),
                },
            }
        )

    def conversation_history(self, *, limit: int = 60) -> dict[str, Any]:
        """Return recent persisted in-game dialogue for authenticated local clients."""

        limit = max(1, min(int(limit), 200))
        saved = self.storage.get_runtime("conversation_history_v1", {})
        history = saved if isinstance(saved, dict) else self._conversation_history
        messages: list[dict[str, Any]] = []
        for speaker_key, entries in history.items():
            if not isinstance(entries, list):
                continue
            key = str(speaker_key)
            key_kind, separator, key_value = key.partition(":")
            if separator and key_kind == "name":
                speaker = key_value or "unknown speaker"
            elif separator and key_kind == "object":
                speaker = f"object {key_value}" if key_value else "unknown speaker"
            else:
                speaker = key or "unknown speaker"
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                content = " ".join(str(entry.get("content") or "").split())
                if not content:
                    continue
                messages.append(
                    {
                        "speaker_key": key,
                        "speaker": " ".join(
                            str(entry.get("speaker") or speaker).split()
                        ),
                        "role": str(entry.get("role") or "speaker"),
                        "speaker_kind": str(
                            entry.get("speaker_kind") or "unknown_in_game_speaker"
                        ),
                        "content": content,
                        "occurred_at": str(entry.get("at") or ""),
                    }
                )
        messages.sort(key=lambda item: item["occurred_at"])
        observation = self.last_observation or {}
        return {
            "messages": messages[-limit:],
            "timezone": self.config.deployment.timezone,
            "character_name": self._character_name(observation)
            or self.config.game.agent,
        }

    def status(self, *, detail: str = "summary", include_recent_events: int = 3) -> dict[str, Any]:
        if detail not in {"supervision", "summary", "goal", "diagnostic"}:
            raise ValueError("detail must be supervision, summary, goal, or diagnostic")
        observation = self.last_observation or {}
        foreground_action = (
            dict(self._foreground_action)
            if isinstance(self._foreground_action, dict)
            else None
        )
        observation, live_progress = self._foreground_status_observation(observation)
        if foreground_action is not None and live_progress is not None:
            foreground_action["progress"] = live_progress
        active = self.storage.active_goal()
        queued = self.storage.goals(["queued"])
        recent = self.storage.latest_events(limit=200, interesting_only=True)
        planner_feedback = self._planner_feedback(active) if active else None
        health = None
        try:
            health = self.broker.health(timeout=1)
        except BrokerError:
            pass
        if detail in {"supervision", "goal"}:
            compact = self._supervision_status(
                active=active,
                queued=queued,
                health=health,
                observation=observation,
            )
            if detail == "goal":
                inactive = self.storage.goals(["paused", "blocked"])
                current = active or (
                    max(inactive, key=lambda item: str(item.get("updated_at") or ""))
                    if inactive
                    else None
                )
                compact["goal_detail"] = current
                if include_recent_events:
                    compact["recent_events"] = recent[
                        -max(0, min(20, include_recent_events)) :
                    ]
                return redact(compact)
            return compact
        campaign_memory = self.learning.status_summary(observation)
        campaign_execution = self._campaign_execution_status(active)
        value: dict[str, Any] = {
            "controller": {
                "state": self.state,
                "since": self.started_at,
                "version": self.VERSION,
                "last_heartbeat_at": self.last_heartbeat_at,
                "shutdown": self._shutdown_status_snapshot(),
                "control_owner": "foreground_action" if foreground_action else "controller",
                "foreground_action": foreground_action,
            },
            "game": {
                "connection": "joined" if health and self.config.game.agent in health.get("sessions", []) else "disconnected",
                "server": f"{self.config.game.host}:{self.config.game.port}",
                "character_name": self._character_name(observation),
                "location": deep_get(observation, "look.room.name", deep_get(observation, "look.room")),
                "room_id": deep_get(
                    observation,
                    "look.room.num",
                    deep_get(observation, "look.room_id"),
                ),
                "room_properties": self._room_properties(
                    deep_get(
                        observation,
                        "look.room.num",
                        deep_get(observation, "look.room_id"),
                    )
                ),
                "vitals": deep_get(observation, "status.vitals", deep_get(observation, "look.vitals", {})),
                "risk": self._risk(observation),
                "finances": self._financial_context(observation),
                "observation_age_seconds": round(max(0.0, time.time() - float(observation.get("observed_at", time.time()))), 1),
            },
            "onboarding": self._onboarding_status(observation),
            "goal": None if not active else {"id": active["id"], "title": active["title"], "status": active["status"], "progress_percent": active["completion"].get("percent_estimate", 0), "current_step": active["completion"].get("summary"), "outcome_latched": self._goal_completion_checkpoint(active) is not None},
            "queue": {"count": len(queued), "next_title": queued[0]["title"] if queued else None},
            "attention": {
                "pending_proposals": len(self.storage.proposals()),
                "recent_consequential_actions": len(self.storage.recent_consequences()),
                "warnings": self.warnings,
                "planner_feedback": planner_feedback,
                "deferred_goals": len(campaign_memory["deferred_goals"]),
                "eligible_retries": len(campaign_memory["eligible_retries"]),
                "recent_combat_deaths": campaign_memory.get("combat_readiness", {}).get("recent_combat_deaths", 0),
            },
            "dependencies": self.dependencies,
            "knowledge": {
                "corpus_version": self.knowledge.corpus_version,
                "entities": self.knowledge.metadata().get("entity_count", 0),
                "harness_revision": self.knowledge.metadata().get("harness_revision"),
            },
            "campaign_memory": campaign_memory,
            "campaign_execution": campaign_execution,
            "last_interesting_event": recent[-1] if recent else None,
        }
        if include_recent_events:
            value["recent_events"] = recent[-max(0, min(20, include_recent_events)):]
        if detail == "diagnostic":
            value["goal_detail"] = active
            value["diagnostic"] = {"broker_health": health, "policy_version": self.policy.VERSION, "model": self.config.model.name, "knowledge": self.knowledge.metadata(), "recent_consequences": self.storage.recent_consequences(), "goal_lessons": self.storage.goal_lessons(limit=100)}
        return redact(value)

    @staticmethod
    def _risk(observation: dict[str, Any]) -> str:
        health = deep_get(observation, "status.vitals.health", deep_get(observation, "look.vitals.health"))
        if isinstance(health, dict) and health.get("max"):
            ratio = float(health.get("current", health.get("value", 0))) / float(health["max"])
            return "critical" if ratio < 0.4 else "elevated" if ratio < 0.7 else "low"
        return "unknown"

    def _shutdown_status_snapshot(self) -> dict[str, Any] | None:
        with self._shutdown_lock:
            return (
                dict(self._shutdown_status)
                if isinstance(self._shutdown_status, dict)
                else None
            )

    def _set_shutdown_stage(self, stage: str, **updates: Any) -> dict[str, Any]:
        with self._shutdown_lock:
            value = dict(self._shutdown_status or {})
            value.update(updates)
            value["stage"] = stage
            value["updated_at"] = timestamp()
            self._shutdown_status = value
            return dict(value)

    def safe_stop(
        self, *, destination_room_id: int | None = None
    ) -> dict[str, Any]:
        """Request a controller-owned pause, safe return, logout, and stop.

        The API thread only records intent and wakes the controller loop. The
        loop itself drains the request after any in-flight game action returns,
        preserving the single broker-mutation owner. Repeated requests are
        idempotent while a drain is active.
        """

        if destination_room_id is not None:
            if (
                not isinstance(destination_room_id, int)
                or isinstance(destination_room_id, bool)
                or destination_room_id <= 0
            ):
                raise ValueError(
                    "shutdown destination_room_id must be a positive integer"
                )
            if self._verified_safe_staging(destination_room_id) is None:
                raise ValueError(
                    f"shutdown destination room {destination_room_id} is not "
                    "source-verified as a sanctuary or no-combat room"
                )

        with self._shutdown_lock:
            existing = self._shutdown_status
            if (
                isinstance(existing, dict)
                and existing.get("stage")
                not in {"failed", "complete"}
            ):
                return dict(existing)
            requested = {
                "request_id": uuid7(),
                "stage": "requested",
                "requested_at": timestamp(),
                "updated_at": timestamp(),
                "requested_destination_room_id": destination_room_id,
                "paused_goal_ids": [],
                "safe_room": None,
                "logged_out": False,
                "error": None,
            }
            self._shutdown_status = requested

        self.state = "shutdown_requested"
        self._shutdown_requested.set()
        self._wake_event.set()
        self.storage.emit_event(
            "runtime.shutdown_requested",
            "Coordinated pause, safe return, logout, and shutdown requested",
            severity="notice",
            interesting=True,
            data={
                "request_id": requested["request_id"],
                "requested_destination_room_id": destination_room_id,
            },
        )
        return dict(requested)

    @staticmethod
    def _shutdown_full_health(observation: dict[str, Any]) -> bool:
        health = deep_get(
            observation,
            "status.vitals.health",
            deep_get(observation, "look.vitals.health"),
        )
        if not isinstance(health, dict):
            return False
        current = health.get("current", health.get("value"))
        maximum = health.get("max")
        try:
            return float(current) > 0 and float(current) >= float(maximum)
        except (TypeError, ValueError):
            return False

    @staticmethod
    def _shutdown_keeper_threat_clear(status: Any) -> bool:
        if not isinstance(status, dict):
            return True
        threat = status.get("threat")
        if not isinstance(threat, dict):
            return True
        for key in ("could_reach_us", "camped_on_us", "in_swing_range"):
            try:
                if float(threat.get(key, 0) or 0) > 0:
                    return False
            except (TypeError, ValueError):
                return False
        try:
            return float(threat.get("landing_damage", 0) or 0) <= 0
        except (TypeError, ValueError):
            return False

    def _refresh_shutdown_observation(self) -> dict[str, Any]:
        observation = self._reconcile_recent_inventory_creation(
            self._reconcile_recent_room_transition(self.broker.observe())
        )
        self.last_observation = observation
        self._remember_safe_staging(observation)
        self.storage.record_snapshot(redact(observation))
        self.last_heartbeat_at = timestamp()
        return observation

    def _pause_all_runnable_goals_for_shutdown(self) -> list[str]:
        paused: list[str] = []
        # Storage promotes the next queued goal whenever an active goal is
        # paused. Looping therefore atomically drains every runnable goal into
        # the durable paused state before broker ownership changes.
        for _ in range(200):
            active = self.storage.active_goal()
            if active is None:
                return paused
            result = self.manage_goal(
                {
                    "request_id": f"shutdown-pause-{uuid7()}",
                    "goal_id": active["id"],
                    "expected_version": active.get("version"),
                    "action": "pause",
                    "reason": (
                        "Coordinated shutdown paused all runnable work before "
                        "safe return and logout"
                    ),
                }
            )
            goal = result.get("goal") if isinstance(result, dict) else None
            if not isinstance(goal, dict) or goal.get("status") != "paused":
                raise RuntimeError(
                    f"shutdown could not verify paused goal {active['id']}"
                )
            paused.append(str(goal["id"]))
        raise RuntimeError("shutdown refused to drain more than 200 runnable goals")

    def _shutdown_safe_candidates(
        self,
        observation: dict[str, Any],
        requested_room_id: int | None,
    ) -> list[dict[str, Any]]:
        current_room = deep_get(
            observation,
            "look.room.num",
            deep_get(observation, "look.room_id"),
        )
        current = self._verified_safe_staging(current_room)
        if current is not None and requested_room_id is None:
            return [{**current, "basis": "already_in_verified_safe_room"}]

        candidates: list[dict[str, Any]] = []
        if requested_room_id is not None:
            requested = self._verified_safe_staging(requested_room_id)
            if requested is not None:
                candidates.append(
                    {**requested, "basis": "operator_requested_safe_room"}
                )

        finder = getattr(self.knowledge, "safe_location_candidates", None)
        if callable(finder) and current_room is not None:
            try:
                found = finder(
                    int(current_room),
                    preferred_room_id=(
                        requested_room_id
                        if requested_room_id is not None
                        else FAMILIARS_ROOM_ID
                    ),
                    limit=12,
                )
            except (TypeError, ValueError):
                found = None
            raw = found.get("candidates") if isinstance(found, dict) else None
            for item in raw if isinstance(raw, list) else []:
                if not isinstance(item, dict):
                    continue
                verified = self._verified_safe_staging(item.get("room_id"))
                if verified is not None:
                    candidates.append(
                        {
                            **verified,
                            "distance": item.get("distance"),
                            "basis": item.get("basis") or "source_safe_candidate",
                        }
                    )

        remembered = self.storage.get_runtime(SAFE_STAGING_RUNTIME_KEY, {})
        if isinstance(remembered, dict):
            verified = self._verified_safe_staging(remembered.get("room_id"))
            if verified is not None:
                candidates.append(
                    {
                        **verified,
                        "basis": "source_revalidated_last_observed_safe_room",
                    }
                )

        unique: list[dict[str, Any]] = []
        seen: set[int] = set()
        for item in candidates:
            room_id = int(item["room_id"])
            if room_id in seen:
                continue
            seen.add(room_id)
            unique.append(item)
        return unique[:SHUTDOWN_MAX_SAFE_CANDIDATES]

    def _stop_keeper_for_shutdown(self) -> dict[str, Any]:
        status = self.broker.call_tool(
            "autopilot",
            {"agent": self.config.game.agent, "action": "status"},
            timeout=20,
            mutation=False,
        )
        if not self._keeper_is_driving(status):
            return status if isinstance(status, dict) else {"running": False}
        result = self.broker.call_tool(
            "autopilot",
            {
                "agent": self.config.game.agent,
                "action": "stop",
                "hard": True,
                "why": (
                    "coordinated shutdown is transferring movement ownership "
                    "to verified safe return"
                ),
            },
            timeout=30,
            mutation=True,
        )
        # Upstream hard-stop is intentionally asynchronous: it marks the keeper
        # as stopping and returns its current status, which can still have
        # running=true until the in-flight pass reaches its cancellation
        # boundary. Poll the authoritative state instead of mistaking that
        # acknowledgement for a refusal and immediately reviving the keeper.
        deadline = time.monotonic() + SHUTDOWN_KEEPER_STOP_TIMEOUT_SECONDS
        status = result
        while self._keeper_is_driving(status) and time.monotonic() < deadline:
            time.sleep(0.25)
            status = self.broker.call_tool(
                "autopilot",
                {"agent": self.config.game.agent, "action": "status"},
                timeout=20,
                mutation=False,
            )
        if self._keeper_is_driving(status):
            raise RuntimeError(
                "keeper did not release control before the shutdown timeout"
            )
        return status if isinstance(status, dict) else {"running": False}

    def _recover_for_shutdown(
        self, observation: dict[str, Any]
    ) -> dict[str, Any]:
        current_room = deep_get(observation, "look.room.num")
        if self._verified_safe_staging(current_room) is not None:
            return observation
        keeper = self.broker.call_tool(
            "autopilot",
            {"agent": self.config.game.agent, "action": "status"},
            timeout=20,
            mutation=False,
        )
        if self._shutdown_full_health(observation) and self._shutdown_keeper_threat_clear(
            keeper
        ):
            return observation

        self._set_shutdown_stage(
            "recovering",
            detail="survival keeper is recovering or withdrawing before safe travel",
        )
        self._ensure_survival_keeper()
        deadline = time.monotonic() + SHUTDOWN_RECOVERY_TIMEOUT_SECONDS
        while time.monotonic() < deadline:
            time.sleep(2.0)
            observation = self._refresh_shutdown_observation()
            current_room = deep_get(observation, "look.room.num")
            if self._verified_safe_staging(current_room) is not None:
                return observation
            keeper = self.broker.call_tool(
                "autopilot",
                {"agent": self.config.game.agent, "action": "status"},
                timeout=20,
                mutation=False,
            )
            if self._shutdown_full_health(
                observation
            ) and self._shutdown_keeper_threat_clear(keeper):
                return observation
        raise RuntimeError(
            "survival keeper did not establish full-health, threat-clear travel "
            "readiness before the shutdown recovery timeout"
        )

    def _travel_to_shutdown_safety(
        self,
        observation: dict[str, Any],
        requested_room_id: int | None,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        current_room = deep_get(observation, "look.room.num")
        current_safe = self._verified_safe_staging(current_room)
        if current_safe is not None and (
            requested_room_id is None
            or str(current_room) == str(requested_room_id)
        ):
            return observation, {
                **current_safe,
                "basis": "already_in_verified_safe_room",
            }

        candidates = self._shutdown_safe_candidates(
            observation, requested_room_id
        )
        if not candidates:
            raise RuntimeError(
                f"no source-verified shutdown sanctuary is available from room {current_room}"
            )

        capabilities = self.broker.capabilities()
        self._stop_keeper_for_shutdown()
        failures: list[dict[str, Any]] = []
        for candidate in candidates:
            destination = int(candidate["room_id"])
            self._set_shutdown_stage(
                "travelling",
                destination_room_id=destination,
                destination_name=candidate.get("name"),
                route_failures=failures,
            )
            self._begin_foreground_action("shutdown_safe_return")
            try:
                if "rest" in capabilities:
                    self.broker.call_tool(
                        "rest",
                        {"agent": self.config.game.agent, "stand": True},
                        timeout=10,
                        mutation=True,
                    )
                if "look" in capabilities:
                    self.broker.call_tool(
                        "look",
                        {"agent": self.config.game.agent},
                        timeout=20,
                        mutation=False,
                    )
                arguments: dict[str, Any] = {
                    "agent": self.config.game.agent,
                    "to": destination,
                }
                travel_tool = capabilities.get("travel")
                if travel_tool is not None and travel_tool.accepts("max_hops"):
                    arguments["max_hops"] = 50
                result = self.broker.call_tool(
                    "travel",
                    arguments,
                    timeout=SHUTDOWN_TRAVEL_TIMEOUT_SECONDS,
                    mutation=True,
                )
            except (BrokerError, ValueError) as exc:
                result = {"error": str(exc)[:500]}
            finally:
                self._end_foreground_action()

            observation = self._refresh_shutdown_observation()
            arrived_room = deep_get(observation, "look.room.num")
            verified = self._verified_safe_staging(arrived_room)
            if verified is not None and str(arrived_room) == str(destination):
                return observation, {
                    **verified,
                    "basis": candidate.get("basis"),
                }
            failures.append(
                {
                    "destination_room_id": destination,
                    "result": redact(result),
                    "observed_room_id": arrived_room,
                }
            )
            observation = self._recover_for_shutdown(observation)
            self._stop_keeper_for_shutdown()

        raise RuntimeError(
            "every source-verified shutdown sanctuary route failed: "
            + "; ".join(
                f"room {item['destination_room_id']} left us in "
                f"{item.get('observed_room_id')}"
                for item in failures
            )
        )

    def _logout_for_shutdown(self) -> dict[str, Any]:
        capabilities = self.broker.capabilities()
        leave = capabilities.get("leave")
        if leave is None:
            raise RuntimeError("broker does not expose the controller-owned leave tool")
        arguments: dict[str, Any] = {"agent": self.config.game.agent}
        if leave.accepts("forget"):
            # FR-CHAR-006: ordinary shutdown must preserve the credential roster.
            arguments["forget"] = False
        result = self.broker.call_tool(
            "leave", arguments, timeout=30, mutation=True
        )
        if not isinstance(result, dict) or result.get("left") is not True:
            try:
                health = self.broker.health(timeout=3)
            except BrokerError:
                health = None
            sessions = health.get("sessions") if isinstance(health, dict) else None
            if not isinstance(sessions, list) or self.config.game.agent in sessions:
                raise RuntimeError(
                    "broker did not affirm that the character logged out"
                )
        if not isinstance(result, dict):
            result = {"left": True}
        if result.get("forgotten") is True:
            raise RuntimeError(
                "broker unexpectedly removed the character from its credential roster"
            )

        deadline = time.monotonic() + SHUTDOWN_SESSION_EXIT_TIMEOUT_SECONDS
        session_absent = False
        while time.monotonic() < deadline:
            try:
                health = self.broker.health(timeout=3)
            except BrokerError:
                # The affirmative leave receipt is enough if the broker begins
                # shutting down before its next health response.
                session_absent = True
                break
            sessions = health.get("sessions")
            if isinstance(sessions, list) and self.config.game.agent not in sessions:
                session_absent = True
                break
            time.sleep(0.25)
        if not session_absent:
            raise RuntimeError(
                "character remained in the broker session list after logout"
            )
        return result

    def _fail_safe_shutdown(self, exc: Exception) -> None:
        message = str(exc)[:1000]
        try:
            health = self.broker.health(timeout=3)
            joined = self.config.game.agent in health.get("sessions", [])
        except BrokerError:
            joined = False
        if joined:
            try:
                self._ensure_survival_keeper()
            except (BrokerError, ValueError):
                pass
        self._shutdown_requested.clear()
        self.state = "shutdown_failed"
        self.warnings = [*self.warnings[-9:], f"shutdown: {message}"]
        self._set_shutdown_stage(
            "failed",
            error=message,
            logged_out=not joined,
            fail_safe=(
                "controller remains running with goals paused; survival keeper "
                "was retained or restarted when the session was still joined"
            ),
        )
        self.storage.emit_event(
            "runtime.shutdown_failed",
            "Coordinated shutdown failed safe; controller remains running",
            severity="error",
            interesting=True,
            data={"error": message, "joined": joined},
        )

    def _perform_safe_shutdown(self) -> dict[str, Any]:
        request = self._shutdown_status_snapshot() or {}
        requested_room_id = request.get("requested_destination_room_id")
        self._mark_planned_phase_stop()
        self.state = "draining"
        self._set_shutdown_stage("pausing", error=None)
        try:
            paused_goal_ids = self._pause_all_runnable_goals_for_shutdown()
            self._set_shutdown_stage(
                "securing", paused_goal_ids=paused_goal_ids
            )
            try:
                health = self.broker.health(timeout=3)
            except BrokerError as exc:
                raise RuntimeError(
                    "cannot verify the broker session before shutdown"
                ) from exc
            if self.config.game.agent not in health.get("sessions", []):
                final = self._set_shutdown_stage(
                    "complete",
                    paused_goal_ids=paused_goal_ids,
                    logged_out=True,
                    safe_room=None,
                    detail="character was already absent from the broker session list",
                )
            else:
                observation = self._refresh_shutdown_observation()
                observation = self._recover_for_shutdown(observation)
                observation, safe_room = self._travel_to_shutdown_safety(
                    observation,
                    int(requested_room_id)
                    if requested_room_id is not None
                    else None,
                )
                current_room = deep_get(observation, "look.room.num")
                if self._verified_safe_staging(current_room) is None:
                    raise RuntimeError(
                        "shutdown safe-room verification was lost before logout"
                    )
                self._set_shutdown_stage(
                    "logging_out", safe_room=redact(safe_room)
                )
                self._stop_keeper_for_shutdown()
                leave_result = self._logout_for_shutdown()
                final = self._set_shutdown_stage(
                    "complete",
                    paused_goal_ids=paused_goal_ids,
                    safe_room=redact(safe_room),
                    logged_out=True,
                    leave_result=redact(leave_result),
                )
            self.storage.emit_event(
                "runtime.shutdown_complete",
                "Paused runnable work, verified safety, logged out, and completed shutdown",
                severity="notice",
                interesting=True,
                data=redact(final),
            )
            self.state = "stopping"
            self._shutdown_requested.clear()
            self.stop_event.set()
            self._wake_event.set()
            return final
        except Exception as exc:
            self._fail_safe_shutdown(exc)
            return self._shutdown_status_snapshot() or {"stage": "failed"}

    def _active_campaign_phase_identity(self) -> tuple[str, str, str] | None:
        goal = self.storage.active_goal()
        if goal is None:
            return None
        run = self.storage.campaign_run(goal["id"])
        if run is None:
            return None
        phase = self.storage.active_campaign_phase(run["id"])
        if phase is None:
            return None
        return str(goal["id"]), str(run["id"]), str(phase["id"])

    def _mark_planned_phase_stop(self) -> None:
        identity = self._active_campaign_phase_identity()
        if identity is None:
            return
        goal_id, run_id, phase_id = identity
        existing = self.storage.get_runtime(PLANNED_CONTROLLER_STOP_RUNTIME_KEY, {})
        if (
            isinstance(existing, dict)
            and str(existing.get("goal_id") or "") == goal_id
            and str(existing.get("run_id") or "") == run_id
            and str(existing.get("phase_id") or "") == phase_id
            and isinstance(existing.get("stopped_unix"), (int, float))
        ):
            return
        self.storage.set_runtime(
            PLANNED_CONTROLLER_STOP_RUNTIME_KEY,
            {
                "goal_id": goal_id,
                "run_id": run_id,
                "phase_id": phase_id,
                "stopped_at": timestamp(),
                "stopped_unix": time.time(),
            },
        )

    def _account_planned_phase_downtime(self) -> dict[str, Any] | None:
        marker = self.storage.get_runtime(PLANNED_CONTROLLER_STOP_RUNTIME_KEY, {})
        if not isinstance(marker, dict):
            return None
        stopped_unix = marker.get("stopped_unix")
        if not isinstance(stopped_unix, (int, float)):
            self.storage.set_runtime(PLANNED_CONTROLLER_STOP_RUNTIME_KEY, None)
            return None
        identity = self._active_campaign_phase_identity()
        marker_identity = (
            str(marker.get("goal_id") or ""),
            str(marker.get("run_id") or ""),
            str(marker.get("phase_id") or ""),
        )
        if identity is None or identity != marker_identity:
            self.storage.set_runtime(PLANNED_CONTROLLER_STOP_RUNTIME_KEY, None)
            return None
        goal_id, run_id, phase_id = identity
        added_seconds = max(0.0, time.time() - float(stopped_unix))
        prior = self.storage.get_runtime(CAMPAIGN_PHASE_DOWNTIME_RUNTIME_KEY, {})
        prior_seconds = 0.0
        if (
            isinstance(prior, dict)
            and str(prior.get("phase_id") or "") == phase_id
        ):
            try:
                prior_seconds = max(0.0, float(prior.get("seconds", 0.0) or 0.0))
            except (TypeError, ValueError):
                prior_seconds = 0.0
        total_seconds = prior_seconds + added_seconds
        value = {
            "goal_id": goal_id,
            "run_id": run_id,
            "phase_id": phase_id,
            "seconds": total_seconds,
            "updated_at": timestamp(),
        }
        self.storage.set_runtime(CAMPAIGN_PHASE_DOWNTIME_RUNTIME_KEY, value)
        self.storage.set_runtime(PLANNED_CONTROLLER_STOP_RUNTIME_KEY, None)
        self.storage.emit_event(
            "campaign.phase.downtime_accounted",
            "Excluded planned controller downtime from the active phase budget",
            goal_id=goal_id,
            data={
                "run_id": run_id,
                "phase_id": phase_id,
                "added_seconds": round(added_seconds, 1),
                "total_seconds": round(total_seconds, 1),
            },
        )
        return value

    def close(self) -> None:
        self.stop_event.set()
        if (
            self._notification_thread
            and self._notification_thread.is_alive()
            and self._notification_thread is not threading.current_thread()
        ):
            self._notification_thread.join(
                timeout=min(55.0, max(2.0, self.config.model.responder_timeout_seconds + 5.0))
            )
        if (
            self._social_thread
            and self._social_thread.is_alive()
            and self._social_thread is not threading.current_thread()
        ):
            self._social_thread.join(
                timeout=min(55.0, max(2.0, self.config.model.responder_timeout_seconds + 5.0))
            )
        self.broker.shutdown_owned_process()
        self.storage.close()
